\paragraph{Organization of the Article.}
Section~\ref{sec:model} introduces a SOLG framework with an explicit climate externality. 
Section~\ref{sec:calibration} explains our choice of key parameters and functional forms of the model.
Section~\ref{sec:methodology} develops a generic, machine-learning-based procedure for computing Pareto-improving policies in heterogeneous-agent economies with various sources of uncertainty. Section~\ref{sec:results} illustrates the method’s performance through a series of numerical experiments, and Section ~\ref{sec:conclusion} concludes.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{A Stochastic OLG Model with Climate Change}
\label{sec:model}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We consider a stochastic OLG economy with climate change caused by industrial emissions, which leads to a decrease in future total factor productivity.
There is an infinite time-horizon, $ t=0,\ldots $, and exogenous Markovian shocks realize every period.
The economic block consists of 12 overlapping generations of selfish agents, in which each period spans five calendar years; households enter the economy at age~20 and exit at age~80~\citep{kotlikoff2020pareto}. 
A representative firm produces a single consumption good using capital and labor as inputs and emitting CO$_2$ during the production process. We assume exogenously declining stochastic carbon intensity dynamics.
The climate block is represented by a reduced-form, cumulative-emissions emulator~\citep{dietz2019cumulative}.\footnote{Climate emulators are simplified models that link CO$_2$ emissions to global mean temperature at negligible computational cost and are therefore well suited for policy analysis. For more details, see, e.g.,~\cite{doi:10.1086/713977,Folini_2021}, and~\cite{eftekhari2024building}.} 
Climate damages follow the convex specification of~\citet{weitzman2012ghg}, augmented with stochastic tipping points in the spirit of~\citet{kotlikoff2020pareto}.
We outline the model in the following steps: Section~\ref{sec:firms} presents the firm block, Section~\ref{sec:households} explains household behaviour, Section~\ref{sec:government} details the role of the government, Section~\ref{sec:climate_module} describes the climate module, and Section~\ref{sec:equilbrium} defines the competitive equilibrium.


\subsection{Firms}
\label{sec:firms}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The representative firm produces consumption good $Y$ and emissions $e_t$ at each time $t$:
%
\begin{equation}
(Y_t,e_t)=f_t(K_t,L_t,\mu_t)=\left( \Omega(T^{AT}_t)\Phi(1-\mu_t) K_t^{\alpha} L_t^{1-\alpha} + (1 - \delta) K_t, (1-\mu_t) \kappa_t K_t^{\alpha} L_t^{1-\alpha}\right).
\end{equation}
%
Production is given by a Cobb-Douglas production function, where $\alpha$ represents the elasticity of substitution of capital, $K$, $L$, and $\delta$ are capital, labour, and depreciation, respectively. $ \mu $ denotes abatement, and $ \Phi:[0,1] \rightarrow [0,1] $ is a mitigation cost function. $\kappa$ is the exogenous carbon intensity of production and $\Omega(T^{AT})$ are damages arising from climate change, where $ T^{AT} $ denotes current average temperature. Firms take as given a carbon tax rate $\tau_t$ and maximize profits:
%
\begin{equation}
    \max_{\mu_t, K_t, L_t} \Pi  =\Omega_t(T_{t}) (1-\theta_{1}\mu_t^{\theta_2}) K_t^{\alpha} L_t^{1-\alpha} + (1- \delta) K_t -w_tL_t-(1+r_t)K_t - \tau_t (1-\mu_t) \kappa_t K_t^{\alpha} L_t^{1-\alpha}
    \label{eq:profit}
\end{equation}
$$\text{s.t.} \quad 0 \leq \mu_t \leq 1.$$

The carbon intensity ($\kappa_t$) follows an exogenous time-varying stochastic process. In the calibration, our objective will be to capture the uncertainty in CO$_2$ emissions and account for the possibility that emissions remain elevated over the next 100 years. 

We assume an abatement function of the form $ \Phi (1- \mu) = 1 - \theta_{1} \mu_t^{\theta_2}$ in the spirit of \cite{nordhausRevisitingSocialCost2017}. Abatement is restricted to be $0 \leq \mu \leq 1$. Unabated emissions lead to an increase in atmospheric temperature, which triggers damages that reduce output. We employ a damage function as in \cite{weitzman2012ghg} and follow  \cite{kotlikoff2020pareto} by enhancing damages with stochastic tipping:
%
\begin{align}
    \label{eq:damage_func_tipping_new}
    \Omega_t \left( T_t^{AT} \right) =  \frac{1}{1 + \left(\frac{1}{\psi_1} T_t^{AT} \right)^{2} + \left( \frac{1}{2 \cdot TP_{t}} T_t^{AT} \right)^{6.754}},
\end{align}
%
where $T_t^{AT}$ is atmospheric temperature and $TP_t$ is the tipping point which follows a random walk.\footnote{A tipping point is a critical threshold in the climate system beyond which a small additional change triggers large, abrupt, and often irreversible shifts in the state of the system (examples include a collapse of the Atlantic Meridional Overturning Circulation, Amazon rainforest dieback, or disintegration of the West Antarctic Ice Sheet; see, e.g., \citealp{lenton2008tipping,doi:10.1086/701890}). 
Note that, whereas we refer to a tipping point in Equation~\eqref{eq:damage_func_tipping_new}, \citet{DIETZ2012321} consider such a damage specification, with a changing exponent, as an instance of epistemic uncertainty.}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Households}
\label{sec:households}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In each period, a new household enters the economy with zero assets. Households live for A =12 periods, where each period corresponds to 5 years. There is no uncertainty regarding lifetime. An agent born at time $t$ maximizes expected lifetime utility given by:
%
\begin{equation}
     {\mathbb E}_t \sum\limits_{j = 1}^{A} \beta^j \frac{C_{t+j-1, j}^{1-\sigma}}{1-\sigma}, 
    \label{eq:agentproblem}
\end{equation} 
subject to: 
%
\begin{equation}
C_{t,j}+a_{t+1, j+1}=(1+r_t)a_{t,j} + w_{t} l_{j} + \mathbb{T}_{t,j},
\label{eq:BC_main}
\end{equation} 
%
where $\beta$ is the discount factor, $C_{t,j}$, $a_{t, j}$, $l_{j}$ are consumption, assets, and labour endowment of generation $j$ at time $t$. $r_t$ and $w_t$ are the factor prices of production (interest rate and wages), and $\mathbb{T}_{t,j}$ is the transfer from the government.

In each period, households sell their assets to the firm and supply labor inelastically. Households choose consumption $C_{j,t}$ and savings $a_{t+1, j+1}$ in period $t$. We follow \citet{benzell2015simulating} and assume that agents enter the workforce with $0$ assets, work for $8$ periods ($40$ years), and then retire. After retirement, agents' labor endowment drops to $40\%$ of the endowment in period 8, which serves as a proxy for a pension system. 
Further details on the recursive formulation of the household problem are given in Appendix~\ref{sec:appendix_recursive}.

We define the time-zero expected utilities of a future generation, born at time $t$ as 
%
\begin{equation}
\tilde{U}_t = \mathbb{E}_0 \sum\limits_{j = 1}^{A} \beta^j \frac{C_{t+j-1, j}^{1-\sigma}}{1-\sigma}, 
\label{eq:utility} 
\end{equation}
%
where $ C_{t+j-1,j} $ denotes the agent's optimal consumption under a policy scenario with taxes. This distinguishes it from the utility in the BAU case, denoted by $U_t$, which assumes zero taxes and is defined analogously.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Government}
\label{sec:government}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The government levies a carbon tax on firms and redistributes the tax income among concomitant households. It sets the path for the tax rate $\tau_t$ and redistribution schedule $\mathbb{T}_{t}$ in period 0 to maximize ex-ante welfare given Welfare weights $\gamma$. Specifically, the government maximizes the ex-ante sum of weighted utilities:
%
\begin{equation}
    \max_{\tau_t} \sum_{t=-10}^{29} \gamma_t \tilde{U_t},
    \label{eq:planner_objective_general}
\end{equation}
%
subject to the resource constraint:
%
\begin{equation}
    \sum_{j=1}^{A} \mathbb{T}_{t,j} = \tau_{t} e_t \quad  \forall t .
\label{eq:resource_constraint_planner}
\end{equation}
%
In the numerical experiments performed in Section~\ref{sec:results}, we consider linear, state-dependent taxes, $\tau_t(\cdot)$, on cumulative emissions, carbon intensity, and the climate-tipping variable.
We evaluate welfare gains by computing the consumption equivalence factor:
%
  \begin{equation}
       \left(\frac{\tilde{U}_t}{U_t}\right)^{\frac{1}{1-\sigma}}-1,
       \label{eq:cons_equiv_variation}
  \end{equation}   
%
In addition to considering the maximization problem (\ref{eq:planner_objective_general}), we also consider the additional constraint 
\begin{equation}
\label{eq:paretoim}
  \left(\frac{\tilde{U}_t}{U_t}\right)^{\frac{1}{1-\sigma}}-1 \ge 0, \mbox{ for all } t=-10,\ldots,29 .
       \end{equation}
%


%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Climate Module}
\label{sec:climate_module}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Climate science has established a near-linear relationship between cumulative CO$_2$ emissions and the resulting global warming, which we adopt: 
\begin{equation}
    T_t^{AT} \approx \sigma_{CCR} \sum_{s=0}^{t-1} e_s ,
\end{equation}
where $T_t^{AT}$ denotes the global mean surface temperature, $e_s$ represents global emissions, and $ \sigma_{CCR}$ is the constant of proportionality, referred to as the carbon-climate response (CCR) or the Transient Climate Response to Cumulative Carbon Emissions (TCRE; \citealp{matthews2009proportionality, dietz2019cumulative}). We report emissions in terms CO$_2$. For notational convenience, we also define the stock of carbon in the atmosphere as
%
\begin{equation}
    E_t = \frac{1}{3.666}\sum_{s=0}^{t-1} e_s, 
\end{equation}
%
where $3.666$ is the conversion factor from Carbon C to CO$_2$.
Additional details can be found in Appendix~\ref{sec:Climate_module_appendix}.\footnote{We report cumulative emissions in thousand gigatonnes of carbon (th Gt C) and, for brevity, use the terms ``stock of carbon'' and ``cumulative emissions'' interchangeably.}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Equilibrium}
\label{sec:equilbrium}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

A competitive equilibrium, given initial conditions ($E_0,T_0^{AT},TP_0,\kappa_0,\{a_{0,j} \}_1^A$), a tax function (e.g., $\tau(E,\kappa,TP)$) and transfer scheme ($\mathbb{T}$), is a collection of choices for households ($\{c_{0,j} \}_{j=1}^A$,$\{a_{0,j+1} \}_{j=1}^{A}$), the representative firm $(K_t,L_t)_{t=0}^\infty$, and prices $(r_t,w_t)_{t=0}^\infty$ such that:
%    
\begin{enumerate}
    \item Given $(r_t, w_t, \mathbb{T})_{t=0}^\infty$, households maximize \eqref{eq:utility} subject to \eqref{eq:BC_main}.
    \item Given $(r_t, w_t, \tau_t)_{t=0}^\infty$, firms maximize \eqref{eq:profit}.
    \item All markets clear, that is,
    \begin{equation}
\label{eq:capmarket}
    \sum_{j = 1}^{A} a_{t,j} = K_t \quad \forall t,
\end{equation}
\begin{equation}
\label{eq:labmarket}
    \sum_{j = 1}^{A} l_j = L_t \quad \forall t.
\end{equation}
\end{enumerate}
%
%
The first-order conditions of the firm imply that
%
\begin{equation}
    \label{eq:FOC_mu}
\Omega_t(T_{t}^{AT}) (\theta_1\theta_2\mu_t^{\theta_2-1})  = \tau_t \kappa_t,
\end{equation}
%
\begin{equation}
 r_t = \alpha K_t^{\alpha-1} L_t^{1-\alpha}\left(\Omega_t(T_{t}^{AT}) (1-\theta_1\mu_t^{\theta_2}) - \tau_t \kappa_t(1-\mu_t)  \right)  - \delta,
\end{equation}
%
\begin{equation}
    w_t = (1-\alpha) K_t^{\alpha} L_t^{-\alpha} \left(\Omega_t(T_{t}^{AT}) (1-\theta_1\mu_t^{\theta_2}) -\tau_t \kappa_t (1-\mu_t) \right) .
\end{equation}
%
The Euler equations for the households $j \in 1,...,A-1$ are given by:
\begin{equation}
\label{eq:euler}
  C_{t,j}^{-\sigma} = \beta \mathbb{E}_t \left[ (1+r_{t+1}) C_{t+1,j+1}^{-\sigma}  \right]. 
\end{equation}
%
Note that there is no Euler equation for $j=A$ because agents consume their entire endowment in the final period.


