\subsection{Recursive Formulation Of The Household Problem}
\label{sec:appendix_recursive}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

In order to assess lifetime utility (cf. Section~\ref{sec:households}), we reformulate the household problem into a recursive problem:
%
\begin{equation}
    V_{t,j} = \max_{c_{t,j},a_{t+1,j}} \left\{ \left( \frac{C_{t,j}^{1-\sigma}}{1-\sigma} \right) + \beta \mathbb{E}_t V_{t+1,j+1} \right\} \quad \forall j \in 1,...,A-1
    \label{eq:Value_function}
\end{equation}
\begin{equation}
    V_{t,A} = \left( \frac{C_{t,A}^{1-\sigma}}{1-\sigma} \right)
    \label{eq:Value_function_oldest}
\end{equation}
subject to the budget constraint \eqref{eq:BC_main} initial and terminal conditions $a_{t,1} = 0$, $a_{t+1,A+1} = 0$.

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{The Climate Module}
\label{sec:Climate_module_appendix}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Global emissions, $e_t$, in period $t$ are defined as
\begin{equation}
    e_t = (1 - \mu_t) \kappa_t K_t^{\alpha} L_t^{1-\alpha}.
\end{equation}
The stock of atmospheric carbon, $E_t$, and the atmospheric temperature, $T_t^{AT}$, then evolve according to
\begin{align}
    E_{t}      & = E_{t-1} + e_t / \text{C2CO2}, \\
    T_t^{AT} & = \sigma_{CCR} E_t,
\end{align}
where $\text{C2CO2} \approx 3.666$ is the conversion factor from carbon to CO$_2$ concentration and $\sigma_{CCR}$ is the transient climate response to cumulative carbon emissions (cf. Table~\ref{tab:Parameters}).

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{Deep Equilibrium Nets for SOLG IAMs}
\label{sec:DEQN_for_SOLG_IAM}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this appendix, we detail the procedure for mapping a stochastic, nonlinear, and non-stationary SOLG IAM presented 
in Section~\ref{sec:model} onto the DEQN framework. 
Recall that the state of the economy (for the optimal policy case) at time \( t \) is given by
%
\begin{equation}
  x_t = \bigl[
      t,\;
      TP_t,\;
      TP_{\text{reached},t},\;
      \kappa_t,\;
      \{a_{t,j}\}_{j=1}^{A},\;
      E_t,\;
      \vartheta
    \bigr]^{\top} \in \mathbb{R}^{A+5+d_\vartheta},
\label{eq:state_optimal}
\end{equation}
%
In the BAU case, the state vector simplifies to
%
\begin{equation}
  x_t^{BAU}= \bigl[
      t,\;
      TP_t,\;
      TP_{\text{reached},t},\;
      \kappa_t,\;
      \{a_{t,j}\}_{j=1}^{A},\;
      E_t
    \bigr]^{\top} \in \mathbb{R}^{A+5},
\end{equation}
%
as no tax-and-transfer schemes are present (\(\vartheta = \emptyset\)) and no mitigation occurs. This reduces the state space dimension by excluding the tax-and-transfer parameters and reflects the absence of policy interventions in the model.

To address the non-stationary nature of the IAM, as in~\cite{traeger4StatedDICEQuantitatively2014,Folini_2021}, we include time as a state variable and map the unbounded physical time \( t \in [0,\infty) \) to a computational time scale via the monotonic transformation
%
\begin{equation}
    t_{\text{comp}} = 1 - \exp(-\zeta t),
    \label{eq:time_trafo}
\end{equation}
%
where \( t_{\text{comp}} \in (0,1] \) and \( \zeta > 0 \) is a scaling parameter. The physical time is recovered using the inverse transformation
%
\begin{equation}
    t = -\frac{\ln(1 - t_{\text{comp}})}{\zeta}.
\end{equation}
%
In our numerical applications (cf. Section~\ref{sec:results}), we set $\zeta=0.015$ 
This transformation ensures computational tractability while preserving the model’s temporal dynamics.

To stabilize the training, we normalize consumption, asset holdings, and capital in effective labour units:
%
\begin{equation}
c_t = \frac{C_t}{L_t}, \hat{a}_{t,j} = \frac{a_{t,j}}{L_t}, k_t = \frac{K_t}{L_t}, \hat{l}_j = \frac{l_j}{L_t}, v_{t,j} = \frac{V_{t,j}}{L_t^{1/(1-\sigma)}}.
\end{equation}
%
Emissions are given by
%
\begin{equation}    
e_t = (1 - \mu_t) \kappa_t L_t k_t^{\alpha}. 
\end{equation}
%
The period utility functions (and therefore also the value functions) are scaled with a constant $B=20$:
\begin{equation}    
U(C_t) = U(B c_t).
\end{equation}
%%%%%%%%%%%%%%%%%% good until here
\vspace{-1.25em}
\paragraph{First-order Equations, and Loss Function for the BAU case.}
Given those normalizations, the first-order equations in the BAU case read as follows:
%
\begin{align}
    0 & = \frac{\left(\beta \mathbb{E}_t \left[ (1+r_{t+1}) c_{t+1,j+1}^{-\sigma}  \right]\right)^{-1/\sigma}}{c_{t,j}} - 1, \quad \forall j \in 1,...,A-1, \label{eq:EE_error_BAU}\\
0 & = c_{t,j}+\hat{a}_{t+1, j+1} - (1+r_t)\hat{a}_{t,j} -w_{t} \hat{l}_{j} , \quad \forall j \in 1,...,A,\label{eq:bc_error_BAU}\\
0 & = u_{t,j} + \beta  \mathbb{E}_t \left[ v_{t+1,j+1} \right] - v_{t,j} , \quad \forall j \in 1,...,A-1,\label{eq:value_error_BAU}
\end{align}
%
with the initial conditions $\hat{a}_{t,1} = 0$, and the terminal conditions $\hat{a}_{t+1,A+1} = 0$. 
In addition, we use the following definitions:
%
\begin{align}
k_t & = \sum_{j = 1}^{A} \hat{a}_{t,j},  \\
1  & = \sum_{j = 1}^{A} \hat{l}_j ,\\
r_t & =  \Omega_t T^{\mathrm{AT}}_t \alpha k_t^{\alpha-1}  - \delta, \\
w_t & =  \Omega_t T^{\mathrm{AT}}_t (1-\alpha) k_t^{\alpha} , \\
c_{t,j} & =  (1+r_t)\hat{a}_{t,j} + w_{t} \hat{l}_{j} -\hat{a}_{t+1, j+1} ,\\
u_{t,j}  & = c_{t,j}^{1-\sigma}{1-\sigma},\\ 
\sum_{j = 1}^{A} c_{t,j} + \sum_{j = 1}^{A-1} \hat{a}_{t+1,j}  & = \Omega_t T_{t}^{\mathrm{AT}} \left( k_t^{\alpha} \right) + (1- \delta) k_t.
\end{align}
%

%%%%%%%%%%%%%%%%%%%%%%%%%%%%% 
The (normalized) policy function $P(x_t)$ we intend to approximate with the aid of deep neural networks is given by:
%
\begin{equation}
  \mathcal{N}(x_t^{BAU})
  \;=\;
  \bigl[
      \{\hat{a}_{t+1,j+1}, v_{t,j}\}_{j=1}^{A-1}
    \bigr]^{\top}
  \in \mathbb{R}^{2(A-1)}.
  \label{eq:NN_approx_appendix}
\end{equation}
%

Having presented the preceding definitions, we can now specify the individual terms that constitute the loss function used by the DEQN algorithm:
%
\begin{align}
    l_1, ..., l_{11}:= &  \frac{\left(\beta \mathbb{E}_t \left[ (1+r_{t+1}) c_{t+1,j+1}^{-\sigma} \right]\right)^{-1/\sigma}}{c_{t,j}} - 1  \quad \forall j \in \{1,...,11\}, \label{eq:EE_error_BAU_ERROR}\\
l_{12}:= & c_{t,1}+\hat{a}_{t+1, 2} -w_{t} \hat{l}_{1} ,\label{eq:bc_error_BAU_2}\\
l_{13}, ..., l_{22}:= & c_{t,j}+\hat{a}_{t+1, j+1} - (1+r_t)\hat{a}_{t,j} -w_{t} \hat{l}_{j} \quad \forall j \in \{2,...,11\} ,\label{eq:bc_error_BAU_3}\\
l_{23}:= & c_{t,12} - (1+r_t)\hat{a}_{t,12} -w_{t} \hat{l}_{12} ,\label{eq:bc_error_BAU_4}\\
l_{24}, ..., l_{34}:= & \frac{ u_{t,j} + \beta  \mathbb{E}_t \left[ v_{t+1,j+1} \right] }{v_{t,j}}- 1 \quad \forall j \in \{1,...,11\}. \label{eq:value_error_BAU_ERROR}
\end{align}
%
Taken together, these expressions result in the total loss function, that is,
\begin{equation}
    \ell_{\nu}^{BAU} := \frac{1}{N_{\text{path length}}} \sum_{{x}^{BAU}_t \in \text{sim. path}} \sum_{m=1}^{N_{\text{eq}} = 34} \left( \ell_m({x}^{BAU}_t, \mathcal{N}({x}^{BAU}_t) \right)^2.
    \label{eq:total_BAU_LOSS}
\end{equation}
%

The final ingredient required by the DEQN algorithm is the one–step state transition for the BAU economy, which allows the loss
function~\eqref{eq:total_BAU_LOSS} to be evaluated along simulated
trajectories, together with the initial state at \(t=0\)
(cf.\ Section~\ref{sec:DEQN}).  In the BAU SOLG, the forward mapping for the DEQN simulation is given by
%
\begin{equation}
  x_{t+1}^{\text{BAU}}
  =[
      t+1,\,
      TP_{t+1},\,
      TP_{\text{reached},t+1},\,
      \kappa_{t+1},\,
      \{a_{t+1,j}\}_{j=1}^{A},\,
      E_{t+1}
    ]^T.
    \label{eq:Bau_LOM}
\end{equation}
%
All simulations start in the year 2015 (\(t=0\)), so the initial state vector is
\begin{equation}
  \label{eq:x0_display}
  x_0^{BAU}
  =[
      0,\,
      3.0,\,
      0,\,
      0.35032,\,
      \{a_{0,j}\}_{j=1}^{A},\,
      0.851
    ]^T,
\end{equation}
corresponding to
%
\begin{equation}
      [t,\;TP_0,\;TP_{\text{reached},0},\;\kappa_0,\;
    \{a_{0,j}\},\;E_0]^T .
\end{equation}
%
The endogenous state variables are rolled forward according to
%
\begin{align}
  \hat{a}_{t+1,j} &\Rightarrow \hat{a}_{t,j+1}, \\
  k_{t+1}         &\Rightarrow k_t,             \\
  E_{t+1}         &\Rightarrow E_t,             \\
  T_{t+1}^{\mathrm{AT}} &\Rightarrow T_{t}^{\mathrm{AT}},
\end{align}
%
where the ``$\Rightarrow$'' indicates that a choice variable at step $t$ becomes an endogenous state at $t+1$.
The initial asset distribution is obtained from a deterministic simulation without climate change, and provided in Table~\ref{tab:init_assets}.\footnote{The initial asset distribution for our simulations is the non-stochastic steady state derived from a simplified, deterministic version of our BAU model in which temperature and damages are held constant at their $t=0$ levels (see Equation~\eqref{eq:x0_display}).}
