In this supplementary, we present the details of the derivation for the gauge connection $\xi_{{\textbf n} \bar{\textbf z}} $, the velocity field in a single vortex-monopole composite, the interaction between composites,  the equation of motion for vortices, and the numerical method.



\section{The explicit form of $\xi_{\textbf n\bar{\textbf z}} $}
In this section, we determine the gauge connection $\xi_{\textbf n\bar{\textbf z}} $ from the relation $\nabla_s \xi_{\textbf n\bar{\textbf z}} = \textbf{A}_{\textbf n} - \textbf{A}_{\bar{\textbf z}}$ through integration along a special path on the sphere.

First, we consider the path integral along fixed $\phi = \phi_{\textbf n}$:
\begin{equation}
\int_{\phi=\phi_{\textbf n}} (\textbf{A}_{\textbf n} - \textbf{A}_{\bar{\textbf z}})\cdot d\bm \ell = R \int_{\phi=\phi_{\textbf n}} (\textbf{A}_{\textbf n} - \textbf{A}_{\bar{\textbf z}})\cdot \hat{\textbf e}_\theta d\theta,
\end{equation}
Note that
\begin{equation}
\textbf{A}_{\textbf m} \cdot \hat{\textbf e}_\theta \propto {\textbf m \times \textbf r \cdot \hat{\textbf e}_\theta} = {\textbf m \cdot \hat{\textbf e}_\phi} =  -\sin\theta_{\textbf m} \sin(\phi - \phi_{\textbf m}).
\end{equation}
Since $\phi =\phi_{\textbf n}$, we have
\begin{equation}
\textbf{A}_{\textbf n}(\textbf r) \cdot \hat{\textbf e}_\theta {\big |}_{\phi =\phi_{\textbf n}} =0.
\end{equation}
For $\textbf{A}_{\bar{\textbf z}}$, since $\sin\theta_{\bar{\textbf z}} =0$, we have
\begin{equation}
\textbf{A}_{\bar{\textbf z}}(\textbf r) \cdot \hat{\textbf e}_\theta {\big |}_{\phi =\phi_{\textbf n}} =0.
\end{equation}
These results lead to the integral along fixed $\phi = \phi_{\textbf n}$ vanishing.


Next, we consider integrating along a latitude circle with fixed $\theta$. The path integral becomes:
\begin{equation}
\xi_{\textbf n\bar{ \textbf z}} \sim \int_{\phi_{\textbf n}}^\phi (\textbf{A}_{\textbf n} - \textbf{A}_{\bar{\textbf z}})\cdot \hat{\textbf{e}}_\phi ~ R\sin\theta d \phi,
\end{equation}
where
\begin{equation}
(\textbf{A}_{\textbf n} - \textbf{A}_{\bar{\textbf z}})\cdot \hat{\textbf{e}}_\phi = \frac{g\left[\sin\theta_{\textbf n}\cos\theta\cos(\phi - \phi_{\textbf n}) - \cos\theta_{\textbf n}\sin\theta\right]}{R\left[1 - \sin\theta_{\textbf n}\sin\theta\cos(\phi - \phi_{\textbf n})- \cos\theta_{\textbf n}\cos\theta\right]} - \frac{g \sin\theta}{R (1 + \cos\theta)}.
\end{equation}
After careful evaluation, we obtain:
\begin{equation}
\xi_{\textbf n\bar{ \textbf z}} \sim 2g\left[ -\frac{\phi - \phi_{\textbf n}}{2} - \text{Arctan}\left( \frac{\sin\left(\frac{\theta+\theta_{\textbf n}}{2}\right)\sin\left(\frac{\phi-\phi_{\textbf n}}{2}\right)}{\sin\left(\frac{\theta-\theta_{\textbf n}}{2}\right)\cos\left(\frac{\phi-\phi_{\textbf n}}{2}\right)} \right) \right] + \text{const.}
\end{equation}
The explicit transformation to the $\bar{ \textbf z}$-gauge can be written as
\begin{align}\label{connection}
  \xi_{ \textbf n  \bar{ \textbf z}}(\textbf r) &= 2 g \, \text{Arg} \Bigg\{ \exp \left(-i \frac{\phi - \phi_{\textbf n}}{2} \right) \bigg[-\sin \left(\frac{\theta-{\theta_{\textbf n}}}{2}\right) \notag\\
  &\cos \left(\frac{\phi -{\phi_{\textbf n}}}{2}\right) + i \sin \left(\frac{\theta +{\theta_{ \textbf n}}}{2}\right) \sin \left(\frac{\phi -{\phi_{\textbf n}}}{2}\right)\bigg]\Bigg\}.
\end{align}
In our convention, for the north and south pole points, we set $\phi_{\textbf n} = 0$. Then, we have $\xi_{ \bar{\textbf z} \bar{\textbf z}}(\textbf r) =0$ and $\xi_{\textbf z\bar{\textbf z}}(\textbf r) = -2g(\phi+\pi)$, after discarding a multiple of $2\pi$.

\section{The velocity field in a single vortex-monopole composite}

For a general vortex position $R \textbf{n}_v$ on the sphere, the phase in the gauge $\bar{\textbf{n}}_v \equiv -{\textbf{n}}_v$ is given by $\Phi^c_{\bar{\textbf n}_v}(\textbf{r}, \textbf{n}_v) = c \phi'$, where $\phi'$ is the azimuthal angle in a coordinate system with ${\textbf{n}}_v$ as the $z'$-axis. Explicitly,
\begin{eqnarray}
 \phi' &=&  \text{Arg} \left\{ \textbf{r} \cdot [(\textbf{z} \times \textbf{n}_v) \times \textbf{n}_v] + i \textbf{r} \cdot (\textbf{z} \times \textbf{n}_v) \right\} \notag \\
 &=& \text{Arg} \big\{\sin(\theta_v ) \big[\sin (\theta ) \cos (\theta_v) \cos (\phi -\phi_v)-\cos (\theta ) \sin (\theta_v)
 +i \sin (\theta ) \sin (\phi -\phi_v)\big]\big\} \notag \\
&=&
\text{Arg} \big[\sin (\theta ) \cos (\theta_v) \cos (\phi -\phi_v)-\cos (\theta ) \sin (\theta_v)  +i \sin (\theta ) \sin (\phi -\phi_v)\big].
\end{eqnarray}

For the vortex at the north pole, the velocity distribution is \cite{Zheng2025}
\begin{equation}
  \textbf v_c (\textbf{r}; \textbf{z}) = \frac{c}{2 m R}\frac{(1+\cos{\theta})}{ \sin{\theta}}\textbf {e}_\phi,
\end{equation}
To generalize the form to arbitrary vortex position  $R \textbf{n}_v$, we use replacements $\cos\theta = \textbf{n}_v \cdot \hat{\textbf{e}}_r$, $\textbf {e}_\phi = \textbf{n}_v \times \hat{\textbf{e}}_r /\sin \theta$ and $\sin^2\theta = 1- \cos^2\theta = 1-(\textbf{n}_v \cdot \hat{\textbf{e}}_r)^2$. Finally, we have
\begin{equation}
\textbf{v}_c(\textbf{r}; \textbf{n}_v) \equiv \frac{\nabla \Phi^c_{\bar{\textbf n}_v}- \textbf{A}_{\bar{\textbf n}_v}}{m} = \frac{c}{2 m R} \frac{\textbf{n}_v \times \textbf{r}}{R - \textbf{n}_v \cdot \textbf{r}},
\end{equation}


\section{The interaction between composites}

For two composites with velocity fields $\textbf v_{c_1}$ and $\textbf v_{c_2}$, due to the rotational symmetry, we can assume that one vortex is at $(\theta_v^1, \phi_v^1) = (0, 0)$ and the other one at $(\theta_v^2, \phi_v^2) = (\theta_v, 0)$, without loss of generality. From the formula of the velocity, we have the cross term,
\begin{equation}
E_{2v} = {\rho} m R^{2} \int d\Omega  \textbf v_{c_1} \cdot \textbf v_{c_2} = \frac{\rho c_1 c_2}{4m} \int d\Omega  \frac{1+\cos{\theta}}{\sin{\theta}} \frac{\textbf {e}_\phi \cdot (\textbf{n}_v \times \hat{\textbf{e}}_r)}{ 1 -\textbf{n}_v \cdot \hat{\textbf{e}}_r}.
\end{equation}
Using the fact that $\textbf {e}_\phi \cdot (\textbf{n}_v \times \hat{\textbf{e}}_r) = - \textbf {e}_\theta \cdot \textbf{n}_v$, we obtain
\begin{eqnarray}
    E_{2v} = \frac{\rho c_1 c_2}{4m} \int d\theta d\phi \Bigg\{(1+\cos{\theta}) \frac{-\cos\theta\sin\theta_v\cos\phi  + \sin\theta\cos\theta_v}{ 1 - \sin\theta \sin\theta_v \cos\phi - \cos\theta \cos\theta_v } \Bigg\}.
    \end{eqnarray}
Partial integration gives
\begin{equation}\label{x}
 E_{2v} =
      \frac{\rho c_1 c_2}{4m} \Bigg\{\int d\phi \Big[({1+\cos{\theta}}) f(\theta,\phi,\theta_v) \Big]_{\theta=0}^{\theta=\pi} + I_2 \Bigg\},
\end{equation}
where
\begin{eqnarray}
f(\theta,\phi,\theta_v) &=& \ln(1 - \sin\theta \sin\theta_v \cos\phi - \cos\theta \cos\theta_v )  \
\end{eqnarray}
and
\begin{eqnarray}
I_2 &=& \int d\theta d\phi {\sin\theta} f(\theta,\phi,\theta_v)  = \int d\Omega \ln(1-\hat{\textbf{e}}_r \cdot \textbf n_v) .
\end{eqnarray}
Note that the integral $I_2$ does not depend on the orientation of $\textbf n_v$. Therefore, we can set $\textbf n_v = \textbf z$ in the integral $I_2$, and we get $I_2 = \int d\Omega \ln(1-\cos\theta) = 4 \pi (\ln 2-1)$. Directly calculating the first part of \eqref{x}, we finally obtain
\begin{equation}
E_{2v} = -\frac{\pi {\rho} c_1 c_2}{m} \ln(1 -\cos\theta_v) + \frac{ {\rho} c_1 c_2}{4 m} I_2.
\end{equation}
After discarding the constant term $I_2$, we obtain the formula in the main text.


\section{The equation of motion for vortices}
In the $\bar{\textbf z}$-gauge, we define
\begin{equation}
  \psi_{\bar{\textbf z}}(\textbf r)= \hat {\mathcal{R}}_z \hat {\mathcal{R}}_y \exp[i c \phi(\textbf r)] \equiv \exp[i \Phi(\textbf r)] ,
\end{equation}
and
\begin{equation}
   \hat {\mathcal{R}}_z = \exp[-i\hat{L}_{z} (g) \phi_v],~~~~  \hat {\mathcal{R}}_y = \exp[-i\hat{L}_{y} (g) \theta_v],~~~  \hat {\mathcal{R}} = \hat {\mathcal{R}}_z \hat {\mathcal{R}}_y.
\end{equation}
In Dirac notation, $|\psi_{\bar{\textbf z}} ({\textbf{n}_v}) \rangle = \hat {\mathcal{R}} |\psi_{\bar{\textbf z}}(\textbf{z})\rangle  $, where $|\psi_{\bar{\textbf z}}(\textbf{z})\rangle $ is the state with a vortex of winding number $c$ at the north pole. The angular momentum operators satisfy the commutation relations $[\hat L_i,\hat L_j] = i\hbar \epsilon_{ijk} \hat L_k$. Thus, we have
\begin{equation} \label{cccc}
\hat{\mathcal{R}}^\dagger \hat{L}_z \hat{\mathcal{R}} = -\sin\theta_v \hat{L}_x + \cos\theta_v \hat{L}_z, ~~~~ \hat{\mathcal{R}}_y^\dagger \hat{L}_y \hat{\mathcal{R}}_y = \hat{L}_y.
\end{equation}


We consider the wavefunction
\begin{equation}
  \Psi_{\bar{\textbf {z}}}(\textbf{r},t) =  \exp(-i \mathcal{E} t) \sqrt{\rho}  \prod_{j} \big[ \hat{\mathcal{R}}(g_j;\phi_v^j,\theta_v^j) \exp(i c_j \phi)\big],
\end{equation}
where $\hat{\mathcal{R}}(g_j;\theta_v^j,\phi_v^j) = \exp[-i\hat{L}_{z}(g_j) \phi_v^j] \exp[-i\hat{L}_{y}(g_j) \theta_v^j]$ rotates a vortex from the north pole to the real-time position $(\theta_v^j(t),\phi_v^j(t))$.
Note that
\begin{eqnarray}
   R^2 \int d\Omega [i\Psi^*_{\bar{\textbf {z}}} \partial_t \Psi_{\bar{\textbf {z}}}] &=&  \mathcal{E} N + \sum_j R^2 \rho \int d\Omega i \big[\hat{\mathcal{R}}(g_j) \exp(i c_j \phi)\big]^* \partial_t \big[ \hat{\mathcal{R}}(g_j) \exp(i c_j \phi )\big] \notag \\
   &=&  \mathcal{E} N + i N \sum_j  \langle \hat{\mathcal{R}}(g_j)\psi_{\bar{\textbf z}}(\textbf{z}) | \partial_t |\hat{\mathcal{R}}(g_j)\psi_{\bar{\textbf z}}(\textbf{z})\rangle \notag \\
   &=&  \mathcal{E} N + i N \sum_j  \langle \psi_{\bar{\textbf z}}(\textbf{z}) | [ \hat{\mathcal{R}}^\dagger(g_j) \partial_t \hat{\mathcal{R}}(g_j)] |\psi_{\bar{\textbf z}}(\textbf{z})\rangle
\end{eqnarray}
and
\begin{eqnarray}
 i \hat{\mathcal{R}}^\dagger(g_j) \partial_t \hat{\mathcal{R}}(g_j)
    &=& \dot{\phi}_v^j \hat{\mathcal{R}}^\dagger(g_j) \hat{L}_{z} \hat{\mathcal{R}}(g_j)  +  \dot{\theta}_v^j \hat{\mathcal{R}}_y^\dagger(g_j) \hat{L}_{y} \hat{\mathcal{R}}_y(g_j).
\end{eqnarray}
Using Eq.\,\eqref{cccc} and $\langle \psi_{\bar{\textbf z}}(\textbf{z}) | \hat{\textbf {L}}(g_j)|\psi_{\bar{\textbf z}}(\textbf{z})\rangle = \hat{\textbf e}_z c_j/2  $, we have
\begin{eqnarray}
   R^2 \int d\Omega [i\Psi^*_{\bar{\textbf {z}}} \partial_t \Psi_{\bar{\textbf {z}}}] =  \mathcal{E} N +  \frac{N }{2} \sum_j c_j  \dot{\phi}_v^j \cos\theta^j_v.
\end{eqnarray}
As a result,
 \begin{equation}
\mathcal{L} (\theta_v^1,\phi_v^1, \cdots, \dot{\theta}_v^1,\dot{\phi}_v^1, \cdots) = N \sum_i \frac{c_i}{2} \dot{\phi}_v^i\cos\theta_v^i - E_{\text{int}},
\end{equation}
after getting rid of a constant.


Minimizing the action $S = \int \mathcal{L} dt$ leads to
\begin{eqnarray}
- N \frac{c_i}{2} \dot{\phi}_v^i \sin \theta_v^i &=& \frac{\partial E_{\text{int}}}{\partial \theta_v^i} ~=~  \frac{\partial \bm l_i}{ \partial \theta_v^i} \cdot \nabla_{ \bm l_i} E_{\text{int}},  \\
N \frac{c_i}{2}
\dot{\theta}_v^i \sin \theta_v^i &=& \frac{\partial E_{\text{int}}}{\partial \phi_v^i} ~=~ \frac{\partial \bm l_i}{ \partial \phi_v^i}  \cdot \nabla_{ \bm l_i} E_{\text{int}}.
\end{eqnarray}
where $\bm l_ i \equiv c_i \textbf{n}^i_v /2$ and $\textbf{n}^i_v  = (\sin \theta_v^i \cos \phi_v^i, \sin \theta_v^i \sin \phi_v^i, \cos \theta_v^i)$.
Using the differential relation $\dot{\bm l_i} = \dot{\theta}_v^i {\partial \bm l_i}/{\partial \theta_v^i} +\dot{\phi}_v^i {\partial\bm l_i}/{\partial \phi_v^i} $, we finally get the evolution of the `spin' of composite,
\begin{equation}\label{eomx}
\dot{\bm l_i} = \frac{2}{N c_i} \nabla_{ \bm l_i} E_{\text{int}}\times \left[ \frac{\partial\bm l_i}{\partial \theta_v^i} \times \frac{\partial\bm l_i}{\sin\theta_v^i \partial \phi_v^i} \right] =
\bm \omega_i \times \bm l_i,
\end{equation}
where $\bm{\omega}_i \equiv \nabla_{\bm l_i} (E_{\text{int}}/N)$. In the above, we have used the fact that
\begin{equation}
   \frac{\partial \textbf{n}^i_v}{\partial \theta_v^i} \times \frac{\partial \textbf{n}^i_v}{\sin\theta_v^i \partial \phi_v^i} = \textbf{n}^i_v.
\end{equation}


\section{The numerical method}
The covariant Laplacian on a sphere with radius $ R $ in spherical coordinates $(\theta, \phi)$, in the presence of a gauge field $\mathbf{A} = (A_\theta, A_\phi)$, is given by
\begin{equation}
\nabla_A^2 \psi = \frac{1}{R^2 \sin \theta} D_\theta \left( \sin \theta \, D_\theta \psi \right) + \frac{1}{R^2 \sin^2 \theta} D_\phi^2 \psi,
\end{equation}
where $ D_\theta = \partial_\theta - i R A_\theta $ is the covariant derivative in $\theta$ and
 $ D_\phi = \partial_\phi - i R \sin \theta \, A_\phi $ is the covariant derivative in $\phi$. For the $\bar{\textbf z}$-gauge,
\begin{equation}
{A}_\theta (\textbf r)=0,~~~~\text{and}~~~~{A}_\phi (\textbf r)=\frac{g( 1-\cos{\theta})}{R \sin{\theta}}.
\end{equation}
Rewrite the covariant Laplacian using the variable $z =\cos\theta $,
\begin{equation}
\nabla_A^2 \psi = \frac{1}{R^2}\left\{\partial_z\left[(1-z^2)\partial_z\psi\right] + \frac{1}{1-z^2}\left[\partial_\phi - ig(1-z)\right]^2\psi\right\}.
\end{equation}\
The Gross-Pitaevskii equation (GPE) reads
\begin{equation}\label{xxx}
  i \partial_t \psi  = - \frac{1}{2m}\nabla_A^2 \psi + \lambda |\psi|^2\psi.
\end{equation}
Using the split-step method, we develop the Python code to time-evolve the GPE for $z \in [-1, 1]$ and $\phi \in [0, 2 \pi)$. In the numerical simulation, we discretize $z$  in to $N$ points, with  $z_i  =  -1 + (i+1/2) \Delta z$ and $\Delta z = 2/N$, where $i=0,\cdots, N-1$. The endpoints $z =-1$ and $z=1$ are not involved. We use a $256\times256$ grids for $(z,\phi)$ in our simulations.


