Our numerical computations indicate that, when the uniform-density state is unstable, it is so for wavenumbers in a single finite interval, $\text{Re}(s_1) > 0$ for $k\in (k_-,k_+)$ and $\text{Re}(s_1) < 0$ for $k > k_+$ (Fig.~\ref{StabFig1}a in the Main Text). While we do not have a formal proof of this observation, it is supported by numerical computations of the eigenvalues of the matrix $M(k)$. Our computations also indicate that, for $\alpha < \alpha_c(\nu)$, the uniform-density state is stable for all values of $\varrho_0$. An expression for $\alpha_c$ will be given in Eq.~\eqref{Crit1a}. For $\alpha > \alpha_c$, we observe that %$\mathcal{D}$  spans a single finite interval $\varrho_0\in (\varrho_-,\varrho_+)$, 
the boundary of $\mathcal{D}$ is a simple closed curve that may be decomposed into two parts: a single interval on the $\varrho_0$-axis ($k=0$), which we call $\mathcal{B}_0$, and a smooth curve $\mathcal{B}_1$. For $\alpha_c(\nu) < \alpha < \alpha^*(\nu)$, $\mathcal{B}_0$ is an interval $(\varrho_-,\varrho_+)$ and $\mathcal{B}_1$ is given by a single-valued function $k=k_+(\varrho_0)$ (Fig.~\ref{StabFig1}c), so the stability problem exhibits long-wave instabilities ($k_-=0$) for all $\varrho_0\in (\varrho_-,\varrho_+)$. For $\alpha > \alpha^*(\nu)$, $\mathcal{B}_1$ is given by a multi-valued function of $\varrho_0$ (Fig.~\ref{fig:FiniteAmp}), with finite wavelength ($k_->0$) instabilities in an interval $(\varrho_-,\varrho^*)$ and long-wave ones ($k_-=0$) in $(\varrho^*,\varrho_+)$. In Eqs.~\eqref{rhoM} and~\eqref{rhoP}, we obtain asymptotic expressions for the long-wave instability interval $(\varrho^{\text{L}}_-,\varrho^{\text{L}}_+)$ in the limit $\nu\rightarrow 0$, where $\varrho^{\text{L}}_+=\varrho_+$ and $\varrho^{\text{L}}_-=\varrho_-$ ($\varrho^{\text{L}}_-=\varrho^*$) for $\alpha < \alpha^*$ ($\alpha > \alpha^*$). We will also show in \S\ref{App:astar} that $\alpha^*\rightarrow 1+\sqrt{2}$ as $\nu\rightarrow 0$.

We proceed by finding an equation that describes $\mathcal{B}_1$. Defining $s=s_{\text{R}}+\rmi s_{\text{I}}$, $\mathcal{B}_1$ is defined by the solutions to $F(\rmi s_{\text{I}},k)=0$. The real and imaginary parts of this equation are
\begin{subequations}\label{BoundEq}
\begin{align}
a_0-b_1s_{\text{I}}-a_2s_{\text{I}}^2&=0,\label{BoundReal} \\
b_0+a_1s_{\text{I}}-b_2s_{\text{I}}^2-s_{\text{I}}^3&=0,\label{BoundImag}
\end{align}
\end{subequations}
where the real ($a_i$) and imaginary ($b_i$) parts of the functions $f_i(k)$ in Eq.~\eqref{fiFuncs} are
\begin{align}
a_0&=\nu k^2(1+\alpha^2),\quad a_1=-\frac{\varrho_0}{C_0}+2\nu k^2,\quad a_2=2+\varrho_0+\nu k^2,\nonumber \\
b_0&=-k(1+\alpha^2)(1+C_0),\quad b_1=-2k(1+C_0),\quad b_2=-k(1+C_0).\label{aibiCoeffs}
\end{align}
%and $C_0=-\varrho_0/(1+\alpha^2+\varrho_0)$. 
Multiplying Eq.~\eqref{BoundReal} by $s_{\text{I}}$, Eq.~\eqref{BoundImag} by $a_2$ and subtracting the two equations, we obtain
\begin{align}
-a_2b_0+(a_0-a_1a_2)s_{\text{I}}+(a_2b_2-b_1)s_{\text{I}}^2=0.\label{BoundInt}
\end{align}
Using Eq.~\eqref{BoundReal}, the $s_{\text{I}}^2$--term in Eq.~\eqref{BoundInt} can be eliminated:
\begin{align}
\left[(a_0-a_1a_2)a_2-b_1(a_2b_2-b_1)\right]s_{\text{I}}+(a_2b_1-b_1)a_0-a_2^2b_0=0.\label{BoundLin}
\end{align}
The positive solution $s_{\text{I}}$ of Eq.~\eqref{BoundReal} is
\begin{align}
s_{\text{I}}=k\frac{1+C_0+\sqrt{(1+C_0)^2+\nu(1+\alpha^2)(2+\varrho_0+\nu k^2)}}{2+\varrho_0+\nu k^2}.\label{sIsoln}
\end{align}
Substituting Eq.~\eqref{aibiCoeffs} and Eq.~\eqref{sIsoln} into Eq.~\eqref{BoundLin} and canceling out a factor of $k(1+C_0)$, we obtain
\begin{align}
%&\phantom{=}G(k;\varrho_0,\alpha,\nu)\equiv\left\{-\frac{2(1+\alpha^2)^2k^2(\nu k^2+\varrho_0)}{(1+\alpha^2+\varrho_0)^2}+(2+\varrho_0+\nu k^2)\left[(1+\alpha^2)\nu k^2-(2+\varrho_0+\nu k^2)(1+\alpha^2+\varrho_0+2\nu k^2)\right]\right\}\nonumber \\
%&\times\left(\frac{1+\tilde{C}_0+\sqrt{(1+\tilde{C}_0)^2+\nu(1+\alpha^2)(2+\varrho_0+\nu k^2)}}{2+\varrho_0+\nu k^2}\right)+\frac{(1+\alpha^2)^2}{1+\alpha^2+\varrho_0}\left[(2+\varrho_0)^2+\nu k^2(4+\varrho_0)\right]=0\quad\markred{\text{uncancelled red factor}}.\nonumber \\
&\phantom{=}G(k;\varrho_0,\alpha,\nu)\equiv\left\{-\frac{2(1+\alpha^2)^2k^2(\varrho_0+\nu k^2)}{(1+\alpha^2+\varrho_0)^2(2+\varrho_0+\nu k^2)}+(1+\alpha^2)\nu k^2-(2+\varrho_0+\nu k^2)(1+\alpha^2+\varrho_0+2\nu k^2)\right\}\nonumber \\
&\times\left(1+\sqrt{1+\nu\frac{(2+\varrho_0+\nu k^2)(1+\alpha^2+\varrho_0)^2}{1+\alpha^2}}\right)+(1+\alpha^2)\left[(2+\varrho_0)^2+\nu k^2(4+\varrho_0)\right]=0.\label{GBound}
\end{align}
For fixed $\alpha$ and $\nu$, the solution(s) to Eq.~\eqref{GBound} define $\mathcal{B}_1$. Due to the complexity of that equation, we proceed by studying its solutions in two limits: the long-wave limit $k\rightarrow 0$ (\S\ref{App:Long}) and the zero-diffusion limit $\nu=0$ (\S\ref{App:kplus}).

\subsection{Long-wave instabilities}\label{App:Long}


We now deduce the parameter regime in which long-wave instabilities ($k_-=0$) exist. To that end, we evaluate the limit of $G$ in Eq.~\eqref{GBound} as $k\rightarrow 0$:
\begin{align}
%G(0;\varrho_0,\alpha,\nu)=-(2+\varrho_0)(1+\alpha^2+\varrho_0)\left(1+\tilde{C}_0+\sqrt{(1+\tilde{C}_0)^2+\nu(1+\alpha^2)(2+\varrho_0)}\right)+\frac{(1+\alpha^2)^2(2+\varrho_0)^2}{1+\alpha^2+\varrho_0}.\nonumber \\
%G(0;\varrho_0,\alpha,\nu)&=(2+\varrho_0)\left[\frac{(1+\alpha^2)(1+\alpha^2(1+\varrho_0))}{1+\alpha^2+\varrho_0}-(1+\alpha^2+\varrho_0)\sqrt{(1+\tilde{C}_0)^2+\nu(1+\alpha^2)(2+\varrho_0)}\right].\quad\markred{\text{uncancelled red factor}}\nonumber \\
%G(0;\varrho_0,\alpha,\nu)&=(2+\varrho_0)\left[-(1+\alpha^2+\varrho_0)\sqrt{1+\nu\frac{(2+\varrho_0)(1+\alpha^2+\varrho_0)^2}{1+\alpha^2}}+1+\alpha^2(1+\varrho_0)\right]\nonumber \\
&\lim_{k\rightarrow 0}G(k;\varrho_0,\alpha,\nu)=(2+\varrho_0)\left(G_0-G_1\right),\quad\text{where}\quad G_0=1+\alpha^2(1+\varrho_0)\nonumber \\
&\text{and}\quad G_1=(1+\alpha^2+\varrho_0)\sqrt{1+\nu\frac{(2+\varrho_0)(1+\alpha^2+\varrho_0)^2}{1+\alpha^2}}.\label{G0Bound}
\end{align} 
Note that $G_0,G_1 > 0$. Multiplying and dividing by $G_0+G_1$, we obtain
\begin{align}
\lim_{k\rightarrow 0}G(k;\varrho_0,\alpha,\nu)=\frac{(2+\varrho_0)^2}{(1+\alpha^2)(G_0+G_1)}B,\quad
\text{where}\,\,\,\,B(\varrho_0,a,\nu)=\varrho_0(a-2)a^2-\nu(\varrho_0+a)^4\quad\text{and}\quad a=1+\alpha^2.\label{G0Bound2}
\end{align}
Note that $B$ is a quartic polynomial in $\varrho_0$, is negative both as $\varrho_0\rightarrow 0$ and $\varrho_0\rightarrow\infty$, and has a unique local maximum ($\partial B/\partial \varrho_0=0$) at $\varrho_{\text{max}}=\mu^{-1/3}-a$, where  $\mu=4\nu/[(a-2)a^2]$ and $B(\varrho_{\text{max}})=\nu\left(3\mu^{-1/3}-4a\right)/\mu$. Since $B(\varrho_{\text{max}}) > 0$ (and $\varrho_{\text{max}} > 0$) for $\mu < (3/4a)^3$, we conclude that if
\begin{align}
\alpha > \alpha_c\equiv\sqrt{\frac{2}{1-4\nu(4/3)^3}-1},\label{Crit1a}
\end{align}
there exist values $\varrho_0=\varrho_-^{\text{L}}$ and $\varrho_+^{\text{L}}$ with $\varrho_-^{\text{L}}<\varrho_+^{\text{L}}$ for which $\lim_{k\rightarrow 0}G(k;\varrho_0,\alpha,\nu)$ equals zero. We thus conclude that $\mathcal{B}_1$ intersects the horizontal axis ($k=0$) at the values $\varrho_0=\varrho_{\pm}^{\text{L}}$.

To show that $\mathcal{B}_0$ is the interval $(\varrho_-^{\text{L}},\varrho_+^{\text{L}})$, we need to show that $\text{Re}(s_1)>0$ in a neighborhood of $k=0$. %determine the behavior of $s_1(k)$ as $k\rightarrow 0$. 
Differentiating the equation $F(s_1(k),k)=0$ with respect to $k$ yields 
\begin{align}
\partial_sFs_1^{\prime}+\partial_kF=0,\label{Fk}
\end{align}
where primes denote differentiation with respect to $k$. We thus obtain
\begin{align}
s_1^{\prime}(0)=-\frac{\partial_kF(0,0)}{\partial_sF(0,0)}=-\frac{f_0^{\prime}(0)}{f_1(0)}=\rmi\left(\frac{1+\alpha^2}{1+\alpha^2+\varrho_0}\right)^2,
\end{align}
which agrees with Eq.~\eqref{EigLong}. The behavior of $\text{Re}(s_1)$ is deduced by differentiating Eq.~\eqref{Fk} with respect to $k$,
\begin{align}
\partial_sFs_1^{\prime\prime}+\partial_{ss}F(s_1^{\prime})^2+2\partial_{sk}Fs_1^{\prime}+\partial_{kk}F=0,\label{Fkk}
\end{align}
so
\begin{align}
s_1^{\prime\prime}(0)&=-\frac{\partial_{kk}F+2\partial_{sk}Fs_1^{\prime}+\partial_{ss}F(s_1^{\prime})^2}{\partial_sF}=-\frac{f_0^{\prime\prime}(0)+2f_1^{\prime}(0)s_1^{\prime}+2f_2(0)(s_1^{\prime})^2}{f_1(0)}=\frac{2a}{(a+\varrho_0)^5}B,\label{s2Deriv}
%&=-\frac{2\nu(1+\alpha^2)-4\rmi (1+\alpha^2)/(1+\alpha^2+\varrho_0)s^{\prime}+2(2+\varrho_0)(s^{\prime})^2}{1+\alpha^2+\varrho_0}=\frac{2a}{(a+\varrho_0)^5}B
\end{align}
where all derivatives of $F$ are evaluated at $k=0$ and $s=0$ (see Eq.~\eqref{EigLong}), and $B$ was defined in Eq.~\eqref{G0Bound2}. We conclude that, for $\alpha > \alpha_c$ and $\varrho_0\in (\varrho_-^{\text{L}},\varrho_+^{\text{L}}$), $B>0$ so $\text{Re}[s_1^{\prime\prime}(0)]>0$, which in turn implies that $\text{Re}(s_1)>0$ in a neighborhood of $k=0$ because $\text{Re}[s_1(0)]=\text{Re}[s_1^{\prime}(0)]=0$ (Eq.~\eqref{EigLong}). That is, long-wave instabilities ($k_-=0$) exist provided that $\alpha > \alpha_c$ and $\varrho_0\in (\varrho_-^{\text{L}},\varrho_+^{\text{L}}$). In particular, a long-wave instability exists only if $\nu < (1/4)(3/4)^3\approx 0.106$. 
Note that Eq.~\eqref{Crit1a} is precisely the criterion given in Eq.~\eqref{Crit1} in the Main Text.

\subsubsection{Asymptotic expressions for $\rho_{\pm}^{\text{L}}$ in the limit $\nu\rightarrow 0$}\label{App:qLqR}

For a fixed $\nu$ and $\alpha$ satisfying Eq.~\eqref{Crit1a}, the values $\varrho_{\pm}^{\text{L}}$ are given by the two real roots of $B$, for which analytical expressions are cumbersome. We proceed by deriving asymptotic expressions for $\varrho_{\pm}^{\text{L}}$ in the limit $\nu \rightarrow 0$. To that end, we write 
\begin{align}
B = (a-2)a^2D(\sigma,a,\mu)\quad\text{where}\quad D= \sigma-a- \frac{\mu\sigma^4}{4} \quad\text{and}\quad \sigma=a+\varrho_0,
\end{align}
and approximate the roots of $D$ (a quartic polynomial in $\sigma$) in the limit $\mu\rightarrow 0$. Note that $D(\sigma,a,0)$ is a linear function in $\sigma$ with a single root at $\sigma=a$, so the other root of $D$ must go to infinity as $\mu\rightarrow 0$. 

Writing $\sigma=a+\mu\varsigma$, we find that
\begin{align}
D(a+\mu\varsigma,a,\mu)=-\frac{\mu a^4}{4}+(1-\mu a^3)\mu\varsigma+O(\mu^3),
\end{align}
which is $O(\mu^3)$ for $\varsigma=a^4/4(1-\mu a^3)$. We thus find that one root of $D$ may be approximated as %$\sigma=a+\mu a^4/4(1-\mu a^3)+O(\mu^3)$, which is equivalent to
\begin{align}
\sigma=a+\frac{\mu a^4}{4(1-\mu a^3)}+O(\mu^3)\quad\Rightarrow\quad \varrho_-^{\text{L}}=\frac{\nu(1+\alpha^2)^2}{\alpha^2-1-4\nu(1+\alpha^2)}+O(\nu^3).\label{rhoM}
\end{align}
The other real root of $D$, which goes to infinity as $\mu\rightarrow 0$, is obtained by writing $\sigma=(4/\mu)^{1/3}+\varsigma$. Indeed,
\begin{align}
D((4/\mu))^{1/3}+\varsigma,a,\mu)=-a-3\varsigma+O(\mu^{1/3}),
\end{align}
which is $O(\mu^{1/3})$ for $\varsigma=-a/3$. We thus find that the other root of $D$ may be approximated as 
\begin{align}
\sigma=(4/\mu)^{1/3}-a/3+O(\mu^{1/3})\quad\Rightarrow\quad \varrho_+^{\text{L}}=(\alpha^2+1)\left[\left(\frac{\alpha^2-1}{\nu(\alpha^2+1)}\right)^{1/3}-\frac{4}{3}\right]+O(\nu^{1/3}).\label{rhoP}
\end{align}

\subsubsection{Asymptotic expression for $\alpha^*$ in the limit $\nu\rightarrow 0$}\label{App:astar}

We now examine the shape of the upper boundary $\mathcal{B}_1$ of $\mathcal{D}$ for $k\gtrsim 0$ and $\varrho_0\approx \varrho_{\pm}^{\text{L}}$. We restrict our attention to the regime $\nu \ll 1$, for which asymptotic expressions for $\varrho_{\pm}^{\text{L}}$ are available [see Eq.~\eqref{rhoM} and~\eqref{rhoP}]. For fixed $\alpha$ and $\nu$, $\mathcal{B}_1$ is defined by $G(k,\varrho_0,\alpha,\nu)=0$, where $G$ is defined in Eq.~\eqref{GBound}. Differentiating with respect to $k$, we obtain $\partial_kG+\partial_{\varrho_0}G\varrho_0^{\prime}=0$. Since $\partial_kG=0$ at $k=0$, and
\begin{align}
\partial_{\varrho_0}G(0,\varrho_-^{\text{L}},\alpha,\nu)&=2(\alpha^2-1)+O(\nu),\quad
\partial_{\varrho_0}G(0,\varrho_+^{\text{L}},\alpha,\nu)=-\frac{3}{2\alpha^2}\left(\frac{\alpha^2-1}{\alpha^2+1}\right)^{1/3}(\alpha^2-1)(\alpha^2+1)^2\nu^{-1/3}+\dots,
\end{align}
(i.e. $\partial_qG\neq 0$), we conclude that $\varrho_0^{\prime}=0$ at $\varrho_0=\varrho_{\pm}^{\text{L}}$ and $k=0$. That is, $\mathcal{B}_1$ intersects the $\varrho_0$--axis vertically (see Fig.~\ref{StabFig1}c and Fig.~\ref{fig:FiniteAmp}). Differentiating Eq.~\eqref{GBound} twice with respect to $k$, we obtain
\begin{align}
\partial_{kk}G+2\partial_{k\varrho_0}G\varrho_0^{\prime}+\partial_{\varrho_0\varrho_0}G(\varrho_0^{\prime})^2+\partial_{\varrho_0}G\varrho_0^{\prime\prime}=0.\label{G2k}
\end{align}
Evaluating Eq.~\eqref{G2k} at $k=0$ and using the fact that $\varrho_0^{\prime}=0$ there, we obtain the expression $\varrho_0^{\prime\prime}=-\partial_{kk}G/\partial_{\varrho_0}G$ at $k=0$. Using Eqs.~\eqref{rhoM} and~\eqref{rhoP}, we have the following expressions for $\partial_{kk}G$:
\begin{align}
\partial_{kk}G(0,\varrho_-^{\text{L}},\alpha,\nu)=4\nu\frac{\alpha^4-6\alpha^2+1}{\alpha^2-1}+O(\nu^2),\quad
\partial_{kk}G(0,\varrho_+^{\text{L}},\alpha,\nu)=-\frac{(\alpha^2+1)^{5/3}(5\alpha^4-2\alpha^2+1)}{\alpha^2(\alpha^2-1)^{2/3}}\nu^{2/3}+\dots.\label{GkkEq}
\end{align}
That is, $\partial_{kk}G < 0$ at $\varrho_0=\varrho_+^{\text{L}}$, so $\varrho_0^{\prime\prime}<0$ there; that is, $\mathcal{B}_1$ curves to the left at $\varrho_0=\varrho_+^{\text{L}}$ (see Fig.~\ref{StabFig1}c and Fig.~\ref{fig:FiniteAmp}). For $1 < \alpha <\alpha^*$, where $\alpha^*\approx 1+\sqrt{2}$ by Eq.~\eqref{GkkEq}, $\partial_{kk}G<0$ at $\varrho_0=\varrho_-^{\text{L}}$ so $\varrho_0^{\prime\prime} > 0$ there. That is, $\mathcal{B}_1$ curves to the right at $\varrho_0=\varrho_-^{\text{L}}$  for $1 < \alpha < \alpha^*$ (Fig.~\ref{StabFig1}c). However, it curves to left at $\varrho_0=\varrho_-^{\text{L}}$ for $\alpha > \alpha^*$ (Fig.~\ref{fig:FiniteAmp}).

We note that $\alpha^*$ is defined as the value for which $\mathcal{B}_1$ has an inflection point at $k=0$, $\varrho_0=\varrho_-^{\text{L}}$, specifically, 
\begin{align}
\partial_{kk}G(0,\varrho_-^{\text{L}}(\alpha^*,\nu),\alpha^*,\nu)=0,\label{astar}
\end{align}
where $\varrho_0=\varrho_-^{\text{L}}$ is the smaller root of $B$ in Eq.~\eqref{G0Bound2}. The numerical solutions $\alpha^*(\nu)$ of Eq.~\eqref{astar} are shown in Table~\ref{tab:astar}, and they approach $1+\sqrt{2}$ in the limit $\nu\rightarrow 0$, as expected.

