\section{No large wall as an induced minor} \label{no-large-wall} 

The main result of this section is the following lemma:

\begin{lemma} \label{no-wall-im}
    There exists $h_0\in \poi$ such that for all $g,k\in \poi$, the graph $G_k^g$ does not contain $W_{h_0 \times h_0}$ as an induced minor.
\end{lemma}


The proof involves series-parallel graphs, which are exactly the graphs with treewidth at most $2$. The definition given here is adapted from \cite{series-parallel}. A \emph{two-terminal graph} is a graph $G$ where two distinct vertices $s,t \in V(G)$ are designated as the \emph{terminals} of $G$, where $s$ is the \emph{source} and $t$ is the \emph{sink}. If $G$ is a two-terminal graph with source $s$ and sink $t$, and $H$ is a two-terminal graph with source $s'$ and sink $t'$, then the \emph{series-composition of $G$ and $H$} is the two-terminal graph obtained by combining $G$ and $H$ via identifying $t$ and $s'$ into a single vertex (that is, replacing them by a single vertex with neighbor set $N_G(t) \cup N_H(s')$), and declaring $s$ as the source and $t'$ as the sink of the resulting graph. The \emph{parallel-composition of $G$ and $H$} is the two-terminal graph obtained by combining $G$ and $H$ via identifying $s,s'$ into a single vertex and declaring that vertex as the source of the resulting graph, and identifying $t,t'$ into a single vertex and declaring that vertex as the sink of the resulting graph. A two-terminal graph $G$ with source $s$ and sink $t$ is \emph{$(s,t)$-series-parallel} if $G$ can be obtained from copies of $K_2$ via a sequence of series-compositions and parallel-compositions, where each copy of $K_2$ begins with one of its vertices as the source and the other as the sink. A graph $G$ is \emph{series-parallel} if it is a subgraph of some $(s,t)$-series-parallel graph. 


We now return to the proof of Lemma \ref{no-wall-im}. It is a consequence of Lemma 3.6 in \cite{stone-wall} that, for every constant $t > 0$, there is a constant $h_t > 0$ such that every graph containing $W_{h_t \times h_t}$ as an induced minor contains a subdivision of $W_{t \times t}$ or the line graph of a subdivision of $W_{t \times t}$ as an induced subgraph. Recall that for all $g,k\in \poi$, the graph $G_k^g$ is triangle-free, and so does not contain the line graph of a subdivision of any wall. Thus, to show the existence of the desired $h_0$, it suffices to show that $G_k^g$ does not contain a subdivision of a large wall as an induced subgraph. This will be accomplished in Lemma~\ref{no9wall}, but we first need two more lemmas. Our goal is to show that for every induced subgraph of $G_k^g$, if we contract all edges not contained in $P_1, \dots, P_k$ (the vertical edges in Figure \ref{fig:G34}), then the resulting graph is series-parallel. 

\begin{lemma} \label{general-series-parallel}
    Let $F$ be a two-terminal graph with source $s$ and sink $t$, and the following specifications.
    \begin{enumerate}[{\rm (i)}]
        \item There are paths $P_1,\ldots,P_k$ from $s$ to $t$ such that $V(F) = V(P_1) \cup \ldots \cup V(P_k)$ and $V(P_i^*) \cap V(P_j^*) = \varnothing$ for $i \neq j$.
        \item For $1 \leq i \leq k$ and every $v \in P_i^*$, exactly one of the following holds:
        \begin{itemize}
            \item $N_F(v) \setminus V(P_i) = \varnothing$; we let $S'(F)$ denote the set of all vertices in $F$ for which this outcome holds.
            \item $i < k$, the vertex $v$ has exactly one neighbor in $P_j^*$ for every $i < j \leq k$, and $v$ has no other neighbors apart from its neighbors in $P_i$; in this case, we write $N_F'[v] = (N_F(v) \setminus V(P_i)) \cup \{v\}$. We let $B'(F)$ denote the set of all vertices in $F$ for which this outcome holds.
            \item $i > 1$, and $v$ has exactly one neighbor in $P_j^*$ for some $j < i$, and $v$ has no other neighbors outside $P_i$.
        \end{itemize}
        \item Let $v_1,v_2\in B'(F) \cap V(P_i^*)$ be distinct for some $1 \leq i < k$  such that $\dist_{P_i}(s,v_1) < \dist_{P_i}(s,v_2)$. Then for every $i < j \leq k$, we have $\dist_{P_j}(s,u_1) < \dist_{P_j}(s,u_2)$, where $u_1$ is the unique neighbor of $v_1$ in $P_j^*$ and $u_2$ is the unique neighbor of $v_2$ in $P_j^*$.
    \end{enumerate}

    Then the model in $F$ induced by 
    \[ \{ N_F'[v]: v \in B'(F) \} \cup \{\{w\}: w \in S'(F)\} \cup \{\{s\},\{t\}\}, \]
    denoted by $c(F)$, is an $(s,t)$-series-parallel graph.
\end{lemma}

\begin{proof}
    We proceed by induction on $|B'(F)|$. If $|B'(F)| = 0$, then $c(F)$ is isomorphic to $F$ and consists of $k$ pairwise internally anticomplete paths from $s$ to $t$, and so it is $(s,t)$-series-parallel. We now assume that $|B'(F)| > 0$. We may further assume that $P_1$ contains a vertex in $B'(F)$; if this is not the case, then we may apply the argument on $F[V(P_t) \cup \ldots \cup V(P_k)]$, where $t$ is minimal such that $P_t$ contains a vertex in $B'(F)$, and then take the parallel-composition of this graph with $P_1,\ldots,P_{t-1}$ to show that $F$ is $(s,t)$-series-parallel. Now, let $b \in B'(F) \cap V(P_1^*)$ with $\dist_{P_1}(s,b)$ minimal. Since $b$ has a neighbor in each of $P^*_2,\ldots,P^*_k$ in $F$, it follows that $F \setminus N'[b]$ has two components, one containing $s$ and the other containing $t$. Let $C_s$ and $C_t$, respectively, denote these components.

    We now observe that the model $F_s$ in $F$ induced by $\{ \{v\}: v \in V(C_s) \} \cup \{N'[b]\}$ satisfies the requirements of the lemma, with terminals $s$ and $N'[b]$ and the paths from $s$ to $N'[b]$ being the truncated versions of the paths $P_1,\ldots,P_k$. Clearly $B'(F_s) \subseteq B'(F)$; furthermore, this containment is strict, since $b \in B'(F)$, and $b \notin B'(F_s)$ as it is part of the terminal vertex $N_F'[b]$ in $F_s$. By induction, we find that $c(F_s)$ is $(s,N'_F[b])$-series-parallel. Similarly, $c(F_t)$ is $(N_F'[b],t)$-series-parallel, where $F_t$ is the model in $F$ induced by $\{ \{v\}: v \in V(C_t) \} \cup \{N_F'[b]\}$. Since $c(F)$ is the series-composition of $c(F_s)$ and $c(F_t)$, it follows that $c(F)$ is series-parallel.
\end{proof}

\begin{lemma} \label{H'-SP}
    Let $g,k\in \poi$ and let $H$ be an induced subgraph of $G_k^g$. For every vertex $b \in B(G_k^g) \cap V(H)$, let $N_H^M(b) = N_H(b) \cap M(G_k^g)$ and let $N_H^M[b] = N_H^M(b) \cup \{b\}$. Let $B' = \{ N_H^M[b]: b \in B(G_k^g) \cap V(H) \}$ and let $H'$ be the model in $H$ induced by $B' \cup \{\{v\}: v \in V(H), v \notin \bigcup_{Y \in B'} Y\}$; equivalently, $H'$ is obtained from $H$ by contracting every edge $e \in E(H)$ that has both ends in $N_{H}^M[b]$ for some $b \in B(G_k^g) \cap V(H)$. Then $H'$ is series-parallel (in particular, $\tw(H') \leq 2)$.
\end{lemma}

\begin{proof}
    Let $X \subseteq V(G_k^g)$ be such that $H = G_k^g \setminus X$. Put $X_B = X \cap B(G_k^g)$, $X_M = X \cap M(G_k^g)$, and $X_S = X \cap S(G_k^g)$. Let $F$ be obtained from $G_k^g$ by, for each $b \in X_B$, removing every edge incident with $b$ whose other end is in $M(G_k^g)$. Next, we add auxiliary terminal vertices $s$ and $t$ to $F$, where $s$ is incident to $P_\ell^0$ for $1 \leq \ell \leq k$ and $t$ is incident to $P_\ell^{2^{k+g}}$ for $1 \leq \ell \leq k$. Applying Lemma \ref{general-series-parallel} gives that $c(F)$ is $(s,t)$-series-parallel, where $c(F)$ is as defined there. We now show that $H'$ is a subgraph of $c(F)$. We observe that $H'$ can be obtained from $c(F)$ as follows:
    \begin{enumerate}[{\rm (i)}]
        \item Delete $s$ and $t$.
        \item For $v \in X_S$, delete the vertex $\{v\}$ from $c(F)$.
        \item For $m \in X_M$, let $b$ be the unique neighbor (in $G_k^g$) of $m$ in $B(G_k^g)$, and let $s_1$ and $s_2$ be the two neighbors of $m$ in $S(G_k^g)$.
        \begin{itemize}
            \item If $b \in X_B$, delete $\{m\}$ from $c(F)$ (since $b \in X_B$, there is no edge between $b$ and $m$ in $F$, and so $\{ m \}$ is a vertex of $c(F)$).
            \item If $b \notin X_B$, there is a vertex $S$ in $c(F)$ such that $b,m \in S$. If $s_1 \notin X_S$, delete the edge between $v$ and $\{s_1\}$ in $c(F)$. Similarly, if $s_2 \notin X_S$, delete the edge between $v$ and $\{s_2\}$ in $c(F)$.
        \end{itemize}
        \item For $b \in X_B$, delete $\{b\}$ from $c(F)$.
    \end{enumerate}
    Thus $H'$ is a subgraph of the series-parallel graph $c(F)$, and so $H'$ is series-parallel.
\end{proof}

\begin{lemma}\label{no9wall}
    For all $g,k\in \poi$, the graph $G_k^g$ has no induced subgraph isomorphic to a subdivision of $W_{5 \times 5}$.
\end{lemma}

\begin{proof}
Suppose that $H$ is an induced subgraph of $G_k^g$ that is isomorphic to a subdivision of $W_{5 \times 5}$. Say a vertex $v \in V(H)$ is a \emph{branch vertex} of $H$ if $v$ is also a vertex of $W_{5 \times 5}$; that is, $v$ is not a vertex that was created in the subdivision process. Let $H'$ be as defined in Lemma \ref{H'-SP}, and for each vertex $u$ of $H$, let $p(u)$ be the unique vertex of $H'$ such that $u \in p(u)$. We show that $H'$ contains a subdivision of $W_{3 \times 3}$. To see this, let $J$ be a subdivision of $W_{3 \times 3}$ in $H$ such that every two branch vertices of $J$ have distance at least 3 in $J$ (see Figure \ref{fig:5x5wall}). Since $p(u) = p(v)$ can only hold if $u$ and $v$ have distance at most two in $H$, it follows that no two distinct branch vertices of $J$ are mapped to the same vertex in $H'$; thus $H'$ contains a subdivision of $W_{3 \times 3}$. But now $\tw(H')>2$, a contradiction to Lemma~\ref{H'-SP}.
\end{proof}

\section{No Large Complete Bipartite Induced Minor}

In this section we prove the following result:

\begin{lemma} \label{no-bipartite-im}
    There exists $r_0\in \poi$ such that for all $g,k\in \poi$, the graph $G_k^g$ does not contain $K_{r_0,r_0}$ as an induced minor.
\end{lemma}

We need to prepare for the proof. A graph $T$ is a \emph{wide theta of width $m$} if for some distinct vertices $a,b \in V(T)$ (called the \emph{ends} of $T$), there are $m$ pairwise internally anticomplete paths $P_1,\ldots,P_m$ from $a$ to $b$ in $T$, each of length at least $2$, and $T$ has no other vertices or edges. The following is an immediate corollary of 1.3 in \cite{complete-bipartite-minors}:

\begin{lemma}[Chudnovsky, Hajebi, Spirkl \cite{complete-bipartite-minors}]\label{complete-induced-minor}
    For all $h\in \poi$, there exists $r = r(h)\in \poi$ such that if $G$ does not contain a wide theta of width $8$ as an induced subgraph or $W_{h \times h}$ as an induced minor, then $G$ does not contain $K_{r,r}$ as an induced minor.
\end{lemma}

Accordingly, in what follows, we will show that for all $g,k\in \poi$ and every pair of distinct vertices $u,v \in G_k^g$, there can be at most $7$ pairwise internally anticomplete paths between $u$ and $v$ in $G_k^g$. This will be achieved in Corollary \ref{leq-seven-paths}, which, combined with Lemmas \ref{no-wall-im} and \ref{complete-induced-minor}, gives a proof of Lemma \ref{no-bipartite-im}. We remark that through further casework the proof shown here can be extended to obtain a bound of at most $3$ paths, which is tight.

Note that for all $g,k\in \poi$ and every pair of distinct vertices $u,v \in V(G_k^g)$, there can be at most $\min\{ \deg_{G_k^g}(u),\deg_{G_k^g}(v) \}$ pairwise internally anticomplete paths between $u$ and $v$ in $G_k^g$. In particular, if $u$ and $v$ are not both in $B(G_k^g)$, there can be no more than $3$ pairwise internally anticomplete paths between the two. Thus, we need only consider paths between two big vertices in $G_k^g$. We recall the notation used in defining $G_k^g$. Suppose $b_1 = P_{\ell_1}^{x_1} \in B(G_k^g)$ and $b_2 = P_{\ell_2}^{x_2} \in B(G_k^g)$ are two distinct vertices of $G_k^g$; by the symmetry of $G_k^g$, we may assume that $\ell_1 \leq \ell_2$ and $x_1 < x_2$. If $R$ is a path from $b_1$ to $b_2$ in $G_k^g$, we say that \emph{$R$ switches layers at $x$, from $\ell$ to $\ell'$}, if $E(R)$ contains an edge with ends $P_\ell^x$ and $P_{\ell'}^x$. We emphasize that if a path switches layers at $x$ then it contains a big vertex with index $x$.

Suppose $\mathcal{R}$ is a set of paths from $b_1$ to $b_2$ that are pairwise internally anticomplete. For $R \in \mathcal{R}$, let $R^-$ denote the unique neighbor of $b_1$ in $R$ and by $R^+$ the unique neighbor of $b_2$ in $R$. We say that a path $R \in \mathcal{R}$ is \emph{standard} if $R^- = P_{\ell_1'}^{x_1}$ for some $\ell_1' > \ell_1$ and $R^+ = P_{\ell_2'}^{x_2}$ for some $\ell_2' > \ell_2$. Otherwise, we say that $R$ is \emph{nonstandard}. Note that $\mathcal{R}$ can include at most $4$ nonstandard paths, since every nonstandard path uses either an edge of $P_{\ell_1}$ incident with $P_{\ell_1}^{x_1}$ or an edge of $P_{\ell_2}$ incident with $P_{\ell_2}^{x_2}$, and there are only four such edges. In what follows, we show that there may be at most $3$ standard paths in $\mathcal{R}$. 

Let $\mathcal{R}' = \{R^*: R \text{ is a standard path in } \mathcal{R}\}$. For $R^* \in \mathcal{R}'$, say $R$ is an \emph{overpass} if, for some $1 \leq \ell \leq k$, $V(P_\ell[x_1:x_2]) \subseteq V(R^*)$ and $P_\ell[x_1:x_2] \cap B(G_k^g) = \varnothing$. For ease of notation, we will also say that $R^*$ is (or is not) an overpass to mean that $R$ is (or is not) an overpass.

\begin{lemma}
    There is at most one $R^* \in \mathcal{R}'$ that is not an overpass.
\end{lemma}

\begin{proof} \label{non-overpass}
    For $R^* \in \mathcal{R}'$, say $v \in V(R^*)$ is an \emph{internal big vertex of $R^*$} if $v \in B(G_k^g)$ and $b$ has index greater than $x_1$ and smaller than $x_2$.

    We first show that if $R^* \in \mathcal{R}'$ is not an overpass, then contains some internal big vertex $b = P_\ell^x$. Indeed, for each $x_1 \leq x' \leq x_2$, $R^*$ includes a vertex $P_{\ell'}^{x'}$ for some $1 \leq \ell' \leq k$. If, for some $\ell'$, $R^*$ contains all of $P_{\ell'}[x_1:x_2]$, then one of the vertices of $P_{\ell'}[x_1:x_2]$ is a big vertex as otherwise $R^*$ would be an overpass. On the other hand, if there is no $\ell'$ such that $R^*$ contains $P_{\ell'}^{x'}$ for all $x_1 \leq x' \leq x_2$, then $R^*$ switches layers at some index $x$ that is strictly between $x_1$ and $x_2$, and so $R^*$ contains a big vertex with index $x$.

    Now assume that there is at least one element of $\mathcal{R}'$ that is not an overpass; let $b = P_{\ell_0}^{x_0}$ be a big vertex contained in some non-overpass of $\mathcal{R}'$ such that $x_1 < x_0 < x_2$ and $\ell_0$ is minimal. Let $R_0^*$ be the element of $\mathcal{R}'$ containing $b$, and suppose there is some other $R^* \in \mathcal{R}'$ that is not an overpass. $R^*$ contains some vertex with index $x_0$, say $v = P_{\ell}^{x_0}$. It follows that $\ell < \ell_0$, as otherwise $b$ and $v$ would be adjacent or equal. Note that $v$ is a small vertex as $b$ is a big vertex and $v$ has strictly smaller layer than $b$. Thus, there is some index $x'$ such that $R^*$ switches layers to $\ell$ at $x'$ and such that $P_\ell[x',x_0]$ is contained in the subpath of $R^*$ from $R^-$ to $v$. It follows that $R^*$ includes a big vertex with layer at most $\ell$ and index $x'$. By the choice of $b$ and the fact that $\ell < \ell_0$, we deduce that either $x' < x_1$ or $x' > x_2$. The two cases are analogous; we show in detail how to handle the case where $x' < x_1$.

    We now show that $R^*$ contains $P_\ell[x_0:x_2]$ (and thus all of $P_\ell[x_1:x_2]$). Indeed, suppose this is not the case, and let $x''$ be maximal such that $P_\ell[x_0:x'']$ is contained in $R^*$, where $x_0 \leq x'' < x_2$. Since $R^*$ does not contain $P_\ell^{x'' + 1}$, $R^*$ switches layers at index $x''$ from $\ell$ to some other layer, and thus $R^*$ contains a big vertex of index at most $\ell$. But $\ell < \ell_0$ and $x_1 < x'' < x_2$, so this contradicts the choice of $b$.
\end{proof}

\begin{lemma} \label{leq-2-overpasses}
    $\mathcal{R}'$ contains at most two overpasses.
\end{lemma}

\begin{proof}
     For every overpass $R^* \in \mathcal{R}'$, there is some $\ell \leq \ell_1$ such that $P_\ell^x \in V(R^*)$ for all $x_1 \leq x \leq x_2$, and none of these vertices are big. Furthermore, by the construction of $G_k^g$ and the fact that $R^*$ is a standard path, we have $\ell < \ell_1$. It follows that $R^*$ contains a big vertex $b = P^{x_0}_{\ell'}$ for some $\ell' < \ell$, where $x_0 < x_1$.

    Now suppose that $R_\alpha^*$ and $R_\beta^*$ are two distinct elements of $\mathcal{R}'$. Let $b_\alpha = P_{\ell_\alpha}^{x_\alpha}$ be the big vertex in $R_\alpha^*$ with minimal distance to $R_\alpha^-$ in $R_\alpha^*$, subject to the condition $\ell_\alpha < \ell_1$. Similarly, let $b_\beta = P_{\ell_\beta}^{x_\beta}$ be the big vertex in $R_\beta^*$ with minimal distance to $R_\beta^-$ in $R_\beta^*$, subject to the condition $\ell_\beta < \ell_1$.

    We now show that either $x_\alpha < x_1 < x_\beta$ or $x_\beta < x_1 < x_\alpha$ holds. Suppose instead that both $x_\alpha < x_1$ and $x_\beta < x_1$ are true (the case where both are greater than $x_1$ is analagous). Without loss of generality, we assume that $x_\alpha > x_\beta$. Then the subpath of $R_\beta^*$ from $R_\beta^-$ to $b_\beta$ contains some vertex $v$ with index $x_\alpha$ and layer strictly larger than $\ell_\alpha$. But then $b_\alpha$ and $v$ are adjacent, which is a contradiction.

    Now suppose that $\mathcal{R}'$ contains three or more overpasses. Then there exist $R_\alpha^*, R_\beta^* \in \mathcal{R}'$ such that either $x_\alpha < x_1$ and $x_\beta < x_1$ or $x_\alpha > x_1$ and $x_\beta > x_1$, contrary to the claim of the previous paragraph. Thus, $\mathcal{R}'$ contains at most two overpasses.
\end{proof}

\begin{corollary} \label{leq-seven-paths}
    $|\mathcal{R}| \leq 7$.
\end{corollary}

\begin{proof}
    $\mathcal{R}$ contains at most $4$ nonstandard paths. Of the standard paths in $\mathcal{R}$, there are at most $2$ overpasses by Lemma \ref{leq-2-overpasses}, and at most $1$ non-overpass by Lemma \ref{non-overpass}. Thus, there are at most $7$ paths in $\mathcal{R}$.
\end{proof}


\section{No outerstring induced subgraph of large treewidth}

In this section, we prove that:

\begin{lemma} \label{outerstring-isg-bound}
    There exists $L\in \poi$ such that for all $g,k\in \poi$, every induced subgraph $H$ of $G_k^g$ that is an outerstring graph satisfies $\tw(H) \leq L$.
\end{lemma}

We need several results from the literature. Let $G$ be a graph and let $w: V(G) \to [0,1]$. For $X \subseteq V(G)$, we write $w(X)=\sum_{x \in X} w(x)$, and for a subgraph $H$ of $G$ (not necessarily induced), we write $w(H)$ for $\sum_{x \in V(H)} w(x)$. We say that $w$ is a \emph{weight function on $G$} if $w(G) = 1$, and a \textit{weak weight function on $G$} if $w(G) \leq 1$ (so all weight functions are weak weight functions). A set $X \subseteq V(G)$ is a \emph{$w$-balanced separator in $G$} if $w(D) \leq \frac{1}{2}$ for every component $D$ of $G \setminus X$. Treewidth and balanced separators are closely related through the following lemmas.

\begin{lemma}[\cite{wallpaper, induced-subgraphs-5,params-tied-to-tw, RS-GMII}]
\label{sep-to-tw}
    Let $m\in \poi$ and let $G$ be a graph such that for every weight function $w$ on $G$, there is a $w$-balanced separator $X_w$ in $G$ with $|X_w| \leq m$. Then $\tw(G) \leq 2m$.
\end{lemma}

\begin{lemma}[\cite{induced-subgraphs-5, cygan, RS-GMII}]
\label{tw-to-sep}
     For every graph $G$ and every weak weight function $w$ on $G$, there is a $w$-balanced separator in $G$ of size at most $\tw(G)+1$.
\end{lemma}

We also need the following:

\begin{theorem}[Korhonen \cite{grid-induced-minor-theorem}] \label{bound-no-wall-isg}
    For all $d,t\in \poi$, there exists $L\in \poi$ such that if $G$ is graph of maximum degree at most $d$ that does not contain any subdivision of $W_{t \times t}$ or the line graph of any subdivision of $W_{t \times t}$ as an induced subgraph, then $\tw(G)\leq L$.
\end{theorem}


A \textit{theta} is a graph $T$ consisting of two non-adjacent vertices $a$ and $b$ and three internally anticomplete paths $P_1$, $P_2,$ and $P_3$ from $a$ to $b$, each of length at least $2$, and no other vertices or edges. We call $a$ and $b$ the \emph{ends of $T$}, and the \emph{length of $T$} is $\dist_T(a,b)$. We say that $T$ is an \emph{$\ell$-long theta} if its length is at least $\ell$. 

Next, we recall a result implicit in \cite{polygon-visibility-graphs}, that $\ell$-long thetas are not outerstring graphs for $\ell \geq 4$. Since the class of outerstring graphs is hereditary, it follows that every graph containing an
$\ell$-long theta for $\ell \geq 4$  as an induced subgraph is also not an outerstring graph. This will be the main tool in the proof that every induced subgraph of our construction either has small treewidth or is not an outerstring graph.

Let $G$ be a graph and let $\prec$ be a linear order on $V(G)$. For $X \subseteq V(G)$, we denote by $\prec_X$ the restriction of $\prec$ to the set $X$. We say that the outerstring representation of $G$ is a \emph{$\prec$-constrained} if for all $u,v \in V(G)$, we have $u \prec v$ if and only if the point at which the curve corresponding to $u$ intersects the $x$-axis is to the left of the point at which the curve corresponding to $v$ intersects the $x$-axis. It follows that, for every $X\subseteq V(G)$, the set of all curves in the representation corresponding to the vertices in $X$ forms a $\prec_X$-constrained outerstring representation of $G[X]$. In particular:

\begin{lemma} \label{non-outerstring-criteria}
    Let $G$ be a graph. Assume that for every linear order $\prec$ on $V(G)$, there exists $X \subseteq V(G)$ such that $G[X]$ admits no $\prec_X$-constrained outerstring representation. Then $G$ is not an outerstring graph.
\end{lemma}

The following is implicit in \cite{polygon-visibility-graphs}.
\begin{lemma} \label{long-theta}
    $\ell$-long thetas are not outerstring graphs for all $\ell \geq 4$.
\end{lemma}

\begin{proof}
    Let $T$ be an $\ell$-long theta for some $\ell \geq 4$. In Proposition 6.2 of \cite{polygon-visibility-graphs}, it is shown that for every linear order $\prec$ on $V(T)$, there exists a $4$-subset $X = \{x_1,x_2,x_3,x_4\}$ of vertices such that $x_1 \prec x_2 \prec x_3 \prec x_4$ and $E(T[W]) = \{x_1x_3,x_2x_4\}$. Clearly, this means there is no $\prec_X$-constrained outerstring representation of $T[X]$. Hence, by Lemma~\ref{non-outerstring-criteria}, the graph $T$ is not an outerstring graph.
\end{proof}


In view of Lemmas~\ref{sep-to-tw} and (\ref{long-theta}), in order to prove Lemma \ref{outerstring-isg-bound}, it suffices to show that for every induced subgraph $H$ of $G^g_k$ with no induced long theta and every weight function $w$, there is a small $w$-balanced separator in $H$. We do this by finding small balanced separators with respect to certain weight functions on certain induced minors of $H$, which can then be translated back into a small $w$-balanced separator in $H$.

To this end, we fix $g,k\in \poi$ and put $G = G_k^g$, $B = B(G)$, $M = M(G)$, and $S = S(G)$. Let $H$ be an induced subgraph of $G$, and let $w$ be a weight function on $H$. Let $B_H = B \cap V(H), M_H = M \cap V(H),$ and $S_H = S \cap V(H)$. $H$ inherits from $G$ the properties (\ref{props-2}),(\ref{props-3}), (\ref{props-4}), and (\ref{props-5}) from Lemma \ref{props}, which are restated here:

\begin{lemma}\label{props-H} The following hold.

    \begin{enumerate}[{\rm (i)}]
        \item \label{props-H-1} $H$ is triangle-free.
        \item \label{props-H-2} If $u,v \in V(H)$ are adjacent, then $\deg_H(u) \leq 3$ or $\deg_H(v) \leq 3$, and $\{u,v\} \nsubseteq B_H$.
        \item \label{props-H-3} If $u,v \in B_H$ with $u \neq v$, then $\dist_{G_k^g}(u,v) \geq 2^g$.
        \item \label{props-H-4} If $u \in V(G_k^g)$ and $\deg_{G_k^g}(u) = 3$, then there is at most one $v \in N_{G_k^g}(u)$ with $\deg_{G_k^g}(v) \geq 3$.
    \end{enumerate}
\end{lemma}

For $b \in B$, let $N_H^M(b) = N_H(b) \cap M$ and $N_H^M[b] = N_H^M(b) \cup \{b\}$. Put $B_{H'} = \{N_H^M[b]: b \in B_H\}$, $M_{H'} = \{\{m\}: m \in M_H, m \notin \bigcup_{X \in B_{H'}}X\}$, and $S_{H'} = \{\{s\}: s \in S_H\}$. Let $H'$ be the model in $H$ induced by $B_{H'} \cup M_{H'} \cup S_{H'}$, and define $w': V(H') \to [0,1]$ by $w'(S) = \sum_{v \in S} w(v)$ for $S \in V(H')$. It is easy to see that $w'$ is a weight function on $H'$. We note also that every element of $B_{H'}$ is uniquely identified by a vertex of $B_H$, and every element of $M_{H'}$ or $S_{H'}$ is uniquely identified by a vertex of $M_H$ or $S_H$, respectively.

\begin{lemma} \label{props-H'} The following hold.
    \begin{enumerate}[{\rm (i)}]
        \item \label{props-H'-1} $\deg_{H'}(v) \leq 2$ for every $v \in M_{H'} \cup S_{H'}$.
        \item \label{props-H'-2} $\dist_{H'}(u_1,u_2) \geq 2^g/3-2$ for all pairs of distinct $u_1,u_2 \in B_{H'}$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    If $v = \{s\} \in S_{H'}$, then $\deg_G(s) \leq 2$, so $\deg_H(s) \leq 2$ and thus $\deg_{H'}(\{s\}) \leq 2$. Next suppose that $v = \{m\} \in M_{H'}$, then $\deg_G(m) = 3$ and $N_G(m) = \{b,s_1,s_2\}$ for some $b \in B$ and $s_1,s_2 \in S$. Since $m$ and $b$ are adjacent in $G$, $b$ cannot be a vertex of $H$, as then $v$ would be an element of $N_H^M[b]$. Thus, $\deg_{H'}(\{m\}) \leq 2$. This proves Statement (\ref{props-H'-1}). Statement (\ref{props-H'-2}) follows from Lemma \ref{props-H} (\ref{props-H-3}) and the observation that a path of length $d$ from $u_1$ to $u_2$ in $H'$ gives rise to a path of length at least $3(d+2)$ in $H$. 
\end{proof}

Note that $H'$ here is defined analogously to Section \ref{no-large-wall}, and so by Lemma~\ref{H'-SP}, we have $\tw(H') \leq 2$. It follows from Lemma \ref{tw-to-sep} that there is a $w'$-balanced separator $K' \subseteq V(H')$ for $H'$ of size at most $3$. It is straightforward to see that taking $K = \bigcup_{X \in K'} X$  gives a $w$-balanced separator in $H$. However, there is no bound on the size of the sets $X$, as each big vertex of $G$ can have up to $k$ medium neighbors, and our desired bound needs to be independent of $k$.

To remove this dependence on $k$, we now define a new induced minor of $H$ related to $H'$ and $K'$. First, we partition $K'$ by defining the following sets:
\begin{align*}
    & Y'_{B,>3} = \{ b \in B_H: N_H^M[b] \in K', \deg_H(b) > 3 \}, \\
    & Y'_{B, \leq 3} = \{ b \in B_H: N_H^M[b] \in K', \deg_H(b) \leq 3 \}, \\
    & K'_{B,>3} = \{N_H^M[b]: b \in Y'_{B,>3}\}, \\
    & K'_{B,\leq 3} = \{N_H^M[b]: b \in Y'_{B,\leq 3}\}, \\
    & K'_M = K' \cap M_{H'}, \\
    & K'_S = K' \cap S_{H'}.
\end{align*}
Note that $K' = K'_{B,>3} \cup K'_{B,\leq 3} \cup K'_M \cup K'_S$ and all of these subsets are pairwise disjoint. The set $K'_{B,>3}$ comprises ``troublesome'' vertices of $K'$ in the sense that they are the vertices preventing $\bigcup_{S \in K'} S$ from having bounded size. 

Let $\mathcal{N} = \bigcup_{b \in Y'_{B,>3}} \{\{n\}: n \in N_H^M(b)\}$ and $\mathcal{D} = \{\bigcup_{X \in V(D)} X: D \text{ is a component of } H' \setminus K' \}$. Let $H''$ be the model in $H$ induced by $\mathcal{N} \cup \mathcal{D}$; it is straightforward to see that $H''$ is a bipartite graph with bipartition $(\mathcal{N},\mathcal{D})$. Define $w'': V(H'') \to [0,1]$ by $w''(S) = \sum_{v \in S} w(v)$ for $S \in V(H'')$. Since $\bigcup_{S \in V(H'')} S \subseteq V(H)$, $w''$ is a weak weight function on $H''$. To bound the treewidth of $H''$, we need the following lemma:

\begin{lemma}[\cite{wallpaper, submodular-functions}] \label{three-vertices}
    Let $T$ be a graph that does not contain $K_3$ as a subgraph. Let $v_1,v_2,v_3$ be distinct vertices of $T$, and assume that $F$ is a connected induced subgraph of $T \setminus \{v_1,v_2,v_3\}$ such that $V(F)$ contains at least one neighbor of each of $x_1,x_2,x_3$, and that $V(F)$ is minimal subject to inclusion. Then, one of the following holds:

    \begin{enumerate}[{\rm (i)}]
        \item \label{three-vertices-1} For some $\{i,j,k\} = \{1,2,3\}$, there exists $P$ that is either a path from $x_i$ to $x_j$ or a hole containing the edge $x_ix_j$ such that
        \begin{itemize}
            \item $V(F) = V(P) \setminus \{x_i,x_j\}$, and
            \item $x_k$ has at least two non-adjacent neighbors in $F$.
        \end{itemize}
        \item \label{three-vertices-2} There is a vertex $a \in V(F)$ and three paths $P_1,P_2,P_3$, where $P_i$ is from $a$ to $x_i$, such that
        \begin{itemize}
            \item $V(F) = (V(P_1) \cup V(P_2) \cup V(P_3)) \setminus \{x_1,x_2,x_3\}$, and
            \item the sets $V(P_1) \setminus \{a\}, V(P_2) \setminus \{a\}$, and $V(P_3) \setminus \{a\}$ are pairwise disjoint, and
            \item for distinct $i,j \in \{1,2,3\}$, there are no edges between $V(P_i)$ and $V(P_j)$ except possibly $x_ix_j$.
        \end{itemize}
    \end{enumerate}

\end{lemma}

