\begin{lemma} \label{H''-bounded-degree}
    At least one of the following holds.
    \begin{enumerate}[(i)]
        \item \label{H''-bound} $H''$ has maximum degree less than $9$.
        \item \label{long-theta-outcome} $H$ contains an $\ell$-long theta as an induced subgraph, for some $\ell \geq 2^g-1$.
    \end{enumerate}
    In particular, if $H$ is an outerstring graph, then Statement (\ref{H''-bound}) holds.
\end{lemma}

\begin{proof}
    Suppose that Statement (\ref{H''-bound}) does not hold. For $\{n\} \in \mathcal{N}$, we have $n \in M_H$ by construction, so $\deg_H(n) \leq 3$ and thus $\deg_{H''}(\{n\}) \leq 3$. This means that there is some $D \in \mathcal{D}$ with $\deg_{H''}(D) \geq 9$. Since $|K'_{B,>3}| \leq |K'| = 3$, there is $b \in Y'_{B,>3}$ such that there are at least $3$ edges of $H''$ with one end $D$ and the other end in $\{\{n\}: n \in N_H^M(b)\}$. It follows that there exist distinct $n_1,n_2,n_3 \in N_H^M(b)$ such that $N_{H}(n_i) \cap D \neq \varnothing$ for every $i \in \{1,2,3\}$.

    Let $X \subseteq D$ be minimal (with respect to inclusion) such that $H[X]$ is connected and contains at least one neighbor of each of $n_1,n_2,n_3$. We now apply Lemma \ref{three-vertices} with $n_1,n_2,n_3$ and $H[X]$.

    Suppose that case (\ref{three-vertices-1}) applies; let $\{i,j,k\} = \{1,2,3\}$ and $P$ be such that $P$ is a path in $H$ from $n_i$ to $n_j$, $n_k$ has at least two non-adjacent neighbors in $P$, and $V(H[X]) = V(P) \setminus \{n_i, n_j\}$. Note that $P$ is not a hole since $n_i$ and $n_j$ are both adjacent to $b$, thus they are not adjacent to each other. Since $n_k$ is adjacent to $b$ in $H$, $n_k$ is a medium vertex, thus $\deg_H(n_k) = 3$. Furthermore, every neighbor of $n_k$ in $P$ (of which there are at least $2$) has degree at least $3$ in $H$. This contradicts Lemma \ref{props-H} (\ref{props-H-4}).

    Suppose instead that case (\ref{three-vertices-2}) applies; let $a \in X$ and $P_1,P_2,P_3$ be such that $P_i$ is a path from $a$ to $n_i$ for each $i \in \{1,2,3\}$, and $X = (V(P_1) \cup V(P_2) \cup V(P_3)) \setminus \{n_1,n_2,n_3\}$, and the sets $V(P_1) \setminus \{a\}$, $V(P_2) \setminus \{a\}$, and $V(P_3) \setminus \{a\}$ are pairwise anticomplete. Note that $\dist_H(a, b) \geq 2^g-1$; this follows from Lemma \ref{props-H} \eqref{props-H-3} as $b \in B(G)$ and $a \in V(D) \subseteq G \setminus N[b]$ and $a$ has degree at least 3 in $G$; so either $a \in B(G)$ and \eqref{props-H-3} applies, or $a$ is adjacent to a vertex $a'$ in $B(G) \setminus \{b\}$ and the statement follows from \eqref{props-H-3} applied to $a'$ and $b$. 

    We now have that $H[V(P_1) \cup V(P_2) \cup V(P_3) \cup \{a,b\}]$ is an induced subgraph of $H$ that is a theta of length at least $2^g-1$, so Statement (\ref{long-theta-outcome}) holds.

    % Write $P_A = p_{i_A}^{A''} \dd a_1 \dd \ldots a_m \dd p_{j_A}^{A''}$. Let $a_{{\rm min}}$ and $a_{{\rm max}}$ be the $a_\alpha$ with minimum and maximum $\alpha$, respectively, subject to being adjacent to $p_{k_A}^{A''}$. Let $a = p_{k_A}^{A''}$, and let $P_{i_A}^a = p_{k_A}^{A''} \dd a_{{\rm min}} \dd \cdots \dd a_1 \dd p_{i_A}^{A''}$ and $P_{j_A}^a = p_{k_A}^{A''} \dd a_{{\rm max}} \dd \cdots \dd a_m \dd p_{j_A}^{A''}$. Let $P_{k_A}^a$ be the graph whose only vertex is $p_{k_A}^{A''}$.

    % If case (\ref{three-vertices-2}) applies, let $a \in A$ and $P_1^a, P_2^a$, and $P_3^a$ be such that
    % \begin{itemize}
    %     \item $P_t^a$ is a path from $a$ to $p_t^{A''}$ for each $t \in \{1,2,3\}$, and
    %     \item $A = (V(P_1^{A''}) \cup V(P_2^{A''}) \cup V(P_3^{A''})) \setminus \{p_1^{A''},p_2^{A''},p_3^{A''}\}$, and
    %     \item the sets $V(P_1^{A''}) \setminus \{a\}, V(P_2^{A''}) \setminus \{a\}, V(P_3^{A''}) \setminus \{a\}$ are anticomplete.
    % \end{itemize}

    % Since vertices in $N_H^M(b)$ have degree at most $2$, the ends of these edges in $\{\{n\}: n \in N_H^M(b)\}$ are all distinct. Let $\{n_1,n_2,n_3\} \subseteq N_H^M(b)$ be such that $\{n_1\},\{n_2\}$, and $\{n_3\}$ are three distinct ends of edges with one end $D$ and the other in $\{\{n\}: n \in N_H^M(b)\}$. Let $X \subseteq V(D)$ be minimal (with respect to inclusion) such that $H[X]$ contains at least one neighbor of each of $n_1,n_2,n_3$. Since each of $n_1,n_2,n_3$ has degree $2$ and they are all neighbors of $b$ which is not in $D$, it follows that each has exactly one neighbor in $H[X]$. Thus, applying Lemma \ref{three-vertices}, we see that only case (\ref{three-vertices-2}) can hold, that is, there is a vertex $a \in X$ and paths $P_1,P_2,P_3$ such that $P_i$ is from $a$ to $X_i$ and $V(P_1) \setminus \{a\}, V(P_2) \setminus \{a\},V(P_3) \setminus \{a\}$ are pairwise anticomplete. Thus, $T = H[\{b\} \cup V(P_1) \cup V(P_2) \cup V(P_3)]$ is a theta with ends $a,b$. It follows from Lemma \ref{props} (\ref{props-3}) that $T$ is a long theta, but $T$ is an induced subgraph of $H$, which is a contradiction.
\end{proof}

From here onwards, we assume that $H$ is an outerstring graph so that we may proceed to bound the treewidth of $H''$ via Lemma \ref{H''-bounded-degree} (\ref{H''-bound}).

\begin{corollary} \label{H''-tw}
    There exists $L''\in \poi$ (independent of $k$ and $H$) such that $\tw(H'') \leq L''$.
\end{corollary}

\begin{proof}
    Let $h_0$ be as in Lemma \ref{no-wall-im}. Since $H''$ is an induced minor of $G$ and $G$ does not contain $W_{h_0 \times h_0}$ as an induced minor, it follows that $H''$ does not contain $W_{h_0 \times h_0}$ as an induced minor, and so in particular $H''$ does not contain any subdivision of $W_{h_0 \times h_0}$ or $L(W_{h_0 \times h_0})$ as an induced subgraph. By Lemma \ref{H''-bounded-degree}, $H''$ has maximum degree less than $9$. The result now follows from Theorem \ref{bound-no-wall-isg}.
\end{proof}

By Lemma \ref{tw-to-sep}, $H''$ has a $w''$-balanced separator $K''$ of size at most $L'' + 1$. Let $K''_\mathcal{N} = K'' \cap \mathcal{N}$ and $K''_\mathcal{D} = K'' \cap \mathcal{D}$.

\begin{lemma} \label{H''-balanced-sep} Let $L''$ be as in Corollary \ref{H''-tw}. Then
    \begin{enumerate}[{\rm (i)}]
        \item \label{H''-balanced-sep-1} $K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})$ is a $w''$-balanced separator in $H''$, and
        \item \label{H''-balanced-sep-2} $|K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})| \leq 9(L''+1)$.
    \end{enumerate}
\end{lemma}

\begin{proof}
    Let $C$ be a component of $H'' \setminus (K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D}))$. First suppose that $V(C) \cap K''_\mathcal{D} \neq \varnothing$, and let $D \in V(C) \cap K''_\mathcal{D}$. Since $N_{H''}(D) \subseteq K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})$, we have $\deg_{H'' \setminus (K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D}))}(D) = 0$, and so $V(C) = \{D\}$. As $H'[D]$ is a component of $H' \setminus K'$, it follows that $w''(D) = w'(H'[D]) \leq \frac{1}{2}$. Now suppose that $V(C) \cap K''_\mathcal{D} = \varnothing$. Then $C$ is a connected induced subgraph of $H'' \setminus K''$, so in particular, there exists a component $C^*$ of $H'' \setminus K''$ such that $V(C) \subseteq V(C^*)$. It follows that $w''(C) \leq w''(C^*) \leq \frac{1}{2}$. This proves (\ref{H''-balanced-sep-1}).

    To see that (\ref{H''-balanced-sep-2}) holds, we observe that $K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})$ is obtained from $K''$ by removing a subset of its elements and replacing each removed element by at most $9$ new elements. Since $|K''| \leq L'' + 1$, the bound follows.
\end{proof}

We are ready to translate the balanced separators for $H'$ and $H''$ back into a $w$-balanced separator in $H$.

\begin{lemma} \label{H-balanced-sep} Let $K^* = K'_{S} \cup K'_{M} \cup K'_{B,\leq 3} \cup K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})$ and let $K = (\bigcup_{X \in K^*} X) \cup Y_{B,\geq 3}$. Then the following hold.
\begin{enumerate}[{\rm (i)}]
    \item \label{H-balanced-sep-1} $K$ is a $w$-balanced separator in $H$.
    \item \label{H-balanced-sep-2} $|K| \leq 21 + 9(L'' + 1)$.
\end{enumerate}
\end{lemma}

\begin{proof}
    The induced subgraph $H \setminus ((\bigcup_{X \in K'_S \cup K'_M \cup K'_{B,\leq 3}} X) \cup Y_{B,\geq 3})$ of $H$, which we will denote by $F$, has vertex set $\{n: \{n\} \in \mathcal{N}\} \cup (\bigcup_{D \in \mathcal{D}} V(D))$. Thus, for every component $C$ of $F \setminus (\{n: \{n\} \in K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})\})$, there is a corresponding component $C''$ of $H''$ such that $V(C) = \bigcup_{X \in C''} X$, and so it follows that $w(C) = w''(C'') \leq \frac{1}{2}$. This proves (\ref{H-balanced-sep-1}).

    Since $K'_S,K'_M,$ and $K'_{B,\leq 3}$ are all subsets of $K'$, they each have size at most $3$. Every element of $K'_S$ and $K'_M$ is a singleton set, and so $|\bigcup_{\{s\} \in K'_S} \{s\}| \leq 3$ and $|\bigcup_{\{m\} \in K'_M} \{m\}| \leq 3$. Every $N_H^M[b] \in K_{B,\leq 3}$ has size at most $4$, and so 
    $$\left|\bigcup_{N_H^M[b] \in K'_{B,\leq 3}} N_H^M[b]\right| \leq 12.$$
    Since $|K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})| \leq 9(L''+1)$ by Lemma \ref{H''-balanced-sep} (\ref{H''-balanced-sep-2}) and every element of $K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})$ is a singleton, we have 
    $$\left|\bigcup_{\{n\} \in K''_\mathcal{N} \cup N_{H''}(K''_\mathcal{D})} \{n\}\right| \leq 9(L'' + 1).$$ 


    Moreover, $Y_{B,\geq 3}$ has the same size as $K_{B,\geq 3}$, and thus it has size at most $3$. Combining these bounds, we have $|K| \leq 3 + 3 + 12 + 9(L'' + 1) + 3 = 21 + 9(L'' + 1)$. This proves (\ref{H''-balanced-sep-2}).
\end{proof}

We are now ready to prove Lemma \ref{outerstring-isg-bound}. 
\begin{proof}[Proof of Lemma \ref{outerstring-isg-bound}.]
    Let $g,k \in \poi$ and let $H$ be an induced subgraph of $G_k^g$ that is an outerstring graph. Let $L''$ be as in Corollary \ref{H''-tw}. Then for every weight function $w$ on $H$, by Lemma \ref{H-balanced-sep} there is a $w$-balanced separator $X_w$ with $|X_w| \leq 21 + 9(L'' + 1)$. The claim now follows from Lemma \ref{sep-to-tw}, with $L = 42 + 18(L'' + 1)$.
\end{proof}

\section{Completing the Proof}

We are now ready to complete the proof of our main result. As discussed at the end of Section~\ref{sec:construction}, we only need to show that:

\begin{theorem}
    There exist $t_0,L\in \poi$ such that for all $g,k \in \poi$, the following hold.
    \begin{enumerate}[(i)]
        \item $G_k^g$ is $W_{t_0 \times t_0}$-induced-minor-free and $K_{t_0,t_0}$-induced-minor-free; and
        \item if $H$ is an induced subgraph of $G$ and $H$ is an outerstring graph, then $\tw(H) \leq L$.
    \end{enumerate}
\end{theorem}

\begin{proof}
    Let $h_0$ and $r_0$ be as in Lemmas~\ref{no-wall-im} and \ref{no-bipartite-im}, and let $t_0 = \max \{h_0,r_0\}$. Let $L$ be as in Lemma \ref{outerstring-isg-bound}. Then, by Lemmas \ref{no-wall-im} and \ref{no-bipartite-im}, $G_k^g$ does not contain $W_{t_0 \times t_0}$ or $K_{t_0,t_0}$ as an induced minor, and by Lemma \ref{outerstring-isg-bound}, if an induced subgraph $H$ of $G_k^g$ is an outerstring graph, then $\tw(H) \leq L$.
\end{proof}

We remark that, due to the more general setup of Lemma \ref{H''-bounded-degree}, our proof in fact gives the following stronger statement:

\begin{theorem}
\label{stronger}
    There exist $t_0,L\in \poi$ such that for all $g,k \in \poi$, the following hold.
    \begin{enumerate}[(i)]
        \item $G_k^g$ is $W_{t_0 \times t_0}$-induced-minor-free and $K_{t_0,t_0}$-induced-minor-free; and
        \item if $H$ is an induced subgraph of $G_k^g$ and $\tw(H) > L$, then $H$ contains an $\ell$-long theta as an induced subgraph for some $\ell \geq 2^g-1$.
    \end{enumerate}
\end{theorem}


