%        \begin{array}{cccccc}
%         \frac{n-p(G)+1}{2}-\theta(G)& if\ G\ has\ pendant\ vertices \\
%          \frac{n}{2}-\theta(G)& if\ p(G)=0\ and\ G\ is\ a\ $cycle-disjoint$\ graph\ \\
%          \frac{n+1}{2}-\theta(G) & if\ p(G)=0\ and\ two\ distinct\ cycles\ have\ common\ vertices \\
 %       \end{array}
%      \right.$$
%\end{thm}
\begin{proof} We will prove this theorem by induction on the order $n$ of $\Gamma$. Firstly, the cases $n=2$ and $n=3$ are verified. If $n=2$, then $\Gamma\cong P_2^\sigma$. Note that $i_+(P_2^\sigma)=1$, $\theta(P_2^\sigma)=0$, and $p(P_2^\sigma)=2$. We have $1=i_+(P_2^\sigma)\geq \frac{2-p(P_2^\sigma)+1}{2}-\theta(P_2^\sigma)=\frac{1}{2}$.
If $n=3$, then $\Gamma\cong P_3^\sigma$ or $C_3^\sigma$ since $\Gamma$ is connected. Suppose that $\Gamma\cong P_3^\sigma$. Then $1=i_+(P_3^\sigma)\geq \frac{3-p(P_3^\sigma)+1}{2}-\theta(P_3^\sigma)=1$ by Lemma \ref{lem-2-5} (iii). Suppose that $\Gamma\cong C_3^\sigma$. Then $1=i_+(C_3^\sigma)\geq \frac{3-p(C_3^\sigma)}{2}-\theta(C_3^\sigma)=\frac{1}{2}$ if $C_3^\sigma$ is balanced, and $2=i_+(C_3^\sigma)\geq \frac{3-p(C_3^\sigma)}{2}-\theta(C_3^\sigma)=\frac{1}{2}$ if $C_3^\sigma$ is unbalanced. Hence it suffice to consider the case $n\geq 4$ as follows and we may assume that the inequalities hold for any connected graph $H^\sigma$ with $2\leq |V(H^\sigma)|\leq n-1$. The following three cases can be distinguished.

{\flushleft\bf Case 1.} $\Gamma$ has no pendant vertices.

Clearly, $\Gamma$ contains at least one cycle, say $C^\sigma$, in this case. Let $x\in V(C^\sigma)$ and $\Gamma-x=H_1^\sigma\cup H_2^\sigma\cup\cdots\cup H_s^\sigma$, where $H_k^\sigma$ $(k=1,\ldots,s)$ are all connected components of $\Gamma-x$. Since $\Gamma$ has no pendant vertices, $2\leq |V(H_k^\sigma)|\leq n-1$ for any $k$. We divide these components into two categories such that $H_i^\sigma$ $(i=1, \ldots, r)$ has pendant vertices and $H_j^\sigma$ $(j=r+1,\ldots,s)$ has no pendant vertices. By applying induction hypothesis to each component $H_i^\sigma$ $(i=1, \ldots, r)$ and $H_j^\sigma$ $(j=r+1,\ldots,s)$, we have
$$ i_+(H_i^\sigma)\geq\frac{n(H_i^\sigma)-p(H_i^\sigma)+1}{2}-\theta(H_i^\sigma),  \ i=1,2,\ldots,r$$
and
$$ i_+(H_j^\sigma)\geq\frac{n(H_j^\sigma)}{2}-\theta(H_j^\sigma),\ j=r+1,\ldots,s.$$
Hence
\begin{align}
i_+(\Gamma)\geq i_+(\Gamma-x)&=\sum_{i=1}^{r}i_+(H_i^\sigma)+\sum_{j=r+1}^{s}i_+(H_j^\sigma)\nonumber\\
&\geq\sum_{i=1}^{r}(\frac{n(H_i^\sigma)-p(H_i^\sigma)+1}{2}-\theta(H_i^\sigma))+\sum_{j=r+1}^{s}(\frac{n(H_j^\sigma)}{2}-\theta(H_j^\sigma))\nonumber\\
&=\sum_{k=1}^{s}\frac{n(H_k^\sigma)}{2}-\sum_{i=1}^{r}\frac{p(H_i^\sigma)}{2}-\sum_{k=1}^{s}\theta(H_k^\sigma)+\frac{r}{2}\nonumber\\
&=\frac{n(\Gamma-x)-p(\Gamma-x)}{2}-\theta(\Gamma-x)+\frac{r}{2}.\nonumber
\end{align}
by Lemma \ref{lem-2-1} and Lemma \ref{lem-2-3}.

Let $m$ be the number of 2-degree neighbors of $x$. Since $\Gamma$ has no pendant vertices, the number of pendant vertices of $\Gamma-x$ equals $m$, that is, $p(\Gamma-x)=\sum_{i=1}^{r}p(H_i^\sigma)=m$. On the other hand, in light of Lemma \ref{lem-2-4} (ii), we have $\theta(\Gamma-x) =\theta(\Gamma)-d(x)+s$. Hence
$$i_+(\Gamma)\geq\frac{n-1-m}{2}-(\theta(\Gamma)-d(x)+s)+\frac{r}{2}=\frac{n}{2}-\theta(\Gamma)+(d(x)-s-\frac{m}{2}+\frac{r}{2}-\frac{1}{2}).$$
Note that $d(x)\geq s+1$ since $x\in V(C^\sigma)$. The inequality $2d(x)\geq 2s+m-r+1$ holds by Lemma \ref{lem-2-4} (i). Hence $d(x)-s-\frac{m}{2}+\frac{r}{2}-\frac{1}{2}\geq 0$, and so
$$i_+(\Gamma)\geq\frac{n}{2}-\theta(\Gamma)=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$$ because $p(\Gamma)=0$, as desired.

Furthermore, suppose that two distinct cycles $C_1^\sigma$ and $C_2^\sigma$ have common vertices in $\Gamma$. Choose $x$ in such a way that $x\in V(C_1^\sigma)\cap V(C_2^\sigma)$ and $d_{C_1^\sigma\cup C_2^\sigma}(x)\geq 3$, which implies $d(x)\geq s+2$. Hence $2d(x)\geq 2s+m-r+2$ by Lemma \ref{lem-2-4} (i), and so $d(x)-s-\frac{m}{2}+\frac{r}{2}-\frac{1}{2}\geq \frac{1}{2}$. Recall that $p(\Gamma)=0$, the inequality
$$i_+(\Gamma)\geq(\frac{n}{2}-\theta(\Gamma))+\frac{1}{2}=\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)$$ holds.

{\flushleft\bf Case 2.} $\Gamma$ has at least two pendant vertices.

Suppose that $x$ is one of pendant vertices of $\Gamma$ and let $y$ be the neighbour of $x$. If $d(y)>2$, then $\theta(\Gamma-x)=\theta(\Gamma)$ and $p(\Gamma-x)=p(\Gamma)-1\geq 1$. Using the fact that $i_+(\Gamma)\geq i_+(\Gamma-x)$ by Lemma \ref{lem-2-1}. By applying induction hypothesis to $\Gamma-x$, the inequaliy
\begin{align}
i_+(\Gamma)&\geq i_+(\Gamma-x)\nonumber\\
&\geq \frac{n(\Gamma-x)-p(\Gamma-x)+1}{2}-\theta(\Gamma-x)\nonumber\\
&=\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)\nonumber
\end{align}
holds.

If $d(y)=2$, then $1\leq p(\Gamma)-1\leq p(\Gamma-x-y)\leq p(\Gamma)$ since $n\geq 4$. Note that $\theta(\Gamma-x-y)=\theta(\Gamma)$. Again by applying induction hypothesis to $\Gamma-x-y$, we have
\begin{align}
i_+(\Gamma)&=i_+(\Gamma-x-y)+1\nonumber\\
&\geq\frac{n(\Gamma-x-y)-p(\Gamma-x-y)+1}{2}-\theta(\Gamma-x-y)+1\nonumber\\
&\geq\frac{n-2-p(\Gamma)+1}{2}-\theta(\Gamma)+1\nonumber\\
&=\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)\nonumber
\end{align}
by Lemma \ref{lem-2-2}.

{\flushleft\bf Case 3.} $\Gamma$ has one unique pendant vertex.

Suppose that $x$ is the unique pendant vertex of $\Gamma$ and let $y$ be the neighbour of $x$. By virtue of Lemma \ref{lem-2-2}, we have
$$i_+(\Gamma)=i_+(\Gamma-x-y)+1.$$

At first, let us consider the subcase $d(y)=2$ and set $x\neq z\in N(y)$. If $d(z)=2$ in this case, then $p(\Gamma-x-y)=p(\Gamma)=1$, $\theta(\Gamma-x-y)=\theta(\Gamma)$. By applying induction hypothesis to $\Gamma-x-y$, we obtain
\begin{align}
i_+(\Gamma)&=i_+(\Gamma-x-y)+1\nonumber\\
&\geq\frac{n(\Gamma-x-y)-p(\Gamma-x-y)+1}{2}-\theta(\Gamma-x-y)+1\nonumber\\
&=\frac{n-2-p(\Gamma)+1}{2}-\theta(\Gamma)+1=\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma).\nonumber
\end{align}
If $d(z)\geq3$, then $p(\Gamma-x-y)=p(\Gamma)-1=0, \theta(\Gamma-x-y)=\theta(\Gamma)$. In this case, we obtain
\begin{align}
i_+(\Gamma)&=i_+(\Gamma-x-y)+1\nonumber\\
&\geq\frac{n(\Gamma-x-y)-p(\Gamma-x-y)}{2}-\theta(\Gamma-x-y)+1\nonumber\\
&=\frac{n-2-p(\Gamma)+1}{2}-\theta(\Gamma)+1=\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma).\nonumber
\end{align}
%Then
%\begin{equation}\label{eq1}
%\ i_+{(G)}\geq\frac{n(G)-P(G)+1}{2}-\theta(G)\\
%\end{equation}

Now, it suffice to prove the inequality when $d(y)\geq 3$. Let $(\Gamma-y)-x=H_1^\sigma\cup H_2^\sigma\cup\cdots\cup H_s^\sigma$ be disjoint union of connected signed components of $(\Gamma-y)-x$. By the similar way as Case 1, set $H_i^\sigma$ $(i=1,\cdots,r)$ contains 2-degree neighbors of $y$, and $H_j^\sigma$ $(j=r+1,\cdots,s)$ contains no 2-degree neighbors of $y$. Since $x$ is the unique pendant vertex of $\Gamma$, we have $2 \leq |V(H_k^\sigma)|\leq n-1$ for each $k\in \{1,\ldots, s\}$. By applying induction hypothesis to each component $H_k$, the following inequalities hold:
$$i_+(H_i^\sigma)\geq\frac{n(H_i^\sigma)-p(H_i^\sigma)+1}{2}-\theta(H_i^\sigma),\ i=1,2,\ldots,r,$$
and
$$i_+(H_j^\sigma)\geq\frac{n(H_j^\sigma)}{2}-\theta(H_j^\sigma),\ j=r+1,\ldots,s.$$

It is clear that $p((\Gamma-y)-x)=\sum_{i=1}^{r}p(H_i^\sigma)=m$ holds, where $m$ denotes the number of 2-degree neighbors of $y$ in $\Gamma$. Hence
\begin{align}
i_+(\Gamma)&=i_+((\Gamma-y)-x)+1=\sum_{i=1}^{r}i_+{(H_i^\sigma)}+\sum_{j=r+1}^{s}i_+{(H_j^\sigma)}+1\nonumber\\
&\geq\sum_{i=1}^{r}(\frac{n(H_i^\sigma)-p(H_i^\sigma)+1}{2}-\theta(H_i^\sigma))+\sum_{j=r+1}^{s}(\frac{n(H_j^\sigma)}{2}-\theta(H_j^\sigma))+1\nonumber\\
&=\sum_{k=1}^{s}\frac{n(H_k^\sigma)}{2}-\sum_{i=1}^{r}\frac{p(H_i^\sigma)}{2}+\frac{r}{2}-\sum_{k=1}^{s}\theta(H_k^\sigma)+1\nonumber\\
&=\frac{n-2-m}{2}-\theta((\Gamma-y)-x)+\frac{r}{2}+1\nonumber.
\end{align}
by Lemma \ref{lem-2-3}.

Note that $y$ must belong to some cycle of $\Gamma$ because $d(y)\geq 3$ and $x$ is unique pendant vertex of $G$. We have $d(y)\geq s+1$. Hence $2d(y)\geq 2s+m-r+1$ by Lemma 2.4 (i). On the other hand, from Lemma \ref{lem-2-4} (ii), one may deduce the equality $\theta((\Gamma-y)-x)=\theta(\Gamma-y)=\theta(\Gamma)-d(y)+s$. Consequently,
\begin{align}
i_+(\Gamma)&\geq(\frac{n+1}{2}-\theta(\Gamma))+(d(y)-s-\frac{m}{2}+\frac{r}{2}-\frac{1}{2})\nonumber\\
&\geq\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)\nonumber
\end{align}
since $p(\Gamma)=0$. The theorem follows by induction.
\end{proof}

\begin{remark}\label{re-1}
\emph{For a disconnected signed graph $\Gamma$, in light of Lemma \ref{lem-2-3} and the additive property of $p(\Gamma)$ and $\theta(\Gamma)$, the inequalities of Theorem \ref{thm-3-1} can therefore be restricted or reduced to each connected signed component of $\Gamma$. Hence these inequalities also hold for disconnected signed graphs.}
\end{remark}

Let $\Gamma$ be a cycle-disjoint signed graph, and $C_1^\sigma, \ldots, C_k^\sigma$ be all induced signed cycles of $\Gamma$. In general, the signed cycles of $\Gamma$ fit together in a treelike structure. By $\Gamma\setminus \{C_1^\sigma,\ldots, C_k^\sigma\}$ we denote the graph obtained from $\Gamma$ by \emph{contracting} each $C_i^\sigma$ $(i=1,\ldots,k)$ into a new vertex $v_{C_i^\sigma}$. Moreover, $v_{C_i^\sigma}$ is adjacent to, except for the former neighbours in $\Gamma$, the vertex $v_{C_j^\sigma}$ for which some vertices of $C_i^\sigma$ are adjacent the vertex of $C_j^\sigma$ in $\Gamma$. Clearly, $\Gamma\setminus \{C_1^\sigma,\ldots, C_k^\sigma\}$ must be a tree since $\Gamma$ is cycle-disjoint. For example, as illustrated in Fig. \ref{fig-1}, for a cycle-disjoint signed graph $\Gamma$, we provide the tree $\Gamma\setminus \{C_1^\sigma,\ldots,C_6^\sigma\}$, which can be denoted by $T_{\Gamma}$. At the end of this section, by using the tree structure introduced above, we will give the characterization of signed graph $\Gamma$ with $i_+(\Gamma)=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$.

