\begin{thm}\label{thm-3-2}
Let $\Gamma$ be a signed graph of order $n$ and each connected component of $\Gamma$ has at least two vertices. Then $i_+(\Gamma)=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$ if and only if $\Gamma\cong C_{n_1}^\sigma\cup C_{n_2}^\sigma\cup\cdots \cup C_{n_t}^\sigma$, where $n_1+n_2+\cdots+n_t=n$, and $n_i\equiv 0(\bmod\ 4)$ if $C_{n_i}^\sigma$ is balanced or $n_i\equiv 2(\bmod\ 4)$ if $C_{n_i}^\sigma$ is unbalanced for $i\in \{1,2,\ldots,t\}$.
\end{thm}
\begin{proof}
Suppose that $\Gamma\cong C_{n_1}^\sigma\cup C_{n_2}^\sigma\cup \cdots \cup C_{n_t}^\sigma$, where $n_1+n_2+\cdots+n_t=n$ and $n_i\equiv 0(\bmod\ 4)$ if $C_{n_i}^\sigma$ is balanced or $n_i\equiv 2(\bmod\ 4)$ if $C_{n_i}^\sigma$ is unbalanced. Then $i_+(\Gamma)=(\frac{n_1}{2}-1)+(\frac{n_2}{2}-1)+\cdots+ (\frac{n_t}{2}-1)=\frac{n}{2}-t$ by Lemma \ref{lem-2-5}. Since $p(\Gamma)=0$ and $\theta(\Gamma)=t$, the equality $i_+(\Gamma)=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$ holds.

Conversely, let $\Gamma$ be a signed graph satisfying $i_+(\Gamma)=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$. Then $i_+(H_i^\sigma)=\frac{n_i-p(H_i^\sigma)}{2}-\theta(H_i^\sigma)$ for each connected signed component $H_i^\sigma$ of $\Gamma$, where $n_i=n(H_i^\sigma)$. Clearly, by virtue of Remark \ref{re-1}, we assert that $p(H_i^\sigma)=0$ and any distinct cycles of $H_i^\sigma$ share no vertices in common. Our first task is to demonstrate $H_i^\sigma\cong C_{n_i}^\sigma$. On the contrary, assume that $H_i^\sigma$ contains at least two signed cycles. Contracting each induced signed cycle of $H_i^\sigma$ into a new vertex, we obtain a tree $T_{H_i^\sigma}$ by the above assertion. Hence there exists a signed cycle $C^\sigma$ of $H_i^\sigma$, which corresponding to a pendant vertex of $T_{H_i^\sigma}$, such that exactly one vertex $x$ in $V(C^\sigma)$ satisfies $d(x)=3$.

Let $y$ be a neighbor of $x$ in $C^\sigma$. Then $H_i^\sigma-y$ has exactly one pendant vertex and $\theta(H_i^\sigma-y)=\theta(H_i^\sigma)-1$. Since $p(H_i^\sigma)=0$, we have
\begin{align}
i_+(H_i^\sigma)\geq i_+(H_i^\sigma-y)&\geq\frac{n(H_i^\sigma-y)-p(H_i^\sigma-y)+1}{2}-\theta(H_i^\sigma-y)\nonumber\\
&=\frac{n_i-1-1+1}{2}-\theta(H_i^\sigma)+1\nonumber\\
&=(\frac{n_i-p(H_i^\sigma)}{2}-\theta(H_i^\sigma))+\frac{1}{2}\nonumber
\end{align}
by Lemma \ref{lem-2-1} and Theorem \ref{thm-3-1}. This contradicts the assumption $i_+(H_i^\sigma)=\frac{n_i-p(H_i^\sigma)}{2}-\theta(H_i^\sigma)$. Hence $H_i^\sigma$ has exactly one induced signed cycle, and so $H_i^\sigma\cong C_{n_i}^\sigma$ because of $p(H_i^\sigma)=0$. Recall that $i_+(H_i^\sigma)=\frac{n_i-p(H_i^\sigma)}{2}-\theta(H_i^\sigma)=\frac{n_i}{2}-1$. We obtain that $n_i\equiv 0(\bmod\ 4)$ if $H_i^\sigma$ is balanced or $n_i\equiv 2(\bmod\ 4)$ if $H_i^\sigma$ is unbalanced by Lemma \ref{lem-2-5}.

%This proves that there is only one cycle in $T$. Next, we demonstrate that the cycle in $T$ is a multiple of $4$.
\end{proof}

\section{Negative inertia index and nullity of signed graphs with given cyclomatic number and given number of pendant vertices}
By replacing the signature $\sigma$ of $\Gamma=(G, \sigma)$ with $-\sigma$, one can obtain a signed graph $-\Gamma=(G, -\sigma)$ known as the negation of $\Gamma$. By elementary linear algebra, the negative inertia index of $\Gamma$ is equal to the positive inertia index of $-\Gamma$. Hence the following Theorems \ref{thm-4-1} and \ref{thm-4-2} in this draft is an immediate consequence of Theorems \ref{thm-3-1} and \ref{thm-3-2}. To better understand these two theorems, we also provide a brief proof process. But the proofs of results about $i_-(\Gamma)$ are similar to that of $i_+(\Gamma)$, we will omit some similar steps.

\begin{thm}\label{thm-4-1}
Let $\Gamma$ be a connected signed graph of order $n\geq 2$. Then $i_-(\Gamma)\geq \frac{n-p(\Gamma)}{2}-\theta(\Gamma)$. Moreover, $i_-(\Gamma)\geq \frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)$ if $p(\Gamma)\geq 1$, or $p(\Gamma)=0$ and two distinct cycles of $\Gamma$ have common vertices.
\end{thm}
\begin{proof}
We also prove this theorem by induction on $n$. Firstly, the inequalities hold for $n=2$ or $n=3$ obviously. Hence let $n\geq 4$ and we discuss the following three cases.

{\flushleft\bf Case 1.} $\Gamma$ has no pendant vertices.

$\Gamma$ must contain an induced signed cycle $C^\sigma$ in this case. Let $x\in V(C^\sigma)$ and $\Gamma-x=H_1^\sigma\cup H_2^\sigma\cup\cdots\cup H_s^\sigma$, where $H_k^\sigma$ $(k=1,\ldots,s)$ are all connected components of $\Gamma-x$. Then $|V(H_k^\sigma)|\geq 2$ since $\Gamma$ has no pendant vertices. Set $H_i^\sigma$ $(i=1, \ldots, r)$ has pendant vertex and $H_j^\sigma$ $(j=r+1,\ldots,s)$ has no pendant vertices. By applying induction hypothesis to $H_i^\sigma$ and $H_j^\sigma$, we have
$i_-(H_i^\sigma)\geq\frac{n(H_i^\sigma)-p(H_i^\sigma)+1}{2}-\theta(H_i^\sigma)$ and $i_-(H_j^\sigma)\geq\frac{n(H_j^\sigma)}{2}-\theta(H_j^\sigma)$. Hence
$$i_-(\Gamma)\geq i_-(\Gamma-x)=\sum_{k=1}^{s}i_-(H_k^\sigma)\geq\frac{n(\Gamma-x)-p(\Gamma-x)}{2}-\theta(\Gamma-x)+\frac{r}{2}$$
by Lemmas \ref{lem-2-1} and \ref{lem-2-3}. Note that $d(x)\geq s+1$ since $x\in V(C^\sigma)$. We have $\theta(\Gamma-x)=\theta(\Gamma)-d(x)+s$ and $2d(x)\geq 2s+m-r+1$ by Lemma \ref{lem-2-4}. Hence $i_-(\Gamma)\geq\frac{n-p(\Gamma)}{2}-\theta(G)$ since $p(\Gamma)=0$.

Furthermore, if two distinct cycles $C_1^\sigma$ and $C_2^\sigma$ of $\Gamma$ have common vertices, then there exists $x\in V(C_1^\sigma)\cap V(C_2^\sigma)$ such that $d(x)\geq s+2$. Hence $2d(x)\geq 2s+m-r+2$ by Lemma \ref{lem-2-4} (i). Similar to positive inertia index, we have $i_-(\Gamma)\geq\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)$.

{\flushleft\bf Case 2.} $\Gamma$ has at least two pendant vertices.

Let $x\in V(\Gamma)$ be a pendant vertex and $N(x)=\{y\}$. Suppose that $d(y)>2$. By applying induction hypothesis to $\Gamma-x$, we have
$$i_-(\Gamma)\geq i_-(\Gamma-x)\geq\frac{n(\Gamma-x)-p(\Gamma-x)+1}{2}-\theta(\Gamma-x)=\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)$$ by Lemma \ref{lem-2-1}. Suppose that $d(y)=2$. By applying induction hypothesis to $\Gamma-x-y$, we have
$$i_-(\Gamma)=i_-(\Gamma-x-y)+1\geq\frac{n(\Gamma-x-y)-p(\Gamma-x-y)+1}{2}-\theta(\Gamma-x-y)+1\geq\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma).$$
by Lemma \ref{lem-2-2}.

{\flushleft\bf Case 3.} $\Gamma$ has one unique pendant vertex.

Let $x$ be the unique pendant vertex of $\Gamma$ and $N(x)=\{y\}$. Suppose that $d(y)=2$ and set $z\in N(y)$. Then $\Gamma-x-y$ has a pendant vertex if $d(z)=2$, and $\Gamma-x-y$ has no pendant vertices if $d(z)\geq 3$. By applying induction hypothesis to $\Gamma-x-y$ in both cases, we obtain
$i_-(\Gamma)=i_-(\Gamma-x-y)+1\geq\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)$ by Lemma \ref{lem-2-2}.

Suppose that $d(y)\geq 3$ and let $\Gamma-y-x=H_1^\sigma\cup H_2^\sigma\cup\cdots\cup H_s^\sigma$. Set $H_i^\sigma$ $(i=1,\ldots,r)$ contains 2-degree neighbors of $y$, and $H_j^\sigma$ $(j=r+1,\ldots,s)$ contains no 2-degree neighbors of $y$. By applying induction hypothesis to $H_i^\sigma$ and $H_j^\sigma$, we have
$i_-(H_i^\sigma)\geq\frac{n(H_i^\sigma)-p(H_i^\sigma)+1}{2}-\theta(H_i^\sigma)$ and $i_-(H_j^\sigma)\geq\frac{n(H_j^\sigma)}{2}-\theta(H_j^\sigma)$.
Since $p(\Gamma-y-x)=\sum_{i=1}^{r}p(H_i^\sigma)=m$, where $m$ denotes the number of 2-degree neighbors of $y$ in $G$, we obtain
$$i_-(\Gamma)=i_-(\Gamma-y-x)+1=\frac{n-2-m}{2}-\theta(\Gamma-y-x)+\frac{r}{2}+1$$
by Lemmas \ref{lem-2-2} and \ref{lem-2-3}. According to Lemma \ref{lem-2-4}, the inequalities $2d(y)\geq 2s+m-r+1$ and $\theta(\Gamma-y-x)=\theta(\Gamma)-d(y)+s$ holds since $d(y)\geq s+1$. Therefore,
$i_-(\Gamma)\geq(\frac{n+1}{2}-\theta(\Gamma))+(d(y)-s-\frac{m}{2}+\frac{r}{2}-\frac{1}{2})\geq\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma)$.
\end{proof}


\begin{remark}\label{re-2}
Similar to the positive inertia index, Theorem \ref{thm-4-1} also holds for disconnected signed graphs.
\end{remark}

\begin{thm}\label{thm-4-2}
Let $\Gamma$ be a signed graph of order $n$ and each connected component of $\Gamma$ has at least two vertices. Then $i_-(\Gamma)=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$ if and only if $\Gamma\cong C_{n_1}^\sigma\cup C_{n_2}^\sigma\cup\cdots \cup C_{n_t}^\sigma$, where $n_1+n_2+\cdots+n_t=n$, and $n_i\equiv 0(\bmod\ 4)$ if $C_{n_i}^\sigma$ is balanced or $n_i\equiv 2(\bmod\ 4)$ if $C_{n_i}^\sigma$ is unbalanced for $i\in \{1,2,\ldots,t\}$.
\end{thm}
\begin{proof}
The sufficiency holds obviously by Lemma \ref{lem-2-5}. We prove the necessity as follows. It only need to consider the connected component $H_i^\sigma$ of $\Gamma$ which satisfies $i_-(H_i^\sigma)=\frac{n_i-p(H_i^\sigma)}{2}-\theta(H_i^\sigma)$, where $n_i=n(H_i^\sigma)$. According to Theorem \ref{thm-4-1}, we assert that $p(H_i^\sigma)=0$ and any distinct cycles of $H_i^\sigma$ share no vertices in common. Firstly, we claim $H_i^\sigma\cong C_{n_i}^\sigma$ as follows. On the contrary, assume that $H_i^\sigma$ contains at least two cycles. Then there exists a signed cycle $C^\sigma$ of $H_i^\sigma$ such that exactly one vertex, say $x\in V(C^\sigma)$, is the only vertex with $d(x)=3$. Let $y$ be a neighbor of $x$ in $C^\sigma$. Then $H_i^\sigma-y$ has exactly one pendant vertex and $\theta(H_i^\sigma-y)=\theta(H_i^\sigma)-1$. Note that $p(H_i^\sigma)=0$, we have
$$i_-(H_i^\sigma)\geq i_-(H_i^\sigma-y)=(\frac{n-p(H_i^\sigma)}{2}-\theta(H_i^\sigma))+\frac{1}{2}$$
by Lemma \ref{lem-2-1} and Theorem \ref{thm-4-1}, a contradiction. Hence $H_i^\sigma\cong C_{n_i}^\sigma$, and so $n_i\equiv 0\ (\bmod\ 4)$ if $H_i^\sigma$ is balanced or $n_i\equiv 2\ (\bmod\ 4)$ if $H_i^\sigma$ is unbalanced by Lemma \ref{lem-2-5}.
\end{proof}

By using the inequalities of positive and negative inertia indices of a signed $\Gamma$ shown in Theorems \ref{thm-3-1} and \ref{thm-4-1}, we can obtain following corollary about the nullity of $\Gamma$, which contains main conclusions in \cite{Xiaobin.Ma}.

\begin{cor}\label{cor-4-1}
Let $\Gamma$ be a signed graph of order $n\geq 2$. Then $\eta(\Gamma)\leq p(\Gamma)+2\theta(\Gamma)$. Moreover, $\eta(\Gamma)\leq p(\Gamma)+2\theta(\Gamma)-1$ if $p(\Gamma)\geq 1$, or $p(\Gamma)=0$ and two distinct cycles of $G$ have common vertices.
\end{cor}
\begin{proof}
Let $\Gamma$ be a signed graph of order $n\geq 2$. In light of Remark \ref{re-1} and Remark \ref{re-2}, we have
$$r(\Gamma)=i_+(\Gamma)+i_-(\Gamma)\geq(\frac{n-p(\Gamma)}{2}-\theta(\Gamma))+(\frac{n-p(\Gamma)}{2}-\theta(\Gamma))=n-p(\Gamma)-2\theta(\Gamma).$$
Therefore,
$$\eta(\Gamma)=n-r(\Gamma)\leq n-(n-p(\Gamma)-2\theta(\Gamma))=p(\Gamma)+2\theta(\Gamma).$$

Furthermore, if $p(\Gamma)\geq 1$, or $p(\Gamma)=0$ and two distinct cycles of $\Gamma$ have common vertices, then

$$r(\Gamma)=i_+(\Gamma)+i_-(\Gamma)\geq(\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma))+(\frac{n-p(\Gamma)+1}{2}-\theta(\Gamma))=n-p(\Gamma)-2\theta(\Gamma)+1.$$
Hence
$$\eta(\Gamma)=n-r(\Gamma)\leq n-(n-p(\Gamma)-2\theta(\Gamma)+1)=p(\Gamma)+2\theta(\Gamma)-1.$$
This complete the proof.
\end{proof}

\begin{cor}\label{cor-4-2}
Let $\Gamma$ be a signed graph of order $n$ and each connected component of $\Gamma$ has at least two vertices. Then $\eta(\Gamma)=p(\Gamma)+2\theta(\Gamma)$ if and only if  $\Gamma\cong C_{n_1}^\sigma\cup C_{n_2}^\sigma\cup\cdots \cup C_{n_t}^\sigma$, where $n_1+n_2+\cdots+n_t=n$, and $n_i\equiv 0(\bmod\ 4)$ if $C_{n_i}^\sigma$ is balanced or $n_i\equiv 2(\bmod\ 4)$ if $C_{n_i}^\sigma$ is unbalanced for $i\in \{1,2,\ldots,t\}$.
\end{cor}
\begin{proof}
According to Theorems \ref{thm-3-2} and \ref{thm-4-2}, the sufficiency of this corollary holds by the equality $\eta(\Gamma)=n-(i_+(\Gamma)+i_-(\Gamma))$.

Conversely, let $\Gamma$ be a signed graph satisfying $\eta(\Gamma)=p(\Gamma)+2\theta(\Gamma)$. Then $r(\Gamma)=n-p(\Gamma)-2\theta(\Gamma)$. We claim that $i_+(\Gamma)=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$ must be correct in this context. In fact, on the contrary, assume that $i_+(\Gamma)\not=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$. Then $i_+(\Gamma)>\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$ by Theorem \ref{thm-3-1}. Hence
$i_-(\Gamma)=r(\Gamma)-i_+(\Gamma)<\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$, which contradicts the conclusion of Theorem \ref{thm-4-1}. Therefore, $i_+(\Gamma)=\frac{n-p(\Gamma)}{2}-\theta(\Gamma)$, and so the assertion holds by Theorem \ref{thm-3-2}.
\end{proof}

