\begin{abstract}
We investigate the rate of convergence toward the Boolean extreme value distribution which is the universal limiting law for the normalized spectral maximum of Boolean independent positive operators, under the von Mises condition.
\end{abstract}


%%%

\section{Introduction}

Extreme value theory has long served as a foundational framework for describing the asymptotic behavior of the maximum of a sequence of independent and identically distributed (i.i.d.) random variables. Over time, it has evolved into a major branch of probability and statistics, playing a central role particularly in the study of large observations and rare events. One of the most important results in extreme value theory is Fisher-Tippett-Gnedenko theorem \cite{FT28, G43} (see also \cite{R}), which states that, under appropriate normalization, the distribution of the maximum of i.i.d. random variables converges to one of the {\it extreme value distributions}:
$$
\Phi_\alpha(x)=\begin{cases}
\exp(-x^{-\alpha})\mathbf{1}_{(0,\infty)}(x), & \alpha>0 \quad \text{(Fr\'{e}chet distribution)};\\
\exp(-(-x)^{-\alpha})\mathbf{1}_{(-\infty,0)}(x) + \mathbf{1}_{[0,\infty)}(x), & \alpha<0 \quad \text{(Weibull distribution)};\\
\exp(-e^{-x})\mathbf{1}_\R(x), & \alpha=0 \quad \text{(Gumbel distribution)}.
\end{cases}
$$

In 2021, Vargas and Voiculescu \cite{VV21} initiated extreme value theory in the context of Boolean independence for non-commutative random variables (see \cite{SW97} for details on Boolean probability theory). Let $(\calH,\xi)$ be a Hilbert space equipped with a unit vector $\xi \in \calH$, and define the vector state $\varphi(X):=\langle T\xi, \xi\rangle_{\calH}$ for a (bounded) linear operator $T$ on $\calH$. If $P$ and $Q$ are Boolean independent projections on $\calH$ with $\varphi(P)=1-p$ and $\varphi(Q)=1-q$ for some $p,q \in [0,1]$, then they showed that $\varphi(P\lor Q)=1-r$ where $r\in [0,1]$ satisfies
$$
r^{-1}-1=(p^{-1}-1) + (q^{-1}+1).
$$
If either $p=0$ or $q=0$, then $r$ is defined to be zero. This identity motivates the definition of a semigroup structure $([0,1], \cup \hspace{-.65em}\lor)$ with the binary operation:
$$
(x\cup \hspace{-.89em}\lor y)^{-1} -1 := (x^{-1}-1) + (y^{-1}-1), \quad x,y \in (0,1]
$$
and $x\cup \hspace{-.89em}\lor y :=0$ if either $x=0$ or $y=0$.

Due to certain constraints in the Boolean setting and operator theory, one must restrict to the class of distribution functions supported on $[0,\infty)$, see \cite[Section 2]{VV21} for details. Let $\Delta_+$ be the set of all distribution functions on $[0,\infty)$. For $F,G\in \Delta_+$, the {\it Boolean max-convolution} is defined as
$$
(F \cup\hspace{-.89em}\lor G)(x):= F(x) \cup\hspace{-.89em}\lor G(x), \quad x \ge0,
$$
with the $n$-fold Boolean max-convolution defined recursively as
$$
F^{\cup \hspace{-.52em}\lor n}:= \underbrace{F\cup\hspace{-.89em}\lor \cdots \cup\hspace{-.89em}\lor F}_{n \text{ times}}, \qquad n\in \N.
$$

One of the most important results in this theory is the discovery of a semigroup isomorphism between $([0,1],\cup\hspace{-.66em}\lor)$ and $([0,1],\cdot)$, given by the map
$$ 
\calX(u):=\exp\left(1-\frac{1}{u}\right), \quad u \in (0,1], \quad \text{and} \quad \calX(0):=0
$$
which satisfies
$$
\calX(u \cup\hspace{-.90em}\lor v) =\calX(u)\calX(v), \qquad u,v\in [0,1].
$$
The inverse map $\calX^{\langle-1\rangle}$ is given by
$$
\calX^{\langle -1\rangle} (u):= \frac{1}{1-\log u}, \quad u\in (0,1], \quad \text{and} \quad \calX^{\langle -1\rangle}(0):=0
$$
and satisfies
$$
\calX^{\langle -1\rangle} (uv) = \calX^{\langle -1\rangle} (u) \cup \hspace{-.90em}\lor \calX^{\langle -1\rangle} (v), \qquad u,v\in [0,1].
$$
For $F\in \Delta_+$, we define the following distribution functions:
$$
(\calX(F))(x):=\calX(F(x)) \quad \text{and} \quad   (\calX^{\langle-1\rangle}(F))(x):=\calX^{\langle-1\rangle}(F(x)), \quad x\ge0.
$$


The mapping $\calX$ facilitates the transfer of classical results into the Boolean setting. Using this framework, Vargas and Voiculescu proved that the distribution function of the normalized spectral maximum $(X_1\lor \cdots \lor X_n)/a_n$, given by
$$
x\mapsto F^{\cup\hspace{-.52em}\lor n}(a_nx), \qquad x\in [0,\infty)
$$
converges weakly to the {\it Boolean extreme value distribution}, also known as {\it Dagum distribution}:
$$
\Phi_\alpha^{\rm boolean}(x) = \frac{1}{1+x^{-\alpha}}, \quad x>0 \quad \text{and} \quad \alpha>0,
$$
as $n\to\infty$, see \cite[Theorem 4.1]{VV21}.
Here $\{X_n\}_n$ is a sequence of Boolean i.i.d. positive random variables whose spectral distribution function is $F\in \Delta_+$, $\{a_n\}_n \subset(0,\infty)$ is a normalization sequence and $\lor$ is the Ando's max-operation (see \cite{A89,BV06, O71}). The following important relations are known:
$$
\calX(\Phi_\alpha^{\rm boolean}) = \Phi_\alpha  \quad \text{and} \quad \calX^{\langle -1\rangle} (\Phi_\alpha)=\Phi_\alpha^{\rm boolean}, \qquad \alpha>0.
$$

The purpose of this paper is to determine the convergence rate of normalized spectral maximum of Boolean independent positive random variables to the Boolean extreme value distribution, under the von Mises condition.


For $\alpha>0$ and for a distribution function $F$ on $\R$ which is differentiable on a neighborhood of $\infty$, we define
\begin{align}\label{eq:F_k}
k_{\alpha,F}(x)= \frac{xF'(x)}{F(x)(1-F(x))}-\alpha.
\end{align}
In this paper, we focus on the following class of distribution functions.
\begin{defn}\label{def:F_alpha}
Let us consider $\alpha>0$. Denote by $\calV_\alpha$ the set of all distribution functions $F$ on $\R$ such that
\begin{enumerate}[\rm (i)]
\item $F(x)<1$ for all $x\in (0,\infty)$, $F(0)=0$ and $F$ is a $C^1$-function on a neighborhood of $\infty$; 
\item there exists a non-increasing continuous function $g$ such that $g(x) \to 0$ as $x\to\infty$ and 
\begin{align}\label{eq:bound}
|k_{\alpha,F}(x)|\le g(x)
\end{align}
for all $x$ in the neighborhood of $\infty$. 
\end{enumerate}
In this case, we call the function $g$ the {\it auxiliary function with \eqref{eq:bound}} and the above assumption (ii) the {\it von Mises condition}. Moreover, we define $\calV_{\alpha,+}:=\calV_\alpha \cap \Delta_+$.
\end{defn}

\begin{thm}\label{thm:main}
Given $\alpha>0$, let us consider $F\in \calV_{\alpha,+}$ and let $g$ be an auxiliary function with \eqref{eq:bound}. Define two positive sequences $a_n>0$ and $a_n'>0$ by $F(a_n)=e^{-\frac{1}{n}}$ and $F(a_n')=\frac{n}{n+1}$, respectively, and define $A_n:=a_n/a_n'\in (0,1]$. Then we obtain
\begin{align*}
\sup_{x \in \R} |F^{\cup \hspace{-.50em}\lor n}(a_n x)- \Phi_\alpha^{\rm boolean} (x)| \le O \left(g(\rho(a_n)) \lor n^{-1} \lor (A_n^{-1}-1) \right),
\end{align*}
for sufficiently large $n$, where $\rho$ is the inverse function of
$$
t\mapsto t\left\{ \frac{\alpha e}{g(t)} - (e+1)\right\}^{\frac{1}{\alpha -g(t)}}.
$$
\end{thm}

A proof of the above theorem is sketched here. The following method of proof is inspired by \cite{KU25}. Let us set $d_n (x):= |F^{\cup \hspace{-.50em}\lor n}(a_n x)- \Phi_\alpha^{\rm boolean} (x)|$. Since both  $F$ and $\Phi_\alpha^{\rm boolean}$ are supported on $[0,\infty)$, it follows immediately that $d_n(x)=0$ for all $x\le 0$. For $x\ge 1$, we show that $d_n(x)$ is estimated by the error between the free max-convolution power of the distribution function $x\mapsto F(a_nx)$ and the free extreme value distribution (see Section \ref{sec:FEV} for details on the free max-settings), together with an additional error term of order $n^{-1}$. Using a previous result in \cite{KU25}, we obtain 
$$
\sup_{x\ge 1}d_n(x) \le O(g(a_n)\lor n^{-1}), 
$$
as shown in Lemma \ref{lem:Estimate:freemax} and Proposition \ref{prop:Estimate:booleanmax}. Next, we consider the case $0<x<1$. Here, the semigroup isomorphism $\calX$ plays a crucial role. By definition of $\calX$, we have $|h_{\alpha,\calX(F)}|\le g$ on the neighborhood of $\infty$, where the function $h_{\alpha,F}$ is defined in \eqref{eq:F_h}. Then, from \cite[Eq. (2.45)]{R}, it follows that 
$$
\Phi_{\alpha+g(a_n'x)} (x) \le \calX(F)^n (a_n'x)\le \Phi_{\alpha-g(a_n'x)}(x),
$$
with $F(a_n')=\frac{n}{n+1}$. Composing this inequality with $\calX^{\langle-1\rangle}$ and applying the method of \cite[Proposition 2.13]{R}, we obtain 
\begin{align}\label{eq:outline}
\sup_{0<x<1}|F^{\cup \hspace{-.52em}\lor n}(a_n'x) - \Phi_\alpha^{\rm boolean}(x)| \le \frac{g(\rho(a_n))}{e(\alpha-g(\rho(a_n)))},
\end{align}
as shown in Proposition \ref{prop:Estimate:booleanmax2}. Finally, for $0<x<1$, we estimate
$$
d_n(x) \le |F^{\cup \hspace{-.52em}\lor n}(a_n' (A_nx)) - \Phi_\alpha^{\rm boolean}(A_n x)| + |\Phi^{\rm boolean}_\alpha(A_nx) -\Phi_\alpha^{\rm boolean}(x)|,
$$ 
where $A_n=a_n/a_n'\in (0,1]$. Since $|\Phi_\alpha^{\rm boolean}(A_nx)-\Phi_\alpha^{\rm boolean}(x)| \le \alpha(A_n^{-1}-1)$ for all $x\in (0,1)$ and the inequality \eqref{eq:outline} holds, we get 
$$
\sup_{0<x<1} d_n(x) \le O\left(g(\rho(a_n))\lor (A_n^{-1}-1)\right).
$$ 
Combining the estimates for all three regions of $x$ yields the main theorem.

In Section \ref{sec:FEV}, we introduce the concepts of max-convolution and extreme value distributions in free probability theory. In Section \ref{sec:ratefree}, we derive a convergence rate toward the free extreme value distribution (see Lemma \ref{lem:Estimate:freemax}) as a partial result contributing to the proof of Theorem \ref{thm:main}. Section \ref{sec:proof} provides the complete proof of Theorem \ref{thm:main}. In Section \ref{sec:application}, we apply Theorem \ref{thm:main} to the Fr\'{e}chet distribution $\Phi_\alpha$. Specifically, we show that $\sup_{x\in \R}|\Phi_{\alpha}^{\cup \hspace{-.52em}\lor n} (n^{1/\alpha} x)- \Phi_\alpha^{\rm boolean}(x)|\le O(n^{-1/2})$ for sufficiently large $n$; see Proposition \ref{prop:appli}. 

