\section{Preliminaries in free extreme value theory}


\subsection{Free max-convolution and free extreme value distributions}
\label{sec:FEV}

In 2006, Ben Arous and Voiculescu \cite{BV06} established extreme value theory in the framework of free probability theory.  In the years that followed, considerable effort has been directed toward advancing the theory of free extreme values \cite{BK10, BGCD10,GN20, HU21, KU25, U22, U22-2, U21}. We will explain more details as follows.

According to \cite[Definition 6.1]{BV06}, for any distribution functions $F$ and $G$ on $\R$, we define
$$
F \Box\hspace{-.94em}\lor G :=  \max\{F+G-1,0\} \quad \text{and} \quad F^{\Box\hspace{-.55em}\lor  n} := \underbrace{F\Box\hspace{-.94em}\lor  \cdots \Box\hspace{-.94em}\lor  F}_{n\text{ times}}.
$$ The operation $\Box\hspace{-.72em}\lor$ is called the {\it free max-convolution}. By \cite[Theorem 6.8]{BV06}, the limiting distribution of the normalized maximum of free i.i.d non-commutative real random variables is known to be type equivalent to one of the three distributions:
\begin{align*}
\Phi_\alpha^{\rm free}(x) := 
\begin{cases}
 (1-x^{-\alpha})\mathbf{1}_{[1,\infty)}(x), & \alpha>0 \quad \text{(Pareto distribution)};\\
 \{1-(-x)^{-\alpha}\}\mathbf{1}_{[-1,0]}(x) + \mathbf{1}_{(0,\infty)}(x), &  \alpha < 0 \quad \text{(Beta distribution)};\\
 (1-e^{-x})\mathbf{1}_{[0,\infty)}(x) & \alpha=0  \quad \text{(Exponential distribution)}.
 \end{cases}
\end{align*}
The distributions $\Phi_\alpha^{\rm free}$ are called the {\it free extreme value distributions}. Rigorously, for a distribution function $F$ on $\R$, there exist $a_n>0$, $b_n\in \R$ and a non-degenerate distribution function $G$ such that, for any $x\in \R$,
$F^{\Box\hspace{-.55em}\lor n} (a_n x +b_n) \to G(x)$ as $n\to\infty$.
Then the function $G$ is the free extreme value distribution. 



\subsection{Rate of convergence for free extreme values}
\label{sec:ratefree}

In this section, we give a rate of convergence toward the free extreme value distribution under the von Mises condition. 
Given $\alpha>0$ and a distribution function $F$ on $\R$ that is differentiable in a neighborhood of $\infty$, we define the function
\begin{align}\label{eq:F_h}
h_{\alpha,F}(x) = \frac{xF'(x)}{F(x)(-\log F(x))}-\alpha.
\end{align}



We can estimate the function $h_{\alpha,F}$ as follows.
\begin{lem}\label{lem:Estimate_h}
Let $\alpha>0$, $F\in \calV_{\alpha}$ and let $g$ be an auxiliary function with \eqref{eq:bound}. Then we obtain
$$
|h_{\alpha,F}(x)|\le g(x) + \alpha \cdot \frac{-\log F(x)-(1-F(x))}{-\log F(x)} = :u(x)
$$
for all $x$ in the neighborhood of $\infty$. Moreover, $u(x)$ is a non-increasing continuous function such that $u(x) \to 0$ as $x\to \infty$.
\end{lem}
\begin{proof}
By \eqref{eq:F_k} and \eqref{eq:F_h}, 
\begin{align*}
h_{\alpha,F}(x) = k_{\alpha,F}(x) \frac{1-F(x)}{-\log F(x)} + \alpha\cdot\frac{1-F(x)-(-\log F(x))}{-\log F(x)}.
\end{align*}
Since $1-F(x) \le -\log F(x)$, it follows from the triangle inequality and Definition \ref{def:F_alpha} that
\begin{align*}
|h_{\alpha,F}(x)| 
&\le |k_{\alpha,F}(x)| + \alpha \cdot \frac{-\log F(x)-(1-F(x))}{-\log F(x)} \\
& \le g(x) + \alpha\cdot  \frac{-\log F(x)-(1-F(x))}{-\log F(x)} =: u(x).
\end{align*}
We set 
$$
\ell (u) := \frac{-\log u - (1-u)}{-\log u}, \quad u\in (0,1).
$$ 
One can see that
\begin{itemize}
\item $\ell'(u) = \dfrac{-u\log u- (1-u)}{u(-\log u)^2}<0$ for all $u\in (0,1)$;
\item $\lim_{u\to 0^+}\ell(u)=1$ and $\lim_{u\to 1^-} \ell(u)=0$.
\end{itemize}
Thus the function 
$$
x\mapsto \frac{-\log F(x)-(1-F(x))}{-\log F(x)}
$$
is non-increasing and goes to $0$ as $x\to \infty$, and therefore so is $u(x)$.
\end{proof}

Choose $a_n = F^{\leftarrow} (e^{-\frac{1}{n}})$, where $F^{\leftarrow} (y) := \inf \{x\in \R: F(x) \ge y\}$. Due to \cite[Proposition 2.2]{KU25}, we have $F^{\Box\hspace{-.55em}\lor n}(a_n\cdot )\xrightarrow{w} \Phi_\alpha^{\rm free}$. Finally, we get the following conclusion.

\begin{lem}\label{lem:Estimate:freemax}
Given $\alpha>0$, let us consider $F\in \calV_{\alpha}$ and an auxiliary function $g$ with \eqref{eq:bound}. We define $a_n=F^{\leftarrow} (e^{-\frac{1}{n}})$. Then $F^{\Box\hspace{-.55em}\lor n}(a_n\cdot )\xrightarrow{w} \Phi_\alpha^{\rm free}$ and
\begin{align*}
\sup_{x\ge 1}|F^{\Box\hspace{-.55em}\lor n}(a_nx) - \Phi_\alpha^{\rm free}(x)| \le O(g(a_n)\lor n^{-1})
\end{align*}
for sufficiently large $n$.
\end{lem}
\begin{proof}
For $x\ge 1$, we have
\begin{align*}
|F^{\Box\hspace{-.55em}\lor n}(a_nx) - \Phi_\alpha^{\rm free}(x)| 
&=|x^{-\alpha}-n(1-F(a_nx))|\\
&\le |x^{-\alpha}- n(-\log F(a_nx))| + n \left\{(-\log F(a_nx))-(1-F(a_nx)) \right\}.
\end{align*}
We define $r(u):=-\log u -(1-u)$ for $u\in (0,1)$. Then $r$ is non-increasing on $(0,1)$, and therefore $r(F(a_nx))\le r(F(a_n))=r(e^{-\frac{1}{n}})$. Hence we get
\begin{align*}
 n \{(-\log F(a_nx))-(1-F(a_nx)) \} &= nr(F(a_nx))\le nr(e^{-\frac{1}{n}})\\
 &= n \{ (-\log e^{-\frac{1}{n}}) -(1-e^{-\frac{1}{n}})\} = O(n^{-1}).
\end{align*}
Since $u(a_n)\to 0$ as $n\to \infty$, for any $\epsilon\in (0,\alpha)$, there exists $n_0\in \N$ such that $|u(a_n)|<\epsilon$ for $n\ge n_0$. For such an $n$, we get
$$
|x^{-\alpha}-n(-\log F(a_nx))| \le \frac{1}{e(\alpha-\epsilon)} u(a_n)
$$
by the proof of \cite[Theorem 2.4]{KU25}. By Lemma \ref{lem:Estimate_h},
\begin{align*}
u(a_n) &= g(a_n) + \alpha (1-n(1-e^{-\frac{1}{n}}))\\
&= g(a_n) + \frac{\alpha}{2n}(1+ O(n^{-1}))  \\
&= O(g(a_n)\lor n^{-1}).
\end{align*}
Hence, the desired result is obtained.
\end{proof}


