\section{Proof of main theorem}
\label{sec:proof}

In this section, we provide a proof of Theorem \ref{thm:main}. We begin by presenting a partial result toward the main theorem.
\begin{prop}\label{prop:Estimate:booleanmax}
Given $\alpha>0$, let us consider $F\in \calV_{\alpha,+}$ and an auxiliary function $g$ with \eqref{eq:bound}. We define $a_n =F^{\leftarrow}(e^{-\frac{1}{n}})$. Then we obtain
\begin{align*}
\sup_{x\ge 1} |F^{\cup \hspace{-.52em} \lor n} (a_nx)- \Phi_{\alpha}^{\rm boolean}(x)| \le O(g(a_n)\lor n^{-1}).
\end{align*}
\end{prop}
\begin{proof}
For $x\ge 1$, we get
\begin{align*}
|F^{\cup \hspace{-.52em} \lor n} (a_nx)- \Phi_{\alpha}^{\rm boolean}(x)|
&=\left|\frac{F(a_nx)}{n-(n-1)F(a_nx)}-\frac{1}{1+x^{-\alpha}} \right|\\
&\le | F(a_nx)(1+x^{-\alpha}) - n + (n-1)F(a_nx)|\\
& \le |nF(a_nx)-n+x^{-\alpha}| + x^{-\alpha}(1-F(a_nx))\\
&=|F^{\Box\hspace{-.55em}\lor n}(a_nx) - \Phi_\alpha^{\rm free}(x)|  +x^{-\alpha}(1-F(a_nx))\\
& \le O(g(a_n)\lor n^{-1}) + 1-F(a_n)\\
& =  O(g(a_n)\lor n^{-1}),
\end{align*}
where the fifth inequality holds by Lemma \ref{lem:Estimate:freemax}.
\end{proof}

Notice that, for any $F\in \calV_{\alpha,+}$, we obtain
\begin{align*}
h_{\alpha,\calX(F)}(x) &= \frac{\calX(F)'(x)}{\calX(F)(x)(-\log \calX(F(x))}-\alpha = \frac{F'(x)}{F(x)(1-F(x))}-\alpha = k_{\alpha,F}(x).
\end{align*}
Thus, $|h_{\alpha,\calX(F)}|\le g$ on the neighborhood of $\infty$ by the assumption {\rm (ii)} of Definition \ref{def:F_alpha}. Thus if we choose $a_n'>0$ by $\calX(F)(a_n') = e^{-\frac{1}{n}}$ (equivalently, $F(a_n')=\frac{n}{n+1}$), then $\calX(F)^n(a_n'\cdot) \xrightarrow{w} \Phi_{\alpha}$ by \cite[Page 107]{R}. Moreover, it was known that, for any $x<1$,
$$
\Phi_{\alpha+ g(a_n'x)}(x) \le \calX(F)^n(a_n'x )  \le \Phi_{\alpha - g(a_n'x)}(x),
$$
due to \cite[Eq. (2.45)]{R}. Since $\calX^{\langle-1\rangle}$ is strictly increasing on $[0,1]$, we get
\begin{align}\label{eq:keyinequality}
\Phi_{\alpha+ g(a_n'x)}^{\rm boolean}(x)  \le F^{\cup \hspace{-.52em}\lor n}(a_n'x) \le \Phi_{\alpha - g(a_n'x)}^{\rm boolean}(x).
\end{align}

To estimate the distance between $F^{\cup \hspace{-.52em}\lor n}(a_n'x)$ and $\Phi_\alpha^{\rm boolean}$, we derive the following inequality for the Dagum distributions.

\begin{lem}\label{lem:Unif_Dagum}
For any $\alpha_1,\alpha_2>0$, we have 
$$\sup_{0<x<1} |\Phi_{\alpha_1}^{\rm boolean}(x)-\Phi_{\alpha_2}^{\rm boolean}(x)| \le  e^{-1} \ \dfrac{|\alpha_2-\alpha_1|}{\alpha_1 \land \alpha_2}.$$
\end{lem}
\begin{proof}
Without loss of generality, we may assume that $\alpha_1 <\alpha_2$. Note that 
$$
\frac{\partial}{\partial\beta} \frac{1}{1+x^{-\beta}} = \frac{x^\beta \log x}{(1+x^\beta)^2}
$$ 
for $\beta>0$ and $x\in (0,1)$. By the mean value theorem, for each $x\in (0,1)$, there exists $\gamma \in (\alpha_1,\alpha_2)$ such that
$$
|\Phi_{\alpha_1}^{\rm boolean}(x)-\Phi_{\alpha_2}^{\rm boolean}(x)| = \left|\frac{x^\gamma \log x}{(1+x^\beta)^2} \right| (\alpha_2-\alpha_1).
$$
Therefore, we get
\begin{align*}
\sup_{0<x<1} |\Phi_{\alpha_1}^{\rm boolean}(x)-\Phi_{\alpha_2}^{\rm boolean}(x)| 
&= \sup_{0<x<1} \left|\frac{x^\gamma \log x}{(1+x^\gamma)^2} \right| (\alpha_2-\alpha_1)\\
&\le \sup_{0<x<1} \sup_{\beta \in [\alpha_1, \alpha_2]} (-x^{\beta}\log x) (\alpha_2-\alpha_1)\\
&\le (\alpha_2-\alpha_1) \sup_{0<x<1} (-x^{\alpha_1} \log x)=e^{-1}\ \frac{\alpha_2-\alpha_1}{\alpha_1}.
\end{align*}
\end{proof}

\begin{prop}\label{prop:Estimate:booleanmax2}
Given $\alpha>0$, let us consider $F\in \calV_{\alpha,+}$ and an auxiliary function $g$ with \eqref{eq:bound}. Moreover, we define $a_n=F^{\leftarrow}(e^{-\frac{1}{n}})$. Then
\begin{align*}
\sup_{0<x<1}|F^{\cup \hspace{-.52em}\lor n}(a_n'x)- \Phi_\alpha^{\rm boolean}(x) | \le \frac{g(\rho(a_n))}{e(\alpha-g(\rho(a_n)))}
\end{align*}
for sufficiently large $n$, where the function $\rho$ is the inverse function of
$$
t\mapsto t\left\{ \frac{\alpha e}{g(t)} - (e+1)\right\}^{\frac{1}{\alpha -g(t)}}.
$$
\end{prop}
\begin{proof}
The proof is essentially the same as that of \cite[Proposition 2.13]{R}, it is included here for the reader’s convenience. By the inequality \eqref{eq:keyinequality}, for any $x\in (0,1)$, we have
$$
\Phi_{\alpha+ g(a_n'x)}^{\rm boolean}(x) -\Phi_{\alpha}^{\rm boolean}(x) \le F^{\cup \hspace{-.52em}\lor n}(a_n'x)-\Phi_{\alpha}^{\rm boolean}(x) \le \Phi_{\alpha - g(a_n'x)}^{\rm boolean}(x)-\Phi_{\alpha}^{\rm boolean}(x).
$$
By Lemma \ref{lem:Unif_Dagum}, we obtain
$$
|F^{\cup \hspace{-.52em}\lor n}(a_n'x)- \Phi_\alpha^{\rm boolean}(x) | \le \frac{g(a_n'x)}{e(\alpha-g(a_n'x))}.
$$
Since $F(a_n')=\frac{n}{n+1} \ge e^{-\frac{1}{n}}=F(a_n)$ and $F$ is a distribution function, we have $a_n' x \ge a_nx$ for each $x\in (0,1)$. The monotonicity of $g$ implies that
$$
\frac{g(a_n'x)}{e(\alpha-g(a_n'x))} \le \frac{g(a_nx)}{e(\alpha-g(a_nx))}.
$$
For any $x\in (0,1)$, we have
$$
|F^{\cup \hspace{-.52em}\lor n}(a_n'x)- \Phi_\alpha^{\rm boolean}(x) | \le \frac{g(a_nx)}{e(\alpha-g(a_nx))},
$$
and hence, for any sequences $\{x_n\}_n \subset (0,1)$ with $x_n\to 0$ and $a_nx_n\to \infty$ as $n\to \infty$, we get
$$
\sup_{x_n \le x <1} |F^{\cup \hspace{-.52em}\lor n}(a_n'x)- \Phi_\alpha^{\rm boolean}(x) | \le \frac{g(a_nx_n)}{e(\alpha-g(a_nx_n))}.
$$
For $x\le x_n$, we obtain
\begin{align*}
F^{\cup \hspace{-.52em}\lor n}(a_n'x) 
\le F^{\cup \hspace{-.52em}\lor n}(a_n'x_n)\le \Phi_{\alpha-g(a_n'x_n)}^{\rm boolean}(x_n) \le \Phi_{\alpha-g(a_nx_n)}^{\rm boolean}(x_n)
\end{align*}
and $\Phi_\alpha^{\rm boolean}(x_n) \le \Phi_{\alpha-g(a_nx_n)}^{\rm boolean}(x_n)$. Thus, we get
$$
\sup_{0<x<1}|F^{\cup \hspace{-.52em}\lor n}(a_n'x)- \Phi_\alpha^{\rm boolean}(x) | \le\frac{g(a_nx_n)}{e(\alpha-g(a_nx_n))} \lor \Phi_{\alpha-g(a_nx_n)}^{\rm boolean}(x_n).
$$
The choice of $x_n$ to minimize the right hand side is to satisfy
\begin{align}\label{eq:g=b}
\frac{g(a_nx_n)}{e(\alpha-g(a_nx_n))}=\Phi_{\alpha-g(a_nx_n)}^{\rm boolean}(x_n).
\end{align}
We explain how to choose such a $x_n$ as follows. Let us set 
$$
a(t):=\left(\frac{1}{-\log F}\right)^{\leftarrow}(t) = \inf \left\{u : \frac{1}{-\log F(u)}\ge t \right\}
$$ 
and define a non-decreasing function $\rho(t)$ via the relation $\rho(a(t))=a(t)x(t)$, where $x(t)$ is an unknown decreasing function such that $x(t)\to 0$ and $a(t)x(t) \to \infty$ as $t\to\infty$. We assume that $\rho(t)$ satisfies
$$
\frac{g(\rho(a(t)))}{e(\alpha-g(\rho(a(t))))} = \frac{1}{1+x(t)^{-(\alpha-g(\rho(a(t))))}}.
$$
This implies that, if let $\rho^{\leftarrow}(t)$ be the inverse function of $\rho(t)$ then it should be
\begin{align}\label{eq:rhoinversedef}
\rho^{\leftarrow}(t) = t\left\{ \frac{\alpha e}{g(t)} - (e+1)\right\}^{\frac{1}{\alpha -g(t)}}
\end{align}
for sufficiently large $t$ such that $g(t) < \alpha e(e+1)^{-1}$. Thus, one can see
\begin{align*}
\lim_{t\to \infty} \frac{\rho^{\leftarrow}(t)}{t}=\infty, \quad
\text{and hence} \quad
\lim_{t\to \infty} \frac{\rho (t)}{t}=0.
\end{align*}
Conversely, if we define the function $\rho^\leftarrow(t)$ by \eqref{eq:rhoinversedef} and consider $\rho(t)$ as the inverse function of $\rho^\leftarrow(t)$, then $x(t) = \rho(a(t))/a(t)$ satisfies $x(t)\to 0$ and $a(t)x(t) =\rho(a(t))\to \infty$ as $t\to\infty$. Therefore $x_n: = x(n)$ satisfies \eqref{eq:g=b}, and also we have
\begin{align*}
\sup_{0<x<1}|F^{\cup \hspace{-.52em}\lor n}(a_n'x)- \Phi_\alpha^{\rm boolean}(x) | \le\frac{g(\rho(a_n))}{e(\alpha-g(\rho(a_n)))}.
\end{align*}
\end{proof}

Finally, we prove the main theorem as follows.

\begin{proof}[Proof of Theorem \ref{thm:main}]
One can easily see that $|F^{\cup \hspace{-.52em}\lor n}(a_n x)- \Phi_\alpha^{\rm boolean} (x)|=0$ for $x\le 0$. Since $a_n' \ge a_n>0$, we have $A_n=a_n/a_n'\in (0,1]$. Furthermore, we get $A_n\to 1$ as $n\to \infty$. Hence, for any $0<x<1$,
\begin{align*}
|F^{\cup \hspace{-.52em}\lor n}(a_n x)- \Phi_\alpha^{\rm boolean} (x)| 
&= |F^{\cup \hspace{-.52em}\lor n}(a_n' (A_nx))- \Phi_\alpha^{\rm boolean} (x)|\\
&\le |F^{\cup \hspace{-.52em}\lor n}(a_n' (A_nx))- \Phi_\alpha^{\rm boolean} (A_nx)| + |\Phi_\alpha^{\rm boolean} (A_nx)-\Phi_\alpha^{\rm boolean} (x)|\\
&\le \frac{g(\rho(a_n))}{e(\alpha-g(\rho(a_n)))} +  |\Phi_\alpha^{\rm boolean} (A_nx)-\Phi_\alpha^{\rm boolean} (x)|
\end{align*}
by Proposition \ref{prop:Estimate:booleanmax2}. Since $\rho(a_n)\to \infty$, for any $0<\epsilon<\alpha$, there exists $n_0 \in \N$ such that $|g(\rho(a_n))|<\epsilon$ for $n\ge n_0$. Hence
$$
\frac{g(\rho(a_n))}{e(\alpha-g(\rho(a_n)))} = O(g(\rho(a_n))).
$$

On the other hand, it is easy to see
\begin{align*}
|\Phi_\alpha^{\rm boolean} (A_nx)-\Phi_\alpha^{\rm boolean} (x)| \le  \alpha \left(A_n^{-1}-1\right), \quad 0<x<1.
\end{align*}
Thus, 
$$
\sup_{0<x<1}|F^{\cup \hspace{-.52em}\lor n}(a_n x)- \Phi_\alpha^{\rm boolean} (x)|  \le O\left( g(\rho(a_n))\lor (A_n^{-1}-1)\right).
$$
Since $\frac{\rho(a_n)}{a_n}\to 0$ as $n\to \infty$, we have $g(\rho(a_n))\ge g(a_n)$ for sufficiently large $n$. Combining Proposition \ref{prop:Estimate:booleanmax} and the above estimates, we get the desired formula.
\end{proof}


\section{Application to the Fr\'{e}chet distribution}
\label{sec:application}

In this section, we apply Theorem \ref{thm:main} to the Fr\'{e}chet distribution $\Phi_\alpha$ ($\alpha>0$) which is in the Boolean max-domain of attraction of $\Phi_\alpha^{\rm boolean}$.

\begin{prop}\label{prop:appli}
Given $\alpha>0$, let us set $a_n=n^{\frac{1}{\alpha}}$. Then we have
\begin{align}\label{prop:asmpt}
\sup_{x\in \R} |\Phi_\alpha^{\cup \hspace{-.52em}\lor n}(a_n x) - \Phi_\alpha^{\rm boolean}(x)| \le O\left(\frac{1}{\sqrt{n}}\right).
\end{align}
for sufficiently large $n$.
\end{prop}
\begin{proof}
First, we define $a_n'>0$ by $\Phi_\alpha(a_n')=\frac{n}{n+1}$. It is easy to see that $a_n'=\left(\log (1+n^{-1})\right)^{\frac{1}{\alpha}}$. We obtain
$$
A_n= \left\{ n\log\left(1+\frac{1}{n}\right)\right\}^{\frac{1}{\alpha}} = 1 -\frac{1}{2\alpha n} + O\left(\frac{1}{n^2}\right),
$$
and therefore
$$
A_n^{-1}-1 = \frac{1}{2\alpha n}\left(1+O\left(\frac{1}{n}\right)\right), \qquad n\to \infty.
$$

Next, we compute the function $k_{\alpha, \Phi_\alpha}$ and define an auxiliary function $g$ with \eqref{eq:bound} as follows:
\begin{align*}
k_{\alpha, \Phi_\alpha}(x) = \alpha \left\{ \frac{x^{-\alpha}}{1-\exp(-x^{-\alpha})}-1 \right\} \quad \text{and} \quad g(x) :=\frac{\alpha}{x^\alpha-1}, \quad \text{respectively}.
\end{align*}

In this case, for sufficiently large $t$, we can compute the asymptotic expansion for the function
\begin{align}\label{eqrhoinverse}
t \left\{\frac{\alpha e}{g(t)} - (e+1) \right\}^{\frac{1}{\alpha-g(t)}} = t \{et^\alpha- (2e+1)\}^{\frac{t^\alpha-1}{\alpha t^\alpha -2\alpha}}.
\end{align}
One can see that
$$
\frac{t^\alpha-1}{\alpha t^\alpha -2\alpha} = \frac{1}{\alpha} (1+t^{-\alpha}+O(t^{-2\alpha})), \quad t \to \infty.
$$
Moreover, we get
\begin{align*}
\log\{et^\alpha- (2e+1) \} = 1+ \alpha \log t - \frac{2e+1}{e t^\alpha} + O(t^{-2\alpha}), \quad t \to \infty.
\end{align*}
Therefore, 
\begin{align*}
\{et^\alpha- (2e+1)\}^{\frac{t^\alpha-1}{\alpha t^\alpha -2\alpha}} 
&= \exp\left\{\frac{1}{\alpha}\left(1+t^{-\alpha}+O(t^{-2\alpha}) \right)\left(1+ \alpha \log t - \frac{2e+1}{e t^\alpha} + O(t^{-2\alpha}) \right) \right\}\\
&= \exp\left\{\frac{1}{\alpha} \left( 1+ \alpha \log t - \frac{e+1}{et^{\alpha}} + \alpha t^{-\alpha} \log t + O(t^{-2\alpha})\right) \right\}\\
&=e^{\frac{1}{\alpha}} t \cdot t^{t^{-\alpha}} (1+O(t^{-\alpha}))\\
&=e^{\frac{1}{\alpha}} t (1+ t^{-\alpha} \log t + O(t^{-2\alpha}(\log t)^2))(1+O(t^{-\alpha}))\\
&=e^{\frac{1}{\alpha}}t (1+O( t^{-\alpha} \log t )),
\end{align*}
as $t \to \infty$. Thus, we can conclude that
\begin{align}\label{eq:asympt_rhoinverse}
\eqref{eqrhoinverse} =e^{\frac{1}{\alpha}}t^2 (1+O( t^{-\alpha} \log t )), \quad t\to \infty.
\end{align}

Note that, the inverse function $\rho$ of \eqref{eqrhoinverse} exists for sufficiently large $t$, and the asymptotic expansion for $\rho$ is given by
\begin{align*}
\rho (x) = e^{-\frac{1}{2\alpha}}x^{\frac{1}{2}} (1+O(x^{-\frac{\alpha}{2}} \log x)), \quad x\to \infty,
\end{align*}
due to the formula \eqref{eq:asympt_rhoinverse}. The above formula implies that
$$
\rho (a_n) = e^{-\frac{1}{2\alpha}}n^{\frac{1}{2\alpha}} (1+ O (n^{-\frac{1}{2}}\log n)), \quad n\to \infty.
$$
Finally, we get
\begin{align*}
g(\rho(a_n)) = \frac{\alpha}{\rho(a_n)^\alpha -1} =\alpha e^{\frac{1}{2}} n^{-\frac{1}{2}} (1+ O(n^{-\frac{1}{2}}\log n)).
\end{align*}

Since
$$
g(\rho (a_n)) \lor n^{-1} \lor (A_n^{-1}-1) = g(\rho(a_n)) = \alpha e^{\frac{1}{2}} n^{-\frac{1}{2}} (1+ O(n^{-\frac{1}{2}}\log n))
$$
for sufficiently large $n$, the desired result \eqref{prop:asmpt} is obtained, due to Theorem \ref{thm:main}.
\end{proof}

\begin{rem}
According to \cite[Example 4.1]{U22}, a result on the rate of convergence in the free case was obtained via Stein's method. More precisely, the following bound holds:
$$
\sup_{x\in \R} |\Phi_\alpha^{\Box\hspace{-.52em}\lor n} (a_n x)- \Phi_\alpha^{\rm free}(x)| \le \frac{1}{n}
$$
where $n\ge 1$ and $a_n=n^{\frac{1}{\alpha}}$. This shows that, in the free case, the rate of convergence is of order $n^{-1}$. In contrast, our result in the Boolean case has a slower rate of convergence.
\end{rem}


