\begin{introthm}[Theorem \ref{exhaustion of expansion with radon controlled} and \ref{thm:Markov structure theorem}]\label{introthm structure theorem}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. Then the following are equivalent:
	\begin{enumerate}
		\item $\mathcal{G}$ is asymptotically expanding in measure.
		\item $\mathcal{G}^{(0)}$ admits an exhaustion by domains of expansion with bounded ratio.
		\item $\mathcal{G}^{(0)}$ admits an exhaustion by domains of Markov expansion with bounded ratio.
	\end{enumerate}
\end{introthm}

