\section{Preliminaries}\label{Preliminaries}
In this section, we recall the notions of groupoids and Markov kernels.

\subsection{Basic notions for groupoids}\label{Basic notions for groupoid}

Recall that a \emph{groupoid} $\mathcal{G}$ is a small category consists of a set $\mathcal{G}$, a subset $\mathcal{G}^{(0)}$ called the \emph{unit space}, two maps $\s,\r:\mathcal{G}\rightarrow \mathcal{G}^{(0)}$ called the \emph{source} and the \emph{range} maps, respectively, a composition law $(\gamma_1,\gamma_2) \mapsto \gamma_1\gamma_2$ for $(\gamma_1,\gamma_2)\in \mathcal{G}^{(2)}\coloneqq \{(\gamma_1,\gamma_2)\in \mathcal{G}\times \mathcal{G} ~|~\s(\gamma_1)=\r(\gamma_2)\}$ and an inverse map $\gamma \mapsto \gamma^{-1}$. There operations satisfy a couple of axioms, including the associativity law and the fact that $\mathcal{G}^{(0)}$ act as units. 
%A subset $Y\subseteq \mathcal{G}^{(0)}$ is called \emph{invariant} if $\r^{-1}(Y)=\s^{-1}(Y)$. 
For $A,B\subseteq \mathcal{G}$, we denote
\begin{itemize}
    \item $A^{-1}\coloneqq\{\gamma^{-1} ~|~ \gamma\in A\}$,
    \item $A \cdot B\coloneqq\{\gamma\in \mathcal{G} ~|~ \gamma=\gamma_1\gamma_2~\text{where}~\gamma_1\in A,\gamma_2 \in B\text{ with }\s(\gamma_1)=\r(\gamma_2)\}$.
\end{itemize}
We say that $A$ is \emph{symmetric} if $A=A^{-1}$, and \emph{unital} if $\Gz \subseteq A$. A subset $A\subseteq \mathcal{G}$ is called a \emph{bisection} if the restrictions of $\s,\r$ to $A$ are injective and recall from (\ref{EQ:alpha_K}) that we have the induced bijection $\tau_A\coloneqq\r|_A \circ (\s|_A)^{-1}: \s(A)\rightarrow \r(A)$.
%{\color{red}{To save notation, we simply write $\tau_A(B)$ for $\tau_A(B \cap \s(A))$ where $B \subseteq \Gz$. }}
%Note that in this case, $\alpha_{A^{-1}}\circ\alpha_{A}(B)=B\cap \s(A)$.

We also need the notion of length functions on groupoids:

\begin{defn}\label{length function}
Let $\mathcal{G}$ be a groupoid. A \emph{length function} on $\G$ is a map $\ell:\G \rightarrow \mathbb{R}^{+}$ such that $\ell(\mathcal{G}^{(0)})=\{0\}$ and
\begin{enumerate}
    \item $\ell(\gamma^{-1})=\ell(\gamma)$ for all $\gamma\in \mathcal{G}$;
    \item $\ell(\gamma_1\gamma_2) \leq \ell(\gamma_1)+\ell(\gamma_2)$ for all $\gamma_1, \gamma_2 \in \G$ with  $\s(\gamma_1)=\r(\gamma_2)$.
\end{enumerate}
\end{defn}

Given a length function $\ell$ on a groupoid $\G$ and $n\in \N$, denote the closed ball
\begin{equation}\label{EQ:Kn}
B_n\coloneqq\{\gamma \in \mathcal{G} ~|~ \ell(\gamma)\leq n\}.
\end{equation}
Clearly $\{B_n\}_{n\in \N}$ is a sequence of increasing subsets in $\G$ satisfying:
\begin{itemize}
\item $\Gz \subseteq B_0$ and $B_n$ is symmetric for $n\in \mathbb{N}$;
\item $B_n \cdot B_m \subseteq B_{n+m}$ for $n,m \in \N$;
\item $\mathcal{G}=\bigcup_{n\in \N} B_n$.
\end{itemize}
Conversely, given an increasing sequence $\{B_n\}_{n\in \N}$ of subsets in $\G$ satisfying the three conditions above, we can construct a function $\tilde{\ell}$ on $\G$ by
\begin{equation}\label{EQ:tilde ell}
\tilde{\ell}(\gamma)\coloneqq\inf\left\{n\in \N ~|~ \gamma\in B_n\right\} \quad \text{for} \quad \gamma \in \G.
\end{equation}
It is routine to check that $\tilde{\ell}$ is a length function on $\G$. Moreover, it is easy to see:


\begin{lem}\label{length function2}
Given a length function $\ell$ on a groupoid $\G$, let $\{B_n\}_{n\in \N}$ be the sequence from Equation (\ref{EQ:Kn}) and define the length function $\tilde{\ell}$ on $\G$ using (\ref{EQ:tilde ell}). Then $\ell$ and $\tilde{\ell}$ are \emph{coarsely equivalent} in the sense that for any $r> 0$, we have:
\[
\sup\{\tilde{\ell}(\gamma) ~|~ \ell(\gamma)\leq r\} < \infty\quad\text{and}\quad\sup\{\ell(\gamma) ~|~ \tilde{\ell}(\gamma)\leq r\}< \infty.
\]
%Hence in the sequel, we can assume that length functions on the groupoid are of the form (\ref{EQ:tilde ell}) if necessary.
\end{lem}


