\begin{defn}\label{admissible}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a measure space. A bisection $K \subseteq \G$ is called \emph{admissible} if $\s(K),\r(K) \in \RR$, $\tau_K: \s(K)\rightarrow \r(K)$ is a measure-class-preserving measurable isomorphism, and $\ell(K)\coloneqq\sup\{\ell(x) ~|~ x\in K\}$ is finite. 
\end{defn}


We record the following elementary observation, whose proof is straightforward and hence omitted.

\begin{lem}\label{inverse,union,composition,intersection still admissible}
If $K,K_1,K_2 \subseteq \G$ are admissible bisections, then $K^{-1}$ and $K_1\cdot K_2$ are also admissible bisections.
\end{lem}


Based on Definition \ref{admissible}, we further introduce the following, which is also motivated from the case of group actions  as explained in Section \ref{sec:intro}.


\begin{defn}\label{decomposable}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a measure space. A subset $K \subseteq \G$ is called \emph{decomposable} if $K=\bigcup_{i=1}^{N} K_{i}$ for $N \in \N$ and admissible bisections $K_i$. 

Given a unital symmetric decomposable $K \subseteq \G$, a decomposition $K=\bigcup_{i=1}^N K_i$ is called \emph{unital} if $K_i = \Gz$ for some $i$ and \emph{symmetric} if there exists a bijection $\sigma:\{1,2,\cdots,N\} \to \{1,2,\cdots,N\}$ such that $K_i^{-1} = K_{\sigma(i)}$. We say that $K$ is \emph{$N$-decomposable} if there exists a unital symmetric decomposition $K=\bigcup_{i=1}^N K_i$ for admissible $K_i$. 
%It is clear that each unital and symmetric decomposable subset admits a unital and symmetric decomposition.
\end{defn}



Applying Lemma \ref{inverse,union,composition,intersection still admissible}, we obtain the following:

\begin{lem}\label{inverse,union,composition still decomposable}
\begin{enumerate}
 \item If $K$ is $N$-decomposable with $\ell(K) \leq L$, then $K^{-1}$ is $N$-decomposable with $\ell(K^{-1}) \leq L$.
 \item If $K_i$ is $N_i$-decomposable with $\ell(K_i) \leq L_i$ for $i=1,2$, then $K_1 \cup K_2$ is $(N_1+N_2)$-decomposable with $\ell(K_1 \cup K_2) \leq \max\{L_1, L_2\}$ and $K_1\cdot K_2$ is $N_1N_2$-decomposable with $\ell(K_1 \cdot K_2) \leq L_1 + L_2$.
\end{enumerate}
\end{lem}


The following easy observation is useful to define (asymptotic) expansion for groupoids later.

\begin{lem}\label{basic assumprop2}
If $K \subseteq \G$ is decomposable and $A \subseteq \Gz$ is measurable, then $\r(K\cdot A)$ is measurable.
\end{lem}

\begin{proof} 
By definition, we can write $K=\bigcup_{i=1}^N K_i$ for admissible bisection $K_i$. Then:
%Let $A\subseteq \mathcal{G}^{(0)}$ be a measurable subset, then 
\[
\r(K\cdot A)=\r\left(\bigcup_{i=1}^{N} K_{i}\cdot A\right)=\bigcup_{i=1}^{N}\tau_{K_{i}}(A\cap \s(K_{i})),
\]
which is measurable since each $\tau_{K_i}$ is a measurable isomorphism on $\s(K_i)$.
\end{proof}

Finally, note that the notion of admissible bisections and decomposability remain the same if we change the length function up to coarse equivalence.
