\subsection{Markov kernel}
Here we recall a few elementary properties of reversible Markov kernels, which will be used later to establish our main results. We refer to the first chapters of \cite{Rev75} for more background and details.


\begin{defn}\label{def of Markov kernel}
	Let $\S$ be a $\sigma$-algebra on a set $X$. A \emph{Markov kernel} on the measurable space $(X,\S)$ is a function $\Pi\colon X\times\S \to [0,1]$ such that:
	\begin{enumerate}
		\item for every $x\in X$, the function $\Pi(x,\variable)\colon\S \to[0,1]$ is a probability measure;
		\item for every $A\in \S$, the function $\Pi(\variable,A)\colon X\to[0,1]$ is $\S$-measurable.
	\end{enumerate}
\end{defn}

The associated \emph{Markov operator} $\P$ is a linear operator on the space of bounded $\S$-measurable functions, defined by
\begin{equation}\label{EQ:Markov operator defn}
\P f(x)\coloneqq  \int_{X}f(y)\Pi(x,\d y).
\end{equation}

\begin{defn}\label{defn:markov boundary}
	Given a measure $\mu$ on $(X,\S)$ and $A\in\S$, the \emph{($\mu$-)size of the boundary} of $A$ (with respect to $\Pi$) is defined as
	\[
	|\partial_\Pi (A)|_\mu\coloneqq\int_A\Pi(x,X\setminus A)\d \mu(x).
	\]
\end{defn}

We are only interested in the special case of reversible Markov kernel:

\begin{defn}
A Markov kernel $\Pi$ is called \emph{reversible} if there exists a measure $m$ on $(X,\S)$ such that
\[
\int_X f(x)\P g(x)\d m(x)=\int_X \P f(x) g(x)\d m(x)
\]
for every pair of measurable bounded functions $f,g: X\to\mathbb{R}$. The measure $m$ is called a \emph{reversing measure} for $\Pi$ (note that $m$ need not be unique in general). In this case, we also say that $\Pi$ is a reversible Markov kernel \emph{on $(X,m)$}.
\end{defn}

Given a reversing measure $m$ on $X$,
