%	|\partial_{\Pi}(A)|_m= \nu(A\times (X\setminus A)) = \nu((X\setminus A) \times A) = |\partial_{\Pi}(X\setminus A)|_m.
%\end{equation}
the Markov operator $\P$ can be regarded as a bounded self-adjoint operator on $L^2(X,m)$ with norm $\|\P\|\leq 1$. 
%Since $m$ is reversing, the operator $\P$ is self-adjoint.
Define the \emph{Laplacian} of $\Pi$ as $\Delta\coloneqq 1-\P$, which is a positive self-adjoint operator whose spectrum is contained in $[0,2]$.

Let $\Pi$ be a reversible Markov kernel on $(X,m)$, where $m$ is a finite measure. Then all constant functions on $X$ belong to $L^2(X,m)$ and are fixed by $\P$. It follows that $\|\P\|=1$ and $1$ belongs to the spectrum of $\P$. Denote the orthogonal complement of the constant functions in $L^2(X,m)$ by $L^2_0(X,m)$, \emph{i.e.}, 
\[
L^2_0(X,m)\coloneqq \left\{f\in L^2(X,m) ~\middle|~ \int_X f(x)\d m(x)=0\right\}.
\]
Note that $L^2_0(X,m)$ is $\P$-invariant and that the spectrum of the restriction of $\P$ on $L^2_0(X,m)$ is contained in $[-1,1]$. We denote the supremum of this spectrum by $\lambda\in \mathbb{R}$. We make the following definition:

\begin{defn}\label{spectral gap markov kernel}
	A reversible Markov kernel on a finite measure space $(X,m)$ is said to have a \emph{spectral gap} if $\lambda<1$. 
\end{defn} 


On the other hand, we recall the notion of Cheeger constant as follows:
\begin{defn}\label{defn:Cheeger.constant.Markov}
	The \emph{Cheeger constant} for a reversible Markov kernel $\Pi$ on a finite measure space $(X,m)$ is defined to be
	\[
	\kappa\coloneqq\inf\left\{\frac{|\partial_\Pi (A)|_m}{m(A)}\;\middle|\; A\in\S,\ 0<m(A)\leq\frac 12 m(X)\right\}.
	\]
\end{defn}

Consequently, we have the following significant result relating the spectral gap with the Cheeger constant from \cite{lawler1988bounds} (see also \cite{li2022markovianroealgebraicapproachasymptotic}):
