\begin{thm}[{\cite[Theorem 2.1]{lawler1988bounds}}]\label{thm:spectral.characterisation.markov.exp}
	Let $\Pi$ be a reversible Markov kernel on $(X,m)$ where $m$ is finite. Then
	\[
	\frac{\kappa^2}{2} \leq 1-\lambda\leq 2\kappa.
	\]
\end{thm}




\section{Asymptotic expansion in measure and structure theorems}\label{sec:asymptotic expansion}

In this section, we introduce the notion of expansion and asymptotic expansion for groupoids and then establish their structure theory. This generalises both (measured) asymptotic expanders in \cite{structure, Li2019QuasilocalAA, faucris.282438222} and asymptotic expansion in measure for group actions in \cite{asymptoticexpansionandstrongergodicity, li2022markovianroealgebraicapproachasymptotic}. 

Again we always assume that $\G$ is a groupoid with a length function $\ell$, and $\Gz$ is equipped with a measure $\mu$ on some $\sigma$-algebra $\RR$. In this section, we require $\mu$ to be finite. For simplicity, further assume that $\mu$ is a \textbf{probability measure}. Note that all the results in this section are also available for finite measures by rescaling.



\subsection{Expansion and asymptotic expansion}\label{Expansion and asymptotic expansion on Borel groupoids}
We firstly introduce the following:


\begin{defn}\label{expanding}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. We say that $\G$ is \emph{expanding (in measure $\mu$)} if there exist $C,N,L>0$ and a unital symmetric\footnote{Since we are only interested in the existence of $K$, we can always make it unital and symmetric.} $N$-decomposable $K \subseteq \G$ with $\ell(K) \leq L$ such that for any $A \in \RR$ with $0 < \mu(A) \leq \frac{1}{2}$, then $\mu(\r(K \cdot A)\setminus A)> C \mu(A)$. 
In this case, we also say that $\G$ is $(C,N,L)$-\emph{expanding}.
\end{defn}

The inequality ``$\mu(\r(K \cdot A)\setminus A)> C \mu(A)$'' in the definition above makes sense since $\r(K \cdot A)$ is measurable thanks to Lemma \ref{basic assumprop2}.

%\begin{defn}\label{expanding}
%Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. Given $C,L>0$ and $N\in \N$, we say that $\mathcal{G}$ is \emph{$(C,N,L)$-expanding (in measure) (}or simply, $\G$ is \emph{expanding} or $(N,L)$-\emph{expanding)} if there exists an $N$-decomposable $K \subseteq \G$ with $\ell(\G) \leq L$ such that for any $A \in \RR$ with $0 < \mu(A) \leq \frac{1}{2}$, we have $\mu(\r(K \cdot A)\setminus A)> C \mu(A)$. 
