In the following, we collect several useful facts for domains of (asymptotic) expansion, generalising those in \cite{asymptoticexpansionandstrongergodicity,faucris.282438222}. They will play an important role to prove the structure result later.

\begin{lem}\label{extend to beta}
Let $Y\subseteq \mathcal{G}^{(0)}$ be a domain of asymptotic expansion. Then for any $\alpha \in (0,\frac{1}{2}]$ and $\beta \in [\frac{1}{2},1)$, there exist $C,N,L>0$ and a unital symmetric $N$-decomposable $K \subseteq \mathcal{G}$ with $\ell(K) \leq L$ such that for any measurable $A\subseteq Y$ with $\alpha \mu(Y) \leq \mu(A) \leq \beta \mu(Y)$, we have:
\[
\mu\big((\r(K \cdot A)\setminus A)\cap Y\big)> C \mu(A). 
\]
Here $C,N,L$ only depend on $\alpha,\beta$ and expansion parameters for $Y$.
\end{lem}

\begin{proof}
For $\beta\in [\frac{1}{2},1)$, set $\alpha'=\frac{1-\beta}{2} \in (0,\frac{1}{4}]$. 
By assumption, there exist $C_{\alpha'}, L_{\alpha'}, N_{\alpha'}>0$ and a unital symmetric $N_{\alpha'}$-decomposable $K_{\alpha'} \subseteq \G$ with $\ell(K_{\alpha'}) \leq L_{\alpha'}$ such that for any measurable $A \subseteq Y$ with $\alpha'\mu(Y) \leq \mu(A) \leq \frac{1}{2}\mu(Y)$, we have:
\begin{equation}\label{EQ:expansion beta}
\mu\big((\r(K_{\alpha'} \cdot A)\setminus A)\cap Y\big)> C_{\alpha'} \mu(A).
\end{equation}
%Without loss of generality, assume $C_{\alpha'} \in (0,1)$.

Given measurable $A\subseteq Y$ with $\mu(A)\in [\frac{1}{2} \mu(Y),\beta \mu(Y)]$, let 
\[
B=Y\setminus \r(K_{\alpha'} \cdot A).
\] 
Then $\mu(B)\leq \mu(Y\setminus A)\leq \frac{1}{2} \mu(Y)$. Now we divide into two cases:

If $\mu(B)< \alpha' \mu(Y)$, then $\mu\big(\r(K_{\alpha'} \cdot A)\cap Y\big)> (1-\alpha')\mu(Y) \geq \frac{1+\beta}{2\beta} \mu(A)$. Hence we obtain $\mu\big((\r(K_{\alpha'}\cdot A)\setminus A)\cap Y\big)> \frac{1-\beta}{2\beta} \mu(A)$.
%> \uC(\alpha')\frac{1-\beta}{2\beta} \mu(A)$.

If $\mu(B)\geq \alpha' \mu(Y)$, Inequality (\ref{EQ:expansion beta}) implies $\mu((\r(K_{\alpha'} \cdot B)\setminus B)\cap Y)> C_{\alpha'} \mu(B)$. Then:
%By the construction of $B$, we have 
\[
\big(\r(K_{\alpha'}\cdot B)\setminus B\big)\cap Y \subseteq \big(\r(K_{\alpha'}\cdot A)\setminus A\big)\cap Y.
\]
Hence
%Since $K_{\alpha{'}}\cup (K_{\alpha'})^{-1}$ is symmetric and $B=Y\setminus (\r((K_{\alpha'}\cup (K_{\alpha'})^{-1}\cup \mathcal{G}^{(0)})A)\cap Y)$, we have 
\[
\mu\big((\r(K_{\alpha'}\cdot A)\setminus A)\cap Y\big) \geq \mu\big((\r(K_{\alpha'}\cdot B)\setminus B)\cap Y\big)> C_{\alpha'}\frac{1-\beta}{2\beta} \mu(A).
\]

Finally, set
\[
C\coloneqq \min\left\{C_{\alpha},\frac{1-\beta}{2\beta} C_{\alpha'}, \frac{1-\beta}{2\beta}\right\} \quad \text{and} \quad K\coloneqq K_\alpha \cup K_{\alpha'}.
\]
Then $K$ is unital symmetric and $(N_\alpha+N_{\alpha'})$-decomposable with $\ell(K) \leq \max\{L_{\alpha}, L_{\alpha'}\}$. Hence we conclude the proof.
% and $K_{\alpha,\beta}=K_\alpha \cup K_{\alpha'}\cup (K_{\alpha'})^{-1}$ which is $(\uN(\alpha)+2\uN(\alpha'),\max\{\uL(\alpha), \uL(\alpha')\})$-decomposable and then we finish the proof.
\end{proof}


\begin{lem}\label{subset also asym expansion1}
Assume $\mathcal{G}$ is asymptotically expanding in measure. Then for any $\beta\in (0,1],\alpha \in (0,\frac{1}{2}]$ and $C\in (0,1)$, there exists a unital symmetric $N$-decomposable $K\subseteq \mathcal{G}$ with $\ell(K) \leq L$ such that for any measurable $Y\subseteq \mathcal{G}^{(0)}$ with $\mu(Y)\geq \beta$ and measurable $A\subseteq Y$ with $\alpha \mu(Y)\leq \mu(A)\leq \frac{1}{2}\mu(Y)$, we have $\mu((\r(K \cdot A)\setminus A)\cap Y)> C \mu(A)$. Here $N,L$ only depend on $\alpha,\beta,C$ and expansion parameters of $\G$.
\end{lem}

\begin{proof}
Fix $\alpha\in (0,\frac{1}{2}],\beta\in (0,1]$, $C\in (0,1)$ and a measurable $Y \subseteq \Gz$ with $\mu(Y)\geq \beta$. Set $\epsilon\coloneqq \frac{1+C}{2}\mu(Y)$ and $\gamma\coloneqq\mu(\mathcal{G}^{(0)}\setminus Y)+\epsilon=1-\frac{1-C}{2}\mu(Y)$. It suffices to find a unital symmetric decomposable $K \subseteq \G$ such that for any measurable $A\subseteq Y$ with $\alpha \mu(Y)\leq \mu(A)\leq \frac{1}{2}\mu(Y)$, then $\mu(\r(K\cdot A))>\gamma$. If this holds, then the proof would be completed by the following estimate:
\[
\mu\big(\r(K\cdot A)\cap Y\big)>\gamma-\mu(\G^{(0)}\setminus Y)=\epsilon\geq \frac{2\epsilon}{\mu(Y)}\mu(A)=(1+C)\mu(A).
\]

Now we aim to find such a $K$. Since $\G$ is asymptotically expanding, Lemma \ref{extend to beta} provides $C',L', N'>0$ and a unital symmetric $N'$-decomposable $K'\subseteq \G$ with $\ell(K') \leq L'$ such that for any measurable $A'\subseteq \G^{(0)}$ with $\alpha\beta\leq \mu(A')\leq 1-\frac{1-C}{2}\beta$, then
\begin{equation}\label{EQ:expansion subspace proof}
\mu\big(\r(K'\cdot A')\big)>(1+C')\mu(A')\geq (1+C')\alpha\beta.
\end{equation}
Set $m$ to be the minimal integer satisfying $(1+C')^m \geq \frac{1}{\alpha\beta}$, and take $K\coloneqq (K')^m$. 
Then Lemma \ref{inverse,union,composition still decomposable} shows that $K$ is unital symmetric $(N')^m$-decomposable and $\ell(K) \leq mL'$.

Now for any measurable $A\subseteq Y$ with $\alpha \mu(Y)\leq \mu(A)\leq \frac{1}{2}\mu(Y)$, we need to show that $\mu(\r(K\cdot A))>\gamma$. If not, then $\mu\big(\r((K')^m \cdot A)\big)\leq \gamma$. This shows that
\[
\alpha\beta\leq \mu\big(\r((K')^i\cdot A)\big)\leq \gamma\leq 1-\frac{1-C}{2}\beta\quad\text{for any}\quad  i=0,1,\cdots m.
\]
Applying Inequality (\ref{EQ:expansion subspace proof}) inductively, we obtain:
\[
\mu\big(\r((K')^m \cdot A)\big)>(1+C')^m \mu(A)\geq (1+C')^m \alpha\beta \geq 1 >\gamma,
\]
which leads to a contradiction.
\end{proof}




\subsection{The structure theorem}\label{ssec:structure thm}

Now we are in the position to introduce the structure theorem for asymptotic expansion on groupoids. The main idea is to approximate by domains of expansions in the following sense:

\begin{defn}\label{def of uniform exhaustion}
	Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space.  We say that a sequence of measurable subsets $\{Y_n\}_{n\in \N}$ in $\mathcal{G}^{(0)}$ \emph{forms a (measured) exhaustion of $\Gz$} if $\lim_{n\to \infty}\mu(Y_n)=1$.
\end{defn}

%\begin{defn}\label{def of uniform exhaustion}
%	Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space.  Given a sequence $\ubar{t}=\{t_n\}_{n\in \N} \subseteq [0,1]$ with $\lim_{n\to \infty} t_n=1$ and a sequence of measurable subsets $\{Y_n\}_{n\in \N}$ in $\mathcal{G}^{(0)}$, we say that $\{Y_n\}_{n\in \N}$ \emph{forms a $\ubar{t}$-exhaustion} (or simply, \emph{an exhaustion}) \emph{of $\Gz$} if $\mu(Y_n)\geq t_n $ for each $n\in \N$.
%\end{defn}


For technical reasons, we also need to consider:

\begin{defn}\label{defn:RN der}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. Given an admissible bisection $K \subseteq \G$, we set
\begin{equation}\label{EQ:RN der}
\RN(K,x)\coloneqq \frac{\d (\tau_K^{-1})_\ast \mu|_{\r(K)}}{\d \mu|_{\s(K)}}(x)
\end{equation}
the Radon-Nikodym derivative at $x\in \s(K)$, where $\tau_K$ comes from (\ref{EQ:alpha_K}). Here $\mu|_{\s(K)}$ and $\mu|_{\r(K)}$ are the restrictions of $\mu$, and $(\tau_K^{-1})_\ast \mu|_K$ is the push-forward measure defined by $\big((\tau_K^{-1})_\ast \mu|_{\r(K)}\big)(A) = \mu(\tau_K(A))$ for measurable $A \subseteq \s(K)$.
\end{defn}


To simplify the statement of our main result, let us package the derivative information into the notion of domain of expansion:

\begin{defn}\label{defn:domain of expansion with bdd ratio}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. For measurable $Y \subseteq \Gz$, we say that $Y$ is a \emph{domain of expansion with bounded ratio} if there exist $C,N,L>0$ and a unital symmetric $N$-decomposable $K \subseteq \G$ with $\ell(K) \leq L$, together with a unital symmetric decomposition $K= \bigcup_{i=1}^N K_i$ satisfying the following:
\begin{enumerate}
 \item for measurable $A \subseteq Y$ with $0 < \mu(A) \leq \frac{1}{2}\mu(Y)$, then we have
 \[
 \mu\big((\r(K_\alpha \cdot A)\setminus A)\cap Y\big)> C_\alpha \mu(A).
 \]
\item there exists $\theta\geq 1$ such that $\frac{1}{\theta}\leq \RN(K_i,x)\leq \theta$ for any $x\in Y$ and $i \in \{1,2,\ \cdots,N\}$ with $\tau_{K_i}(x) \in Y$. (As a priori to $\tau_{K_i}(x) \in Y$, we have $x\in \s(K_i)$ and hence $\RN(K_i,x)$ makes sense.)
\end{enumerate}
In this case, we say that $Y$ is a \emph{domain of $(C,N,L)$-expansion with ratio bounded by $\theta$}.
\end{defn}



The following is our structure theorem:

\begin{thm}\label{exhaustion of expansion with radon controlled}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. Then the following are equivalent:
	\begin{enumerate}
		\item The groupoid $\mathcal{G}$ is asymptotically expanding in measure.
		\item The unit space $\mathcal{G}^{(0)}$ admits an exhaustion by domains $Y_n$ of $(C_n,N_n,L_n)$-expansion of ratio bounded by $\theta_n$ for $C_n,N_n,L_n >0$ and $\theta_n \geq 1$.
%		\item The unit space $\mathcal{G}^{(0)}$ admits an exhaustion by domains of $(c_n,K_n)$-expansion $Y_n$ where $K_n=\bigcup_{i=1}^{N_n} K_{n,i}$ for admissible $K_{n,i}$ such that there exists $\theta_n\geq 1$ satisfying $\frac{1}{\theta_n}\leq \RN(K_{n,i},x)\leq \theta_n$ for every $x\in Y_n$ and $i$ with $\alpha_{K_{n,i}}(x) \in Y_n$.
		\item The unit space $\mathcal{G}^{(0)}$ admits an exhaustion by domains of asymptotic expansion.
	\end{enumerate}
\end{thm}

Here the extra requirement on the Radon-Nikodym derivatives in condition (2) will play an important role to prove our main results in Section \ref{sec:Main results}. 

A key tool to prove Theorem \ref{exhaustion of expansion with radon controlled} is to consider maximal F{\o}lner sets as follows.


\begin{defn}\label{Folner set}
Given measurable $Y\subseteq \mathcal{G}^{(0)}$, decomposable $K \subseteq \G$ and $\epsilon > 0$, we say that a measurable subset $F \subseteq Y$ is \emph{$(\epsilon,K)$-F\o lner in $Y$} if $\mu(F)\leq \frac{1}{2}\mu(Y)$ and 
\[
\mu\big((\r(K\cdot F)\setminus F)\cap Y\big)\leq \epsilon\mu(F).
\]
When $Y=\Gz$, we simply say that $F$ is \emph{$(\epsilon,K)$-F\o lner}.
\end{defn}

Now fix measurable $Y\subseteq \mathcal{G}^{(0)}$, decomposable $K \subseteq \G$ and $\epsilon > 0$. Denote the set of all $(\epsilon,K)$-F\o lner sets in $Y$ by $\mathcal{F}_{\epsilon,K}$. Consider the equivalence relation on $\mathcal{F}_{\epsilon,K}$ by setting $F\sim F'$ in $\mathcal{F}_{\epsilon,K}$ if and only if they differ by a null-set. Define a partial order on $\mathcal{F}_{\epsilon,K}/\sim$ by setting $[F]\sqsubseteq [F']$ if $F\subseteq F'$ up to null-sets.

The following lemma is similar to \cite[Lemma 4.2]{asymptoticexpansionandstrongergodicity}:

\begin{lem}\label{lem:maximal Folner set}
The partial ordered set $(\mathcal{F}_{\epsilon,K}/\sim,\sqsubseteq)$ has maximal elements.
\end{lem}

\begin{proof}
Take an arbitrary $F_0\in \mathcal{F}_{\epsilon,K}$ and set $\beta_0\coloneqq \sup\{\mu(F)~|~F\in \mathcal{F}_{\epsilon,K} \text{ and } F_0\subseteq F\}$. Inductively, we choose $F_n\in \mathcal{F}_{\epsilon,K}$ such that $F_{n-1}\subseteq F_n$ and $\mu(F_n)> \beta_{n-1}-\frac{1}{n}$ where 
\[
\beta_n\coloneqq \sup\left\{\mu(F)~|~F\in \mathcal{F}_{\epsilon,K} \text{ and } F_n\subseteq F\right\}.
\]
%Clearly $\beta_{n+1}\leq \beta_n \leq \frac{1}{2}\mu(Y)$.
If $\beta_n=\mu(F_n)$ for some $n$, then $[F_n]$ is maximal. Otherwise, we obtain an increasing sequence $\{F_n\}_{n \in \N}$. Setting $F\coloneqq\bigcup_{n\in \mathbb{N}}F_n$ and similar to the proof of \cite[Lemma 4.2]{asymptoticexpansionandstrongergodicity}, we obtain that $[F]$ is maximal. 
\end{proof}


Maximal F{\o}lner sets are useful to produce domains of expansions, which are crucial to prove Theorem \ref{exhaustion of expansion with radon controlled}. We start with the following:


\begin{lem}\label{lem:expansion and Folner set}
Given measurable $Y\subseteq \mathcal{G}^{(0)}$, decomposable $K \subseteq \G$ and $\epsilon > 0$, let $F_{\epsilon,K}\subseteq Y$ be a maximal $(\epsilon,K)$-F\o lner set in $Y$. Then for any measurable $A\subseteq Y\setminus F_{\epsilon,K}$ with $0< \mu(A)\leq \frac{1}{2}\mu(Y)-\mu(F_{\epsilon,K})$, we have 
\[
\mu\big(((\r(K\cdot A)\setminus A)\cap Y)\setminus F_{\epsilon,K}\big)> \epsilon\mu(A).
\]
\end{lem}

\begin{proof}
Given such an $A\subseteq Y\setminus F_{\epsilon,K}$, we have $\mu(F_{\epsilon,K})< \mu(A\sqcup F_{\epsilon,K})\leq \frac{1}{2}\mu(Y)$ and $\big(\r(K\cdot(A\sqcup F_{\epsilon,K}))\setminus (A\sqcup F_{\epsilon,K})\big)\cap Y$ is contained in 
\[
\big(((\r(K\cdot A)\setminus A)\cap Y)\setminus F_{\epsilon,K}\big) \cup \big((\r(K\cdot F_{\epsilon,K})\setminus F_{\epsilon,K})\cap Y\big).
\]
By the maximality of $F_{\epsilon,K}$, it follows that 
\begin{align*}
\epsilon\mu(A\sqcup F_{\epsilon,K}) &< \mu\big((\r(K\cdot(A\sqcup F_{\epsilon,K}))\setminus (A\sqcup F_{\epsilon,K}))\cap Y\big)\\ &\leq\mu\big(((\r(K\cdot A)\setminus A)\cap Y)\setminus F_{\epsilon,K}\big)+\mu\big((\r(K\cdot F_{\epsilon,K})\setminus F_{\epsilon,K})\cap Y\big).
\end{align*}
Since $\mu\big((\r(K\cdot F_{\epsilon,K})\setminus F_{\epsilon,K})\cap Y\big) \leq \epsilon\mu(F_{\epsilon,K})$, we have
\[
\epsilon\mu(A)<
\mu\big(((\r(K\cdot A)\setminus A)\cap Y)\setminus F_{\epsilon,K}\big).
\]
Then we finish the proof.
\end{proof}


\begin{proof}[Proof of Theorem \ref{exhaustion of expansion with radon controlled}]
	``$(1)\Rightarrow(2)$'': Fix $C\in (0,\frac{1}{2})$ and let $\alpha_n \coloneqq \frac{C}{(4+2C)(n+1)}$ for each $n \in \N$. Since $\G$ is asymptotically expanding, Lemma \ref{subset also asym expansion1} provides a unital symmetric $N_n$-decomposable $K_n$ with $\ell(K_n) \leq L_n$ satisfying the condition therein for $\beta=\frac{1}{2}$, $\alpha=\alpha_n$ and $C$. Take a unital symmetric decomposition $K_n=\bigcup_{i=1}^{N_n} K_{n,i}$ for admissible $K_{n,i}$ and set $\theta_n\coloneqq N_n\cdot (n+1)$. Denote
\[
	Z_n \coloneqq \left\{\tau_{K_{n,i}}(x)~\middle|~x\in \s(K_{n,i}) \text{ and } i=1,\cdots, N_n \text{ such that } \RN(K_{n,i},x) < \frac{1}{\theta_n}\right\}.
\]
Then $\mu(Z_n)< \frac{N_n}{\theta_n}\cdot \mu(\mathcal{G}^{(0)})=\frac{1}{n+1}$, which implies that 
	\[
	\mu(\mathcal{G}^{(0)}\setminus Z_n)\geq \frac{n}{n+1}\geq \frac{1}{2}.
	\]

	Let $X_n\coloneqq \mathcal{G}^{(0)}\setminus Z_n$, and take $F_n$ to be a maximal $(C,K_n)$-F\o lner sets in $X_n$, ensured by Lemma \ref{lem:maximal Folner set}. Then we have $\mu(F_n) < \alpha_n\cdot \mu(X_n)$. Setting $Y_n\coloneqq X_n \setminus F_n$, then $\mu(Y_n)> (1-\alpha_n)\mu(X_n)\geq (1-\alpha_n)\cdot \frac{n}{n+1}$.

Now we claim that $Y_n$ is a domain of $(\frac{C}{2},N_n, L_n)$-expansion. In fact, we take an arbitrary measurable $A \subseteq Y_n$ with $0< \mu(A)\leq \frac{1}{2}\mu(Y_n)$ and divide into two cases:

\noindent \textbf{Case I.} If $\mu(A)\leq \frac{1}{2}\mu(X_n)-\mu(F_n)$, then by Lemma \ref{lem:expansion and Folner set} we have
	\[
	\mu\big((\r(K_n\cdot A)\setminus A)\cap Y_n\big)> C \mu(A).
	\]
\noindent \textbf{Case II.} If $\mu(A)> \frac{1}{2}\mu(X_n)-\mu(F_n)$, then we have 
	\[
	\frac{1}{2}\mu(X_n)\geq \mu(A) > (\frac{1}{2}-\alpha_n)\mu(X_n)\geq \alpha_n \mu(X_n).
	\]
It follows from the requirement on $K_n$ that $\mu\big((\r(K_n\cdot A)\setminus A)\cap X_n\big)> C\mu(A)$. Since
\[
\mu\big((\r(K_n\cdot A)\setminus A)\cap Y_n\big) \geq \mu\big((\r(K_n\cdot A)\setminus A)\cap X_n\big)-\mu(F_n)> C\mu(A)-\mu(F_n)
\]
and 
\[
\mu(A)> (\frac{1}{2}-\alpha_n) \mu(X_n)\geq (\frac{1}{2}-\frac{C}{4+2C})\mu(X_n)=\frac{1}{C+2}\mu(X_n),
\]
then we have
\[
C\mu(A)-\mu(F_n) > C\mu(A)-\alpha_n \mu(X_n) > C\mu(A)-\alpha_n(C+2)\mu(A) \geq \frac{C}{2}\mu(A).
\]

In conclusion, we showed that $Y_n$ is a domain of $(\frac{C}{2},N_n, L_n)$-expansion with ratio bounded by $\theta_n$ and $\mu(Y_n)> (1-\alpha_n)\cdot \frac{n}{n+1}$.
% and moreover, $\frac{1}{\theta_n}\leq \RN(K_{n,i},x)\leq \theta_n$ for $x\in Y_n$ and $i$ with $\alpha_{K_{n,i}}(x) \in Y_n$. 

	``$(2)\Rightarrow(3)$'' is trivial.

	``$(3)\Rightarrow(1)$'': Take an exhaustion of $\Gz$ by domains $Y_n$ of asymptotic expansion. Assume that $\mathcal{G}$ were not asymptotically expanding. Then there exists $\alpha_0\in(0,\frac{1}{2})$ such that for any $C>0$ and any unital symmetric decomposable $K\subseteq \mathcal{G}$, there exists $A_{C,K} \in \RR$ with $\alpha_0\leq \mu(A_{C,K})\leq\frac{1}{2}$ such that $\mu\big(\r(K\cdot A_{C,K})\setminus A_{C,K}\big) \leq C \mu(A_{C,K})$.

Take $n\in \N$ such that $\mu(Y_n)\geq 1-\frac{\alpha_0}{2}$. Then for any measurable $A \subseteq \Gz$ with $\alpha_0 \leq \mu(A) \leq\frac{1}{2}$, direct calculations show that $\frac{\alpha_0}{2} \mu(Y_n)\leq \mu(A\cap Y_n)\leq\frac{1}{2-\alpha_0}\mu(Y_n)$. Then Lemma \ref{extend to beta} provides $\epsilon> 0$ and unital symmetric decomposable $K \subseteq \mathcal{G}$ such that 
	 \[
	 \mu\big((\r(K \cdot (A\cap Y_n))\setminus (A\cap Y_n))\cap Y_n\big)> \epsilon \mu(A\cap Y_n) \geq \epsilon(\mu(A)-\frac{\alpha_0}{2})\geq \frac{\epsilon}{2} \mu(A), 
	 \]
which implies that
\[
\mu(\r(K\cdot A)\setminus A) \geq \mu\big((\r(K \cdot (A\cap Y_n))\setminus A)\cap Y_n\big) > \frac{\epsilon}{2}\mu(A).
\]
This leads to a contradiction.
\end{proof}


\begin{rem}\label{rem:depending on parameters}
From the proof of ``$(1)\Rightarrow(2)$'' above, we know that if $\G$ is asymptotically expanding, then in condition (2) we can take $C_n \equiv \frac{C}{2}$ for any chosen $C\in (0,\frac{1}{2})$, domains $Y_n$ satisfying $\mu(Y_n)> \big(1-\frac{C}{(4+2C)(n+1)}\big)\cdot \frac{n}{n+1}$, $N_n, L_n$ and $\theta_n$ only depend on the expansion parameters of $\G$.
%, and $\theta_n$ only depends on the multiplicity of $K_n$. 
\end{rem}



\subsection{Markov kernels on groupoids}\label{ssec:Markov structure theorem}

Here we construct reversible Markov kernels on groupoids and study the relation between their Cheeger constants and the expansion of groupoids.


Firstly, we aim to construct a Markov kernel for decomposable subsets. 
%Given a unital and symmetric decomposable subset $K \subseteq \G$, a decomposition $K=\bigcup_{i=1}^N K_i$ is called \emph{unital} if $K_i = \Gz$ for some $i$ and \emph{symmetric} if there exists a bijection $\sigma:\{1,2,\cdots,N\} \to \{1,2,\cdots,N\}$ such that $K_i^{-1} = K_{\sigma(i)}$. It is clear that each unital and symmetric decomposable subset admits a unital and symmetric decomposition.
Let us fix a unital symmetric decomposable subset $K$ together with a unital symmetric decomposition $K = \bigcup_{i=1}^N K_i$.


\begin{defn}\label{defn:Markov kernel for K}
For measurable $Y \subseteq \Gz$ and $x\in Y$, denote 
\begin{equation}\label{EQ:aux func for Markov}
K_{Y,x}:=\{i ~|~ x\in \s(K_i) \text{ and }\tau_{K_{i}}(x)\in Y\} \quad \text{and} \quad \sigma_{Y,K}(x)=\sum_{i \in K_{Y,x}} \RN(K_i,x)^{\frac{1}{2}}.
\end{equation}
The \emph{normalized local Markov kernel} associated to $Y$ and $K$ is the Markov kernel on $Y$ defined as follows:
\begin{equation}\label{EQ:Markov for K}
\Pi_{Y,K}(x,-)=\frac{1}{\sigma_{Y,K}(x)}\sum_{i\in K_{Y,x}} \RN(K_{i},x)^{\frac{1}{2}}\delta_{\tau_{K_i}(x)}(-) \quad \text{for} \quad  x\in Y.
\end{equation}
Here $\delta_y$ is the Dirac delta measure on $y$.
\end{defn}

Since the decomposition is unital, it is clear that $\sigma_{Y,K}>0$ on $Y$ and (\ref{EQ:Markov for K}) makes sense. It is also  routine to check that (\ref{EQ:Markov for K}) is indeed a Markov kernel on $Y$. 
To see that $\Pi_{Y,K}$ is reversible, we consider the measure on $Y$ defined by:
\begin{equation}\label{EQ:reservsing measure}
\d\tilde{\mu}_{Y,K} \coloneqq \sigma_{Y,K}\cdot \d(\mu|_Y).
\end{equation}
Note that both $\Pi_{Y,K}$ and $\tilde{\mu}_{Y,K}$ depend on the decomposition of $K$. 


We collect several useful properties of $\Pi_{Y,K}$ in the following. The proof is similar to that of \cite[Proposition 3.10]{li2022markovianroealgebraicapproachasymptotic} since the decomposition $K=\bigcup_{i=1}^N K_i$ is unital and symmetric. Hence we omit the details.

\begin{prop}\label{check reversible Markov kernel}
In the setting above, we have:
\begin{enumerate}
\item The measure $\tilde{\mu}_{Y,K}$ is reversing for the Markov kernel $\Pi_{Y,K}$. 
%The associated measure $\nu$ on $Y\times Y$ defined in (\ref{eq:mu}) can be calculated as follows: for integrable $F$ on $Y \times Y$,
%\[
%\int_{Y\times Y}F(x,y)\d\nu(x,y)=\sum_{i=1}^N \int_{Y\cap \tau_{K_i}^{-1}(Y)} \RN(K_i,x)^{\frac{1}{2}}F(x,\tau_{K_{i}}(x))\d\mu(x).
%\]
\item For measurable $A \subseteq Y$, we have $\mu(A)\leq \tilde{\mu}_{Y,K}(A) \leq N\sqrt{{\mu(A)\mu(Y)}}$. Hence $\tilde{\mu}_{Y,K}$ is equivalent to the restriction $\mu|_Y$.
\end{enumerate}
\end{prop}


\begin{defn}\label{Markov expansion}
For a measurable $Y \subseteq \Gz$ and $C,N,L > 0$, we call $Y$ a \emph{domain of Markov $(C,N,L)$-expansion} (or simply, \emph{domain of Markov expansion}) if there exists a unital symmetric $N$-decomposable $K$ together with a unital symmetric decomposition $K=\bigcup_{i=1}^N K_i$ such that $\ell(K) \leq L$ and the associated normalised local Markov kernel $\Pi_{Y,K}$ on $(Y, \tilde{\mu}_{Y,K})$ has Cheeger constant greater than $C$. 
%In this case, we simply say that $Y$ is a \emph{domain of Markov expansion}.

Moreover, if the decomposition for $K$ above has ratio bounded by $\theta \geq 1$, then we say that $Y$ is a \emph{domain of Markov $(C,N,L)$-expansion with ratio bounded by $\theta$}.
%For a measurable $Y \subseteq \Gz$ and a unital and symmetric decomposition $K =\bigcup_{i=1}^N K_i$, we say that $Y$ is a \emph{domain of Markov $K$-expansion (with respect to the decomposition)} if the associated normalised local Markov kernel $\Pi_{Y,K}$ on $(Y, \tilde{\mu}_{Y,K})$ has strictly positive Cheeger constant. In this case, we simply say that $Y$ is a \emph{domain of Markov expansion}.
\end{defn}



The following lemma relates the domain of Markov expansion with the ordinary expansion. The proof is similar to that of \cite[Lemma 3.14]{li2022markovianroealgebraicapproachasymptotic} and hence omitted.


\begin{lem}\label{expansion and Markov expansion}
For a measurable $Y \subseteq \Gz$, we have:
% and a unital and symmetric decomposition $K = \bigcup_{i=1}^N K_i$, assume that there exists $\theta \geq 1$ such that $\frac{1}{\theta}\leq \RN(K_i,x)\leq \theta$ for every $x\in Y$ and $i\in K_{Y,x}$. 
\begin{enumerate}
 \item If $Y$ is a domain of $(C,N,L)$-expansion with ratio bounded by $\theta$, then $Y$ is a domain of $(\frac{C}{N\theta}, N,L)$-Markov expansion;
 \item If $Y$ is a domain of $(\kappa,N,L)$-Markov expansion with ratio bounded by $\theta$, then $Y$ is a domain of $(\frac{\kappa}{N\sqrt{\theta} + \kappa}, N,L)$-expansion. 
\end{enumerate}
%Then Y is a domain of $K$-expansion \emph{if and only if} $Y$ is a domain of Markov expansion.
\end{lem}


Combining Theorem \ref{exhaustion of expansion with radon controlled} with Lemma \ref{expansion and Markov expansion}, we reach the following Markovian version of the structure theorem:

\begin{thm}\label{thm:Markov structure theorem}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. Then the following are equivalent:
	\begin{enumerate}
		\item The groupoid $\mathcal{G}$ is asymptotically expanding in measure;
		\item The unit space $\mathcal{G}^{(0)}$ admits an exhaustion by domains $Y_n$ of $(C_n, N_n, L_n)$-Markov expansion with ratio bounded by $\theta_n$ for $C_n,N_n,L_n >0$ and $\theta_n \geq 1$.
	\end{enumerate}
\end{thm}

\begin{rem}\label{rem:dependence 2}
Combining Remark \ref{rem:depending on parameters} and the dependence of parameters in Lemma \ref{expansion and Markov expansion}, we know that if $\G$ is asymptotically expanding, then in Theorem \ref{thm:Markov structure theorem}(2) we can take domains $Y_n$ to  satisfy $\mu(Y_n)> t_n$ for some universal $t_n$ independent of $\G$, $C_n, N_n, L_n$ and $\theta_n$ only depend on expansion parameters of $\G$.
%, and a required unital and symmetric decomposition whose associated Cheeger constant has lower bound only depending on expansion parameters of $\G$.
\end{rem}






\section{Dynamical propagation and quasi-locality}\label{Dynamical concepts on groupoids}

In this section, we introduce the notion of dynamical propagation and dynamical quasi-locality for operators on groupoids. Again we always assume that $\G$ is a groupoid with a length function $\ell$, and $\Gz$ is equipped with a measure $\mu$ on some $\sigma$-algebra $\RR$. To include more examples, here we do \emph{not} require $\mu$ to be finite.



\subsection{Basic Notions}\label{ssec:basic notions}

We start with the following key notions:


\begin{defn}\label{finite dynamical propagation}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a measure space. An operator $T \in \B(L^2(\Gz,\mu))$ is said to have \emph{finite dynamical propagation} if there is a unital symmetric $N$-decomposable subset $K\subseteq \G$ with $\ell(K) \leq L$ for some $N,L>0$ such that for any $A,B \in \RR$ with $\mu(\r(K \cdot A)\cap B)=0$, then $\chi_A T\chi_B=0$. 
In this case, we also say that $T$ has \emph{$(N,L)$-dynamical propagation}.

Denote the set of all operators with finite dynamical propagation by $\C_{\dyn}(\G)$, and its norm completion by $\CC^*_{\dyn}(\mathcal{G})$, called the \emph{dynamical Roe algebra of $\G$}.
\end{defn}

Similarly, we consider its quasi-local counterpart:

\begin{defn}\label{dynamical quasi local}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a measure space. An operator $T \in \B(L^2(\Gz,\mu))$ is called \emph{dynamically quasi-local} if for any $\epsilon > 0$, there is a unital symmetric $N_\epsilon$-decomposable subset $K_\epsilon \subseteq \G$ with $\ell(K_\epsilon) \leq L_\epsilon$ for some $N_\epsilon, L_\epsilon>0$ such that for any $A,B \in \RR$ with $\mu(\r(K_\epsilon \cdot A)\cap B)=0$, then $\|\chi_A T\chi_B\| < \epsilon$. The maps $\epsilon \mapsto N_\epsilon, \epsilon \mapsto L_\epsilon$ are called \emph{quasi-local parameters} for $T$.

Denote the set of all dynamically quasi-local operators in $\B(L^2(\Gz,\mu))$ by $\CC^*_{\dyn,\q}(\mathcal{G})$, called the \emph{dynamical quasi-local algebra of $\G$}.
\end{defn}


The following shows that $\CC^*_{\dyn}(\mathcal{G})$ and $\CC^*_{\dyn,\q}(\mathcal{G})$ are indeed $C^*$-algebras:

\begin{lem}\label{check of finite propagation algebra}
Given $\G$, $\ell$ and $\mu$ as above, we have:
\begin{enumerate}
 \item The set $\C_{\dyn}(\G)$ is a $\ast$-algebra and hence, $\CC^*_{\dyn}(\mathcal{G})$ is a $C^*$-algebra;
 \item The set $\CC^*_{\dyn,\q}(\mathcal{G})$ is a $C^*$-algebra.
\end{enumerate}
\end{lem}

\begin{proof}
We only prove (1), since (2) is similar.

By Lemma \ref{inverse,union,composition still decomposable}, $\C_{\dyn}(\G)$ forms an algebra. To see it preserves the $\ast$-operator, fix $T \in \C_{\dyn}(\G)$. Then there exists a unital symmetric decomposable subset $K = \bigcup_{i=1}^N K_i$  such that for any $A,B \in \RR$ with $\mu(\r(K \cdot A)\cap B)=0$, then $\chi_A T\chi_B=0$. 
%Without loss of generality, we assume $K$ is symmetric and write $K=\bigcup_{i=1}^N K_i$ for admissible $K_i$. 
Then we have $\chi_B T^* \chi_A=0$ for any measurable $A,B \subseteq \Gz$ with $\mu(\r(K \cdot A)\cap B)=0$. Since each $\tau_{K_i}$ is measure-class-preserving and $K$ is symmetric, this is equivalent to that $\mu(\r(K \cdot B)\cap A)=0$. Hence we conclude that $T^* \in \C_{\dyn}(\G)$.
\end{proof}


For a sequence of groupoids, we can combine them into a single groupoid and translate the notion of dynamical propagation and quasi-locality thereon in a uniform version. This is important to recover the case of uniform Roe algebras.
%This is the reason why we need to consider infinite measure $\mu$, which is important to recover the case of uniform Roe algebras later.

More precisely, for each $n\in \N$, let $\G_n$ be a groupoid with a length function $\ell_n$ and $(\Gz_n,\RR_n,\mu_n)$ be a measure space. Form a groupoid $\G$ to be their disjoint union $\bigsqcup_{n\in \N} \G_n$, and equip $\Gz=\bigsqcup_{n\in \N} \Gz_n$ with a measure $\mu$ on some $\sigma$-algebra $\RR$ generated by $\bigsqcup_{n\in \N} \RR_n$ and $\mu$ is determined by $\mu|_{\Gz_n} \coloneqq \mu_n$ for each $n$. Also take a length function $\ell$ on $\G$ to be the disjoint union of $\ell_n$. Then we have
\[
L^2(\Gz, \mu) = \bigoplus_{n\in \N} L^2(\Gz_n, \mu_n).
\]
The following shows that operators in $\CC^*_{\dyn,\q}(\G)$ are always diagonal and can be described in a uniform version:

\begin{lem}\label{family of quasi local and quasi local}
Given $T \in \B(L^2(\Gz,\mu))$, we have:
\begin{enumerate}
 \item $T \in \C_{\dyn}(\G)$ \emph{if and only if} there exists $T_n \in \B(L^2(\Gz_n, \mu_n))$ for each $n\in \N$ with $\sup_{n\in \N} \|T_n\| < \infty$ such that $T= (\SOT)-\sum_{n \in \N} T_n$ and there exist $N,L>0$ satisfying: for any $n\in \N$ there exists a unital symmetric $N$-decomposable $K_n \subseteq \G_n$ with $\ell_n(K_n) \leq L$ such that for any $A,B \in \RR_n$ with $\mu(\r(K_n \cdot A)\cap B)=0$, we have $\chi_A T_n \chi_B=0$. 
 \item $T \in \CC^*_{\dyn,\q}(\G)$ \emph{if and only if} there exists $T_n \in \B(L^2(\Gz_n, \mu_n))$ for each $n\in \N$ with $\sup_{n\in \N} \|T_n\| < \infty$ such that $T= (\SOT)-\sum_{n \in \N} T_n$ and for any $\epsilon > 0$ there exist $N, L>0$ satisfying: for any $n\in \N$, there exists a unital symmetric $N$-decomposable $K_n \subseteq \G_n$ with $\ell_n(K_n) \leq L$ such that for any $A,B \in \RR_n$ with $\mu(\r(K_n \cdot A)\cap B)=0$, we have $\|\chi_A T_n\chi_B\| < \epsilon$. 
\end{enumerate}
\end{lem}


\begin{proof}
(1). \emph{Necessity}: Firstly, we show that $T$ is diagonal. Note that for any $n\neq m$ and $A \in \RR_n$, $B \in \RR_m$, we have $(K \cdot A) \cap B = \emptyset$ for any decomposable $K \subseteq \G$. Then it follows from definition that $\chi_A T \chi_B = 0$, and hence $T= (\SOT)-\sum_{n \in \N} T_n$ for $T_n=\chi_{\Gz_n} T \chi_{\Gz_n}$. 

Furthermore, there exists a unital symmetric decomposable $K \subseteq \G$ such that for any $A,B \in \RR$ with $\mu(\r(K \cdot A)\cap B)=0$, then $\chi_A T\chi_B=0$. Assume that $K$ is $N$-decomposable and $\ell(K) \leq L$ for some $N,L>0$. For each $n\in \N$, set $K_n \coloneqq K \cap \G_n$. Then $K_n$ is $N$-decomposable, unital and symmetric with $\ell_n(K_n) \leq L$. It is easy to check that $K_n$ satisfies the requirement.

\emph{Sufficiency}: Assume $K_n$ satisfies the requirement, and write $K_n=\bigcup_{i=1}^N K_n^{(i)}$ for admissible $K_n^{(i)} \subseteq \G_n$ with $\ell_n(K_n^{(i)}) \leq L$. Define $K\coloneqq \bigsqcup_{n\in \N} K_n \subseteq \G$ and for $i=1,\cdots, N$, define $K^{(i)} \coloneqq \bigsqcup_{n\in \N} K_n^{(i)}$. Since $K_n^{(i)}$ is admissible, it is easy to see that $K^{(i)} \subseteq \G$ is admissible for each $i$. Hence $K$ is $N$-decomposable and $\ell(K) \leq L$. 

Now for any $A,B \in \RR$ with $\mu(\r(K \cdot A)\cap B)=0$, set $A_n\coloneqq A \cap \Gz_n$ and $B_n \coloneqq B \cap \Gz_n$ and then we have $\mu_n(\r(K_n \cdot A_n)\cap B_n)=0$ for each $n\in \N$. By assumption, we have $\chi_{A_n} T_n \chi_{B_n} = 0$. Finally, note that
\[
\chi_A T \chi_B = \sum_{n\in \N} \chi_{A_n} T_n \chi_{B_n} = 0,
\]
which concludes (1). (2) is similar to (1) and hence omitted.
\end{proof}



\subsection{Quasi-locality of the averaging projection}

Now we focus on a special projection operator in $\B(L^2(\Gz,\mu))$ when $\mu$ is a probability measure, whose dynamical quasi-locality is closely related to the asymptotic expansion of the groupoid. 

\begin{defn}\label{defn:ave proj}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a measure space. For any measurable $Y \subseteq \Gz$ with $0< \mu(Y) < \infty$, denote by $P_Y \in \B(L^2(\Gz, \mu))$ the \emph{averaging projection on $Y$}, which is the orthogonal projection onto the one-dimensional subspace in $L^2(\Gz,\mu)$ spanned by $\chi_Y$. In other words, 
\[
P_Y(f)\coloneqq \frac{\langle f,\chi_Y\rangle}{\mu(Y)}\chi_Y \quad \text{for} \quad f \in L^2(\Gz,\mu).
\]
If $\mu(\Gz) < \infty$, we simply write $P_{\G}$ for $P_{\Gz}$.
\end{defn}


To study the quasi-locality of the averaging projection, we firstly record the following. The proof is similar to that of \cite[Lemma 3.8]{Li2019QuasilocalAA}, and hence omitted.


\begin{lem}\label{well known fact for averaging projection}
Assume that $\mu(\Gz) =1$. Then for any measurable $A,B \subseteq \Gz$, we have
\[
\|\chi_A P_\G \chi_B\| = \sqrt{\mu(A) \mu(B)}.
\]
\end{lem}


The following relates the quasi-locality of $P_{\G}$ with asymptotic expansion of $\G$:

\begin{prop}\label{asym expansion and quasi local} 
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. Then the averaging projection $P_{\G}$ is dynamically quasi-local \emph{if and only if} $\G$ is asymptotically expanding in measure $\mu$.
\end{prop}

%\begin{thm}\label{asym expansion and quasi local} 
%The averaging projection $\prod_{i\in I} P_{\mathcal{G}_i^{(0)}}\in \Cdqu(\bigsqcup_{i\in I} \mathcal{G}_i)$ if and only if $\mathcal{G}_i$ are uniformly (strongly) asymptotically expanding in measure.
%\end{thm}

\begin{proof} 
%After rescaling if necessary, we assume that $\mu$ is a probability measure.
\emph{Necessity}. 
Assume $\epsilon \mapsto N_\epsilon$, $\epsilon \mapsto L_\epsilon$ are quasi-local parameters for $P_\G$. Given $\alpha \in (0,\frac{1}{2}]$, set $N\coloneqq N_{\sqrt{\alpha}/2}$ and $L\coloneqq L_{\sqrt{\alpha}/2}$. Then there exists a unital symmetric $N$-decomposable $K$ with $\ell(K) \leq L$ such that for any $A,B \in \RR$ with $\mu(\r(K \cdot A)\cap B)=0$, we have $\|\chi_A T\chi_B\| < \frac{\sqrt{\alpha}}{2}$. Then for any $A \in \RR$ with $\alpha \leq \mu(A) \leq \frac{1}{2}$, Lemma \ref{well known fact for averaging projection} shows:
\[
\sqrt{\mu(A) \cdot \mu\big(\Gz \setminus \r(K \cdot A)\big)} = \|\chi_A P_\G \chi_{\Gz \setminus \r(K \cdot A)}\| <  \frac{\sqrt{\alpha}}{2}.
\]
Hence we obtain 
\[
\mu(A) \cdot \mu\big(\Gz \setminus \r(K \cdot A)\big) < \frac{\alpha}{4},
\]
which implies that $\mu\big(\Gz \setminus \r(K \cdot A)\big) < \frac{1}{4}$. Therefore, we obtain:
\[
\mu(\r(K \cdot A)) > \frac{3}{4} \geq (1+\frac{1}{2}) \cdot \mu(A).
\]
This concludes that $\G$ is asymptotically expanding in measure.


\emph{Sufficiency}. 
Assuming $\alpha \mapsto C_\alpha$, $\alpha \mapsto N_\alpha$ and $\alpha \mapsto L_\alpha$ are expansion parameters for $\G$, we take $K_\alpha$ as in Definition \ref{asymptotically expanding}. Given $0<\epsilon\leq \frac{1}{2}$, take $n \in \N$ to be the smallest number such that 
\[
(1+C_\epsilon)^n \cdot \epsilon > \frac{1}{2}.
\]
Set $K\coloneqq K_\epsilon^{2n}$, which is unital symmetric $N_\epsilon^{2n}$-decomposable with length at most $2nL_\epsilon$ by Lemma \ref{inverse,union,composition still decomposable}. 

For any measurable $A, B \subseteq \Gz$ with $\mu(\r(K \cdot A) \cap B) = 0$, we have
\[
\mu\big(\r(K_\epsilon^n \cdot A) \cap \r(K_\epsilon^n \cdot B) \big) = 0
\]
since $K_\epsilon$ is symmetric. Hence without loss of generality, we assume
\[
\mu(\r(K_\epsilon^n \cdot A)) \leq \frac{1}{2}.
\]
If $\mu(A) < \epsilon$, then by Lemma \ref{well known fact for averaging projection} we have 
\[
\|\chi_A P_\G \chi_B\| = \sqrt{\mu(A)\mu(B)} < \sqrt{\epsilon}.
\]
If $\mu(A) \geq \epsilon$, then using asymptotic expansion inductively, we have:
\[
\frac{1}{2} \geq \mu(\r(K_\epsilon^n \cdot A)) \geq (1+C_\epsilon) \mu(\r(K_\epsilon^{n-1} \cdot A)) \geq \cdots \geq (1+C_\epsilon)^n \mu(A) \geq (1+C_\epsilon)^n \cdot \epsilon.
\]
This leads to a contradiction to the choice of $n$. 
\end{proof}


\begin{rem}\label{rem:dependence of parameters 2}
From the proof above, it is clear that if $P_\G$ is dynamically quasi-local, then we can choose expansion parameters for $\G$ only depending on quasi-local parameters for $P_\G$, and vice versa.
\end{rem}








\section{Main results}\label{sec:Main results}


Having established Proposition \ref{asym expansion and quasi local}, now we are in the position to prove the following fundamental case of the main result:

%Proposition \ref{asym expansion and quasi local} shows that the dynamical quasi-locality of the averaging projection $P_\G$ implies the asymptotic expansion of the groupoid $\G$. In this section, we show further that this can also be characterised by approximating $P_\G$ in terms of operators with finite dynamical propagations.


\begin{thm}\label{thm:main thm ave proj}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a probability measure space. Then the following are equivalent:
\begin{enumerate}
 \item the averaging projection $P_\G \in \CC^*_{\dyn}(\mathcal{G})$;
 \item the averaging projection $P_\G \in \CC^*_{\dyn,\q}(\mathcal{G})$;
 \item the groupoid $\G$ is asymptotically expanding in measure.
\end{enumerate}
\end{thm}


\begin{proof}
``(1) $\Rightarrow$ (2)'' is trivial, and ``(2) $\Leftrightarrow$ (3)'' comes from Proposition \ref{asym expansion and quasi local}. Hence we only focus on ``(3) $\Rightarrow$ (1)''. 

Fix $C\in (0,\frac{1}{2})$. By Theorem \ref{thm:Markov structure theorem}, Remark \ref{rem:depending on parameters} and Remark \ref{rem:dependence 2}, there exists a sequence of measurable subsets $Y_n \subseteq \Gz$ with $\mu(Y_n)> \big(1-\frac{C}{(4+2C)(n+1)}\big)\cdot \frac{n}{n+1}$ such that each $Y_n$ is a domain of $(C_n, N_n, L_n)$-Markov expansion with ratio bounded by $\theta_n$ for $C_n,N_n,L_n >0$ and $\theta_n \geq 1$ only depending on expansion parameters of $\G$. From Definition \ref{Markov expansion}, we can choose a unital symmetric $N_n$-decomposable $K_n$ together with a unital symmetric decomposition $K_n = \bigcup_{i=1}^{N_n} K_n^{(i)}$ such that $\ell(K_n) \leq L_n$ and the associated normalised local Markov kernel $\Pi_n \coloneqq \Pi_{Y_n,K_n}$ from (\ref{EQ:Markov for K}) on $(Y_n, \tilde{\mu}_n)$ has Cheeger constant greater than $C_n$, where $\tilde{\mu}_n \coloneqq \tilde{\mu}_{Y_n,K_n}$ is the reversing measure defined in (\ref{EQ:reservsing measure}). We have a function $\sigma_n\coloneqq \sigma_{Y_n, K_n}$ from (\ref{EQ:aux func for Markov}) such that $\sigma_n\geq 1$ on $Y_n$. 
%$Y_n$ is a domain of $K_n$-Markov expansion with respect to a unital and symmetric decomposition $K_n = \bigcup_{i=1}^{N_n} K_n^{(i)}$ with ratio bounded by $\theta_n$. Here $K_n$, $\theta_n$ and the Cheeger constant $C_n$ of the decomposition above only depend on expansion parameters of $\G$. For each $n\in \N$, recall from (\ref{EQ:aux func for Markov}), (\ref{EQ:Markov for K}) and (\ref{EQ:reservsing measure}) that we have the associated Markov kernel $\Pi_n \coloneqq \Pi_{Y_n,K_n}$, a reversing measure $\tilde{\mu}_n \coloneqq \tilde{\mu}_{Y_n,K_n}$ and a function $\sigma_n\coloneqq \sigma_{Y_n, K_n}$ with $\sigma_n\geq 1$ on $Y_n$. 
Denote the associated Markov operator by $\P_n$ from (\ref{EQ:Markov operator defn}) with spectral gap $\lambda_n$.

Now for each $n\in \N$, we consider the following embedding
\[
I_n: L^2(Y_n,\tilde{\mu}_n) \longrightarrow L^2(\Gz,\mu)
\]
simply by extending each function in $L^2(Y_n,\tilde{\mu}_n)$ by zero on $\Gz \setminus Y_n$. This is well-defined since $\tilde{\mu}_n$ is equivalent to $\mu|_{Y_n}$ and we have $\|I_n\| \leq 1$ thanks to Proposition \ref{check reversible Markov kernel}(2). Direct calculations show that its adjoint has the form:
\[
I_n^*: L^2(\Gz,\mu) \longrightarrow L^2(Y_n,\tilde{\mu}_n), \quad g \mapsto \frac{1}{\sigma_n} \cdot g|_{Y_n} \quad \text{for} \quad g \in L^2(\Gz,\mu).
\]
Denote the adjoint map
\[
\Ad_n: \B(L^2(Y_n,\tilde{\mu}_n)) \longrightarrow \B(L^2(\Gz,\mu)), \quad T \mapsto I_n \circ T \circ I_n^* \quad \text{for} \quad T \in \B(L^2(Y_n,\tilde{\mu}_n)).
\]

Recall from Definition \ref{defn:ave proj} that we have the averaging projection $P_n \coloneqq P_{Y_n}$ in $\B(L^2(\Gz,\mu))$, which is the orthogonal projection onto constant functions on $Y_n$ in $L^2(\Gz,\mu)$. Denote another orthogonal projection $\tilde{P}_n \in \B(L^2(Y_n,\tilde{\mu}_n))$ onto constant functions on $Y_n$ in $L^2(Y_n,\tilde{\mu}_n)$. Direct calculations show that
\begin{equation}\label{EQ:relation between P and tildeP}
\Ad_n(\tilde{P}_n) = \frac{\mu(Y_n)}{\tilde{\mu}_n(Y_n)} \cdot P_n.
\end{equation}

On the other hand, Theorem \ref{thm:spectral.characterisation.markov.exp} shows that $\frac{C_n^2}{2}\leq 1-\lambda_n\leq 2C_n$. Hence $\frac{1}{2} \chi_{Y_n} + \frac{1}{2}\P_n$ has spectrum contained in $[-\frac{3}{4},1-\frac{C_n^2}{4}]\cup\{1\}$. Therefore, for any $m \in \N$ we have
\[
\left\|\left(\frac{1}{2}\chi_{Y_n}+\frac{1}{2}\P_n\right)^m-\tilde{P}_n\right\| \leq \left(1-\frac{C_n^2}{4}\right)^m.
\]
%which implies that $\prod_{i\in I}(\frac{1}{2}\chi_{Y_i}+\frac{1}{2}\mathfrak{B}_{Y_i,K^i})^n$ converges in the supreme norm to $\prod_{i\in I} \widetilde{P}_{Y_i,K^i}$.
Applying $\Ad_n$ and using (\ref{EQ:relation between P and tildeP}), we obtain:
\[
\left\|\frac{\tilde{\mu}_n(Y_n)}{\mu(Y_n)} \cdot\Ad_n\left[\left(\frac{1}{2}\chi_{Y_n}+\frac{1}{2}\P_n\right)^m\right]- P_n\right\| \leq \frac{\tilde{\mu}_n(Y_n)}{\mu(Y_n)} \cdot \left(1-\frac{C_n^2}{4}\right)^m.
\]
Note that 
\[
\frac{\tilde{\mu}_n(Y_n)}{\mu(Y_n)} \leq \|\sigma_n\|_\infty \leq \left\| \sum_{i=1}^{N_n} \RN(K_n^{(i)},x)^{\frac{1}{2}} \right\|_\infty \leq N_n\sqrt{\theta_n}.
\]
Combining the above together, we obtain
\begin{equation}\label{EQ: app for proj}
\left\|\frac{\tilde{\mu}_n(Y_n)}{\mu(Y_n)} \cdot\Ad_n\left[\left(\frac{1}{2}\chi_{Y_n}+\frac{1}{2}\P_n\right)^m\right]- P_n\right\| \leq N_n\sqrt{\theta_n} \cdot \left(1-\frac{C_n^2}{4}\right)^m.
\end{equation}
Hence given $\epsilon>0$, we can choose $m_n \in \N$ such that 
\begin{equation}\label{EQ:estimate in pf of main thm}
N_n\sqrt{\theta_n} \cdot \left(1-\frac{C_n^2}{4}\right)^{m_n} < \frac{\epsilon}{2}. 
\end{equation}
Moreover, direct calculations show that for each $n\in \N$ we have:
\[
\|P_n - P_\G\| \leq \sqrt{\mu(\Gz \setminus Y_n)}  = \sqrt{\frac{1}{n+1} + \frac{nC}{(4+2C)(n+1)^2}}.
\]
For $\epsilon$ above, we can further choose $\tilde{N} \in \N$ such that for any $n >  \tilde{N}$ we have 
\begin{equation}\label{EQ:estimate in pf of main thm2}
\sqrt{\frac{1}{n+1} + \frac{nC}{(4+2C)(n+1)^2}} < \frac{\epsilon}{2}.
\end{equation}
Combining with (\ref{EQ: app for proj}), (\ref{EQ:estimate in pf of main thm}) and (\ref{EQ:estimate in pf of main thm2}), we obtain that for any $n >  \tilde{N}$ we have:
\begin{small}
\begin{align}\label{EQ:estimate in pf of main thm3}
\Big\|\frac{\tilde{\mu}_n(Y_n)}{\mu(Y_n)}  \cdot\Ad_n&\left[\left(\frac{1}{2}\chi_{Y_n}+\frac{1}{2}\P_n\right)^{m_n}\right]- P_\G\Big\| < \Big\|\frac{\tilde{\mu}_n(Y_n)}{\mu(Y_n)} \cdot\Ad_n\left[\left(\frac{1}{2}\chi_{Y_n}+\frac{1}{2}\P_n\right)^{m_n}\right]- P_n\Big\| + \|P_n - P_\G\| \nonumber \\
&<N_n\sqrt{\theta_n} \cdot \left(1-\frac{C_n^2}{4}\right)^{m_n} + \sqrt{\frac{1}{n+1} + \frac{nC}{(4+2C)(n+1)^2}} < \frac{\epsilon}{2} + \frac{\epsilon}{2} = \epsilon.
\end{align}
\end{small}

Finally, for $n\in \N$ and measurable $A,B \subseteq Y_n$ with $\mu((K_n \cdot A) \cap B) = 0$, we have $\tilde{\mu}_n((K_n \cdot A) \cap B) = 0$ by Proposition \ref{check reversible Markov kernel}(2). For $x\in Y_n$ and $\xi \in L^2(Y_n, \tilde{\mu}_n)$, we have:
\begin{align*}
(\chi_A \P_n \chi_B \xi)(x) &= \chi_A(x) \cdot \int_{B} \xi(y) \Pi_n(x, \dy) \\
&= \chi_A(x) \cdot \frac{1}{\sigma_n(x)}\sum_{i:\tau_{K_n^{(i)}}(x) \in B} \RN(K_n^{(i)},x)^{\frac{1}{2}} \xi(\tau_{K_n^{(i)}}(x)).
\end{align*}
It follows that $\chi_A \P_n \chi_B=0$. Note that the operator $I_n$ does not change the propagation and hence, the following  operator
\[
\frac{\tilde{\mu}_n(Y_n)}{\mu(Y_n)}  \cdot\Ad_n\left[\left(\frac{1}{2}\chi_{Y_n}+\frac{1}{2}\P_n\right)^{m_n}\right] \quad \text{in} \quad \B(L^2(\Gz,\mu))
\]
has $(N_n^{m_n}, m_n \cdot L_n)$-propagation.
%is bounded by $(K_n)^{m_n}$, which is $N_n^{m_n}$-decomposable and $\ell((K_n)^{m_n}) \leq m_n \cdot L_n$. 
Combining with (\ref{EQ:estimate in pf of main thm3}), we conclude the proof.
\end{proof}


\begin{rem}\label{rem:dependence on parameters for main thm}
From the proof above together with Remark \ref{rem:depending on parameters} and Remark \ref{rem:dependence 2}, we know that if $\G$ is asymptotically expanding in measure, then for any $\epsilon>0$ we can choose $T_\epsilon \in \C_{\dyn}(\G)$ with $(N_\epsilon, L_\epsilon)$-dynamical propagation such that $\|T_\epsilon - P_\G\| < \epsilon$ and the functions $\epsilon \mapsto N_\epsilon$ and $\epsilon \mapsto L_\epsilon$ only depend on expansion parameters of $\G$.
\end{rem}


In the following, we consider general rank-one projections on $L^2(\Gz,\mu)$ for general $\mu$. Let $P \in \B(L^2(\Gz,\mu))$ be a rank-one projection and $\xi \in L^2(\Gz,\mu)$ be a unit vector in the range of $P$. Then
\[
P(\eta)=\langle \eta,\xi\rangle \xi \quad \text{for} \quad \eta \in L^2(\Gz,\mu).
\]
This induces a probability measure $\nu$ on $(\Gz,\RR)$ defined by
\[
\d \nu(x) \coloneqq |\xi(x)|^2 \d \mu(x) \quad \text{for} \quad x\in \Gz.
\]
It is clear that the measure $\nu$ only depends on $P$, called the \emph{associated measure to $P$}. 

Then we have the following:
%Note that here the measure $\mu$ is \emph{not} required to be finite. 


\begin{thm}\label{thm:main thm ave proj general}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a (not necessarily finite) measure space. Let $P \in \B(L^2(\Gz,\mu))$ be a rank-one projection, and $\nu$ the associated probability measure on $\Gz$. Then the following are equivalent:
\begin{enumerate}
 \item $P \in \CC^*_{\dyn}(\mathcal{G})$;
 \item $P \in \CC^*_{\dyn,\q}(\mathcal{G})$;
 \item $\G$ is asymptotically expanding in measure $\nu$.
\end{enumerate}
\end{thm}

