Our idea is to apply Theorem \ref{thm:main thm ave proj} to the probability measure $\nu$. Firstly, note that $\nu$ might \emph{not} be equivalent to $\mu$ and hence, we consider
\[
Z\coloneqq \{x\in \mathcal{G}^{(0)} ~|~\xi(x)=0\}.
\]
Here $Z$ is well-defined up to $\mu$-null sets. We set $Y \coloneqq \Gz \setminus Z$ and then the restrictions $\mu|_Y$ and $\nu|_Y$ are equivalent. Now we consider the reduction $\G_Y^Y=\s^{-1}(Y) \cap \r^{-1}(Y)$,
equipped with the restriction $\ell_Y$ of the length function $\ell$. Denote
\[
Q: L^2(Y,\mu|_Y) \longrightarrow L^2(\Gz, \mu)
\]
the embedding by extending functions in $L^2(Y,\mu|_Y)$ to $0$ on $Z$. Then 
%we can transfer the dynamical propagation and quasi-locality of $P$ to those restricted to $\G_Y^Y$. More precisely, 
we have:

\begin{lem}\label{lem:reduction Q}
With the notation above, we have:
\begin{enumerate}
 \item $P \in \CC^*_{\dyn,\q}(\mathcal{G})$ \emph{if and only if} $Q^*PQ \in \CC^*_{\dyn,\q}(\G_Y^Y)$;
  \item $P \in \CC^*_{\dyn}(\mathcal{G})$ \emph{if and only if} $Q^*PQ \in \CC^*_{\dyn}(\G_Y^Y)$.
\end{enumerate}
Here we equip $\G_Y^Y$ with the length function $\ell_Y$ and $(\G_Y^Y)^{(0)}=Y$ with the measure $\mu|_Y$ to define $\CC^*_{\dyn}(\G_Y^Y)$ and $\CC^*_{\dyn,\q}(\G_Y^Y)$.
\end{lem}

\begin{proof}
Here we only prove (1), and (2) is similar.

\emph{Necessity}: By assumption, for any $\epsilon>0$ there exists a unital symmetric decomposable subset $K \subseteq \G$ such that for any measurable $A, B \subseteq \Gz$ with $\mu(\r(K \cdot A) \cap B)=0$, we have $\|\chi_A P \chi_B\| < \epsilon$. Set $K'\coloneqq K \cap \G_Y^Y$, which is clearly unital symmetric and decomposable in $\G_Y^Y$. For any measurable $A',B' \subseteq Y$ with $\mu(\r(K' \cdot A') \cap B')=0$, it is easy to see that $\mu(\r(K \cdot A') \cap B')=0$. Hence 
\[
\|\chi_{A'} Q^*PQ \chi_{B'}\| = \|Q^* \chi_{A'} P \chi_{B'}Q\| \leq \|\chi_{A'} P \chi_{B'}\| < \epsilon.
\]
%	`$\Rightarrow$': Since the block-rank-one projection $\prod_{i\in I} P_i\in \Cdqu(\bigsqcup_{i\in I}\mathcal{G}_i)$, we have that for any $\epsilon> 0$ there exist uniformly strongly decomposable $K^i\subseteq \mathcal{G}_i$ such that for any $i\in I$ and measurable $A,B\subseteq \mathcal{G}_i^{(0)}$ with $\mu_i(r((K^i\cup \mathcal{G}_i^{(0)})A)\cap B)=0$ we have that $||\chi_A P_i \chi_B||_{\mathcal{B}(L^2 (\mathcal{G}_{i}^{(0)},\mu_i))}< \epsilon$, i.e., for any $f\in L^2 (\mathcal{G}_{i}^{(0)},\mu_i)$ we have $||\chi_A P_i \chi_B(f)||_{L^2 (\mathcal{G}_{i}^{(0)},\mu_i)}< \epsilon||f||_{L^2 (\mathcal{G}_{i}^{(0)},\mu_i)}$. Let $K^{'i}=K^i\cap \mathcal{G}_i'$, then $K^{'i}$ are uniformly strongly decomposable. It follows that for any measurable $A,B\subseteq \mathcal{G}_i^{'(0)}$ with $\mu_i(r((K^{'i}\cup \mathcal{G}_i^{'(0)})A)\cap B)=0$, we have $\mu_i(r((K^i\cup \mathcal{G}_i^{(0)})A)\cap B)=0$, which implies that for any $f\in L^2 (\mathcal{G}_{i}^{'(0)},\mu_i)$ we have
%	$$||\chi_A Q_i^{\ast} P_i Q_i \chi_B(f)||_{L^2 (\mathcal{G}_{i}^{'(0)},\mu_i)}=||Q_i^{\ast} \chi_A P_i \chi_B Q_i (f)||_{L^2 (\mathcal{G}_{i}^{'(0)},\mu_i)}< \epsilon||f||_{L^2 (\mathcal{G}_{i}^{'(0)},\mu_i)}.$$
%	Hence $\prod_{i\in I} Q_i^{\ast} P_i Q_i \in \Cdqu(\bigsqcup_{i\in I}\mathcal{G}_i')$.

\emph{Sufficiency}: By assumption, for any $\epsilon>0$ there exists a unital symmetric decomposable subset $K \subseteq \G_Y^Y$ such that for any measurable subsets $A, B \subseteq Y$ with $\mu(\r(K \cdot A) \cap B)=0$, we have $\|\chi_A Q^*PQ \chi_B\| < \epsilon$. Set $\hat{K}\coloneqq K \cup \Gz$, which is clearly unital symmetric and decomposable in $\G$. By the construction of $Q$, we have
\[
P = Q(Q^*PQ)Q^*.
\]
Hence for any measurable $\hat{A}, \hat{B} \subseteq \Gz$ with $\mu(\r(\hat{K} \cdot \hat{A}) \cap \hat{B})=0$, we have
\[
\|\chi_{\hat{A}} P \chi_{\hat{B}}\| = \|\chi_{\hat{A}} Q(Q^*PQ)Q^* \chi_{\hat{B}}\| = \|Q\chi_{\hat{A} \cap Y} (Q^*PQ) \chi_{\hat{B} \cap Y}Q^*\| \leq \|\chi_{\hat{A} \cap Y} (Q^*PQ) \chi_{\hat{B} \cap Y}\|  < \epsilon.
\]
Here we use the fact that $\mu\big(\r(K \cdot (\hat{A}\cap Y)) \cap (\hat{B}\cap Y)\big)=0$.
%	`$\Leftarrow$': Since $\prod_{i\in I} Q_i^{\ast} P_i Q_i \in \Cdqu(\bigsqcup_{i\in I}\mathcal{G}_i')$, we have that for any $\epsilon> 0$ there exist uniformly strongly decomposable $K^{'i}\subseteq \mathcal{G}_i'$ such that for any $i\in I$ and measurable $A,B\subseteq \mathcal{G}_i^{'(0)}$ with $\mu_i(r((K^{'i}\cup \mathcal{G}_i^{'(0)})A)\cap B)=0$ we have that $||\chi_A Q_i^{\ast} P_i Q_i \chi_B||_{\mathcal{B}(L^2 (\mathcal{G}_{i}^{'(0)},\mu_i))}< \epsilon$, i.e., for any $f\in L^2 (\mathcal{G}_{i}^{'(0)},\mu_i)$ we have $||\chi_A Q_i^{\ast} P_i Q_i \chi_B(f)||_{L^2 (\mathcal{G}_{i}^{'(0)},\mu_i)}< \epsilon||f||_{L^2 (\mathcal{G}_{i}^{'(0)},\mu_i)}$. Let $K^i=K^{'i}$, then $K^i$ are uniformly strongly decomposable and for any $i\in I$ and measurable $A,B\subseteq \mathcal{G}_i^{(0)}$ with $\mu_i(r((K^{i}\cup \mathcal{G}_i^{(0)})A)\cap B)=0$, we have that for any $f\in L^2 (\mathcal{G}_{i}^{(0)},\mu_i)$ we have
%	\begin{align*}
%		||\chi_A P_i \chi_B(f)||_{L^2 (\mathcal{G}_{i}^{(0)},\mu_i)}&=(\int_A |P_i(\chi_B f)(x)|^2d\mu_i(x))^{\frac{1}{2}}\\
%		&=(\int_A |\langle \chi_B f,\xi_i\rangle \xi_i(x)|^2 d\mu_i(x))^{\frac{1}{2}}\\
%		\text{Since $\xi_i(x)=0$ in $Z_i$,}~&=(\int_{A\cap \mathcal{G}_i^{'(0)}} |\langle \chi_{B\cap \mathcal{G}_i^{'(0)}}  f,\xi_i\rangle \xi_i(x)|^2 d\mu_i(x))^{\frac{1}{2}}\\
%		&=||\chi_{A\cap \mathcal{G}_i^{'(0)}} Q_i^{\ast} P_i Q_i \chi_{B\cap \mathcal{G}_i^{'(0)}} (Q_i^{\ast}f)||_{(L^2 (\mathcal{G}_{i}^{'(0)},\mu_i))}\\
%		&< \epsilon||Q_i^{\ast}f||_{L^2 (\mathcal{G}_{i}^{'(0)},\mu_i)}\\
%		&\leq \epsilon||f||_{L^2 (\mathcal{G}_{i}^{(0)},\mu_i)}
%	\end{align*}
%	which implies that the block-rank-one projection $\prod_{i\in I} P_i\in \Cdqu(\bigsqcup_{i\in I}\mathcal{G}_i)$.
\end{proof}


Consequently, to prove Theorem \ref{thm:main thm ave proj general} we only need consider the case that $\mu$ and $\nu$ are equivalent, \emph{i.e.}, $\mu(Z) = 0$. Therefore in the following, we assume that $Z=\emptyset$.
% and in this case $\G_Y^Y = \G$. 

Now we form the associated dynamical Roe and quasi-local algebras for $\G$ using the measures $\mu$ and $\nu$ on $\Gz$. To tell the difference, we denote $\CC^*_{\dyn}(\G;\mu)$ and $\CC^*_{\dyn,\q}(\G;\mu)$ for the algebras defined using $\mu$, while $\CC^*_{\dyn}(\G;\nu)$ and $\CC^*_{\dyn,\q}(\G;\nu)$ for those using $\nu$. 
Then we have the following:


\begin{lem}\label{lem:equiv measure quasi-local and ppg}
With the notation above and assuming $Z=\emptyset$, we have:
\begin{enumerate}
 \item $P \in \CC^*_{\dyn,\q}(\G;\mu)$ \emph{if and only if} $P_\G \in \CC^*_{\dyn,\q}(\G;\nu)$;
 \item $P \in \CC^*_{\dyn}(\G;\mu)$ \emph{if and only if} $P_\G \in \CC^*_{\dyn}(\G;\nu)$.
\end{enumerate}
Here $P_\G$ is the averaging projection in $\B^2(L^2(\Gz,\nu))$ from Definition \ref{defn:ave proj}.
\end{lem}


\begin{proof}
We only prove (1), since (2) is similar. Denote
\[
U: L^2(\Gz,\nu) \longrightarrow L^2(\Gz,\mu) ,\quad f \mapsto f\cdot \xi \quad \text{for} \quad f \in L^2(\Gz,\nu).
\]
By the construction and the assumption that $Z = \emptyset$ (which implies that $\xi$ is non-zero everywhere), it is easy to check that $U$ is a unitary operator with $U^*\eta = \frac{1}{\xi} \cdot \eta$ for $\eta \in L^2(\Gz,\mu)$.
Denote
\[
\Ad_U: \B(L^2(\Gz,\nu)) \longrightarrow \B(L^2(\Gz,\mu)), \quad T \mapsto UTU^* \quad \text{for} \quad T \in \B(L^2(\Gz,\nu)).
\]
We claim: $\Ad_U(P_\G) = P$. In fact, given $\eta \in L^2(\Gz,\mu)$, we have
\begin{align*}
\Ad_U(P_\G)\eta &= U P_\G U^* \eta = U P_\G \left(\frac{1}{\xi} \cdot \eta\right) =U\left(  \big\langle \frac{1}{\xi} \cdot \eta,\chi_{\Gz}\big\rangle_{L^2(\Gz, \nu)} \chi_{\Gz} \right) \\
&= \big\langle \frac{1}{\xi} \cdot \eta,\chi_{\Gz}\big\rangle_{L^2(\Gz, \nu)} \xi = \left(\int_{\Gz} \frac{1}{\xi}(x) \eta(x) \d \nu(x) \right) \cdot \xi\\
&= \left(\int_{\Gz} \eta(x)\xi(x) \d \mu(x) \right) \cdot \xi = \langle \eta, \xi \rangle_{L^2(\Gz, \mu)} \xi= P\eta.
\end{align*}
Hence we prove the claim. Therefore, for any measurable $A,B \subseteq \Gz$ we have
\[
\Ad_U(\chi_A P_\G \chi_B) = \Ad_U(\chi_A) \circ \Ad_U(P_\G) \circ \Ad_U(\chi_B) = \chi_A P \chi_B.
\]

Finally, since $\mu$ and $\nu$ are equivalent, we have $K \subseteq \G$ is decomposable with respect to $\mu$ if and only if it is decomposable with respect to $\nu$. Moreover, for any measurable $A,B \subseteq \Gz$ and unital symmetric decomposable $K \subseteq \G$, we have $\mu(\r(K \cdot A) \cap B) = 0$ if and only if $\nu(\r(K \cdot A) \cap B) = 0$. So we finish the proof.
%Combining them together, we conclude the proof.
\end{proof}


Now we are in the position to prove Theorem \ref{thm:main thm ave proj general}:

\begin{proof}[Proof of Theorem \ref{thm:main thm ave proj general}]
By Lemma \ref{lem:reduction Q}, we can assume that $Z = \emptyset$. Assume $P$ is dynamically quasi-local. It follows from Lemma \ref{lem:equiv measure quasi-local and ppg} that $P_{\G}\in  \CC^*_{\dyn,\q}(\G;\nu)$. Applying Theorem \ref{thm:main thm ave proj}, we obtain that $P_{\G}\in  \CC^*_{\dyn}(\G;\nu)$. Then using Lemma \ref{lem:equiv measure quasi-local and ppg} again, we obtain that $P \in \CC^*_{\dyn}(\G;\mu) = \CC^*_{\dyn}(\G)$.
\end{proof}


\begin{rem}\label{rem:dependence on parameters for general rank one proj}
Note that the map $\Ad_U$ in the proof of Lemma \ref{lem:equiv measure quasi-local and ppg} preserves propagation. Hence combining with Remark \ref{rem:dependence of parameters 2} and \ref{rem:dependence on parameters for main thm}, we know that if the rank-one projection $P$ belongs to $\CC^*_{\dyn,\q}(\G)$, then for any $\epsilon>0$ we can choose $T_\epsilon \in \C_{\dyn}(\G)$ with $(N_\epsilon, L_\epsilon)$-dynamical propagation such that $\|T_\epsilon - P\| < \epsilon$ and the functions $\epsilon \mapsto N_\epsilon$ and $\epsilon \mapsto L_\epsilon$ only depend on quasi-local parameters of $P$.
\end{rem}


Finally, we introduce two variants of Theorem \ref{thm:main thm ave proj general}.
The first one deals with a family version, following the discussion in Section \ref{ssec:basic notions}. Combining Lemma \ref{family of quasi local and quasi local} and Theorem \ref{thm:main thm ave proj general} together with Remark \ref{rem:dependence on parameters for general rank one proj}, we obtain:

%In other words, we consider a sequence of groupoids and apply the discussion in Section \ref{ssec:basic notions} to obtain a similar result for block-rank-one projections.

\renewcommand{\thethmprime}{5.3'}
\begin{thmprime}\label{cor:cor to thm general case prime} 
For each $n\in \N$, let $\G_n$ be a groupoid with a length function $\ell_n$ and $(\Gz_n,\RR_n,\mu_n)$ be a measure space. Form the groupoid $\G=\bigsqcup_{n\in \N} \G_n$ together with a length function $\ell$ and a measure $\mu$ on $\Gz$ as in Section \ref{ssec:basic notions}. Moreover, let $P_n \in \B(L^2(\Gz_n, \mu_n))$ be a rank-one orthogonal projection for each $n \in \N$ and consider their direct sum
\[
P\coloneqq \mathrm{(SOT)}-\sum_{n\in \N} P_n \in \B(L^2(\Gz,\mu)).
\]
%which is called a \emph{block-rank-one} projection.
Then 
%we have $P \in \CC^*_{\dyn}(\mathcal{G})$ \emph{if and only if} $P \in \CC^*_{\dyn,\q}(\mathcal{G})$.
the following are equivalent:
\begin{enumerate}
 \item $P \in \CC^*_{\dyn}(\mathcal{G})$;
 \item $P \in \CC^*_{\dyn,\q}(\mathcal{G})$;
 \item $\G_n$ is asymptotically expanding in the associated measure $\nu_n$ to $P_n$ uniformly in the sense that they have same expansion parameters.
\end{enumerate}
\end{thmprime}


The second one focuses on a specific family of admissible and decomposable subsets allowed to build the notion of (asymptotic) expansion, dynamical propagation and quasi-locality. More precisely, we introduce the following refined version of Definition \ref{decomposable}:

\begin{defn}\label{defn:allowed family}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(\Gz,\RR,\mu)$ be a measure space. Let $\KK$ be a family of admissible bisections which is closed under taking compositions and inverses and $\Gz \in \KK$. A subset $K \subseteq \G$ is called \emph{$\KK$-decomposable} if $K=\bigcup_{i=1}^{N} K_{i}$ for $N \in \N$ and admissible bisection $K_i \in \KK$. 
\end{defn}

Given such a family $\KK$ in Definition \ref{defn:allowed family}, we can replace the word ``decomposable'' by ``$\KK$-decomposable'' in Definition \ref{expanding}, \ref{asymptotically expanding}, \ref{finite dynamical propagation} and \ref{dynamical quasi local} to define the notion of $\KK$-expansion (in measure), $\KK$-asymptotic expansion (in measure), $\KK$-dynamical propagation and $\KK$-dynamical quasi-local, together with $C^*$-algebras $\CC^*_{\dyn}(\G,\KK)$ and  $\CC^*_{\dyn,\q}(\G,\KK)$.


\begin{rem}\label{rem:cofinal family}
Note that if $\KK$ is \emph{cofinal} in the sense that any admissible bisection is contained in the union of finitely many elements in $\KK$, then these notions coincide with the original ones of \emph{possibly different} parameters.
\end{rem}


Following exactly the same proofs, we obtain:

\renewcommand{\thethmpprime}{5.3''}
\begin{thmpprime}\label{cor:cor to thm general case pprime} 
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, $(\Gz,\RR,\mu)$ be a measure space and  $\KK$ be a family of admissible bisections which is closed under taking compositions and inverses and $\Gz \in \KK$. Let $P \in \B(L^2(\Gz,\mu))$ be a rank-one projection, and $\nu$ the associated probability measure on $\Gz$. Then the following are equivalent:
\begin{enumerate}
 \item $P \in \CC^*_{\dyn}(\mathcal{G},\KK)$;
 \item $P \in \CC^*_{\dyn,\q}(\mathcal{G},\KK)$;
 \item $\G$ is $\KK$-asymptotically expanding in measure $\nu$.
\end{enumerate}
\end{thmpprime}





\section{Examples}\label{Examples of measurable groupoids}

In this section, we apply our theory to several classes of groupoids and recover main results in \cite{structure, li2022markovianroealgebraicapproachasymptotic, faucris.282438222}.


