We aim to relate $\CC^*_{\dyn}(\G)$ to the uniform Roe algebra $C^*_{\u}(X)$, and $\CC^*_{\dyn,\q}(\G)$ to the uniform quasi-local algebra $C^*_{\uq} (X)$. To achieve, we combine Lemma \ref{family of quasi local and quasi local} and Proposition \ref{prop:pair groupoids expansion coincidence} with \cite[Lemma 3.13 and 3.14]{Bao2021StronglyQA} and reach the following:

\begin{prop}\label{prop:relation between uniform Roe algs}
With the same notation as above, we have
\begin{enumerate}
 \item $\CC^*_{\dyn}(\G) = \CC^*_{\u}(X) \cap \Pi_{n\in \N} \B(\ell^2(X_n))$; 
 \item$\CC^*_{\dyn}(\G) + \K(\ell^2(X)) = \CC^*_{\u}(X)$;
 \item $\CC^*_{\dyn,\q}(\G) = \CC^*_{\uq}(X) \cap \Pi_{n\in \N} \B(\ell^2(X_n))$; 
 \item $\CC^*_{\dyn,\q}(\G) + \K(\ell^2(X)) = \CC^*_{\uq}(X)$.
\end{enumerate}
\end{prop}


Finally, combining with Theorem \ref{cor:cor to thm general case prime} and Proposition \ref{prop:pair groupoids expansion coincidence}, we recover both \cite[Theorem C]{structure} and \cite[Theorem B]{faucris.282438222}:

\begin{cor}\label{cor:example Roe}
Let $\{(X_n, d_n)\}_{n\in \N}$ be a sequence of finite metric spaces with uniformly bounded geometry, and $(X,d)$ be their coarse disjoint union. For each $n\in \N$, let $P_n \in \B(\ell^2(X_n))$ be a rank-one projection and $\nu_n$ the associated probability measure on $X_n$. For $P=\mathrm{(SOT)}-\sum_{n\in \N} P_n \in \B(\ell^2(X))$, the following are equivalent:
\begin{enumerate}
 \item $P \in \CC^*_{\u}(X)$;
 \item $P \in \CC^*_{\uq}(X)$;
 \item $\{(X_n, d_n, \nu_n)\}_{n\in \N}$ forms a sequence of measured asymptotic expanders.
\end{enumerate}
\end{cor}



\subsection{Semi-direct product groupoids}\label{main thm for semi-direct product groupoid}

In this subsection, we consider groupoid actions on fibre spaces, generalising those in Section \ref{Group action}. Our idea is to package the information of groupoid actions into semi-direct product groupoids, which allows us to use our main results to study groupoid actions. 


%Here we consider the case of semi-direct product groupoids, which provides a groupoid version of Proposition \ref{prop:group action expansion coincidence}, i.e., we define the notion of asymptotic expanding groupoid actions and study its relationship with the asymptotic expansion of the corresponding semi-direct product groupoid. Furthermore, asymptotic expanding groupoid actions recover the notion of asymptotic expanding group actions by groupoids called discrete groups. 


Let us start with some preliminaries for groupoid actions. A \emph{fibre space} over a set $X$ is a pair $(Y,p)$, where $Y$ is a set and $p\colon Y\rightarrow X$ is a surjective map. For two fibre spaces $(Y_1,p_1)$ and $(Y_2,p_2)$ over $X$, we form their \emph{fibred product} to be
\[
    Y_1\tensor*[_{p_1}]{\ast}{_{p_2}}Y_2 \coloneqq \{(y_1, y_2) \in Y_1 \times Y_2 ~|~ p_1(y_1) = p_2(y_2)\}.
\]


%Now we introduce the notion of groupoid actions:

\begin{defn}
    Let $\G$ be a groupoid. A \textit{left $\G$-space} is a fibre space $(Y,p)$ over $\mathcal{G}^{(0)}$, equipped with a map $(\gamma,y)\mapsto \gamma y$ from $\G\tensor*[_{\s}]{\ast}{_p}Y$ to $Y$ (called a \emph{$\G$-action on $(Y,p)$}) which satisfies the following:
    \begin{itemize}
        \item $p(\gamma y) = \r(\gamma)$ for $(\gamma,y)\in \G\tensor*[_{\s}]{\ast}{_p}Y$, and $p(y)y = y$;
        \item $\gamma_{2}(\gamma_{1}y) = (\gamma_{2}\gamma_{1})y$ for $(\gamma_{1},y)\in \G\tensor*[_{\s}]{\ast}{_p}Y$ and $\s(\gamma_{2}) = \r(\gamma_{1})$.
    \end{itemize}
\end{defn}

Given a $\G$-space $(Y, p)$, the associated \textit{semi-direct product groupoid} $Y\rtimes\G$ is defined (as a set) to be $Y\tensor*[_{p}]{\ast}{_\r}\G$. For $(y,\gamma) \in Y\rtimes\G$, define its range to be $(y,\r(\gamma))$ and its source to be $(\gamma^{-1}y,\s(\gamma))$. The product and inverse are given by
\[
    (y,\gamma)(\gamma^{-1}y,\gamma')=(y,\gamma\gamma') \quad \text{and} \quad (y,\gamma)^{-1} = (\gamma^{-1}y,\gamma^{-1}).
\]
Clearly $(y,p(y))\mapsto y$ is a bijection from the unit space of $Y\rtimes\G$ onto $Y$. Hence from now on, we regard Y as the unit space of the groupoid $Y\rtimes\G$.

Given a bisection $K \subseteq \G$, we define the following map:
\begin{equation}\label{EQ:beta_K}
\beta_{K}: p^{-1}(\s(K))\rightarrow p^{-1}(\r(K)), \quad y \mapsto \gamma_y\cdot y \quad \text{for} \quad y \in p^{-1}(\s(K)),
\end{equation}
where $\gamma_y\in K$ is the unique point in $K$ such that $\s(\gamma_y)=p(y)$. The following is straightforward:

\begin{lem}\label{lem:semi direct groupoid bisection}
For a groupoid $\G$ acting on a fibre space $(Y,p)$ and a bisection $K \subseteq \G$, then $Y\tensor*[_{p}]{\ast}{_\r}K$ is a bisection in $Y\rtimes\G$. Moreover, we have $\tau_{Y\tensor*[_{p}]{\ast}{_\r}K} = \beta_K$, where $\tau_{Y\tensor*[_{p}]{\ast}{_\r}K}$ is defined in (\ref{EQ:alpha_K}) and $\beta_K$ in (\ref{EQ:beta_K}).
\end{lem}



%In the following, we equip $\G$ with a length function and $Y$ with a probability measure. 
Analogous to Definition \ref{admissible}, we introduce the following:

\begin{defn}\label{defn:dynamically admissible}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(Y,p)$ be a $\G$-space equipped with a probability measure structure $(Y,\RR,\mu)$. A bisection $K \subseteq \G$ is called \emph{dynamically admissible} if $p^{-1}(\s(K)),p^{-1}(\r(K)) \in \RR$, the bijection $\beta_{K}$ from (\ref{EQ:beta_K}) is a measure-class-preserving measurable isomorphism and $\ell(K)$ is finite. 
\end{defn}


Now we aim to relate Definition \ref{defn:dynamically admissible} to the notion of admissible bisections for the semi-direct product groupoid $Y \rtimes \G$. Firstly, note that a length function $\ell$ on $\G$ gives rise to a length function $\hat{\ell}$ on $Y \rtimes \G$ by 
\begin{equation}\label{EQ:induced ell}
\hat{\ell}(y,\gamma) \coloneqq \ell(\gamma) \quad \text{for} \quad (y,\gamma)\in Y\rtimes \G.
\end{equation}
Then Lemma \ref{lem:semi direct groupoid bisection} implies the following:
%The following lemma provides a characterisation of dynamical admissible bisections of $\G$ in the setting of the semi-direct product groupoid $Y\rtimes \G$.

\begin{lem}\label{lem:admissible equivalence between betaK and Yrtimes K}
In the setting above, 
%Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(Y,p)$ be a $\G$-space equipped with a probability measure structure $(Y,\RR,\mu)$. Equip $Y\rtimes \G$ with the length function $\hat{\ell}$ from (\ref{EQ:induced ell}). Then
a bisection $K\subseteq \G$ is dynamically admissible \emph{if and only if} $Y\tensor*[_{p}]{\ast}{_\r}K$ is admissible in $Y \rtimes \G$.
\end{lem}

%\begin{proof}
%Since $Y \prescript{}{p}{\ast}_{\r} K=W \prescript{}{p}{\ast}_{\r} K$ where $W=p^{-1}(\r(K))$ and $K$ is dynamically admissible if and only if $W \prescript{}{p}{\ast}_{\r} K$ is admissible, we finish our proof.
%\end{proof}


Lemma \ref{lem:admissible equivalence between betaK and Yrtimes K} suggests us to consider the following specific family of admissible bisection in $Y \rtimes \G$:
\begin{equation}\label{EQ:semi-direct family}
\KK_{\G,Y}=\left\{Y \tensor*[_{p}]{\ast}{_\r} K\subseteq Y\rtimes \G~\big|~K\subseteq \G \text{ dynamically admissible}\right\}.
\end{equation}
It is clear that $\KK_{\G,Y}$ is closed under taking composition and inverse, and contains $Y \tensor*[_{p}]{\ast}{_\r} \Gz = Y$ since $\Gz$ is dynamically admissible. Applying the discussion at the end of Section \ref{sec:Main results}, we define $\KK_{\G,Y}$-decomposability for subsets in $Y \rtimes \G$. This can also be translated using the following notion of dynamical decomposability:


\begin{defn}\label{defn:dynamically decomposable}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(Y,p)$ be a $\G$-space equipped with a probability measure structure $(Y,\RR,\mu)$. A subset $K \subseteq \G$ is called \emph{dynamically decomposable} if $K=\bigcup_{i=1}^{N} K_{i}$ for $N \in \N$ and dynamically admissible bisection $K_i \subseteq \G$.
\end{defn}

Directly from Lemma \ref{lem:admissible equivalence between betaK and Yrtimes K}, we have the following.

\begin{cor}\label{cor:decomposable equivalence between betaK and Yrtimes K}
Let $\mathcal{G}$ be a groupoid with a length function $\ell$, and $(Y,p)$ be a $\G$-space equipped with a probability measure structure $(Y,\RR,\mu)$. Equip $Y\rtimes \G$ with the length function $\hat{\ell}$ from (\ref{EQ:induced ell}). Then for $K\subseteq \G$, $K$ is dynamically decomposable \emph{if and only if} $Y\tensor*[_{p}]{\ast}{_\r}K\subseteq Y\rtimes \G$ is $\KK_{\G,Y}$-decomposable.
\end{cor}

Similar to Lemma \ref{basic assumprop2}, it is easy to see that for any dynamically decomposable $K\subseteq \G$ and measurable $A \subseteq Y$, then $K\cdot A$ is also measurable. Moreover, direct calculations show that 
\[
K\cdot A=\r\big((Y \tensor*[_{p}]{\ast}{_\r} K) \cdot A\big).
\]
Hence it turns out that the $\KK_{\G,Y}$-asymptotic expansion of the semi-direct groupoid $\G \rtimes Y$ is equivalent to the following:

