\subsection{Graph groupoids}\label{main thm for graph groupoid} 

%Our final example focuses on graph groupoids, coming from \cite{KRR97}. 
We firstly recall necessary background knowledge, and details can be found in \cite{KRR97}.

Throughout this subsection, let $G=(V,E,r,s)$ be a directed uniformly locally finite connected graph, where $V$ is the vertex set, $E$ is the edge set and $r,s: E\rightarrow V$ describing the range and source of edges. Here $G$ is called \emph{uniformly locally finite} if $\sup_{v\in V} |s^{-1}(v)|$ and $\sup_{v\in V} |r^{-1}(v)|$ are finite.
Given $v\in V$, denote $\sdeg(v) \coloneqq |s^{-1}(v)|$.

%Consider a directed graph $G=(V,E,r,s)$ consists of a countable set $V$ of vertices, a set $E$ of edges, and maps $r,s: E\rightarrow V$ describing the range and source of edges. We assume that the map $s:E\rightarrow V$ is onto. We say that $G=(V,E,r,s)$ is row finite if $s^{-1}(v)\subseteq E$ is a finite set for all $v\in V$, and uniformly locally finite if both $s^{-1}(v)$ and $r^{-1}(v)$ are uniformly finite for all $v\in V$.

Recall that a \emph{finite path} in $G$ is a sequence $\alpha = (\alpha_1, \cdots, \alpha_k)$ of edges in $E$ with $s(\alpha_{j+1}) = r(\alpha_j)$ for $1\leq j \leq k-1$. Write $s(\alpha) = s(\alpha_1)$ and $r(\alpha) = \r(\alpha_k)$. The \emph{length} of $\alpha$ is defined to be $|\alpha| \coloneqq k$. We denote by $v$ the path of length $0$ with $s(v)=r(v)=v$.
Denote $F(G)$ the set of all finite paths in $G$, and $F(G,v)$ those starting at $v\in V$. Similarly, denote $P(G)$ the set of all infinite paths $\alpha=(\alpha_1,\alpha_2,...)$ in $G$, and $P(G,v)$ those starting at $v\in V$. For $\alpha,\mu\in F(G)$ satisfying $r(\alpha)=s(\mu)$, we define a path $\alpha\mu\in F(G)$ of length $|\alpha|+|\mu|$ by $\alpha\mu=(\alpha_1,...,\alpha_{|\alpha|},\mu_1,...,\mu_{|\mu|})$. We can similarly define $\alpha x\in P(G)$ for $\alpha\in F(G)$ and $x\in P(G)$ satisfying $s(x)=r(\alpha)$. 

%Embed $P(G)$ into the infinite product $\Pi E$ of the edge set, we equip $P(G)$ with the induced topology of the product topology on $\Pi E$. 

Equip $P(G)$ with the induced topology from the product topology on the infinite product $\Pi E$ of the edge set $E$.
By \cite[Corollary 2.2]{KRR97}, this topology is locally compact, $\sigma$-compact, totally disconnected and Hausdorff. Moreover, it has a basis consisting of all the \emph{cylinder sets}:
\[
Z(\alpha)=\left\{x\in P(G) ~|~ x_1=\alpha_1,...,x_{|\alpha|}=\alpha_{|\alpha|}\right\} \quad \text{where} \quad \alpha \in F(G).
\]
By \cite[Lemma 2.1]{KRR97}, $Z(\alpha) \cap Z(\beta) \neq \emptyset$ if and only if either $\alpha$ is a \emph{prefix} of $\beta$ (\emph{i.e.}, $\beta = \alpha \beta'$ for some $\beta' \in F(G)$) or $\beta$ is a prefix of $\alpha$.

%Define
%$$Z(\alpha)=\{x\in P(G):x_1=\alpha_1,...,x_{|\alpha|}=\alpha_{|\alpha|}\}$$
%If $G$ is a row-finite directed graph, the cylinder sets $\{Z(\alpha):\alpha\in F(G)\}$ form a basis of compact open sets for a locally compact, $\sigma$-compact, totally disconnected, Hausdorff topology on $P(G)$, which coincides with the product topology obtained by viewing $P(G)$ as a subset of $\prod E$.


To construct the groupoid associated to the graph $G$, we consider the following equivalence relation on $P(G)$: two paths $x,y\in P(G)$ are \emph{shift equivalent} with lag $k\in \mathbb{Z}$ (written $x\sim_k y$) if there exists $N\in \mathbb{N}$ such that $x_i=y_{i+k}$ for all $i\geq N$. 

\begin{defn}\label{defn:graph groupoid}
For a directed uniformly locally finite connected graph $G=(V,E,r,s)$, the associated \emph{graph groupoid} $\G$ is defined to be (as a set):
\[
\mathcal{G}=\{(x,k,y)\in P(G)\times \mathbb{Z}\times P(G) ~|~ x\sim_k y\}
\]
with $(x,k,y)\cdot (y,l,z)\coloneqq(x,k+l,z)$ and $(x,k,y)^{-1}\coloneqq(y,-k,x)$. The range and source maps are given by $\r(x,k,y)=x$ and $\s(x,k,y)=y$, respectively, with $\Gz = P(G)$.
\end{defn}


For $\alpha, \beta \in F(G)$ with $r(\alpha)=r(\beta)$, denote
\[
Z(\alpha,\beta)\coloneqq \left\{(x,k,y) ~|~ x\in Z(\alpha),y\in Z(\beta),k=|\beta|-|\alpha|,x_i=y_{i+k}~\text{for}~i\geq |\alpha|\right\},
\]
which is a bisection in $\G$ with $\r(Z(\alpha, \beta)) = Z(\alpha)$ and $\s(Z(\alpha, \beta)) = Z(\beta)$.
It follows from \cite[Proposition 2.6]{KRR97} that all the sets $Z(\alpha,\beta)$ form a basis for a locally compact Hausdorff topology on $\mathcal{G}$, which makes it a second countable, \'{e}tale groupoid where each $Z(\alpha,\beta)$ is compact open. The induced topology on $\Gz=P(G)$ coincides with the product topology defined above.

%The topology on the unit space $P(G)$ agrees with the topology it inherits by viewing it as the subset $\mathcal{G}^{(0)}=\{(x,0,x):x\in P(G)\}$ of $\mathcal{G}$.

\bigskip


To apply our results to the graph groupoid $\G$, we firstly endow $\G$ with the following length function $\ell$. For $(x,k,y) \in \G$, choose the smallest $N \in \N$ such that $x_i=y_{i+k}$ for all $i\geq N$, denoted by $N(x,k,y)$, and set:
\begin{equation}\label{EQ:length function for graph groupoids}
\ell(x,k,y)=2N(x,k,y) + k.
\end{equation}
Note that $N(x,k,y)+k \geq 0$ for any $(x,k,y) \in \G$.
Intuitively, $\ell(x,k,y)$ is the total length of the shortest starting segments in $x$ and $y$, deleting which $x$ and $y$ are the same with lag $k$. 
It is routine to check that $\ell$ is indeed a length function on $\G$ taking values in $\N$. Moreover, given $n \in \N$, the ball in $\G$ defined by $B_n\coloneqq \{(x,k,y) \in \G ~|~ \ell(x,k,y) \leq n\}$ can be reconstructed as follows:
\begin{equation}\label{EQ:dec for ball in graph groupoid}
B_n =\bigcup \left\{Z(\alpha,\beta) ~|~ \alpha, \beta \in F(G) \text{ with } r(\alpha)=r(\beta) \text{ and } |\alpha|+|\beta| \leq n\right\}.
\end{equation}
Moreover, we have 
\begin{equation}\label{EQ:convolution of B1}
B_n = (B_1)^n \quad \text{for any} \quad n\in \N.
\end{equation}
These can be verified by direct calculations, and we omit the details. 


Next, we will define a Borel measure $\mu$ on $\Gz=P(G)$. Given $v\in V$ and $b_v>0$, we define a measure $\mu_v$ on $P(G,v)$ by firstly setting:
\begin{equation}\label{EQ:def for mu_v}
\mu_v(Z(\alpha)) \coloneqq b_v \cdot \prod_{i=1}^{k} \frac{1}{\sdeg(s(\alpha_i))} \quad \text{for} \quad \alpha = (\alpha_1, \alpha_2, \cdots, \alpha_k) \in F(G,v).
\end{equation}
Since the sets $Z(\alpha)$ for $\alpha \in F(G,v)$ form a basis for the topology on $P(G,v)$, then the above gives rise to a Borel measure $\mu_v$ on $P(G,v)$.

Now we combine $\mu_v$ into a single probability Borel measure $\mu$ on $P(G)$. Since $G$ is connected and uniformly locally finite, then $V$ is countable. For each $v\in V$, we choose $b_v>0$ such that $\sum_{v\in V} b_v =1$. Note that $P(G) = \bigsqcup_{v\in V} P(G,v)$ and $V$ is countable. Then the measures $\mu_v$ defined above give rise to a Borel measure $\mu$ on $P(G)$. In the sequel, we fix such a measure $\mu$.


%Moreover, it is clear that $Z(\alpha,\beta)$ is a strongly admissible bisection for any $\alpha,\beta\in F(G)$ with $\r(\alpha)=\r(\beta)$.

By the construction of $\ell$ and $\mu$ above, it is clear that for any $\alpha, \beta \in F(G)$ with $r(\alpha)=r(\beta)$, the subset $Z(\alpha, \beta)$ is an admissible bisection. Moreover, we have:

\begin{lem}\label{decomposable and bounded length on graph groupoid}
For the graph groupoid $\G$ with the length function $\ell$ and the measure $\mu$ on $\Gz$ above, the ball $B_n=\{(x,k,y) \in \G ~|~ \ell(x,k,y) \leq n\}$ is decomposable for each $n\in \N$. 
\end{lem}

\begin{proof}
Fix $n\in \N$. We aim to decompose the ball $B_n$ into finitely many admissible bisections. The idea is to combine several $Z(\alpha,\beta)$ in (\ref{EQ:dec for ball in graph groupoid}) into a single bisection. 

To achieve, we construct another graph $\hat{G} = (\hat{V}, \hat{E})$ with 
\[
\hat{V} \coloneqq \big\{(\alpha, \beta) ~\big|~ \alpha, \beta \in F(G) \text{ with } r(\alpha)=r(\beta) \text{ and } |\alpha|+|\beta| \leq n\big\}
\]
and two vertices $(\alpha_1, \beta_1)$ and $(\alpha_2, \beta_2)$ in $\hat{V}$ are connected by an edge if and only if at least one of the following four cases hold: (i) $\alpha_1$ is a prefix of $\alpha_2$; (ii) $\alpha_2$ is a prefix of $\alpha_1$; (iii) $\beta_1$ is a prefix of $\beta_2$; (iv) $\beta_2$ is a prefix of $\beta_1$. 
Since $G$ is uniformly locally finite and connected, then $\hat{G}$ is uniformly locally finite as well. It is a well-known fact (see, \emph{e.g.}, \cite[Lemma 4.2]{ZhangquasilocalityandpropertyA}) that $\hat{V}$ can be decomposed into $\hat{V} = \bigsqcup_{p=1}^N \hat{V}_p$ such that for each $p$, any two distinct vertices in $\hat{V}_p$ are \emph{not} connected by an edge. 

For each $p=1,\cdots,N$, set
\[
K_p\coloneqq \bigsqcup_{(\alpha ,\beta) \in \hat{V}_p} Z(\alpha, \beta).
\]
By the construction of $\hat{E}$, it is routine to check that $K_p$ is an admissible bisection. Finally, (\ref{EQ:dec for ball in graph groupoid}) implies $B_n = \bigcup_{p=1}^N K_p$ and hence, we conclude the proof.
%Thus $B_l (k_0)=\bigcup_{p=1}^N (\bigcup_{(\alpha,\beta)\in \widehat{V}_p} Z(\alpha,\beta))$ where each $\bigcup_{(\alpha,\beta)\in \widehat{V}_p} Z(\alpha,\beta)$ is an open bisection. Since $\G$ is second countable and each $Z(\alpha,\beta)$ is strongly admissible, it follows that $\bigcup_{(\alpha,\beta)\in \widehat{V}_p} Z(\alpha,\beta)$ is strongly admissible, which implies that $B_l (k_0)$ is strongly decomposable. Hence we complete the proof.
\end{proof}


Lemma~\ref{decomposable and bounded length on graph groupoid} shows that the set $\{B_n~|~n\in \N\}$ is cofinal in the set of all decomposable subsets of $\G$ in the sense of Remark \ref{rem:cofinal family}. Hence we can merely use these balls to define asymptotic expansion, dynamical propagation and quasi-locality for graph groupoids by the discussion at the end of Section \ref{sec:Main results}. 


Moreover, we have the following:


