where $\alpha_p\coloneqq (n_p,n_p+1)$. Then we have 
\[
\mu(A_p)>\frac{1}{k}\mu(Z_{0,n_p})\geq \frac{1}{k(k+1)} \quad \text{and} \quad \mu(A_p)\leq \frac{1}{k}\mu(P(G))=\frac{1}{k}.
\]
By the construction of $F(G)_{n_p}$, it is clear that for any $\alpha \in F(G)_{n_p}$ with $|\alpha|\geq 1$ we have $\r(B_1\cdot Z(\alpha\alpha_p))\subseteq A_p$. Hence
\[
\mu(\r(B_1\cdot A_p))=\mu(A_p \sqcup Z(n_p +1))=\mu(A_p)+\frac{1}{2^{n_p +2}},
\]
which shows that $\mu\big(\r((B_1\cdot A_p) \setminus A_p)\big) = \frac{1}{2^{n_p +2}} \to 0$ as $p \to \infty$. This concludes (2).
\end{ex}





