  %%%%%%%%%%%%%%%
  \textbf{Pre-mixer} &  \textbf{Definition } \MAT{P} &  N_P & \textbf{Uncoupled} \\  [0.5mm]   \hline  \noalign{\vskip 1mm}  
  %%%%%%%%%%%%%
