  \textrm{Multi-band} &  \MAT{I}_{N_C} \otimes \VEC{1}_{N_B} & N_C & \textrm{True} \\
    \textrm{Multi-content} &  \VEC{1}_{N_C}\otimes \MAT{I}_{N_B} & N_B  & \textrm{True} \\  [0.5mm]
