%     &= -(\mathcal{L}_c + \mathcal{L}_q )W[\phi,\Pi ; t]
%     \end{split}
% \end{equation}
% where $\mathcal{L}_c = H \Lambda$ is the classical Liouville operator and $\mathcal{L}_q$ (= all higher-order terms) is the quantum jump operator with $\mathcal{O}(\hbar ^2)$ order precision, using the classical Hamiltonian canonical equation


