\section{The relevant derivation of the Wigner Function}%初始W的推导
\label{A.A}
In Eq.~\ref{W_1st}, we derive an explicit expression for the Wigner function of an interacting system, neglecting terms of order $\mathcal{O}(\hbar^2)$. Here, we provide the detailed derivation. The Wigner function is defined as the Weyl-Wigner transform of the density matrix operator~\cite{Yoneya:2024asd,Blakie:2008vka}. We begin by expanding the density matrix operator in Eq.~\ref{rho}:
\begin{equation}
    \label{denstity_expanse}
    W(\phi,\Pi)=(\hat\rho)_{W}=\frac{1}{Z}(1-\beta (\hat{H})_W+\frac{1}{2!}\beta^2(\hat{H}^2)_W+\cdots)
\end{equation}
The subscript $W$ denotes the Weyl-Wigner transformation. By substituting the first-order expansion into the Hamiltonian, we obtain $(\hat{H})_W=\int \mathcal{D} \varphi(x) \exp \left[-i \int d x \Pi(x) \varphi(x)\right]\left\langle\phi(x)+\frac{\varphi(x)}{2}\right|\hat{H} \left|\phi(x)-\frac{\varphi(x)}{2} \right\rangle = Q_{\Pi}+Q_{\nabla}+Q_V$, the three ‘Q’ represents the Wigner transformation of the kinetic energy term, the gradient energy term and the potential energy term respectively, so

% \begin{equation}
%     \label{f2}
%     \begin{split}
%         W[\phi,\Pi]&=\mathcal{N} \int \mathcal{D} \varphi(x) \exp \left[-i \int d x \Pi(x) \varphi(x)\right] \times\left\langle\phi(x)+\frac{\varphi(x)}{2}\right|1-\beta \hat{H} \left|\phi(x)-\frac{\varphi(x)}{2} \right\rangle\\
%         &=\mathcal{N} \int \mathcal{D} \varphi(x) \exp \left[-i \int d x \Pi(x) \varphi(x)\right] \delta(\varphi) \\
%         &\quad -\mathcal{N}\beta \int \mathcal{D} \varphi(x) \exp \left[-i \int d x \Pi(x) \varphi(x)\right]\left\langle\phi(x)+\frac{\varphi(x)}{2}\right|\hat{H} \left|\phi(x)-\frac{\varphi(x)}{2} \right\rangle \\
%         &=\mathcal{N} \left[1-\beta \int \mathcal{D} \varphi(x) \exp \left[-i \int d x \Pi(x) \varphi(x)\right]\left\langle\phi(x)+\frac{\varphi(x)}{2}\right|\hat{H} \left|\phi(x)-\frac{\varphi(x)}{2} \right\rangle \right] \\
%         &=\mathcal{N}\left[1-\beta Q\right]        
%     \end{split}
% \end{equation}

% where $\mathcal{N}= \left[\int \mathcal{D}\phi\frac{\mathcal{D}\Pi}{2\pi}\int \mathcal{D} \varphi(x) \exp \left[-i \int d x \Pi(x) \varphi(x)\right] \left\langle\phi(x)+\frac{\varphi(x)}{2}\right|1-\beta \hat{H} \left|\phi(x)-\frac{\varphi(x)}{2} \right\rangle \right]^{-1} $ is normalization factor, we set $Q=Q_{\Pi}+Q_{\nabla}+Q_V$, so


\begin{equation}
    Q_{\Pi}=\frac{1}{2}\int \mathcal{D} \varphi(x) \int dx \exp \left[-i \int d x \Pi(x) \varphi(x)\right] \left\langle\phi(x)+\frac{\varphi(x)}{2}\right|\hat{\Pi}^2 \left|\phi(x)-\frac{\varphi(x)}{2} \right\rangle
\end{equation}
Introduce the complete set of the momentum $\hat{\Pi}$ eigenstate $\left| \Pi_1 \right\rangle$ and utilize the commutation relation $[\hat{\phi}(x), \hat{\phi}(y)]=[\hat{\Pi}(x), \hat{\Pi}(y)]=0$, we get
\begin{equation}
    \label{f2}
    \begin{split}
        Q_{\Pi}&=\frac{1}{2}\int \mathcal{D} \varphi(x) \int dx \exp \left[-i \int dx \Pi \varphi\right] \int \frac{\mathcal{D}\Pi_1}{2\pi}\left\langle \phi+\frac{\varphi}{2}\left| \hat{\Pi}^2 \right| \Pi_1 \right\rangle \left\langle \Pi_1 \middle|\phi-\frac{\varphi}{2} \right\rangle \\
        &=\frac{1}{2}\int \mathcal{D} \varphi(x) \int dx \exp \left[-i \int dx \Pi \varphi \right] \int \frac{\mathcal{D}\Pi_1}{2\pi} \Pi_1^2 \left\langle \phi+\frac{\varphi}{2} \middle|\Pi_1 \right\rangle \left\langle \Pi_1 \middle|\phi-\frac{\varphi}{2} \right\rangle \\
        &=\frac{1}{2}\int \mathcal{D} \varphi(x) \int dx \int \frac{\mathcal{D}\Pi_1}{2\pi} \Pi_1^2 e^{-i \int dx \Pi \varphi} e^{i \int dx \Pi_1(\phi+ \frac{\varphi}{2})} e^{-i \int dx \Pi_1(\phi- \frac{\varphi}{2})}\\
        &=\frac{1}{2}\int dx \int \mathcal{D}\Pi_1 \Pi_1^2 \int  \frac{\mathcal{D}\varphi(x)} {2\pi} e^{i \int dx \varphi(\Pi_1-\Pi) } \\
        &=\frac{1}{2}\int dx \int \mathcal{D}\Pi_1 \Pi_1^2 \delta(\Pi_1-\Pi) \\
        &=\frac{1}{2}\int \Pi^2(x) dx
    \end{split}    
\end{equation}
It's a little bit more complex for $Q_{\nabla}$
\begin{equation}  
\label{Q_nabla}
        Q_{\nabla}=\int \mathcal{D} \varphi(x) \exp \left[-i \int dx \Pi \varphi\right] \left\langle\phi(x)+\frac{\varphi(x)}{2}\right| \int dx \frac{1}{2} (\nabla \hat{\phi})^2 \left|\phi(x)-\frac{\varphi(x)}{2} \right\rangle             
\end{equation}
in order to deal with the term $\left \langle \right| \int dx \frac{1}{2} (\nabla \hat{\phi})^2 \left| \right\rangle $, we discretize the field, and simplify that the field is distributed in 1 dimensional $x$ space, and subsequent derivations from 1 to higher dimensions are easy to generalize, so
\begin{equation}
    \int dx \frac{1}{2} (\nabla \hat{\phi})^2=\frac{a}{2} \sum_i (\frac{\hat{\phi}_{i+1} - \hat{\phi}_i}{a})^2 = \frac{1}{2a}\sum_i(\hat{\phi}^2_{i+1}+ \hat{\phi}^2_i- \hat{\phi}_{i+1}\hat{\phi}_i- \hat{\phi}_i\hat{\phi}_{i+1} )
\end{equation}
put it in $\left \langle \right| \int dx \frac{1}{2} (\nabla \hat{\phi})^2 \left| \right\rangle $, we get
\begin{equation}
\label{nabla_cacu}
\begin{aligned}
    &\left\langle\phi+\frac{\varphi}{2}\right| \int d x \frac{1}{2}(\nabla \hat{\phi})^2\left|\phi-\frac{\varphi}{2}\right\rangle  \\
    &=\frac{1}{2a} \sum_i\left[\left\langle\phi+\frac{\varphi}{2}\right| \hat{\phi}_{i+1}^2+\hat{\phi}_i^2-\hat{\phi}_{i+1} \cdot \hat{\phi}_i-\hat{\phi}_i \cdot \hat{\phi}_{i+1}\left|\phi-\frac{\varphi}{2}\right\rangle\right. \\
    &=\frac{1}{2a} \sum_i\left[\left(\phi_{i+1}-\frac{\varphi_{i+1}}{2}\right)^2+\left(\phi_i-\frac{\varphi_i}{2}\right)^2-\left(\phi_{i+1}-\frac{\varphi_{i+1}}{2}\right)\left(\phi_i-\frac{\varphi_i}{2}\right) \right. \\
    &\quad -\left(\phi_i-\frac{\varphi_i}{2}\right)\left(\phi_{i+1}-\frac{\varphi_{i+1}}{2}\right)\left] \left\langle\left.\phi+\frac{\varphi}{2} \right\rvert\, \phi-\frac{\varphi}{2}\right\rangle \right. \\
    &=\frac{a}{2} \sum_i\left[\left(\frac{\phi_{i+1}-\phi_i}{a}\right)^2+\frac{1}{2}\left(\frac{\varphi_{i+1}-\varphi_i}{a}\right)^2-\left(\frac{\phi_{i+1}-\phi_i}{a}\right)\left( \frac{\varphi_{i+1}-\varphi_i}{a}\right)\right] \cdot \delta(\varphi) \\
    & \xrightarrow{\text {continue limit}} \frac{1}{2} \delta(\varphi) \int dx\left[(\nabla \phi)^2+\frac{1}{2}(\nabla \varphi)^2-\nabla \phi \cdot \nabla \varphi\right]
\end{aligned}
\end{equation}
so put Eq.\ref{nabla_cacu} in Eq.\ref{Q_nabla}
\begin{equation}
    \begin{aligned}
        Q_{\nabla} &= \frac{1}{2} \int \mathcal{D} \varphi(x) \exp \left[-i \int dx \Pi \varphi\right] \delta(\varphi) \int dx\left[(\nabla \phi)^2+\frac{1}{2}(\nabla \varphi)^2-\nabla \phi \cdot \nabla \varphi\right] \\
        &=\frac{1}{2} \int dx \int \mathcal{D} \varphi(x) \exp \left[-i \int dx \Pi \varphi\right] \delta(\varphi) \left[(\nabla \phi)^2+\frac{1}{2}(\nabla \varphi)^2-\nabla \phi \cdot \nabla \varphi\right] \\
        &=\frac{1}{2} \int ( \nabla\phi(x))^2 dx
    \end{aligned}
\end{equation}
Now we have the $Q_V$ term left, consider the $\hat{\phi}$ operator to any power: $\hat{\phi}^m $, where $m$ is a positive integer, we can utilize the Weyl ordering of the operators\cite{Yoneya:2024asd}\cite{Hillery:1983ms}, use such symmetric ordering method and combined with the commutation relation mentioned earlier, makes it easy for us to obtain
\begin{equation}
    \begin{aligned}
        & \int \mathcal{D}\varphi(x) \exp[-i\int dx\Pi\varphi] \int dx \left\langle\phi+\frac{\varphi}{2}\right| \hat{\phi}^m\left|\phi-\frac{\varphi}{2}\right\rangle \\
        = & \int \mathcal{D} \varphi(x) \exp \left[-i \int dx \Pi \varphi\right] \int dx\left(\phi-\frac{\varphi}{2}\right)^m\left\langle\left.\phi+\frac{\varphi}{2} \right\rvert\, \phi-\frac{\varphi}{2}\right\rangle \\
        = & \int dx \int \mathcal{D} \varphi(x) \exp \left[-i \int dx \Pi \varphi\right]\left(\phi-\frac{\varphi}{2}\right)^m \cdot \delta\left(\varphi \right) \\
        = & \int \phi^m(x) dx
    \end{aligned}
\end{equation}
so for a polynomial with a potential energy of $\phi$, we can easily get
\begin{equation}
    Q_V=\int V(\phi) dx
\end{equation}
To sum up, we can obtain that the Weyl-Wigner transformation of the Hamiltonian operator is the classic Hamiltonian $(\hat{H})_W=H_W=\int dx^3[\frac{1}{2}\Pi^2(x) + \frac{1}{2}(\nabla \phi(x))^2 + V(\phi)]$. To handle the higher-order terms of the density matrix operator expansion, we need to consider the Moyal product 
'$\star$' \cite{Hillery:1983ms}\cite{Moyal:1949sk}\cite{POLKOVNIKOV20101790}

 \begin{equation}
     \label{H^2_W}
     \begin{aligned}
         (\hat{H}^2)_W=&H_W\star H_W =H_W exp(\frac{i\hbar}{2}\Lambda)H_W\\
         =& H_W \cdot H_W+\frac{i\hbar}{2}\{H_W,H_W\}_{PB}-\frac{\hbar^2}{8}\Lambda^2(H_W,H_W)+\mathcal{O}(\hbar^3) \\
         =&H_W^2-\frac{\hbar^2}{8}[ \frac{\delta^2 H_W}{\delta\phi(x)\delta\phi(y)} \frac{\delta^2 H_W}{\delta\Pi(x)\delta\Pi(y)}-2\frac{\delta^2 H_W}{\delta\phi(x)\delta\Pi(y)} \frac{\delta^2 H_W}{\delta\Pi(x)\delta\phi(y)}+\frac{\delta^2 H_W}{\delta\Pi(x)\delta\Pi(y)} \frac{\delta^2 H_W}{\delta\phi(x)\delta\phi(y)} ]+\mathcal{O}(\hbar^3) \\
         =&H_W^2-\frac{\hbar^2}{4}V''(\phi)+\mathcal{O}(\hbar^3)
     \end{aligned}
 \end{equation}
 Here $\Lambda$, like in Eq.\ref{W_eom}, is a Poisson Bracket operator '$\{ ~,\}_{PB}$', in the second row, we have already expanded the Taylor series and the Hamiltonian was introduced for simplification. For the Wigner transformation of the higher-order terms of the Hamiltonian operator, we can also obtain it by a similar method
  \begin{equation}
     \label{H^3_W}
     \begin{aligned}
         (\hat{H}^3)_W
         =&H_W^3+\frac{i\hbar}{2} \{H_W^2,H_W\}_{PB} -\frac{\hbar^2}{8}[\Lambda^2(H_W,H_W)H_W+\Lambda^2(H_W^2,H_W)]+\mathcal{O}(\hbar^3)
     \end{aligned}     
 \end{equation}
Ultimately, we can apply the Weyl-Wigner transformation to the Hamiltonian operator raised to an arbitrary power, and obtain the following form: $(\hat{H}^n)_W=H_W^n+\frac{i\hbar}{2}\{H_W^{n-1},H_W\}_{PB}+\mathcal{O}(\hbar^2)$. It can be shown that the first-order term in $\hbar$ vanishes, thus we obtain:
\begin{equation}
    W[\phi,\Pi] =\frac{1}{Z} e^{-\beta H_W}\left[1+\mathcal{O}(\hbar^2)\right] 
    \end{equation}
\section{More presentation of the numerical results}
We give the initial power spectrum by Eq.~\ref{initial_spectrum}, in our $1+1$ dimensional work, the two-point correlation functions in $k$ space can be written as:
\begin{equation}
    \label{two point corre}
    \begin{aligned}
        \left \langle\phi(k)\phi(k')\right \rangle &= 2\pi \mathcal{P}_{\phi}(k)\delta(k-k')\\
        \left \langle\Pi(k)\Pi(k')\right \rangle &= 2\pi \mathcal{P}_{\Pi}(k)\delta(k-k')\\
        \left \langle\phi(k)\Pi(k')\right \rangle &= 0
    \end{aligned}
\end{equation}
We can use the rescale factor $f^{\star}$ and $\omega^{\star}$ to get the dimensionless initial variance of the Fourier modes in the lattice, it can be expressed as:
\begin{equation}
    \label{initial variance}
    \begin{aligned}
        | \tilde{\phi}(\tilde{k})|^2 &=(\frac{\omega^{\star}}{f^{\star}})^2(\frac{N}{\Delta x_s})\tilde{\mathcal{P}}_{\phi}(\tilde{k}) \\
        | \tilde{\Pi}(\tilde{k})|^2 &=(\frac{\omega^{\star}}{f^{\star}})^2(\frac{N}{\Delta x_s})\tilde{\mathcal{P}}_{\Pi}(\tilde{k})
    \end{aligned}
\end{equation}
where $\tilde{\mathcal{P}} \equiv \omega^{\star} \mathcal{P}$ denotes the dimensionless power spectrum used in the simulation. Typically, a complex Gaussian variable can be generated by sampling the modulus from a Rayleigh distribution determined by the variance, and the phase from a uniform distribution, then combining them as a complex number. However, in the 1+1 dimensional case, due to the symmetry properties of the one-dimensional discrete Fourier transform (DFT), it is more straightforward to generate each frequency component by directly sampling the real and imaginary parts from two independent Gaussian distributions. Only the non-negative frequency components need to be generated; the final result automatically satisfies the required conjugate symmetry. The initial conditions correspond to thermal fluctuations at different temperatures. We statistically analyzed the initial distribution of field values across all lattice points and all samples, as shown in Fig.~\ref{fig:initial distribution}. As seen from the initial distributions generated by thermal fluctuations, higher temperatures correspond to a larger number of grid points where the field values lie within the true vacuum region.

