\title{A novel parallelizable convergence accelerating method: Pointwise Frequency Damping}

\author[1]{Zikun Liu}
\author[2]{Xukun Wang}
\author[1]{Yilang Liu}
\author[1]{Weiwei Zhang}
\cortext[cor1]{Corresponding author}
