\begin{document}

\title{Energy Spectra of Compressed Quantum States}

\author{Daochen Wang}\thanks{University of British Columbia \newline Email: \texttt{wdaochen@gmail.com}}

\begin{abstract}
Quantum algorithms for estimating the ground state energy of a quantum system often operate by preparing a classically accessible quantum state and then applying quantum phase estimation. Whether this approach yields quantum advantage hinges on the state's energy spectrum, that is, the sequence of the state's overlaps with the energy eigenstates of the system Hamiltonian. For any entanglement-compressed quantum state with minimal expected energy, it is shown that its energy spectrum decays at most with the inverse-squared energy eigenvalues. This explains the main empirical finding of Silvester, Carleo, and White \cite{unusual_white_2025} (\textit{Physical Review Letters}, 2025) that the energy spectra of matrix product states do not decay exponentially. It also reduces the question of quantum advantage to the energy and entanglement profile of the Hamiltonian's eigenstates.
\end{abstract}
\maketitle

%======================
\section*{Introduction}
%======================

Estimating ground state energies of quantum systems is widely regarded as a promising application of quantum computation \cite{elucidataing_reiher_2017,qchem_survey_cao_2019,qchem_survey_bauer_2020,qchem_survey_mcardle_2020,catalysis_vonburg_2021,battery_kim_2022,qchem_riverlane_2022,evaluating_chan_2023,drug_santagati_2024,spiers_chan_24,fermions_anschuetz_2024,dissipative_lin_2025}. Yet, without further qualifying the system, this problem is believed to be intractable even for quantum computers \cite{yellow_ksv_2002,complexity_watrous_2009}. This raises a fundamental question: \emph{for which} systems could quantum computers offer an advantage over classical computers?

A leading quantum algorithmic paradigm for ground state energy estimation \cite{qpe_abrams_lloyd_1999,qpe_aspuruguzik_2005,quartic_hastings_2020,dequantize_gharibian_2023,improved_glhp_cade_2023,sparse_hamiltonian_chen_2024,probing_choi_izmaylov_2024,state_prep_fomichev_2024,state_prep_berry_2025,lhp_macomplete_jiang_2025,qpe_overlap_lin_izmaylov_2025,van_vleck_simon_2025,glhp_instantiated_schmidhuber_2025,beating_legall_2025} operates in two steps: (i) prepare a classically accessible initial state $\ket{\psi}$, and (ii) apply a standard quantum subroutine (typically, phase estimation \cite{qpe_kitaev_1995}) to produce an energy estimate. To yield quantum advantage, $\ket{\psi}$'s expected energy should be far from the ground state energy \emph{and} $\ket{\psi}$'s overlap (i.e., squared inner product) with the ground state should also be high. The first condition prevents classical algorithms from succeeding via step (i), while the second condition makes step (ii) quantumly efficient. For both conditions to be met, it is necessary and sufficient for $\ket{\psi}$ to have high overlap with the ground state \emph{and} non-negligible overlap with excited states. The sequence of ground and excited state overlaps is known as $\ket{\psi}$'s \emph{energy spectrum} (or distribution) \cite{state_prep_fomichev_2024,unusual_white_2025}. Therefore, the initial question reduces to one about energy spectra. 

We focus on states $\ket{\psi}$ with limited entanglement, known as \emph{compressed quantum states} \cite{unusual_white_2025}. These states constitute a substantial family of classically accessible states that includes matrix product states (MPSs) and, more generally, tensor network states \cite{mps_schollwock_2011,tns_eisert_2013,tns_orus_2019,mps_review_cirac_2021}. Our main result characterizes $\ket{\psi}$'s energy spectrum assuming that its expected energy is minimal under a convex relaxation of the compression constraint. The result implies that $\ket{\psi}$'s energy spectrum decays at most with the inverse-squared energy eigenvalues. This explains the empirical finding of Silvester, Carleo, and White in Ref.~\cite{unusual_white_2025} that the energy spectra of MPSs do not decay exponentially. We end by illustrating how the result can be used to answer the initial question on quantum advantage.

%===========================================================================================
\section*{\texorpdfstring{Energy spectra via entanglement}{Energy spectra via entanglement}}
%===========================================================================================

Key to our analysis is a robust notion of matrix rank known as stable rank. This quantity appears to have first been introduced by Rudelson and Vershynin in Ref.~\cite{stable_rank_rudelson_2007}. For a more recent reference, see Ref.~\cite{stable_rank_ipsen_2024}.

\begin{definition}[Stable rank]
Let $L,R\in \mathbb{N}$. The \emph{stable rank} of $0\neq A\in \mathbb{C}^{L\times R}$, denoted $\chi(A)$, is defined to be 
\begin{equation}
    \chi(A) \coloneqq \norm{A}_F^2 \, \big/ \, \norm{A}^2,
\end{equation} 
where $\norm{A}_F$ denotes the Frobenius norm of $A$ and $\norm{A}$ denotes the spectral norm of $A$. The stable rank of every matrix with all entries equal to $0$ is defined to be $0$. (Note that the stable rank is at most the rank.)
\end{definition}

We adapt the notion of stable rank to measure the entanglement of quantum states. We will focus on qubit states for simplicity; generalizations are straightforward. For $n\in \mathbb{N}$, we write $[n] \coloneqq \{1,\dots,n\}$. We say $A,B\subset [n]$ is a bipartition if $A\cup B=[n]$, $A\cap B = \emptyset$, and $A,B\neq [n]$.

\begin{definition}[Stable Schmidt rank]\label{def:stable_bond_dim}
    Let $n\geq 2$ be an integer. Let $A,B\subset [n]$ be a bipartition. Let $\ket{\psi}$ be an $n$-qubit state. The \emph{stable Schmidt rank of $\ket{\psi}$ with respect to $A,B$}, denoted $\chi_{A,B}(\ket{\psi})$, is defined to be the stable rank of the unique matrix $\Gamma \in \mathbb{C}^{\{0,1\}^A \times \{0,1\}^B}$ such that 
    \begin{equation}
        \ket{\psi} = \sum_{x \in \{0,1\}^A, \, y\in \{0,1\}^B} \Gamma_{x,y}\ket{x}_A\ket{y}_B.
    \end{equation}
\end{definition}
    We will often omit the subscript $A,B$ from $\chi_{A,B}$ when $A,B$ are clear from context or are immaterial.

    The stable rank of $\ket{\psi}$ directly relates to the entanglement \emph{min-entropy} of $\ket{\psi}$. More precisely, if we write $\rho_A$ and $\rho_B$ for the reduced density matrices of $\ket{\psi}$ on $A$ and $B$, and $S_{\min}(\rho) \coloneqq \log_2(1/\norm{\rho})$ for the min-entropy of a density matrix $\rho$, then
 \begin{align}
     \chi_{A,B}(\ket{\psi}) =&\frac{1}{\norm{\rho_A}} = \frac{1}{\norm{\rho_B}} =  2^{S_{\min}(\rho_A)} = 2^{S_{\min}(\rho_B)},
 \end{align}
 which follows from $\rho_A = \Gamma\Gamma^\dagger$ and $\rho_B = (\Gamma^\dagger\Gamma)^{\intercal}$, and $\norm{\Gamma}_F^2 = \tr[\Gamma\Gamma^\dagger] = \tr[(\Gamma^\dagger\Gamma)^{\intercal}] =\tr[\rho_A] =\tr[\rho_B] = 1$ and $\norm{\Gamma}^2 = \norm{\Gamma\Gamma^{\dagger}} = \norm{(\Gamma^\dagger\Gamma)^{\intercal}} = \norm{\rho_A} = \norm{\rho_B}$.

 Since $S_{\min}(\rho) \in [0,\log_2(\dim(\rho))]$, we have $\chi_{A,B}(\ket{\psi}) \in [1, 2^{n/2}]$ for all $n$-qubit $\ket{\psi}$ and all bipartitions $A,B\subset [n]$.

 For all $\alpha\in [0,\infty]$, we have $S_{\alpha}(\rho) \geq S_{\min}(\rho) $, where $S_{\alpha}(\rho) \coloneqq (1-\alpha)^{-1}\log_2(\tr[\rho^\alpha])$  is the $\alpha$-R\'enyi entropy of $\rho$. Moreover, if $\alpha>1$, then $S_{\min}(\rho) \geq (1-1/\alpha)S_{\alpha}(\rho)$ \footnote{If $0\leq \alpha \leq 1$, there does not exist a constant $c>0$ such that $S_{\min}(\rho) \geq c S_{\alpha}(\rho)$ for all $\rho$. For example, take $\rho \in \mathbb{C}^{d\times d}$ to be  $\diag(2^{-1}, (2d-2)^{-1},\dots, (2d-2)^{-1})$, in which case $S_{\min}(\rho) = 1$ but $S_\alpha(\rho) \geq S_1(\rho) = 2^{-1} + 2^{-1}\log_2(2d-2)$.}. This means that all results about R\'enyi entropies, see, e.g., Refs.~\cite{entropy_page_93,mps_verstraete_cirac_2006,area_law_hastings_2007,renyi_mps_schuch_2008,entropy_cft_calabrese_cardy_2009,renyi_afhm_song_2011,eigenstates_keating_linden_wells_2015,eigenstates_rigol_2017,arealaw_vidick_2017,renyi_chaotic_lu_grover_2019,renyi2_brydges_zoller_2019,eigenstate_miao_qiang_2021,eigenstate_miao_qiang_2022,area_anshu_2022,area_renyi_anshu_harrow_soleimanifar_2022,area_volume_joshi_zoller_2023,eat_metger_2024,entanglement_childs_2024,area_generalized_kim_kuwahara_2025}, immediately carry over to $\chi(\cdot)$.

 A key observation about $\chi$ is that any decomposition of a state with small $\chi$ into a sum of pairwise orthogonal states each with large $\chi$ must contain many terms. This can be seen as a consequence of the following general property of stable rank for matrices.


\begin{restatable}{proposition}{stablerank}
\label{prop:stablerank}
    Let $L,R,k\in \mathbb{N}$. Suppose $0\neq \Gamma\in \mathbb{C}^{L\times R}$ and $0\neq \Gamma_1,\dots,\Gamma_k \in \mathbb{C}^{L\times R}$ satisfy
    \begin{enumerate}
        \item\label{item:cond1} $\Gamma = \sum_{i=1}^k \alpha_i\Gamma_i$ for some $(\alpha_1,\dots,\alpha_k)\in \mathbb{C}^k$;
        \item\label{item:cond2} $\tr[\Gamma_i^\dagger \cdot \Gamma_j] = 0$ for all $i\neq j$.
    \end{enumerate}

    Then,
    \begin{equation}\label{eq:lemma_main}
        k \geq \frac{\min_{i=1}^k \chi(\Gamma_i)}{\chi(\Gamma)}.
    \end{equation}
\end{restatable}
\begin{proof}
   The simple proof, as well as an example of possible tightness, is deferred to \cref{app:proof_stablerank}.
\end{proof}

The key point of \cref{prop:stablerank} is its use of stable rank rather than the usual rank. Indeed, the lemma fails completely if $\chi(\cdot)$ is replaced by $\rk(\cdot)$, in which case counter-examples abound. For example, consider $k=2$ and $L=R$, and the $L\times L$ diagonal matrices
$\Gamma_1 \coloneqq \diag(1, \dots,1,1)$, 
$\Gamma_2 \coloneqq \diag(-1,\dots,-1,L-1)$, and $\Gamma \coloneqq\Gamma_1 + \Gamma_2 = \diag(0,\dots,0,L)$. Then, $\tr[\Gamma_1^\dagger\cdot \Gamma_2]=0$, $\rk(\Gamma) = 1$, and  $\rk(\Gamma_1) = \rk(\Gamma_2) = L$. Therefore, \cref{eq:lemma_main} with $\chi(\cdot)$ replaced by $\rk(\cdot)$ can be violated by an arbitrarily large amount by setting $L$ to be large.

We now specialize \cref{prop:stablerank} to quantum states. Due to the specialization, the lower bound on $k$ can be enhanced to involve the notion of \emph{harmonic mean}, which is defined for $v\in \mathbb{R}^k_{>0}$ by $\Hm(v) \coloneqq k/(\sum_{i=1}^k 1/v_i)$.

\begin{proposition}\label{prop:coefs_lower_bound}
Let $k\in \mathbb{N}$. Let $m, M_1,\dots, M_k>0$. Suppose $\ket{\psi}$ and $\ket{\psi_1},\dots,\ket{\psi_k}$ are quantum states on the same number of qubits such that
\begin{enumerate}
    \item\label{item:state_cond1} $\ket{\psi} = \sum_{i=1}^k \alpha_i \ket{\psi_i}$ for some $(\alpha_1,\dots,\alpha_k)\in \mathbb{C}^k$,
    \item\label{item:state_cond2} $\braket{\psi_i|\psi_j} = 0$ for all $i\neq j$,
    \item\label{item:state_cond3} $\chi_{A,B}(\ket{\psi}) \leq m$ for some bipartition $A,B\subset [n]$,
    \item\label{item:state_cond4} $\chi_{A,B}(\ket{\psi_i})\geq M_i$ for all $i \in [k]$.
\end{enumerate}

    Then,
    \begin{equation}\label{eq:coefs_lower_bound}
        \sum_{i=1}^k\frac{\abs{\alpha_i}}{\sqrt{M_i}} \, \geq \, \frac{1}{\sqrt{m}}.
    \end{equation}
    Moreover,
    \begin{equation}\label{eq:refined_no_terms_lower_bound}
        k\geq \frac{\Hm(M_1,\dots,M_k)}{m}.
    \end{equation} 
\end{proposition}

\begin{proof}
Let $A,B\subset [n]$ be such that \hyperref[item:state_cond3]{conditions 3} and \hyperref[item:state_cond4]{4} are satisfied. Write $\chi$ for $\chi_{A,B}$. Write $\Gamma$ and $\Gamma_i$ for the matrices corresponding to $\ket{\psi}$ and $\ket{\psi_i}$ as defined in \cref{def:stable_bond_dim}. By definition, we have $\chi(\ket{\psi}) = \chi(\Gamma)$, $\chi(\ket{\psi_i}) = \chi(\Gamma_i)$, and 
\begin{align}
    \ket{\psi} =&~\sum_{x\in \{0,1\}^A, \, y\in \{0,1\}^B} \Gamma_{x,y}\ket{x,y},
    \\
    \ket{\psi_i} =&~\sum_{x\in \{0,1\}^A, \, y\in \{0,1\}^B} (\Gamma_i)_{x,y}\ket{x,y}.
\end{align}

Since $\norm{\Gamma}_F^2 = \norm{\Gamma_i}_F^2 = 1$, we have $1/\chi(\ket{\psi}) = \norm{\Gamma}^2$ and  $1/\chi(\ket{\psi_i}) = \norm{\Gamma_i}^2$ for all $i\in [k]$.

    Therefore, \hyperref[item:state_cond3]{condition 3} gives
    \begin{equation}\label{eq:combine_1}
        \frac{1}{m} \leq \frac{1}{\chi(\ket{\psi})} = \norm{\Gamma}^2;
    \end{equation}
    while \hyperref[item:state_cond1]{conditions 1} and \hyperref[item:state_cond4]{4},  and the triangle inequality, give
    \begin{align}
        \norm{\Gamma}^2=&~\Bigl\|\sum_{i=1}^k \alpha_i\Gamma_i\Bigr\|^2\leq \Bigl(\sum_{i=1}^k \abs{\alpha_i} \norm{\Gamma_i}\Bigr)^2\notag
        \\
        =&~\Bigl(\sum_{i=1}^k \frac{\abs{\alpha_i}}{\sqrt{\chi(\ket{\psi_i})}}\Bigr)^2 \leq \Bigl(\sum_{i=1}^k \frac{\abs{\alpha_i}}{\sqrt{M_i}}\Bigr)^2.\label{eq:combine_2}
    \end{align}
    Chaining \cref{eq:combine_1,eq:combine_2} gives the main inequality of the proposition, \cref{eq:coefs_lower_bound}.

    For the ``moreover'' part, observe that  \hyperref[item:state_cond1]{conditions 1} and \hyperref[item:state_cond2]{2} imply that $\sum_{i=1}^k \abs{\alpha_i}^2 = 1$. Therefore, \cref{eq:refined_no_terms_lower_bound} follows from applying the Cauchy-Schwarz inequality on \cref{eq:coefs_lower_bound} to obtain $\sum_{i=1}^k 1/M_i \geq 1/m$, and then rewriting it using the definition of the harmonic mean.
\end{proof}

\cref{prop:coefs_lower_bound} can be seen as a standalone result on the ``entanglement of superposition''~\cite{entanglement_superposition_linden_2006,entanglement_superposition_gour_2007,entanglement_superposition_gour_roy_2008}, except it uses a different entanglement measure, stable rank. Changing the measure is important: Ref.~\cite[Example 4]{entanglement_superposition_gour_2007} implies that natural analogues of \cref{prop:coefs_lower_bound} with stable rank replaced by (von Neumann) entropy are ``very'' false. 

The narrative has focused on \cref{eq:refined_no_terms_lower_bound} of \cref{prop:coefs_lower_bound} so far. But we can go much further by leveraging its predecessor, \cref{eq:coefs_lower_bound}. Suppose that $\ket{\psi_i}$ is associated with an energy $E_i$ and $\ket{\psi} \coloneqq \sum_i \alpha_i \ket{\psi_i}$ minimizes its expected energy, i.e., $\sum_i \abs{\alpha_i}^2 E_i$, \emph{subject to \cref{eq:coefs_lower_bound}}, then we can \emph{completely characterize} the $\abs{\alpha_i}^2$s by

\begin{restatable}{proposition}{energymin}\label{prop:energy_min}
    Let $k\in \mathbb{N}$. Let $m,M_1,\dots,M_k>0$. Let $E_1,\dots,E_k \in \mathbb{R}$ be such that $E_1\leq E_2\leq \dots\leq E_k$. Let $l\in [k]$ be the size of the set $\{i\in [k] \colon E_i = E_1\}$.

    Suppose
    \begin{alignat}{2}
      &l~<~&&\Hm(M_1,\dots,M_l)/m \label{eq:non_triviality_l},
      \\
      &k~>~&&\Hm(M_1,\dots,M_k)/m. \label{eq:non_triviality_k}
    \end{alignat}

    Then, the solution to
    \begin{alignat}{2}
        &\mathrm{minimize} \quad &&\sum_{i=1}^k \abs{\alpha_i}^2 E_i\label{eq:primal}
        \\
        &\mathrm{s.t.} \quad && \alpha \in \mathbb{C}^k, \, \norm{\alpha}_2 = 1\notag
        \\
        &\quad && \sum_{i=1}^k\frac{\abs{\alpha_i}}{\sqrt{M_i}} \, \geq \, \frac{1}{\sqrt{m}}\notag
    \end{alignat}
    is 
    \begin{equation}\label{eq:dual}
        \max_{\nu < E_1} \quad  \nu +\Bigl(m \sum_{i=1}^k \frac{1}{M_i(E_i - \nu)}\Bigr)^{-1};
    \end{equation}
    and the maximum in \cref{eq:dual} is uniquely attained at the unique solution $\nu^* < E_1$ to
    \begin{equation}\label{eq:dual_optimum_condition}
    \frac{1}{m} \sum_{i=1}^k \frac{1}{M_i(E_i-\nu^*)^2} = \Big(\sum_{i=1}^k\frac{1}{M_i(E_i-\nu^*)}\Bigr)^2.
    \end{equation}

    Moreover, every minimizer $\alpha\in \mathbb{C}^k$ of \cref{eq:primal} obeys:
    \begin{equation}\label{eq:inv_square}
        \abs{\alpha_i}^2 \propto \frac{1}{M_i(E_i-\nu^*)^2} \quad \text{for all $i\in [k]$.}
    \end{equation}
\end{restatable}

\begin{proof}
    The proof, which uses some basic duality theory for convex optimization, is deferred to \cref{app:proof_energymin}.
\end{proof}

Note that \cref{eq:non_triviality_l,eq:non_triviality_k} ensure non-triviality:
\begin{enumerate}[leftmargin=*]
    \item If $l\geq \Hm(M_1,\dots,M_l)/m$, then the minimum is simply $E_1$, attained at any $\alpha$ with $\abs{\alpha_i}^2 = M_i^{-1}/\textstyle\sum_{i=1}^l M_i^{-1}$ for all $i\in [l]$ and $\abs{\alpha_i} = 0$ for all $i>l$.
    \item If $k < \Hm(M_1,\dots,M_k)/m$, then there is no feasible $\alpha$. If $k = \Hm(M_1,\dots,M_k)/m$, then the minimum is $m \sum_{i=1}^k E_i/M_i$, attained at any $\alpha$ with $\abs{\alpha_i}^2=m/M_i$ for all $i\in[k]$. (Both statements follow from the Cauchy-Schwarz inequality.)
\end{enumerate}

A salient feature of \cref{prop:energy_min} is its \cref{eq:inv_square}, which characterizes $p_i\coloneqq |\alpha_i|^2$ by an inverse-square law in terms of $E_i$. Therefore, if the $M_i$s are reasonably well-behaved, this would result in a flat tail when the $p_i$s are plotted on a logarithmic scale against the $E_i$s, which agrees with the main empirical finding of Ref.~\cite{unusual_white_2025}. (More recently, Ref.~\cite{chen_temperature_2024} also observes flat-looking tails, but the authors speculate that those tails are in fact slightly sloped.)

%=============================
\section*{Case study: 2D AFHM}
%=============================

This section uses \cref{prop:energy_min} to predict spectra and compares them with the actual spectra from DMRG~\cite{dmrg_white_92} for the main system considered in Ref.~\cite{unusual_white_2025}: the spin-$1/2$ 2D anti-ferromagnetic Heisenberg model (AFHM) on an $\ell\times \ell$ grid with periodic boundary condition (PBC). 

The system Hamiltonian on $n \coloneqq \ell^2$ spins is
\begin{equation}
    H = \frac{1}{4}\sum_{\langle i, j \rangle} X_i X_{j} + Y_i Y_{j} + Z_i Z_{j},
\end{equation}
where the sum ranges over distinct sets $\{i,j\}\subseteq [n]$ such that $i$ and $j$ are neighbors on the grid with PBC, and 
$X \coloneqq \begin{psmallmatrix}
    0 & 1
    \\
    1 &0
\end{psmallmatrix}$,  $Y\coloneqq \begin{psmallmatrix}
    0 & -i
    \\
    i &0
\end{psmallmatrix}$, and $Z\coloneqq \begin{psmallmatrix}
    1 & 0
    \\
    0 & -1
\end{psmallmatrix}$.

To use \cref{prop:energy_min}, we let $\ket{\psi}$ be the $n$-qubit MPS computed by DMRG with maximum bond dimension set to $D\in \mathbb{N}$. Since the stable rank is at most the rank, we immediately deduce
\begin{equation}
    m\coloneqq \chi_{A,B}(\ket{\psi})\leq D
\end{equation}
for every bipartition $A,B\subset [n]$ aligned with the ordering of the $n$ qubits in the MPS. 
Note that the actual value of $\chi_{A,B}(\ket{\psi})$ may be much smaller than $D$, which will turn out to be the case. Then, for all $i \in [2^n]$, let $\ket{\psi_i}$ be the $i$th energy eigenstate of $H$; write $E_i$ for its energy and
\begin{equation}
    M_i \coloneqq \chi_{A,B}(\ket{\psi_i}).
\end{equation}

Having computed the above values, the ``moreover'' part of \cref{prop:energy_min} allows us to predict $\ket{\psi}$'s energy spectrum \emph{under the assumption} that DMRG minimizes $\ket{\psi}$'s expected energy according to \cref{eq:primal}.

Following Ref.~\cite{unusual_white_2025}, we focus on the largest $\ell$ that is computationally feasible, $\ell=4$. We also choose $A,B\subset[n]$ to be the bipartition such that $A$ consists of the gridpoints in the left half and $B$ the right half, so that $\abs{A} = \abs{B} = \ell^2/2= 8$. This choice of $A,B$ is expected to maximize $\chi_{A,B}(\ket{\psi_i})$ \emph{and} minimize $\chi_{A,B}(\ket{\psi})$, and thus give the tightest possible constraints in the optimization problem of \cref{eq:primal} \footnote{Using the top and bottom halves for $A$ and $B$ does not work well as it increases $\chi_{A,B}(\ket{\psi})$: the TeNPy library \cite{tenpy2024} used for DMRG calculations that output MPS $\ket{\psi}$ orders the qubits such that the top-bottom bipartition cuts $4$ bonds, as opposed to $1$ for the left-right bipartition}.

In \cref{fig:2d_comparison_entropy}, we plot $\log_2(M_i) = S_{\min}(\tr_A[\ketbrasame{\psi_i}])$ and the entanglement entropy of $\ket{\psi_i}$, i.e., $S_1(\tr_A[\ketbrasame{\psi_i}])$. Their behaviors are similar, agreeing with theory that predicts bulk eigenstates  should have larger entanglement (volume law) than edge eigenstates (area law) \cite{eigenstate_miao_qiang_2021,eigenstate_miao_qiang_2022}.

\begin{figure}
    \includegraphics[width=0.875\linewidth]{2d_comparison_entropy.pdf}
    \captionsetup{justification=raggedright,singlelinecheck=false}
    \caption{%
    The entanglement min-entropy ($S_{\min}$) and entropy ($S_1$) of eigenstates of the 2D AFHM on $n=16$ spins. Each data point represents the mean of all $S_{\alpha}$ values corresponding to $(E-E_1)$ values within a bin of the form $[0.1j-0.05,0.1j+0.05)$, where $j\in \mathbb{Z}$. All $S_{\alpha}$ values are theoretically at most $\log_2(2^{n/2}) = 8$.
    }
    \label{fig:2d_comparison_entropy}
\end{figure}

In \cref{fig:flat_spectrum}, we plot the predicted and actual energy spectra of the DMRG ground state $\ket{\psi}$, computed with maximum bond dimension $D$ set to $50$, $100$, and $150$. The corresponding values of $m \coloneqq \chi(\ket{\psi})$ are much smaller: $1.778$, $1.843$, and $1.863$ to four significant figures (s.f.), respectively. Now, $H$ has $k \coloneqq 2^n$ eigenstates, and its ground state is non-degenerate and has stable rank $1.868$. Therefore, \cref{eq:non_triviality_l,eq:non_triviality_k} of \cref{prop:energy_min} hold, so we can use it to predict energy spectra.

