\section{\texorpdfstring{Proof of \cref{prop:stablerank}}{}}
\label{app:proof_stablerank}
%===========================================================

Recall \cref{prop:stablerank}:
\stablerank*
\begin{proof}
    Let $\langle \cdot \, , \cdot \rangle \colon \mathbb{C}^{L\times R}\times \mathbb{C}^{L\times R}\to \mathbb{C}$ denote the Hilbert-Schmidt inner product, i.e., $\langle X, Y\rangle = \tr[X^\dagger \cdot Y]$. Write $\chi_{\min} \coloneqq \min_{i=1}^k \chi(\Gamma_i)$.

   Then, we have
    \begin{align*}
        \norm{\Gamma}_F^2~=&~\Big\langle \sum_{i=1}^k\alpha_i\Gamma_i,\sum_{j=1}^k\alpha_j\Gamma_j \Big\rangle &&\text{($\norm{\Gamma}_F^2 = \langle\Gamma,\Gamma\rangle$)}
        \\
        =&~\sum_{i=1}^k \abs{\alpha_i}^2 \norm{\Gamma_i}^2_F &&\text{(\hyperref[item:cond2]{condition~2})}
        \\
        =&~\sum_{i=1}^k \abs{\alpha_i}^2 \chi(\Gamma_i) \norm{\Gamma_i}^2 &&\text{(definition of $\chi$; $\Gamma_i\neq 0$)}
        \\
        \geq&~\chi_{\min} \sum_{i=1}^k \abs{\alpha_i}^2 \norm{\Gamma_i}^2 &&\text{(definition of $\chi_{\min}$)}
        \\
        \geq&~\frac{\chi_{\min}}{k} \Bigl(\sum_{i=1}^k \norm{\alpha_i\Gamma_i} \Bigr)^2 &&\text{(Cauchy-Schwarz inequality)}
        \\
        \geq&~\frac{\chi_{\min}}{k} \Bigl\|\sum_{i=1}^k \alpha_i\Gamma_i\Bigr\|^2 &&\text{(triangle inequality)}
        \\
        =&~\frac{\chi_{\min}}{k} \|\Gamma\|^2 &&\text{(\hyperref[item:cond1]{condition~1}).}
    \end{align*}
    Since $\Gamma\neq 0$, dividing the above inequality by $\norm{\Gamma}_F^2/k$ gives 
        $k \geq \chi_{\min}/\chi(\Gamma)$,
    as required.
\end{proof}
\begin{remark}\cref{prop:stablerank} can be tight. For example, consider $k$ equal to a power of $2$ and $L=R=k$. Let $\Gamma_i$ be the $k\times k$ diagonal matrix with the diagonal equal to the $i$th row vector of the $k\times k$ Hadamard matrix, which exists since $k$ is a power of $2$. Let $\Gamma= \sum_{i=1}^k \Gamma_i = \diag(k,0,\dots,0)$. Then $\tr[\Gamma_i^\dagger\cdot\Gamma_j] =0$ for all $i\neq j$, $\chi(\Gamma) = 1$, and $\chi(\Gamma_i) = k$ for all $i$. So both sides of \cref{eq:lemma_main} are equal to $k$.
\end{remark}

