\section{\texorpdfstring{Proof of \cref{prop:energy_min}}{}}
\label{app:proof_energymin}
%===========================================================

Recall \cref{prop:energy_min}:
\energymin*

The following proof uses duality theory for convex optimization; see Ref.~\cite[Chapter 5]{cvx_boyd_vandenberghe_2004} for all necessary background.

\begin{proof}[Proof of \cref{prop:energy_min}.] We write $p_i\coloneqq \abs{\alpha_i}^2$. Then the minimization problem is equivalent to 
    \begin{alignat}{2}
        &\mathrm{minimize} \quad &&\sum_{i=1}^k p_i E_i\label{eq:primal_copy}
        \\
        &\mathrm{s.t.} \quad && \sum_{i=1}^k\sqrt{\frac{p_i}{M_i}} \, \geq \, \frac{1}{\sqrt{m}}\notag
        \\
        &\quad && \forall i\in [k], \ p_i\geq 0\notag
        \\
        &\quad && \sum_{i=1}^k p_i = 1.\notag
    \end{alignat}

    This is a convex optimization problem with domain $\mathbb{R}_{\geq 0}^k$. Observe that the non-triviality condition on $k$, \cref{eq:non_triviality_k}, implies that $p \coloneqq Z^{-1}\cdot(1/M_1,\dots, 1/M_k)\in \mathbb{R}_{>0}^k$, where $Z\coloneqq \sum_{i=1}^k 1/M_i$, is a strictly feasible solution. Therefore, Slater's condition is satisfied, which implies that the dual optimum equals the primal optimum given by \cref{eq:primal_copy}. We proceed to show that the dual optimum can be written as \cref{eq:dual}.

    The associated Lagrangian $L\colon \mathbb{R}^k_{\geq0} \times \mathbb{R}^{k+1} \times \mathbb{R} \to \mathbb{R}$ is defined by 
    \begin{align}
        L(p,\lambda,\nu) &\coloneqq \sum_{i=1}^k p_i E_i - \lambda_0\Bigl(
        \sum_{i=1}^k \sqrt{\frac{p_i}{M_i}} - \frac{1}{\sqrt{m}} \Bigr) - \sum_{i=1}^k \lambda_i p_i -\nu\Bigl(\sum_{i=1}^k p_i -1 \Bigr).
    \end{align}

    The dual function $g\colon \mathbb{R}^{k+1}\times \mathbb{R} \to \mathbb{R}\cup \{-\infty\}$ is defined by 
    \begin{equation}
        g(\lambda,\nu) \coloneqq \min_{p \in \mathbb{R}^k_{\geq0}} L(p,\lambda,\nu).
    \end{equation}
    To compute $g$, we first rewrite
    \begin{align}
        g(\lambda,\nu) =&~\nu + \frac{\lambda_0}{\sqrt{m}} + \sum_{i=1}^k \min_{p_i\geq 0}\Big(p_i(E_i-\lambda_i-\nu) - \lambda_0\sqrt{\frac{p_i}{M_i}}\Bigr).\label{min_pi}
    \end{align}
    We analyze according to the following cases:
    \begin{enumerate}[leftmargin=*]
        \item Case $E_i-\lambda_i-\nu<0$ for some $i\in[k]$: $g(\lambda,\nu) = -\infty$. 
        \item Case $E_i-\lambda_i-\nu\geq 0$ for all $i\in[k]$:
        \begin{enumerate}[leftmargin=*]
            \item If $\lambda_0\leq 0$, then $g(\lambda,\nu) = \nu + \lambda_0/\sqrt{m}$. 
            \item If $\lambda_0>0$ and $E_i-\lambda_i-\nu = 0$, then $g(\lambda,\nu) = -\infty$.
            \item If $\lambda_0>0$ and $E_i-\lambda_i-\nu > 0$, then we can explicitly solve the minimization problem in \cref{min_pi} for each $p_i$ independently to obtain
            \begin{equation}\label{eq:pi_form}
                p_i = \frac{\lambda_0^2}{4M_i(E_i-\lambda_i-\nu)^2} \quad \text{ for all $i\in[k]$},
            \end{equation}
           which yields
            \begin{equation}
                g(\lambda,\nu) = \nu + \frac{\lambda_0}{\sqrt{m}} - \sum_{i=1}^k \frac{\lambda_0^2}{4M_i(E_i-\lambda_i-\nu)}.
            \end{equation}
        \end{enumerate}
    \end{enumerate}

    Therefore, the dual problem, i.e.,
    \begin{alignat}{2}
        &\mathrm{maximize} \quad &&g(\lambda,\nu)
        \\
        &\mathrm{s.t.} \quad && \lambda \in \mathbb{R}^{k+1}_{\geq 0},\notag
    \end{alignat}
    can be expressed as
    \begin{alignat}{2}
        &\mathrm{maximize} \quad &&\nu + \frac{\lambda_0}{\sqrt{m}} - \sum_{i=1}^k \frac{\lambda_0^2}{4M_i(E_i-\lambda_i-\nu)}\label{eq:dual_with_lambdai}
        \\
        &\mathrm{s.t.} \quad && \lambda \in \mathbb{R}^{k+1}_{\geq 0}\notag
        \\
        & \quad &&\forall i\in [k], \, E_i-\lambda_i - \nu > 0;\notag
    \end{alignat}
    which, using $E_1 = \min_{i=1}^k E_i$, is equivalent to 
    \begin{alignat}{2}
        &\mathrm{maximize} \quad &&\nu + \frac{\lambda_0}{\sqrt{m}} - \sum_{i=1}^k \frac{\lambda_0^2}{4M_i(E_i-\nu)}\label{eq:dual_without_lambdai}
        \\
        &\mathrm{s.t.} \quad && \lambda_0 \in \mathbb{R}_{\geq 0}\notag
        \\
        & \quad &&\nu < E_1;\notag
    \end{alignat}
    which, upon maximizing the quadratic in $\lambda_0$ for fixed $\nu$, is equivalent to
    \begin{equation}\label{eq:dual_copy}
        \max_{\nu < E_1} \quad  \nu +\Bigl(m \sum_{i=1}^k \frac{1}{M_i(E_i - \nu)}\Bigr)^{-1}.
    \end{equation}

   To see that the maximization in \cref{eq:dual_copy} is uniquely attained at the unique solution $\nu^*<E_1$ satisfying \cref{eq:dual_optimum_condition}, it suffices to show that the function $h\colon (-\infty,E_1)\to \mathbb{R}$ defined by 
   \begin{equation}
       h(\nu) \coloneqq \nu +\Bigl(m \sum_{i=1}^k \frac{1}{M_i(E_i - \nu)}\Bigr)^{-1}
   \end{equation}
    satisfies
    \begin{enumerate}
        \item $h'(\nu^*) = 0$ is equivalent to \cref{eq:dual_optimum_condition};
        \item $h$ is strictly concave;
        \item $\lim_{\nu \rightarrow E_1^-}h'(\nu) < 0$; and
        \item $\lim_{\nu \rightarrow -\infty}h'(\nu) > 0$.
    \end{enumerate}

    We prove each item in turn. For convenience, for $p\in \mathbb{N}$ and $\nu<E_1$, we write
   \begin{equation}
       S_p(\nu) \coloneqq \sum_{i=1}^k \frac{1}{M_i(E_i-\nu)^p}.
   \end{equation}

    \begin{enumerate}
    \item To see $h'(\nu^*) = 0$ is equivalent to \cref{eq:dual_optimum_condition}, observe that
   \begin{equation}
       h'(\nu) = 1 - \frac{1}{m}\frac{S_2(\nu)}{S_1(\nu)^2},
   \end{equation} 
   so $h'(\nu^*) = 0$ is clearly equivalent to \cref{eq:dual_optimum_condition}.

    \item To see $h$ is strictly concave, observe that
   \begin{equation}
       h''(\nu) = -\frac{2}{m}\frac{\, S_1(\nu) \, S_3(\nu) - S_2(\nu)^2}{S_1(\nu)^3}.
   \end{equation}
   Then observe that for each fixed $\nu<E_1$, $S_2(\nu)^2 \leq S_1(\nu)S_3(\nu)$ by the Cauchy-Schwarz inequality and that equality holds if and only if $E_i = E_1$ for all $i\in [k]$, that is $l=k$. But $l=k$ is forbidden by combining \cref{eq:non_triviality_l,eq:non_triviality_k}, so we must have $S_2(\nu)^2 < S_1(\nu)S_3(\nu)$.
   Therefore, $h''(\nu)<0$ for all $\nu<E_1$, so $h$ is strictly concave. 

    \item To see $\lim_{\nu \rightarrow E_1^-}h'(\nu) < 0$, observe that
   \begin{align}
       \lim_{\nu \rightarrow E_1^-}h'(\nu) =&~1 - \frac{1}{m\cdot \sum_{i=1}^l M_i^{-1}} = 1 - \frac{\Hm(M_1,\dots,M_l)}{m\cdot  l}<0,
   \end{align}
   where the last inequality uses the non-triviality condition on $l$, \cref{eq:non_triviality_l}.

    \item To see $\lim_{\nu \rightarrow -\infty}h'(\nu) >0$, observe that 
   \begin{equation}
       h'(-\nu) = 1 - \frac{1}{m}\frac{\sum_{i=1}^k M_i^{-1}(1+E_i/\nu)^{-2}}{\bigl(\sum_{i=1}^k M_i^{-1}(1+E_i/\nu)^{-1}\big)^2},
   \end{equation}
   and so 
   \begin{align}
      \lim_{\nu \rightarrow -\infty}h'(\nu) =&~ 
      \lim_{\nu \rightarrow \infty}h'(-\nu) = 1 - \frac{1}{m}\frac{1}{\sum_{i=1}^k M_i^{-1}} = 1 -\frac{1}{k} \frac{\Hm(M_1,\dots,M_k)}{m} > 0,
   \end{align}
   where the last inequality uses the non-triviality condition on $k$, \cref{eq:non_triviality_k}.
    \end{enumerate}

   The ``moreover'' part of the proposition follows from \cref{eq:pi_form} and the fact that the dual optimizer has $\lambda_i =0$ for all $i>0$, as can be seen from the equivalence between \cref{eq:dual_with_lambdai} and \cref{eq:dual_without_lambdai}.
\end{proof}

%===================================
\section{Slack of convex relaxation}
\label{app:compare_constraints}
%===================================

In this appendix, we analyze the relationship between
\begin{equation}\label{eq:compare}
    \NS \coloneqq \Bigl\|\sum_{i=1}^{k} \alpha_i \Gamma_i\Bigr\| \quad \text{and} \quad
    \SN \coloneqq \sum_{i=1}^k \abs{\alpha_i} \norm{\Gamma_i},
\end{equation}
where
\begin{enumerate}
    \item $d\in \mathbb{N}$ and $k\coloneqq d^2$. (In the AFHM case study, $d = 2^{n/2}$ and $k=2^{n}$, where $n$ is the number of qubits.)
    \item $\alpha \in \mathbb{C}^k$ is an amplitude vector, i.e., $\norm{\alpha}_2 = 1$. (For $p>0$, we write $\norm{\alpha}_p \coloneqq (\sum_{i=1}^k \abs{\alpha_i}^p)^{1/p}$, the $\ell_p$-norm of $\alpha$.)
    \item The $\Gamma_i$s form an orthonormal basis of $\mathbb{C}^{d\times d}$ with respect to the Hilbert-Schmidt inner product. 
\end{enumerate}

Of course, the triangle inequality implies $\NS\leq \SN$. Therefore, any lower bound on $\NS$ is a lower bound on $\SN$. Recall that we exploited this fact to analytically predict energy spectra of compressed wavefunctions. This is possible because a lower bound on $\SN$ is a \emph{convex} constraint (in terms of the probability distribution $p\in \mathbb{R}^k$ with $p_i \coloneqq \abs{\alpha_i}^2$ for all $i$), which is analytically tractable. In contrast, a lower bound on $\NS$ is \emph{not} convex (even when $d=1$), and it appears difficult to analyze. In this language, our use of $\NS\leq \SN$ to turn a lower bound on $\NS$ into a lower bound on $\SN$ can be seen as a \emph{convex relaxation}. 

Now, the constraint we actually have \emph{is} a lower bound on $\NS$. Therefore, better comparing $\NS$ and $\SN$ would reduce the gap between the predicted and actual energy spectra. We give two methods for better comparing $\NS$ and $\SN$:
\begin{enumerate}[leftmargin=*]
    \item \emph{Tighter relaxation.} Given $\|\Gamma_i\Gamma_j^\dagger\|$, we find a $\SNX$ such that $\NS\leq \SNX \leq \SN$ and a lower bound on $\SNX$ is still convex. 
    \item \emph{Random matrices.} For fixed $\alpha$ and random $\Gamma_i$s, we show $\NS= \Theta(\norm{\alpha}_1^{-1}) \SN$ with high probability.
\end{enumerate}
We elaborate on each in each of the next two subsections. 

\subsection{Tighter relaxation}
Since $\norm{A} = \norm{AA^\dagger}^{1/2}$ for every complex matrix $A$, we have
\begin{equation}
    \NS = \biggl\|\sum_{i,j\in[k]} \alpha_i \alpha_j^*\Gamma_i\Gamma_j^\dagger\biggr\|^{1/2} \leq \Bigl(\sum_{i,j\in [k]} \abs{\alpha_i} \abs{\alpha_j} \|\Gamma_i \Gamma_j^\dagger\|\Bigr)^{1/2} \leq \Bigl(\sum_{i,j\in [k]} \abs{\alpha_i} \abs{\alpha_j} \|\Gamma_i \| \cdot \|\Gamma_j\|\Bigr)^{1/2} = \SN,
\end{equation}
where the first inequality is the triangle inequality, and the second inequality is because the spectral norm is sub-multiplicative and is invariant under Hermitian conjugation.

Therefore, 
\begin{equation}
    \SNX \coloneqq \Bigl(\sum_{i,j\in [k]} \abs{\alpha_i} \abs{\alpha_j} \|\Gamma_i \Gamma_j^\dagger\|\Bigr)^{1/2},
\end{equation}
satisfies $\NS\leq \SNX\leq \SN$.

Moreover, it is easy to see that a lower bound on $\SNX$ gives a convex constraint in terms of $p\in \Delta_k$ with $p_i \coloneqq \abs{\alpha_i}^2$ for all $i$, where $\Delta_k \coloneqq \{p\in \mathbb{R}^k_{\geq 0} \colon \sum_{i=1}^k p_i = 1\}$ denotes the set of $k$-dimensional probability vectors.  This follows from the next lemma since a lower bound on a concave function gives a convex constraint.
\begin{lemma}
The function $f\colon \Delta_k \to \mathbb{R}$ defined by $f(p) \coloneqq \sum_{i,j\in [k]} \|\Gamma_i \cdot \Gamma_j^{\dagger}\| \, \sqrt{p_i}\sqrt{p_j}$ is concave.
\end{lemma}
\begin{proof}
     For fixed $i,j\in [k]$, the function mapping $p\in \Delta_k$ to  $\sqrt{p_i}\sqrt{p_j}$ is concave because: for all $p,q\in \Delta_k$ and $\lambda\in [0,1]$,
    \begin{equation}
    \bigl(\sqrt{\vphantom{\lambda p_j + (1-\lambda) q_j}\lambda p_i + (1-\lambda) q_i} \cdot \sqrt{\lambda p_j + (1-\lambda) q_j} \, \bigr)^2 - (\lambda \sqrt{p_ip_j}+(1-\lambda) \sqrt{q_iq_j})^2 = \lambda(1-\lambda)(\sqrt{p_iq_j}-\sqrt{q_ip_j})^2\geq 0.
    \end{equation}
    Since $f$ is a weighted sum of such functions with non-negative weights, $f$ is also concave.
\end{proof}

Energy minimization subject to a lower bound on $\SNX$ can be cast as a Second-Order Cone Program (SOCP), which admits specialized and fast numerical solvers:
\begin{proposition}\label{prop:socp}
    Let $E_1,\dots, E_k \in \mathbb{R}$. Let $\gamma_{i,j} \geq 0$ for all $i,j\in [k]$. Let $m>0$. Then, the convex program:
    \begin{alignat}{2}
        &\mathrm{minimize} \quad &&\sum_{i=1}^k p_i E_i\label{eq:socp_raw}
        \\
        &\mathrm{s.t.} \quad && p \in \Delta_k \notag
        \\
        &\quad && \sum_{i,j \in [k]} \gamma_{i,j} \, \sqrt{p_i} \, \sqrt{p_j} \geq 1/m \notag
    \end{alignat}
    is equivalent to the SOCP:
    \begin{alignat}{2}
        &\mathrm{minimize} \quad &&\sum_{i=1}^k p_i E_i\label{eq:socp_primal}
        \\
        &\mathrm{s.t.} \quad && p \in \Delta_k, \ z \in \mathbb{R}^{k\times k} \notag
        \\
        &\quad && \forall i,j\in [k], \, \norm{(2z_{i,j}, p_i - p_j)}_2 \leq p_i + p_j \notag
        \\
        & &&\sum_{i,j\in[k]} \gamma_{i,j} \, z_{i,j} \geq 1/m. \notag
    \end{alignat}
\end{proposition}
\begin{proof}
    The proposition follows by inspection after rewriting $\norm{(2z_{i,j}, p_i - p_j)}_2 \leq p_i + p_j$ as $z_{i,j}^2 \leq p_i p_j$. 
\end{proof}

Next, we compare the energy spectra predicted by \cref{prop:socp} with that predicted by \cref{prop:energy_min} as well as the actual spectra. (Recall that \cref{prop:socp} uses a lower bound on $\SNX$ whereas \cref{prop:energy_min} uses a lower bound on $\SN$.) Unfortunately, we cannot perform the comparison on the  2D AFHM studied in the main text because numerically solving the SOCP in \cref{prop:socp} is computationally prohibitive for this system. Instead, we perform the comparison on the \emph{1D} AFHM with $n = 10$ spins and periodic boundary conditions. That is, the system defined by the Hamiltonian
\begin{equation}
    H = \frac{1}{4}\sum_{i=1}^{n} X_i X_{i+1} + Y_i Y_{i+1} + Z_i Z_{i+1},
\end{equation}
where every subscript of ``$n+1$'' is identified with a subscript of ``$1$''.

The numerical results are shown in \cref{fig:flat_spectrum_1d}. (``CR'' stands for convex relaxation.) We observe that using a lower bound on $\SNX$ can give significantly improved predictions, and that the improvement appears to increase with $m$.

