\subsection{Random matrices}
We compare $\NS$ and $\SN$ in the case $\alpha$ is fixed and the $\Gamma_i$s are random. Let $E_{1}, \dots, E_{k}$ be the standard basis of $\mathbb{C}^{d\times d}$. As a case study, consider the following natural joint distribution on $\Gamma_1,\dots,\Gamma_k$: for all $i\in [k]$,
\begin{equation}
    \Gamma_i = \sum_{j=1}^k U_{j,i} E_j,
\end{equation}
where $U\in \mathbb{C}^{k\times k}$ is distributed according to the Haar measure on the set $\calU(k)$ of $k\times k$ unitary matrices. 

Note that the $\Gamma_i$s automatically form an orthonormal basis for $\mathbb{C}^{d\times d}$ (with respect to the Hilbert-Schmidt inner product). Moreover, the distribution is natural in that it is independent of our particular choice of orthonormal basis $E_1,\dots,E_k$ due to the unitary invariance of the Haar measure. For the rest of this subsection, we view $\NS \coloneqq \bigl\|\sum_{i=1}^k \alpha_i \Gamma_i\bigr\|$ and $\SN \coloneqq \sum_{i=1}^k \abs{\alpha_i} \norm{\Gamma_i}$ as random variables under the above distribution on the $\Gamma_i$s.

By the unitary invariance of the Haar measure and $\norm{\alpha}_2 = 1$, we also see that $\Gamma \coloneqq \sum_{i=1}^k \alpha_i \Gamma_i$ has the same distribution as $\sum_{j=1}^k U_{j,1} E_j$, \emph{independent} of $\alpha$; which, by Ref.~\cite[Theorem 7.22]{tqi_watrous_2018}, is the same as $\sum_{j=1}^k u_j E_j$, where $u \in \mathbb{C}^k$ is distributed according to the uniform spherical measure on $\calS(k) \coloneqq \{v\in \mathbb{C}^k \colon \norm{v}_2 = 1\}$. Therefore, $\Gamma$ and (the marginal distribution of) $\Gamma_i$ for each $i$ are all distributed as $\sum_{j=1}^k u_j E_j$. From the definition of the uniform spherical measure \cite[Definition 7.16]{tqi_watrous_2018}, the explicit form of this common distribution can be written as $G/\norm{G}_F$, where $G\in \mathbb{C}^{d\times d}$ is distributed according to: for all $a,b\in [d]$,
\begin{equation}
    G_{a,b} = A_{a,b} + i B_{a,b},
\end{equation}
where $A_{a,b}$ and $B_{a,b}$ are independent standard normal distributions. 

Therefore, $\NS$, which equals $\norm{\Gamma}$, and $\norm{\Gamma_i}$ for each $i$ are all distributed as $\norm{G}/\norm{G}_F$. In particular, we have
\begin{equation}
    \expect[\NS] = \expect[\norm{G}/\norm{G}_F] \quad \text{and} \quad
    \expect[\SN] = \expect\Bigl[ \sum_{i=1}^k \abs{\alpha_i} \norm{\Gamma_i} \Bigr] = \norm{\alpha}_1 \cdot \expect[\norm{G}/\norm{G}_F],
\end{equation}
and so $\expect[\NS] = \norm{\alpha}_1^{-1} \cdot \expect[\SN]$. We note that $\norm{\alpha}_1^{-1}$ can be tiny despite $\norm{\alpha}_2^{-1} = 1$: in the extreme case, $\alpha_i = 1/\sqrt{k}$ for all $i$ and $\norm{\alpha}_1^{-1} = 1/\sqrt{k}$. This suggests that the inequality $\NS \leq \SN$ could be very slack, which offers another explanation for the lack of quantitative agreement between the predicted and actual spectra in \cref{fig:flat_spectrum}. To improve agreement, it could make sense to counteract the slack by artificially scaling \emph{down} the value of $m$ in \cref{prop:energy_min}. Indeed, as shown in \cref{fig:flat_spectrum}, scaling $m$ down does \emph{raise} the heights of the predicted tails, making them better match the heights of the actual tails.

One objection to the above justification of artificially scaling down $m$ is that we only showed $\NS = \norm{\alpha}_1^{-1} \SN$ \emph{in expectation}. For the rest of this subsection, we address this objection by proving that $\NS = \Theta(\norm{\alpha}_1^{-1}) \SN$ holds \emph{with high probability}. Our proof uses existing concentration-of-measure results to show that $\NS=\Theta(1/\sqrt{d})$ with high probability and $\SN=\Theta(\norm{\alpha}_1/\sqrt{d})$ with high probability.

We will use the following results. To state them conveniently, for $D\in \mathbb{N}$, we write $\chi^2(D)$ for the chi-squared distribution on $D$ degrees of freedom.
\begin{fact}[{Ref.~\cite[Lemma 1]{chisquare_laurent_massart_2000}}]\label{fact:chi_squared_concentration}
    Suppose $X$ is distributed according to $\chi^2(D)$. Then, for all $r\geq 0$,
    \begin{equation}
        \Pr(X \geq D + 2 \sqrt{D r} + 2r) \leq \exp(-r) \quad \text{and} \quad \Pr(X \leq D -  2\sqrt{Dr}) \leq \exp(-r).
    \end{equation}
\end{fact}

\begin{fact}[{Ref.~\cite[Lemma 2.1]{kostlan_spectra_1992}}]
\label{fact:complex_gaussian_concentration}  Suppose $X$ is distributed according to $\chi^2(2(2d-1))$. Then, for all $r\geq 0$,
\begin{equation}
    \Pr[X > r^2] \leq \Pr[\norm{G}>r] \leq \frac{(2d-1)!}{(d!)^2}\Pr[X > r^2].
\end{equation}
\end{fact}

Combining \cref{fact:chi_squared_concentration,fact:complex_gaussian_concentration}, and using $(2d-1)!/(d!)^2 \leq 4^d = \exp(d \cdot \ln 4)$,  gives
\begin{corollary}\label{cor:spectral_norm_G}
There exist constants $C>c>0$ and $\epsilon>0$ such that for all sufficiently large $d$,
\begin{equation}
    \Pr[c \sqrt{d} \leq \norm{G} \leq  C \sqrt{d}] \geq 1 - \exp(-\epsilon \cdot d).
\end{equation}
\end{corollary}

On the other hand, $\norm{G}_F^2 = \sum_{a,b\in [d]}(A_{a,b}^2 + B_{a,b}^2)$ is clearly distributed as $\chi^2(2d^2)$, so \cref{fact:chi_squared_concentration} gives
\begin{corollary}\label{cor:frobenius_norm_G}
    There exist constants $C>c>0$ and $\epsilon>0$ such that for all sufficiently large $d$,
\begin{equation}
    \Pr[c d \leq \norm{G}_F \leq  C d] \geq 1 - \exp(-\epsilon \cdot d^2).
\end{equation}
\end{corollary}
Combining \cref{cor:spectral_norm_G,cor:frobenius_norm_G} gives
\begin{corollary}\label{cor:NS_whp}
There exist constants $C>c>0$ and $\epsilon>0$ such that for all sufficiently large $d$,
\begin{equation}
    \Pr[c/\sqrt{d} \leq \norm{G}/\norm{G}_F \leq  C/\sqrt{d}] \geq 1 - \exp(-\epsilon \cdot d).
\end{equation}
\end{corollary}

Since $\NS$ is distributed as $\norm{G}/\norm{G}_F$, \cref{cor:NS_whp} shows that $\NS$ is equal to $\Theta(1/\sqrt{d})$ with high probability. 

We will now show that $\SN$ is equal to $\Theta(\norm{\alpha}_1/\sqrt{d})$ with high probability. First, note that $\norm{G}/\norm{G}_F\leq 1$, so using \cref{cor:NS_whp} and the law of total expectation, conditioning on whether $\norm{G}/\norm{G}_F = \Theta(1/\sqrt{d})$, gives 
\begin{equation}
    \expect[\norm{G}/\norm{G}_F] = \Theta(1/\sqrt{d} + 1\cdot \exp(-\Omega(d))) = \Theta(1/\sqrt{d}).
\end{equation}
Therefore, $\expect[\SN] = \Theta(\norm{\alpha}_1/\sqrt{d})$. Therefore, to show $\SN=\Theta(\norm{\alpha}_1/\sqrt{d})$ with high probability, it suffices to show the claim that $\abs{\SN-\expect[\SN]} \leq o(\norm{\alpha}_1/\sqrt{d})$ holds with high probability. This claim follows from
\begin{proposition}\label{prop:haar_concentration}
For all $r\geq 0$,
\begin{equation}\label{eq:sn_concentration}
    \Pr\Bigl[\Bigl|\SN - \expect[\SN]\Bigr|\geq r\Bigr] \leq 2 \exp(-k r^2/24).
\end{equation}    
\end{proposition}
By setting $r = C/\sqrt{k} = C/d$ for a large constant $C>0$ in the proposition, we see $\abs{\SN-\expect[\SN]} \leq C/d$ holds with high probability, $1-2\exp(-C^2/24)$. Since  $\norm{\alpha}_1 \geq 1$, we have $C/d = o(\norm{\alpha}_1/\sqrt{d})$ and hence the claim.

\begin{proof}[Proof of \cref{prop:haar_concentration}]
Define $f\colon \calU(k) \to \mathbb{R}$ by
\begin{equation}
    f(U) \coloneqq \sum_{i=1}^k \abs{\alpha_i} \Bigl\|\sum_{j=1}^k U_{j,i} E_j\Bigr\|.
\end{equation}
Then $f$ is $1$-Lipschitz with respect to the Hilbert-Schmidt metric on $\calU(k)$ because: for all $U,V \in \calU(k)$,
\begin{align}
    \abs{f(U) - f(V)} \leq&~\sum_{i=1}^k \abs{\alpha_i} \Bigl\|\sum_{j=1}^k (U_{j,i}-V_{j,i}) E_j\Bigr\| \leq \sum_{i=1}^k \abs{\alpha_i} \Bigl\|\sum_{j=1}^k (U_{j,i}-V_{j,i}) E_j\Bigr\|_F \notag
    \\
    =&~\sum_{i=1}^k \abs{\alpha_i} \Bigl(\sum_{j=1}^k \abs{U_{j,i}-V_{j,i}}^2\Bigr)^{1/2} \leq \Bigl(\sum_{i=1}^k \abs{\alpha_i}^2\Bigr)^{1/2} \Bigl(\sum_{i=1}^k\sum_{j=1}^k \abs{U_{j,i}-V_{j,i}}^2\Bigr)^{1/2} = \norm{U-V}_F.
\end{align}

By definition, the distribution of $f(U)$ when $U$ is chosen according to the Haar measure on $\calU(k)$ is the same as the distribution of $\SN$. Therefore, slightly adapting Ref.~\cite[Theorem 5.17]{random_matrix_meckes_2019} gives \cref{eq:sn_concentration}. 
\end{proof}

