\title{Scheduling on identical machines with conflicts to minimize the mean flow time}

\author{Nour ElHouda Tellache}
\address{N.E.H. Tellache, Decision Support \& Operations Research Group, Department of Informatics, University of Fribourg, Fribourg, Switzerland}
\email{nourelhouda.tellache@unifr.ch}

\author{Lydia Aoudia}
\address{L. Aoudia, RECITS Laboratory, USTHB university, BP 32 El-Alia, Bab-Ezzouar, Algiers, Algeria}
\email{aoudialydia96@gmail.com}

\author{Mourad Boudhar}
