\end{center}
	\caption{Agreement graph $\overline{G} = (V, \overline{E})$ associated with the reduction of Theorem~\ref{th1}}\label{Fig1}
\end{figure}
\begin{proof} We establish this result through a polynomial reduction from the Hamiltonian Path (HP) problem. Given an undirected graph \( G' = (V', E') \), the HP problem asks whether there exists a path that visits each vertex exactly once. It is well known that the HP problem is NP-complete~\cite{GJ79}.

	Given an arbitrary instance of HP, we construct an instance of \( P2 | \text{ConfG} = (V, E), p_i \in \{a, b\} | \sum C_j \) as follows (see Figure~\ref{Fig1}). Specifically, we derive the agreement graph $\overline{G} = (V, \overline{E})$ from \( G' \), where:
	\begin{itemize}
		\item $V=V'\cup \{J_{n+1}\} $ (adding a extra vertex),
		\item $\overline{E}=E'\cup \{(J_{i}, J_{n+1}), j \in 1,...,n\}$,
	\end{itemize}
	The processing times of the jobs are defined as follows, with $a < b$:
	\begin{itemize}
		\item $p_j=b$, $j=1,...,n$;
		\item $p_{n+1}=a$.
	\end{itemize}

	We show that the HP problem has a solution if and only if there exists a feasible schedule of the jobs such that the total completion time satisfies

	\begin{equation}
		\sum C_j \leq 
		\begin{cases}
			\dfrac{n+2}{2}\left( \dfrac{n}{2}b+a\right), & \text{if } n \text{ is even}, \\
			\\
			\dfrac{n+1}{2}\left( \dfrac{n+1}{2}b+a\right), & \text{if } n \text{ is odd}.
		\end{cases}
		\label{eqth1:completion_times}
	\end{equation}

	Suppose the HP problem has a solution, meaning there exists a Hamiltonian path in the graph \(G'\) that visits each vertex exactly once. From this solution, we construct a solution to our scheduling problem by assigning the jobs to two machines according to their order in the Hamiltonian path, alternating between the two machines and starting with \(J_{n+1}\), as shown in Figures~\ref{Fig2a} and~\ref{Fig2b}.

	\begin{figure}[H]
		\centering 
		\begin{center}
		\psscalebox{1.0 1.0} % Change this value to rescale the drawing.
		{
			\includegraphics{figure2.pdf}
		}
	\end{center}
		\caption{Feasible schedule for even $n$ in the reduction instance of Theorem~\ref{th1}.}\label{Fig2a}
	\end{figure}

	\begin{figure}[H]
			\begin{center}
			\psscalebox{1.0 1.0} % Change this value to rescale the drawing.
			{
				\includegraphics{figure3.pdf}
			}
		\end{center}
		\caption{Feasible schedule for odd $n$ in the reduction instance of Theorem~\ref{th1}.}\label{Fig2b}
	\end{figure}

	The sum of the completion times when $n$ is even is given by:
	$$
	\sum C_j= \left( a+(a+b)+(a+2b)+\ldots+\left(a+ \frac{n}{2}b\right) \right) +\left( b+2b+\ldots+\frac{n}{2}b\right) 
	$$

	This simplifies to:
	$$
	\sum C_j= \dfrac{n+2}{2}\left( \dfrac{n}{2}b+a\right) 
	$$

	Similarly, for $n$ odd, the sum of the completion times is:
	$$
	\sum C_j= \left( a+(a+b)+(a+2b)+\ldots+\left(a+ \frac{n-1}{2}b\right) \right) +\left( b+2b+\ldots+\frac{n+1}{2}b\right) 
	$$

	This simplifies to:
	$$
	\sum C_j= \dfrac{n+1}{2}\left( \dfrac{n+1}{2}b+a\right) 
	$$

	Therefore, the desired result follows.

	Conversely, suppose that the scheduling problem has a feasible solution that satisfies~\eqref{eqth1:completion_times}. We now demonstrate that the only possible schedule satisfying~\eqref{eqth1:completion_times} is the one shown in Figures~\ref{Fig2a} and~\ref{Fig2b}. Suppose, by contradiction, that there exists another schedule satisfying~\eqref{eqth1:completion_times} but differing from the one in Figures~\ref{Fig2a} and~\ref{Fig2b}. Such a schedule could arise in one of the following ways:

	\begin{itemize} 
		\item Scheduling $J_{n+1}$ at a time later than $0$. This would increase the sum of the completion times according to the SPT rule, thereby violating~\eqref{eqth1:completion_times}. 
		\item Scheduling $J_{n+1}$ at the beginning, but not in parallel with any other job. This would introduce idle time on the opposite machine, and it can be checked that~\eqref{eqth1:completion_times} would not hold.
		\item Scheduling at least one job with processing time $b$ not in parallel with two other jobs. This would cause idle time on one machine because $J_{n+1}$ is scheduled at the beginning, which increases the sum of the completion times and violates~\eqref{eqth1:completion_times}. \end{itemize}

	Thus, the only feasible schedule that satisfies~\eqref{eqth1:completion_times} is the one shown in Figures~\ref{Fig2a} and~\ref{Fig2b}. A Hamiltonian path is constructed by following the dashed paths in these figures, which connect jobs scheduled in parallel. Finally, it can be verified that the reduction is polynomial, completing the proof of Theorem~\ref{th1}.
\end{proof}

When $p_j=1$ for all jobs, the two-machine problem can be solved in polynomial time for arbitrary conflict graphs by finding a maximum matching in the agreement graph. The algorithmic steps are outlined in Algorithm~\ref{Algo1}.

\begin{algorithm}[H]
	\caption{Optimal schedule for $P2|\text{ConfG} = (V, E),p_j=1|\sum C_j$}\label{Algo1}
	\begin{algorithmic}[1]
		\State Find a maximum matching $M$ in $\overline{G}$.
		\State Schedule each pair of jobs from the matching to run in parallel at the earliest available time, in any order (see Figure~\ref{Fig6}).
		\State Schedule the remaining jobs (those not in the matching) after the matched jobs, in disjoint time intervals, starting at the earliest possible time and in any order (see Figure~\ref{Fig6}).
		%\State $\overline{C} = \dfrac{|M|(|M|-1)}{n}+ \dfrac{n + 1}{2}$.
	\end{algorithmic}
\end{algorithm}

\begin{figure}[h!]
	\begin{center}
	\psscalebox{1.0 1.0} % Change this value to rescale the drawing.
	{
		\includegraphics{figure4.pdf}
	}
\end{center}
	\caption{Optimal schedule for $P2|G =(V, E),p_{j}=1|\sum C_j$, as generated by Algorithm~\ref{Algo1}}\label{Fig6}
\end{figure}

\begin{theorem}\label{thm2}
	$P2 \mid \text{ConfG} = (V, E),\ p_j = 1 \mid \sum C_j $  can be solved in polynomial time by Algorithm~\ref{Algo1}, and the optimal total completion time is
	\[
	\sum C_j = |M|(|M|-n) + \frac{n(n+1)}{2},
	\]
	where \( M \) is a maximum matching in \( \overline{G} \).
\end{theorem}

\begin{proof}
	Suppose by contradiction that the schedule produced by Algorithm~\ref{Algo1} is not optimal. Then, there exists another schedule with a smaller total completion time. This would require that at least one job is completed earlier than in the schedule produced by Algorithm~\ref{Algo1}. However, the jobs corresponding to the matching \( M \) are already scheduled as early as possible, in parallel pairs. Therefore, the only way to improve the schedule would be to schedule one of the unmatched jobs earlier, in parallel with another unmatched job. This would imply that these two jobs are not in conflict, meaning that an edge exists between them in the agreement graph \( \overline{G} \). Consequently, the matching \( M \) would not be maximum, contradicting its maximality. Thus, the schedule produced by Algorithm~\ref{Algo1} is optimal. As a maximum matching can be computed in polynomial time, the problem $P2 \mid \text{ConfG} = (V, E),\ p_j = 1 \mid \sum C_j $ is solvable in polynomial time.

	It remains to compute the optimal total completion time. We have:
	$$
	\sum_{j=1}^{n} C_j = 2(1+2+\ldots+|M|) + ((|M|+1)+(|M|+2)\ldots+(n-|M|)) 
	$$

	$$
	\sum_{j=1}^{n} C_j = 2 \times \left(\dfrac{|M| (|M| + 1)}{2}\right) + 
	\dfrac{n+1}{2} (n-2|M|)
	$$

	$$
	\sum_{j=1}^{n} C_j = \dfrac{n(n+1)}{2}+|M|(|M|-n)
	$$
\end{proof}


