\title{Fractional Programming for Stochastic Precoding over Generalized Fading Channels}

\author{
    \IEEEauthorblockN{
    Wenyu Wang, \IEEEmembership{Graduate Student Member,~IEEE} and Kaiming Shen, \IEEEmembership{Senior Member,~IEEE},
   } % <-this % stops a space
%\thanks{
