\hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y})= \\\sum_{(j,k)}\omega_{jk}\Bigg[\log\big|\mathbf{I}+\mathbf{\Gamma}_{jk}\big|-\mathrm{Tr}\big(\mathbf{\Gamma}_{jk}\big)+\mathrm{Tr}\Bigg(\big(\mathbf{I}+\mathbf{\Gamma}_{jk}\big)\Bigg(2\Re\big\{\mathbf{V}_{jk}^H\mathbf{C}_{jk}^H\mathbf{Y}_{jk}\big\}-\mathbf{Y}_{jk}^H\Bigg(\sum_{(\ell,s)}\mathbf{U}_{jk,\ell s}+\sigma^2\mathbf{I}\Bigg)\mathbf{Y}_{jk}\Bigg)\Bigg)\Bigg] \tag{26}
\label{obj:Epgy}
