We now specialize the above matrix FP method for the stochastic precoding problem \eqref{prob:orig}. In light of the following correspondences:
\begin{align}
    \sqrt{\mathbf A_n(x\mid\theta^+_n)} &\;\Longleftrightarrow\; \mathbf H_{jk,j}\mathbf V_{jk},\\
    \mathbf B_n(x\mid\theta^-_n) &\;\Longleftrightarrow\; \mathbf F_{jk},
\end{align}
problem \eqref{prob:orig} is converted to 
\begin{subequations}\label{prob:bound}
    \begin{align}
        \underset{\mathbf{V},\bm\Gamma,\mathbf Y}{\text{maximize}}&\quad \hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y})\\
    \text{subject to}& \quad \sum^K_{k=1}\text{Tr}(\mathbf{V}_{jk}\mathbf{V}_{jk}^H)\leq P,\; \forall j\label{cons:power}\\
    &\quad\, \bm\Gamma_{jk}\in\mathbb S^{M_r\times M_r}_+,\; \forall (j,k) \label{cons:gamma}\\
    &\quad\, \mathbf Y_{jk}\in\mathbb C^{M_r\times M_r},\; \forall (j,k),\label{cons:y}
    \end{align}
\end{subequations}
where the new objective function $\hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y})$ is shown in \eqref{obj:Epgy} at the top of next page, with the shorthand
\setcounter{equation}{26}
\begin{align}
\mathbf U_{jk,\ell s} = \mathbb E\big[\mathbf{H}_{jk,\ell}\mathbf{V}_{\ell s}\mathbf{V}_{\ell s}^H\mathbf{H}_{jk,\ell}^H\big].
\end{align}
Each entry of $\mathbf U_{jk,\ell s}\in\mathbb S^{M_r\times M_r}_+$ can be obtained from the current $\mathbf V$ and the second moment $\mathbf D_{jk,\ell}$ as
\begin{align}
&\big(\mathbf U_{jk,\ell s}\big)_{m,n}\notag\\
&=\sum_{m'=1}^{M_t}\sum_{n'=1}^{M_t}\big(\mathbf V_{\ell s}\mathbf V^H_{\ell s}\big)_{m',n'}\mathbb{E}\big[\big(\mathbf{H}_{jk,\ell}\big)_{m,m'}\big(\mathbf{H}^c_{jk,\ell}\big)_{n,n'}\big]\notag\\
&= \sum_{m'=1}^{M_t}\sum_{n'=1}^{M_t}\Big(\big(\mathbf V_{\ell s}\mathbf V^H_{\ell s}\big)_{m',n'}\notag\\
&\qquad\times(\mathbf D_{jk,\ell})_{(m'-1)M_r+m,(n'-1)M_r+n}\Big)
\label{U}
\end{align}



We then optimize $(\mathbf{V},\bm\Gamma,\mathbf Y)$ in an iterative fashion. When $\mathbf{V}$ and $\mathbf Y$ are both held fixed, each $\bm\Gamma_{jk}$ can be optimally determined as
\begin{multline}\label{eq:Ga_opt}
\mathbf{\Gamma}_{jk}^\star=\mathbf{V}_{jk}^H\mathbf{C}_{jk}^H\Bigg(\sigma^2\mathbf{I}+\sum_{(\ell,s)}\mathbf U_{jk,\ell s}\\-\mathbf{C}_{jk}\mathbf{V}_{jk}\mathbf{V}_{jk}^H\mathbf{C}_{jk}^H\Bigg)^{-1}\mathbf{C}_{jk}\mathbf{V}_{jk}.
\end{multline}
When $\mathbf{V}$ and $\bm\Gamma$ are both held fixed, each $\mathbf Y_{jk}$ can be optimally determined as
\begin{equation}\label{eq:Y_opt}
\mathbf{Y}_{jk}^\star=\Bigg(\sigma^2\mathbf{I}+\sum_{(\ell,s)}\mathbf U_{jk,\ell s}\Bigg)^{-1}\mathbf{C}_{jk}\mathbf{V}_{jk}.
\end{equation}
After $\bm\Gamma$ has been optimized according to \eqref{eq:Ga_opt} for the current $\mathbf Y$, the solution of each $\mathbf V_{jk}$ is given by
\begin{equation}\label{eq:upPbisearch}
\mathbf{V}_{jk}=\Bigg(\eta_j\mathbf{I}+\sum_{(\ell,s)}\omega_{\ell s}\bm \Lambda_{j,\ell s}\Bigg)^{-1}\omega_{jk}\mathbf{C}_{jk}^H\mathbf{Y}_{jk}(\mathbf{I}+\mathbf{\Gamma}_{jk}),
\end{equation}
where the Lagrangian multiplier $\eta_j\ge0$ for the power constraint is optimally determined as
\begin{align}
\label{Lagrange multiplier}
    \eta_j^\star=\min\Bigg\{\eta_j\geq0:\sum^K_{k=1}\mathrm{Tr}(\mathbf{V}_{jk}\mathbf{V}_{jk}^H)\leq P\Bigg\},
\end{align}
and the matrix $\bm \Lambda_{j,\ell s}\in\mathbb S^{M_t\times M_t}_{+}$ is given by
\begin{equation}
\bm \Lambda_{j,\ell s} = \mathbb{E}\big[\mathbf{H}_{\ell s,j}^H\mathbf{Y}_{\ell s}(\mathbf{I}+\mathbf{\Gamma}_{\ell s})\mathbf{Y}_{\ell s}^H\mathbf{H}_{\ell s,j}\big].
\end{equation}
We can use $\mathbf D_{jk,\ell}$ to recover each entry of $\bm \Lambda_{j,\ell s}$ as
\begin{align}
&\big(\bm \Lambda_{j,\ell s}\big)_{m,n}\notag\\
&=\sum_{m'=1}^{M_r}\sum_{n'=1}^{M_r}\Big(\big(\mathbf{Y}_{\ell s}(\mathbf{I}+\mathbf{\Gamma}_{\ell s})\mathbf{Y}_{\ell s}^H\big)_{m',n'}\notag\\
&\qquad\qquad\qquad\quad\times\mathbb{E}\big[\big(\mathbf{H}^c_{\ell s,j}\big)_{m',m}\big(\mathbf{H}_{\ell s,j}\big)_{n',n}\big]\Big)\notag\\
&= \sum_{m'=1}^{M_r}\sum_{n'=1}^{M_r}\Big(\big(\mathbf{Y}_{\ell s}(\mathbf{I}+\mathbf{\Gamma}_{\ell s})\mathbf{Y}_{\ell s}^H\big)_{m',n'}\notag\\
&\qquad\qquad\qquad\times(\mathbf D_{\ell s,j}^c)_{(m-1)M_r+m',(n-1)M_r+n'}\Big).
\label{Lambda}
\end{align}

Algorithm \ref{alg1} summarizes the above steps for stochastic precoding. Its per-iteration complexity equals $\mathcal{O}(L^2K^2M_r^2M_t^2+LKM_r^3+LM_t^3)$. The following theorem provides a convergence analysis for this algorithm.
\begin{algorithm}[t]
    \caption{Stochastic Precoding Based on Matrix FP}
    \label{alg1}
    \begin{algorithmic}[1]
        \STATE \textbf{input:} first and second moments $\{\mathbf C,\mathbf D\}$ of fading channels
        \REPEAT
        \STATE compute $\mathbf{U}$ by \eqref{U} and then update $\mathbf{Y}$ by \eqref{eq:Y_opt}
        \STATE update $\bm{\Gamma}$ by \eqref{eq:Ga_opt}
        \STATE compute $\bm\Lambda$ by \eqref{Lambda}
        and then update $\mathbf{V}$ by \eqref{eq:upPbisearch}
        \UNTIL{the objective value converges}
        \STATE \textbf{output:} precoding matrix $\mathbf V$
    \end{algorithmic}
\end{algorithm}

