\label{obj:Epgy new}
\hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y})=\sum_{(j,k)}\Bigg(\omega_{jk}\log\big|\mathbf{I}+\mathbf{\Gamma}_{jk}\big|-\omega_{jk}\mathrm{Tr}\big(\mathbf{\Gamma}_{jk}\big)\\
+\mathrm{Tr}\Bigg(2\omega_{jk}\big(\mathbf{I}+\mathbf{\Gamma}_{jk}\big)\Re\big\{\mathbf{V}_{jk}^H\mathbf{C}_{jk}^H\mathbf{Y}_{jk}\big\}-\omega_{jk}\sigma^2\big(\mathbf{I}+\mathbf{\Gamma}_{jk}\big)\mathbf{Y}_{jk}^H\mathbf{Y}_{jk}-\mathbf{V}_{jk}^H\Bigg(\sum_{(\ell,s)}\omega_{\ell s}\mathbf{\Lambda}_{j,\ell s}\Bigg)\mathbf{V}_{jk}\Bigg)\Bigg)\tag{40}
