\begin{proposition}
    Algorithm \ref{alg1} guarantees convergence to a stationary point $(\mathbf V,\bm\Gamma,\mathbf Y)$ of problem \eqref{prob:bound}. Moreover, the new objective in \eqref{prob:bound} is a lower bound to the original objective:
    \begin{equation}
        \hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y}) \le \sum^L_{j=1}\sum^K_{k=1}\mathbb{E}\Big[\omega_{jk}\mathcal{R}_{jk}\Big].
    \end{equation}
\end{proposition}
\begin{IEEEproof}
    The convergence result follows by the property of FP as shown in \cite{fp_ii}. The lower bound result follows by Theorem \ref{thm:lower bound}.
\end{IEEEproof}

\begin{remark}
The computations of $\mathbf U$ and $\bm\Lambda$ in Algorithm \ref{alg1} can be further simplified when fading channels are known to be Rayleigh or Rician. In that case, each $\mathbf H_{jk,\ell}$ has a Gaussian distribution:
\begin{equation}
    \mathbf{H}_{jk,\ell} = \widetilde{\mathbf{H}}_{jk,\ell}+\mathbf{W}_{jk,\ell}\odot\mathbf{X}_{jk,\ell},
\end{equation}
where $\widetilde{\mathbf{H}}_{jk,\ell}\in\mathbb C^{M_r\times M_t}$ and $\mathbf{W}_{jk,\ell}\in\mathbb C^{M_r\times M_t}$ are fixed matrices, and $\mathbf{X}_{jk,\ell}\in\mathbb C^{M_r\times M_t}$ is a random matrix with each entry drawn i.i.d. from the standard complex Gaussian distribution $\mathcal{CN}(0,1)$. Then $\mathbf U$ and $\bm\Lambda$ are directly given by
\begin{align}
    &\mathbf U_{jk,\ell s} = \widetilde{\mathbf{H}}_{jk,\ell}\mathbf{V}_{\ell s}\mathbf{V}_{\ell s}^H\widetilde{\mathbf{H}}_{jk,\ell}^H\notag\\
    &\;+\mathrm{diag}\Big(\big(\mathbf{W}_{jk,\ell}\odot\mathbf{W}_{jk,\ell}\big)\mathrm{Diag}\big(\mathbf{V}_{\ell s}\mathbf{V}_{\ell s}^H\big)\Big),\\
    &\bm \Lambda_{j,\ell s} = \widetilde{\mathbf{H}}_{jk,\ell}^H\mathbf{Y}_{\ell s}(\mathbf{I}+\mathbf{\Gamma}_{\ell s})\mathbf{Y}_{\ell s}^H\widetilde{\mathbf{H}}_{jk,\ell}\notag\\
    &\;+\mathrm{diag}\Big(\big(\mathbf{W}_{jk,\ell}^H\odot\mathbf{W}_{jk,\ell}^H\big)\mathrm{Diag}\big(\mathbf{Y}_{\ell s}(\mathbf{I}+\mathbf{\Gamma}_{\ell s})\mathbf{Y}_{\ell s}^H\big)\Big),
\end{align}
so we no longer need to compute these matrices entry by entry as in \eqref{U} and \eqref{Lambda}. As a result, the per-iteration complexity of Algorithm \ref{alg1} reduces to $\mathcal{O}(L^2K^2M_rM_t^2+L^2K^2M_r^2M_t+LKM_r^3+LM_t^3)$.
In particular, if we further let $M_r=1$ then Algorithm \ref{alg1} reduces to the precoding method in \cite{shi21}. 






