\section{Acceleration for Large-Scale MIMO}
\label{sec:fast FP}

In this section we cope with such a challenge: for the large-scale MIMO case with $M_t$ being a large number, the $M_t\times M_t$ matrix inverse in \eqref{eq:upPbisearch} renders the update of $\mathbf V$ computationally formidable in Step 5 of Algorithm \ref{alg1}. The main idea is to get rid of this $M_t\times M_t$ matrix inverse by further modifying the matrix FP. We start by introducing a useful inequality from \cite{chenfastfp,nonhomobound}.

%We now assume that the number of transmit antennas, $M_t$, is extremely large, namely \emph{massive MIMO}. As a consequence, the update of $\mathbf{V}$  in step 4 of Algorithm \ref{alg1} is computationally formidable, because it entails computing an $M_t\times M_t$ matrix inverse as in \eqref{eq:upPbisearch}. The main result of this section is to show that the fast FP technique from \cite{shen_accqt} can be carried over to our problem case, so as to eliminate the $M_t\times M_t$ matrix inverse and also accelerate the convergence.

%However, the large number of antennas equipped by BSs causes that the matrix inversion in \eqref{eq:upPbisearch} consumes a large amount of computational resources and the bisection search further reduces algorithm efficiency. Thus, we introduce a nonhomogeneous bound, which is first proposed in \cite{shen_accqt} to prompt the FP algorithm.


\begin{lemma}\label{lemma:nonhomo}
Consider any two ${M\times M}$ Hermitian matrices $\mathbf{L},\mathbf{K}$ satisfying $\mathbf{L}\preceq\mathbf{K}$. For any $\mathbf{X},\mathbf{Z}\in\mathbb{C}^{M\times N}$, we have
\begin{multline}
\label{nonhomo inequality}
\mathrm{Tr}\big(\mathbf{X}^H\mathbf{L}\mathbf{X}\big)\leq\mathrm{Tr}\big(\mathbf{X}^H\mathbf{K}\mathbf{X}+2\Re\{\mathbf{X}^H(\mathbf{L}-\mathbf{K})\mathbf{Z}\}\\+\mathbf{Z}^H(\mathbf{K}-\mathbf{L})\mathbf{Z}\big),
\end{multline}
where the equality holds if $\mathbf{Z}=\mathbf{X}$.
\end{lemma}

To see how the above inequality may assist with our problem case, we first rewrite $\hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y})$ in \eqref{obj:Epgy} in a quadratic form of $\mathbf V_{jk}$, as shown in \eqref{obj:Epgy new}. Now observe that the $M_t\times M_t$ matrix inverse in \eqref{eq:upPbisearch} is caused by the quadratic term $\mathbf{V}_{jk}^H(\sum_{(\ell,s)}\omega_{\ell s}\mathbf{\Lambda}_{j,\ell s})\mathbf{V}_{jk}$ in \eqref{obj:Epgy new}. Let us treat $\sum_{(\ell,s)}\omega_{\ell s}\mathbf{\Lambda}_{j,\ell s}$ as $\mathbf L$ in \eqref{nonhomo inequality}. The main idea here is to replace this matrix with a ``simpler'' matrix $\mathbf K$ in the quadratic term by using Lemma \ref{lemma:nonhomo};
since we seek to eliminate matrix inverse, it is desirable to let $\mathbf K=\alpha \mathbf I$ so that its inverse is directly given by $\mathbf K^{-1}=(1/\alpha) \mathbf I$. But how do we choose the factor $\alpha$ to meet the condition $\mathbf{L}\preceq\mathbf{K}$ in Lemma \ref{lemma:nonhomo}? As suggested in \cite{shen_accqt}, we may set $\alpha$ to the largest eigenvalue of $\mathbf L$.

\begin{algorithm}[t]
    \caption{Fast Stochastic Precoding for Large-Scale MIMO}
    \label{alg2}
    \begin{algorithmic}[1]
        \STATE \textbf{input:} first and second moments $\{\mathbf C,\mathbf D\}$ of fading channels
        \REPEAT
        \STATE compute $\mathbf{U}$ by \eqref{U} and then update $\mathbf{Y}$ by \eqref{eq:Y_opt}
        \STATE update $\bm{\Gamma}$ by \eqref{eq:Ga_opt}
        \STATE update $\mathbf{Z}$ by \eqref{eq:z_opt}
        \STATE compute $\bm\Lambda$ by \eqref{Lambda}
        and then update $\mathbf{V}$ by \eqref{eq:upPfast}
        \UNTIL{the objective value converges}
        \STATE \textbf{output:} precoding matrix $\mathbf V$
    \end{algorithmic}
\end{algorithm}


By applying the inequality \eqref{nonhomo inequality} to $\hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y})$ in \eqref{obj:Epgy}, we obtain a lower bound 
\setcounter{equation}{40}
\begin{equation}
\zeta(\mathbf{V},\mathbf{\Gamma},\mathbf{Y},\mathbf Z)\le \hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y}),
\end{equation}
which is shown in \eqref{obj:pgyz} with the shorthands
\setcounter{equation}{42}
\begin{equation}
\bm\Xi_j=\sum_{(\ell,s)}\omega_{\ell s}\mathbf{\Lambda}_{j,\ell s}
\end{equation}
and
\begin{equation}
    \alpha_j=\lambda_{\max}(\bm\Xi_j).
\end{equation}
Problem \eqref{prob:bound} is now turned to
\begin{subequations}\label{prob:fastbound}
    \begin{align}
        \underset{\mathbf{V},\mathbf Z,\bm\Gamma,\mathbf Y}{\text{maximize}}&\quad \zeta(\mathbf{V},\mathbf{Z},\mathbf{\Gamma},\mathbf{Y})\\
    \text{subject to}& \quad \eqref{cons:power},\eqref{cons:gamma},\eqref{cons:y}\\
    &\quad\, \mathbf Z_{jk}\in\mathbb C^{M_t\times M_r},\; \forall (j,k).
    \end{align}
\end{subequations}
As before, we optimize these variables in an iterative fashion. When $(\mathbf{V},\mathbf{\Gamma},\mathbf{Y})$ are fixed, as shown in Lemma \ref{lemma:nonhomo}, each $\mathbf Z_j$ can be optimally determined as
\begin{align}\label{eq:z_opt}
    \mathbf{Z}_{jk}^\star = \mathbf{V}_{jk},
\end{align}
The iterative optimal updates of $\mathbf Y$ and $\bm \Gamma$ are still given by \eqref{eq:Y_opt} and \eqref{eq:Ga_opt}, respectively. Moreover, for fixed $(\mathbf{Y},\mathbf{\Gamma},\mathbf{Z})$, after removing the constant terms, 
problem \eqref{prob:fastbound} can be divided into a set of subproblems on a per-cell basis:
\begin{subequations}\label{prob:upV}
\begin{align}
\underset{\mathbf{V}_{j1},\dots,\mathbf{V}_{jK}}{\text{minimize}}&\quad \sum^K_{k=1}\mathrm{Tr}\Big(2\Re\Big\{\omega_{jk}(\mathbf{I}+\mathbf{\Gamma}_{jk})\mathbf{V}_{jk}^H\mathbf{C}_{jk}^H\mathbf{Y}_{jk}\notag\\
&\quad+\mathbf{V}_{jk}^H(\alpha_{j}\mathbf{I}-\bm\Xi_j)\mathbf{Z}_{jk}\Big\}-\alpha_{j}\mathbf{V}_{jk}^H\mathbf{V}_{jk}\Big)\\%\Big\|\alpha_{j}\mathbf{V}_{jk}-\omega_{jk}\mathbf{C}_{jk}^H\mathbf{Y}_{jk}(\mathbf{I}+\mathbf{\Gamma}_{jk})\nonumber\\&\qquad\qquad\qquad-(\alpha_j\mathbf{I}-\mathbf{\Xi}_j)\mathbf{Z}_{jk}\Big\|^2_\mathrm{F}\\
\text{subject to}& \quad \sum^K_{k=1}\mathrm{Tr}(\mathbf{V}_{jk}\mathbf{V}_{jk}^H)\leq P,
\end{align}
\end{subequations}
for $j=1,2,\ldots,L$. The optimal solution of $\mathbf V_{jk}$ is given by
\begin{equation}
    \mathbf{V}_{jk}^\star=\frac{1}{\alpha_j+\eta_j^\star}\bigg(\omega_{jk}\mathbf{C}_{jk}^H\mathbf{Y}_{jk}(\mathbf{I}+\mathbf{\Gamma}_{jk})+\big(\alpha_j\mathbf{I}-\mathbf{\Xi}_j\big)\mathbf{Z}_{jk}\bigg),
\end{equation}
where the optimal Lagrange multiplier $\eta_j^\star$ is still computed as in \eqref{Lagrange multiplier}.
After a bit algebra, it can be shown that the above solution boils down to
\begin{align}\label{eq:upPfast}
\mathbf{V}^\star_{jk}=\left\{
\begin{array}{ll}
    {\bm\Psi}_{jk} & \text{if}\; \sum^K_{k=1}\mathrm{Tr}(\bm\Psi_{jk}^H\bm\Psi_{jk})\leq P\vspace{0.5em}\\
    \beta_j\bm\Psi_{jk} & \text{otherwise},
    \end{array}
    \right.
\end{align}
where
\begin{align}\label{eq:upVnonhomo}
\bm\Psi_{jk}
&=\mathbf{Z}_{jk}+\frac{1}{\alpha_{j}}\Big(\omega_{jk}\mathbf{C}_{jk}^H\mathbf{Y}_{jk}(\mathbf{I}+\mathbf{\Gamma}_{jk})-\mathbf{\Xi}_j\mathbf{Z}_{jk}\Big)
\end{align}
and
\begin{equation}
\beta_j = \sqrt{\frac{P}{\sum^K_{k=1}\mathrm{Tr}(\bm\Psi_{jk}^H\bm\Psi_{jk})}}.
\end{equation}
Algorithm \ref{alg2} summarizes the above steps. Its per-iteration complexity equals $\mathcal{O}(L^2K^2M_r^2M_t^2+LKM_r^3)$.

The following proposition shows that Algorithm \ref{alg2} converges to a stationary point solution not only of problem \eqref{prob:upV} but also of problem \eqref{prob:bound}, so the problem approximation based on Lemma \ref{lemma:nonhomo} does not cause performance loss.
\begin{proposition}
Algorithm \ref{alg2} converges to $(\mathbf V_0,\bm\Gamma_0,\mathbf Y_0,\mathbf Z_0)$ which is a stationary point of problem \eqref{prob:upV}. Moreover, $(\mathbf V_0,\bm\Gamma_0,\mathbf Y_0)$ is a stationary point of problem \eqref{prob:bound}.
\end{proposition}
\begin{IEEEproof}
We only sketch the basic ideas which follow the existing work \cite{shen_accqt} closely. First, Algorithm \ref{alg2} can be recognized as a minorization-maximization (MM) method for problem \eqref{prob:upV}; because each step of Algorithm \ref{alg2} boils down to solving a convex subproblem, the convergence to a stationary point can be verified by the MM theory \cite{shen_accqt}. Moreover, using the inequality in Lemma \ref{lemma:nonhomo} to bound $\hat f(\mathbf{V},\mathbf{\Gamma},\mathbf{Y})$ can be thought of as constructing a surrogate function for problem \eqref{prob:bound}, so each stationary point of problem \eqref{prob:upV} can be mapped to a stationary point of problem \eqref{prob:bound} according to the MM theory.
\end{IEEEproof}



%\subsection{Time Complexity Analysis}

%We now compare the time complexity of Algorithm \ref{alg1} and Algorithm \ref{alg2}. Notice that these two algorithms have the same update formulas of $\mathbf{Y}$ and $\mathbf{\Gamma}$. These two formulas consist of matrix multiplication between matrices with dimensions $M_r\times M_t$, $M_t\times M_r$ or $M_r\times M_r$ and inversion of matrices with dimensions $M_r\times M_r$. Thus, the time complexity of these two formulas is $\mathcal O(LKM_rM_t^2+M_r^3)$. Plus, in Algorithm \ref{alg1}, $\mathbf{V}$ is updated by \eqref{eq:upPbisearch}. Suppose the precision of bisection search is required as $\epsilon$, the complexity of search iterations is $O(-\log\epsilon)$. Besides, the inversion of a larger matrix needs to be computed in each search iteration, which makes the time complexity of \eqref{eq:upPbisearch} become $\mathcal O(-\log\epsilon(LKM_r^2M_t+M_t^3))$. To update these variables for all user terminals, the time complexity of each updating iteration in Algorithm \ref{alg1} is ultimately $\mathcal O(L^2K^2M_rM_t^2+LKM_r^3-\log\epsilon(L^2K^2M_r^2M_t+M_t^3))$. Different from Algorithm \ref{alg1}, the updating formula of $\mathbf{V}$ in Algorithm \ref{alg2}, i.e. \eqref{eq:upPfast}, only contains some matrix multiplications whose time complexity can be calculated by $\mathcal O(LKM_r^2M_t+LKM_rM_t^2)$. So, the time complexity of each updating iteration in Algorithm \ref{alg2} is ultimately $\mathcal O(L^2K^2M_r^2M_t+L^2K^2M_rM_t^2+LKM_r^3)$. Since $M_t\gg M_r$ in massive MIMO system, Algorithm \ref{alg2} demonstrates significantly superior time efficiency, which is shown in Table \ref{tab:run_time_comm}.

