\center
\includegraphics[width=0.6\textwidth]{figs/qpm_delta.eps}
%\includegraphics[width=0.49\textwidth]{figs/phiq_delta.eps}
\caption{Fermi points $q_\pm$ as a function of $n/t$, for various dimerizations $\delta$.}
\label{fig:qpm}
\end{figure}
%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

With the expression \eqref{qdif} at hand, the density follows immediately as
%
\eq{
\rho(n,t) = \frac{q_+-q_-}{\pi} = \frac{1}{\pi}\arccos \left(\frac{n}{v_{max}t}\right),
%\zeta \, , \qquad %\zeta = \frac{x}{v_{max}t} ,
\label{dens}}
%
which is nothing but the result for the domain-wall melting in a homogeneous chain \cite{ARRS99},
up to a rescaling by the front velocity $v_{max}$.
% It is useful to introduce the ray variable $\zeta = \frac{n}{v_{max}t}$, such that
The expression of the current in \eqref{rhoj} depends on the parity of $n$, and the
respective matrix element is contained in $\mathbf{C}_{n,n}(t)$ or $\mathbf{C}_{n,n+1}(t)$
for odd or even $n$. The corresponding off-diagonal entries in the integrand of \eqref{ctdw2} read
%
\eq{
\sin \varphi_q = (1-\delta)\frac{\sin q \cos q}{\omega_q} =
\frac{v_q}{1+\delta} \, , \qquad
\sin (2q-\varphi_q) = (1+\delta)\frac{\sin q \cos q}{\omega_q} =
\frac{v_q}{1-\delta} \, .
\label{sphiq}}
%
These factors have to be multiplied by the respective hopping amplitudes $2t_n = 1\pm \delta$,
and one thus obtains for the current
%
\eq{
J(n,t) = \int_{q_-}^{q_+} \frac{\dd q}{\pi} \, v_q= %\omega_{q_-}- \omega_{q_+}=
\frac{v_{max}}{\pi}\sqrt{1-\left(\frac{n}{v_{max}t}\right)^2}.
\label{curr}}
%

Hence, despite the lack of translational invariance of the time-evolution operator,
both the density and the current becomes a smooth function of the position, without any parity
dependence. In fact, it is easy to check that the continuity equation is satisfied
%
\eq{
\partial_t \rho(n,t) + \partial_n J(n,t) =0 \, .
}
%
The hydrodynamic limit results \eqref{dens} and \eqref{curr} are compared
to numerical calculations on a finite-size open chain with $N=300$ in Fig.~\ref{fig:denscurr}, finding an excellent
agreement.

