A_j & =-\sqrt{5(2 j+1)} A_0, \\
\Gamma_{j j^{\prime}} & =\sqrt{5} \gamma_{j j^{\prime}} \Gamma_0, \\
\Lambda_{j j^{\prime}}^{ j^{\prime \prime}} & =-2 \sqrt{\frac{5}{2 j^{\prime \prime}+1}} \beta_{j j^{\prime \prime}} \beta_{j^{\prime} j^{\prime \prime}} \Lambda_0,
