 \begin{definition} 
A continuous map   $q \colon S^1 \to \C$   is called a {\it generalized solution} of \eqref{eq:twistedODEforq} if it satisfies the following conditions:
\begin{enumerate}
    \item the collision set $\mathfrak{C}_q = \{ t \in S^1 \mid q(t) \in \{E, M \}\}$ is finite;

    \item  on the complement $S^1 \setminus \mathfrak{C}_q$ the map $q$ is smooth and satisfies \eqref{eq:twistedODEforq};  

    \item  the energy 
    \[
     \frac{1}{2}\lvert \dot{q}(t)\rvert ^2 -\frac{ 1-\mu }{\lvert q(t)-E\rvert}-\frac{\mu}{\lvert q(t)-M\rvert} + \int_t^1 \dot{E}_s(q(s))ds + E_t(q(t)),  
    \]
    defined on $ S^1 \setminus \mathfrak{C}_q,$
    extends to a continuous function on the whole circle. 
\end{enumerate}

\end{definition}
\noindent
Note that the energy is constant along every generalized solution.




