\section{Birkhoff transformation}\label{sec:Birkhoff}



 We now normalize the positions of the two primaries by setting $E=-1$ and $M=+1 $ and denote  by 
\begin{equation}\label{eq:Birkhoffmap}
B \colon \C\setminus \{ 0\} \to \C, \quad B(z) = \frac{1}{2}\left( z + \frac{1}{z}\right)
\end{equation}
the Birkhoff regularization map.


%\begin{equation}\label{eq:Birkhoffeachcoordinate}
%q_1 = \frac{1}{2}\left( x + \frac{x}{x^2+y^2}\right), \quad \quad q_2 = \frac{1}{2}\left( y- \frac{y}{x^2+y^2}\right)
%\end{equation}









Let $z \colon S^1 \to \C$ be a continuous map, and define its collision set by
\[
\mathfrak{C}_z:=\{ \tau \in S^1 \mid z(\tau) = \pm 1 \}.
\]
Assume that this set is finite and that the following integral is well-defined:
\begin{equation*}\label{eq:hatz}
\hat{z}:= \int_0^1  w(z(\tau)) d\tau <\infty,
\end{equation*}
where
\begin{equation}\label{eq:w}
w(z) = \frac{\lvert z - 1\rvert^2\lvert z +1\rvert^2} {4 \rvert z \rvert^2}  
\end{equation}
Note that $w$ is invariant under the inversion $z \mapsto \frac{1}{z}.$

 We introduce a reparametrization map $t_z \colon S^1 \to S^1,$ defined by 
\begin{equation}\label{eq:timerepart_z}
t_z(\tau):= \frac{1}{\hat z} \int_0^\tau  w(z(s))ds  .
\end{equation}
 Its derivative is given by
\begin{equation*}\label{eq:derivativeoftz}
t_z'(\tau) = \frac{w(z(\tau))}{\hat{z}}%\frac{|z(\tau)-E|^2|z(\tau)-M|^2}{4\lvert z \rvert^4}
\end{equation*}
so that the set of   critical point of $t_z$ coincides with the collision set:
\[
{\rm crit} (t_z)=\mathfrak{C}_z.
\]
Finiteness of   $\mathfrak{C}_z$  ensures that   the map $t_z$ is a strictly increasing continuous function with finitely many critical points, and thus defines  a  homeomorphism of $S^1.$ In particular, there exists a continuous inverse
\[
\tau_z:=t_z^{-1} \colon S^1 \to S^1
\]
which is smoothly differentiable on the complement $S^1 \setminus t_z(\mathfrak{C}_z),$ with derivative
\begin{equation*}\label{eq:derivativeoftau}
    \dot{\tau}_z(t) = \frac{\hat{z}}{w(z_{\tau}(\tau_z(t)))}
\end{equation*}
Using this, we define a continuous map  
\begin{equation}\label{eq:qz}
q_z \colon S^1 \to \C, \quad q_z(t):= B(z(\tau_z(t))) = \frac{1}{2}\left( z(\tau_z(t)) + \frac{1}{z(\tau_z(t))} \right),
\end{equation}
where $B$ denotes the Birkhoff map, see \eqref{eq:Birkhoffmap}. 
Since   $B$ is a $2$-to-$1$ covering branched at $\pm1,$ the collision set of $q$
\[
   \mathfrak{C}_q  := \{ t \in S^1 \mid q(t) = \pm 1 \} 
   \]
     satisfies the relation 
\[
\mathfrak{C}_z = \tau_z (\mathfrak{C}_q) \quad {\rm or\;\;equivalently\;\;}\;\mathfrak{C}_q = t_z(\mathfrak{C}_z).
\]
In particular, the  collision sets $\mathfrak{C}_z$ and $\mathfrak{C}_q$ are in one-to-one correspondence under the homeomorphisms $\tau_z$  and   $t_z$.





