\section{Birkhoff type BOV-regularization}
We study Birkhoff type BOV-regularization of the  time-dependent planar  two-center Stark-Zeeman systems, described by the Newtonian equation
 \begin{equation}\label{eq:twistedODEforSZ}
\ddot{q}   = -\mathfrak{B}(q) i \dot{q} - \frac{(1-\mu) (q+1)}{\lvert q+1\rvert^3 } - \frac{\mu(q-1)}{\lvert q - 1 \rvert^3} - \nabla E_t(q).
\end{equation}
As explained in the introduction, periodic solutions that avoid collisions with $\pm1 $ are critical points of the action functional $\mathscr{A}\colon \mathfrak{L}\mathfrak{D} \to \R$ defined by
 \[  \mathscr{A}(q)  =   \frac{1}{2}\|\dot{q} \|^2  - \int_{S^1} q^*A      + \int_0^1 \frac{ 1-\mu }{\lvert q(t)+1\rvert}  dt + \int_0^1  \frac{\mu}{\lvert q(t) - 1\rvert} dt   - \int_0^1  E_t(q(t))  dt
 \]




Let $\mathfrak{Z}_0:=B^{-1}(\mathfrak{D}_0)$ denote the open subset of $\C$ containing  $ \pm1 ,$   which is the preimage of $\mathfrak{D}_0$ under the Birkhoff map $B.$ Note that $\mathfrak{Z} = \mathfrak{Z}_0\setminus \{ \pm 1 \} = B^{-1}(\mathfrak{D}).$
Since every $z \in \mathfrak{L}\mathfrak{Z}$ does neither hit $+1$  nor $-1,$   the map $t_z$ defined in \eqref{eq:timerepart_z} (and hence  its inverse $\tau_z$) is a diffeomorphism of the circle. %and we denote by
%$$\tau_z=t_z^{-1} \colon S^1 \to S^1$$
%its inverse. 
We define
\begin{equation}\label{eq:SIGMA}
\Sigma \colon \mathfrak{L}\mathfrak{Z} \to \mathfrak{L}\mathfrak{D}, \quad \Sigma(z):=   q_z,
\end{equation}
where $q=q_z$ is given as in \eqref{eq:qz}.  
We compute
\begin{equation}\label{eq:dotqandz}
\dot{q}(t) = \frac{1}{2}\left( 1 - \frac{1}{z(\tau)^2}\right)  \frac{\hat{z}}{w(z(\tau ))} z'(\tau)
\end{equation}
and
\begin{align*}
\ddot{q}(t) &=  \Bigg[  \frac{z''(\tau)}{2} \frac{z(\tau)^2-1}{z(\tau)^2}  +   \frac{z'(\tau)^2}{z(\tau)^3}   - \frac{ z'(\tau)  }{2}\frac{z(\tau)^2-1}{z(\tau)^2}      \frac{\frac{dw}{dz} z'(\tau) + \frac{dw}{d\bar{z}}\bar{z}'(\tau) }{w(z(\tau))}      \Bigg]\frac{\hat{z}^2}{w(z(\tau))^2} \\
&=   \Bigg[  \frac{z(\tau)^2-1}{z(\tau)^2}  z''(\tau)  +   \frac{1-z(\tau)^2}{ z(\tau)^3} z'(\tau)^2 - \frac{ (z(\tau)^2-1)(\bar{z}(\tau)^2+1)}{ z(\tau)\lvert z(\tau)\rvert^2 (\bar{z}(\tau)^2-1) }\lvert z'(\tau)\rvert^2\Bigg]\frac{\hat{z}^2}{2w(z(\tau))^2}\end{align*}
where $\tau = \tau_z(t).$



We  now pull back the functional $\mathscr{A}$ via the map $\Sigma$: 
\begin{align*}
 \label{eq:regularizedfunctionalSZ}   \Sigma^*\mathscr{A}(z) &= \frac{\hat{z}}{2}\int_0^1 \frac{ \lvert z'(\tau)\rvert^2}{\lvert z(\tau)\rvert^2}d\tau - \int_{S^1} z^*{B}^*A +\frac{1-\mu}{2\hat{z}} \int_0^1 \frac{\lvert z(\tau)-1\rvert^2}{\lvert z(\tau)\rvert}d\tau \\
\nonumber    &\;\;\;\;+\frac{\mu}{2\hat{z}} \int_0^1\frac{\lvert z(\tau)+1\rvert^2}{\lvert z(\tau)\rvert}d\tau - \frac{1}{\hat{z}} \int_0^1 E_{t_{z}(\tau)} (B(z(\tau))) \frac{\lvert z(\tau)-1\rvert^2\lvert z(\tau)+1\rvert^2}{4\lvert z(\tau)\rvert^2}d\tau
\end{align*}
This expression naturally extends to a  functional $\mathscr{B} \colon \mathfrak{L}^*\mathfrak{Z}_0  \to \R,$ defined on the extended domain 
\begin{equation*}\label{eq:LstarZ0}
\mathfrak{L}^*\mathfrak{Z}_0:=\{ z \in \mathfrak{L}\mathfrak{Z}_0 \mid \hat{z}\neq 0\}.
\end{equation*}
via the same formula.
To streamline notation, we introduce the functionals
\begin{align*}
\nonumber \mathcal{F}(z) &= \hat{z} = \int_0^1   w(z(\tau))  d\tau, \quad  \quad \quad \mathcal{G}(z) = \frac{1}{2} \int_0^1 \frac{\lvert z'(\tau)\rvert^2}{\lvert z(\tau)\rvert^2}d\tau \\
\label{eq:functionalsEuler} \mathcal{H}_1(z)  &=  \frac{1}{2} \int_0^1   \frac{\lvert z(\tau)-1\rvert^2}{\lvert z(\tau) \rvert}  d\tau ,       \quad  \quad  \quad \mathcal{H}_2(z) =\frac{1}{2} \int_0^1   \frac{\lvert z(\tau)+1\rvert^2}{\lvert z(\tau) \rvert}  d\tau \\
\nonumber \mathcal{M}(z)&= \int_{S^1}z^*B^*A, \quad     \quad \mathcal{E}(z)= \frac{1}{\hat{z}}  \int_0^1 E_{t_{z}(\tau)} (B(z(\tau))) \frac{\lvert z(\tau)-1\rvert^2\lvert z(\tau)+1\rvert^2}{4\lvert z(\tau)\rvert^2}d\tau
\end{align*}
so that
\[ 
\mathscr{B}(z) =   \mathcal{F}(z)\mathcal{G}(z) +\frac{(1-\mu)\mathcal{H}_1(z)+\mu \mathcal{H}_2(z)}{ \mathcal{F}(z)}- \mathcal{M}(z) - \mathcal{E}(z).
\]





We compute the  differentials of the above functionals individually. Choose $z \in \mathfrak{L}^*\mathfrak{Z}_0$ and $\xi \in T_z \mathfrak{L}^*\mathfrak{Z}_0= \mathfrak{L}\C.$
We compute that
\begin{align}
\nonumber d\mathcal{F}(z)\xi &= \int_0^1   \left< \frac{(z-1)\lvert z+1\rvert^2  +(z+1)\lvert z-1\rvert^2}{{2\lvert z \rvert^2} } - \frac{z\lvert z-1\rvert^2 \lvert z+1\rvert^2 }{2\lvert z\rvert^4}  , \xi \right> d\tau \\
\label{eq:differentaildF} &= \int_0^1   \left< \frac{ z(z^2-1)(\bar{z}^2+1) }{2\lvert z\rvert^4}  , \xi \right> d\tau
\end{align}
and further that
\begin{align*}
    d\mathcal{G}(z)\xi &= \int_0^1 \left< \frac{z'}{\lvert z\rvert^2}, \xi'\right> d\tau - \int_0^1 \left< \frac{\lvert z'\rvert^2}{\lvert z\rvert^4}z, \xi \right>d\tau \\
    &= - \int_0^1 \left< \frac{d}{d\tau} \frac{z'}{\lvert z\rvert^2}, \xi \right> d\tau - \int_0^1 \left< \frac{\lvert z'\rvert^2}{\lvert z\rvert^4}z, \xi \right>d\tau \\
        &=  \int_0^1 \left< -  \frac{z''}{\lvert z\rvert^2} + \frac{\bar{z}(z')^2}{\lvert z \rvert^4}, \xi \right> d\tau 
\end{align*}
Moreover, we compute
\begin{align*}
    d\mathcal{H}_1(z)\xi &= \int_0^1 \left< \frac{z-1}{\lvert z\rvert} - \frac{ z\lvert z-1\rvert^2}{2\lvert z \rvert^3} , \xi \right> d\tau=\int_0^1 \left<   \frac{z(z-1)(\bar{z}+1)}{2\lvert z \rvert^3} , \xi \right> d\tau\\
        d\mathcal{H}_2(z)\xi &= \int_0^1 \left< \frac{z+1}{\lvert z\rvert} - \frac{ z\lvert z+1\rvert^2}{2\lvert z \rvert^3} , \xi \right> d\tau =\int_0^1 \left<   \frac{z(z+1)(\bar{z}-1)}{2\lvert z \rvert^3} , \xi \right> d\tau
\end{align*}
 Since the magnetic two-form $\sigma_{\mathfrak{B}}$ pulls back under the Birkhoff map $B$ to 
 \[
 B^* \sigma_{\mathfrak{B}} (z) =  \frac{ \lvert z-1\rvert^2 \lvert z+1\rvert^2}{4\lvert z\rvert^4} \mathfrak{B}( B(z))  dx \wedge dy, \quad \quad z=(x,y),
 \]
the differential of the magnetic part $\mathcal{M}(z)$ is computed as:
\begin{align*}
 d\mathfrak{M}(z)\xi &= \int_0^1 \mathcal{L}_{\xi}( B^*A)(z'(\tau))d\tau\\ 
&= \int_{0}^1B^*\sigma_{\mathfrak{B}}(z(\tau))(\xi(\tau), z'(\tau))d\tau                   \\
%&= \int_0^1 B^* \sigma_{\mathfrak{B}}(z(\tau))( z'(\tau), \xi(\tau)) d\tau              \\
 &=   \left<    \frac{\lvert z-1\rvert^2 \lvert z+1\rvert^2}{4\lvert z\rvert^4} \mathfrak{B} (B(z )) i z' , \xi\right>
\end{align*}
To compute the differential of the electric part $\mathcal{E},$ define $\mathcal{N}(z) := \hat{z}\mathcal{E}(z).$ Using the identity \eqref{eq:differentaildF} we compute:
\begin{align*}
     d\mathcal{N}(z)\xi &= \int_0^1 \dot{E}_{t_z(\tau)}(B(z(\tau)))dt_z(\xi)(\tau) w(z(\tau)) d\tau \\
     &\;\;\;\;+ \int_0^1 \left< \nabla E_{t_z(\tau)}(B(z(\tau))), dB(z(\tau))\xi(\tau)\right>w(z(\tau))d\tau \\
     &\;\;\;\;+ \int_0^1E_{t_z(\tau)}(B(z(\tau)))\left<   \frac{ z(\tau)(z(\tau)^2-1)(\bar{z}(\tau)^2+1) }{2\lvert z(\tau)\rvert^4}  , \xi(\tau) \right> d\tau\\
&= \int_0^1 \dot{E}_{t_z(\tau)}(B(z(\tau)))dt_z(\xi)(\tau) w(z(\tau)) d\tau \\
     &\;\;\;\;+ \int_0^1 \left< \nabla E_{t_z(\tau)}(B(z(\tau))), dB(z(\tau))\xi(\tau)\right>w(z(\tau))d\tau \\
     &\;\;\;\;+ \int_0^1E_{t_z(\tau)}(B(z(\tau)))\left<   \frac{ z(\tau)(z(\tau)^2-1)(\bar{z}(\tau)^2+1) }{2\lvert z(\tau)\rvert^4}  , \xi(\tau) \right> d\tau\\
&= \frac{1}{\hat{z}}\int_0^1 \dot{E}_{t_z(\tau)}(B(z(\tau)))  \left( \int_0^\tau  \left<   \frac{ z(s)(z(s)^2-1)(\bar{z}(s)^2+1) }{2\lvert z(s)\rvert^4}    , \xi(s) \right>  ds  \right) w(z(\tau)) d\tau \\
&\;\;\;\;- \frac{1}{\hat{z}^2}\left<   \frac{ z (z ^2-1)(\bar{z} ^2+1) }{2\lvert z \rvert^4}   , \xi \right> \int_0^1 \dot{E}_{t_z(\tau)}(B(z(\tau))) \left(   \int_0^\tau w(z(s))ds         \right) w(z(\tau)) d\tau \\
     &\;\;\;\;+ \int_0^1 \left< \nabla E_{t_z(\tau)}(B(z(\tau)))  \overline{dB(z(\tau))},\xi(\tau)\right>w(z(\tau))d\tau \\
     &\;\;\;\;+ \int_0^1E_{t_z(\tau)}(B(z(\tau)))\left<   \frac{ z(\tau)(z(\tau)^2-1)(\bar{z}(\tau)^2+1) }{2\lvert z(\tau)\rvert^4}  , \xi(\tau) \right> d\tau
     \end{align*}
Therefore, if we introduce
\begin{align*}
\mathcal{E}^1(z) &=   \frac{1}{\hat{z}^2} \int_0^1 \dot{E}_{t_z(\tau)}(B(z(\tau))) \left(   \int_0^\tau w(z(s))ds         \right) w(z(\tau)) d\tau   \\
\varepsilon_1(z)(\tau)&=   \frac{1}{\hat{z}} \left( \int_\tau^1 \dot{E}_{t_z(s)}(B(z(s)) w(z(s))ds \right) \frac{ z(\tau)(z(\tau)^2-1)(\bar{z}(\tau)^2+1) }{2\lvert z(\tau)\rvert^4}     \\
\varepsilon_2(z)(\tau)&=  \nabla E_{t_z(\tau)}(B(z(\tau))) \frac{1}{2}\left( 1 - \frac{1}{\bar{z}(\tau)^2}\right) w(z(\tau))    \\
\varepsilon_3(z)(\tau)&= E_{t_z(\tau)}(B(z(\tau)))    \frac{ z(\tau)(z(\tau)^2-1)(\bar{z}(\tau)^2+1) }{2\lvert z(\tau)\rvert^4}   
\end{align*}
then the differential of $\mathcal{E}$ becomes
\begin{align*}
    d\mathcal{E}(z)\xi  &= \frac{1}{\hat{z}}d\mathcal{N}(z)\xi - \frac{\mathcal{E}(z)}{\hat{z}}d\mathcal{F}(z)\xi \\
    &=  - \frac{ \mathcal{E}(z) + \mathcal{E}^1(z)}{\hat{z}}\left<   \frac{ z (z ^2-1)(\bar{z} ^2+1) }{2\lvert z \rvert^4}   , \xi \right> + \frac{1}{\hat{z}}\left< \varepsilon_1(z)+\varepsilon_2(z)+\varepsilon_3(z), \xi\right>.
\end{align*}

We have thus proven:

\begin{proposition}
  A point $z \in \mathfrak{L}^*\mathfrak{Z}_0$ is a critical point of the regularized functional $\mathscr{B}$ if and only if it is a solution of the following second-order delay differential equation
\begin{align}
 \nonumber   z''(\tau) &= \frac{1}{2\hat{z}^2}\frac{ z(\tau)(z(\tau)^2-1)(\bar{z}(\tau)^2+1) }{\lvert z(\tau)\rvert^2}C  + \frac{\bar{z}(\tau)}{\lvert z(\tau)\rvert^2}z'(\tau)^2\\
 \label{eq:delayequationgeneral}  &\;\;\;\;+ \frac{1}{2\hat{z}^2}\Bigg[ (1-\mu) \frac{z(z-1)(\bar{z}+1)}{  \lvert z \rvert } + \mu   \frac{z(z+1)(\bar{z}-1)}{ \lvert z \rvert }      \Bigg]  \\
 \nonumber    &\;\;\;\; - \frac{w(z(\tau))}{\hat{z}} \mathfrak{B}(B(z(\tau)))iz'(\tau)   - \frac{\lvert z(\tau)\rvert^2}{\hat{z}^2}( \varepsilon_1(z)(\tau)+\varepsilon_2(z)(\tau)+\varepsilon_3(z)(\tau)),
\end{align}
where the constant $C$ is given by
\begin{equation*}\label{eq:constantKgeneral}
C =    \frac{\hat{z}}{2}   \int_0^1 \frac{\lvert z'(\tau)\rvert^2}{\lvert z(\tau)\rvert^2}d\tau    - \frac{1-\mu}{2\hat{z}} \int_0^1   \frac{\lvert z(\tau)-1\rvert^2}{\lvert z(\tau) \rvert}  d\tau  - \frac{\mu}{2\hat{z}} \int_0^1   \frac{\lvert z(\tau)+1\rvert^2}{\lvert z(\tau) \rvert}  d\tau  + \mathcal{E}(z) +\mathcal{E}^1(z)
\end{equation*}
\end{proposition}



To investigate the correspondence between periodic solutions of the Newtonian equation \eqref{eq:twistedODEforSZ} and the delay equation \eqref{eq:delayequationgeneral}, we first extend the definition of the map $t_z,$ originally defined in \eqref{eq:timerepart_z} for $z \in \mathfrak{L}\mathfrak{Z},$ to those $z \in \mathfrak{L}^*\mathfrak{Z}_0$ which are critical points of the regularized functional $\mathscr{B}.$






Assume that $z\in \mathfrak{L}^*\mathfrak{Z}_0$   is a  solution to the delay equation \eqref{eq:delayequationgeneral}. We define $t_z \colon S^1 \to S^1$ exactly by the same formula as in  \eqref{eq:timerepart_z}:
\[
t_z(\tau):=\frac{1}{\hat{z}}\int_0^{\tau}w(z(s))ds.
\]
As before, the collision set is given by
\[
\mathfrak{C}_z = \{ \tau \in S^1 \mid z(\tau) = \pm 1 \} = {\rm crit}(t_z).
\]

\begin{lemma}\label{lem:finitecollisionset}
    The collision set $\mathfrak{C}_z$ is finite.
\end{lemma}
\begin{proof}
The right-hand side of \eqref{eq:delayequationgeneral} can be written in the form 
\[
z''(\tau) = a(z,\tau)z(\tau) + b(z,\tau)\bar{z}(\tau) +c(z,\tau)z'(\tau) 
\]
for continuous functions  $a,b,$ and $c,$ where $a(z,\tau)=b(z,\tau)=0$ whenever $\tau \in \mathfrak{C}_z.$  Assume that $z'(\tau_*)=0$ for some $\tau_* \in \mathfrak{C}_z.$ Then all terms on the right-hand side vanish at $\tau_*,$ implying $z''(\tau_*)=0.$
By the uniqueness theorem of ODE, this would force $ z\equiv  0,$  contradicting the assumption that  $z \in \mathfrak{L}^*\mathfrak{Z}_0.$ Therefore,  $z'(\tau )\neq0$ for every $\tau  \in \mathfrak{C}_z,$ from which we see that the collision set $\mathfrak{C}_z$ is a discrete subset of $S^1,$ and hence finite. 
This completes the proof.
\end{proof}


The previous lemma tells us that the map $t_z$ is a strictly increasing and continuous function having only finitely many critical points. Hence, $t_z$ is a homeomorphism of $S^1,$ and so is its continuous inverse    $\tau_z := t_z^{-1} \colon S^1 \to S^1.$  We then define 
\[
q = q_z \colon S^1 \to \mathfrak{D}_0
\]
as before. Namely, given a critical point $z \in \mathcal{L}^*\mathfrak{Z}_0$ of $\mathscr{B},$ we define
\begin{equation*}\label{eq:qgeneralcase}
q(t) = B(z(\tau_z(t))),
\end{equation*}
which is continuous on the whole circle and smoothly differentiable on the complement of the collision set $\mathfrak{C}_q = t_z(\mathfrak{C}_z).$











Suppose that $z \in \mathfrak{L}^*\mathfrak{Z}_0$ is a solution of the delay equation \eqref{eq:delayequationgeneral} and let $q\colon S^1 \to \mathfrak{D}_0$ be the corresponding map as above.   If  $\mathfrak{C}_z$ is empty, then the map $q$ is smooth and directly satisfies the Newtonian equation   \eqref{eq:twistedODEforSZ} avoiding collisions with $\pm 1. $


We now consider the case $\#\mathfrak{C}_q  = N >0. $ Our goal is to show that $q$ is a generalized periodic   solution of  \eqref{eq:twistedODEforSZ}.
To this end, we decompose the complement $S^1 \setminus \mathfrak{C}_z$ into $N$ open intervals:
\[
S^1 \setminus \mathfrak{C}_z = \bigcup_{j=1}^N \mathcal{I}_j,
\]
where each component is of the form $\mathcal{I}_j:= (\tau_j^-, \tau_j^+),$ and we adopt the cyclic convention 
\[
\tau_j^+ = \tau_{j+1}^-, \;j= 1,2,\ldots, n-1 \quad \quad \text{ and } \quad \quad \tau_n^+ = \tau_1^-.
\]
Let
\[
t_j^\pm :=t_z(\tau_j^\pm), \;\;\; j = 1,\ldots, N
\]
denote the corresponding zeros of the map $q $ and define
\[
\mathcal{J}_j := t_z(\mathcal{I}_j) = (t_j^-, t_j^+) \subset S^1 \setminus \mathfrak{C}_q. 
\]





We define
\[
\mathcal{C}(q) := \int_0^1  E_t(q(t))  dt
\]
so that
\[
\mathcal{E}(z) = \mathcal{C}(q).
\]
We also compute,  by the change of variable $\tau=\tau_z(t)$, that
\begin{align*}
\mathcal{E}^1(z) &=    \int_0^1 \dot{E}_{t_z(\tau)}(B(z(\tau))) \left(   \int_0^\tau \frac{w(z(s))}{\hat{z}}ds         \right) \frac{w(z(\tau))}{\hat{z}} d\tau   \\
&= \int_0^1 \dot{E}_t (q(t)) \left( \int_0^t ds \right) dt\\
&= \int_0^1 t \dot{E}_t (q(t)) dt\\
&=: \mathcal{C}^1(q).
\end{align*}
Moreover, using  \eqref{eq:dotqandz} we find
\[
\frac{z(\tau)^2-1}{2z(\tau)^2}\frac{\hat{z}}{w(z(\tau))}\mathfrak{B}(B(z(\tau))) i z'(\tau) = \mathfrak{B}(q(t))i \dot{q}(t) .
\]
\begin{comment}
For the vector fields $\varepsilon_j, j=1,2,3,$ we find
\begin{align*}
\frac{z(\tau)^2-1}{2z(\tau)^2}\frac{\lvert z(\tau)\rvert^2}{w(z(\tau))^2}\varepsilon_1(z)(\tau_z(t)) &=         \frac{4\bar{z}(\tau)(\bar{z}(\tau)^2+1)}{(\bar{z}(\tau)^2-1)^2}   \int_\tau^1 \dot{E}_{t_z(s)}(B(z(s)) \frac{w(z(s))}{\hat{z}}ds       \\
&= \frac{2\bar{q}(t)}{ (\bar{q}(t)^2-1)} \int_t^1 \dot{E}_s (q(s))ds\\
\frac{z(\tau)^2-1}{2z(\tau)^2}\frac{\lvert z(\tau)\rvert^2}{w(z(\tau))^2}\varepsilon_2(z)(\tau_z(t)) &=     \nabla E_{t}(q(t))       \\
\frac{z(\tau)^2-1}{2z(\tau)^2}\frac{\lvert z(\tau)\rvert^2}{w(z(\tau))^2}\varepsilon_3(z)(\tau_z(t)) &=  \frac{4\bar{z}(\tau) (\bar{z}(\tau)^2+1)}{ (\bar{z}(\tau)^2-1)^2}E_{t_z(\tau)}(B(z(\tau)))             \\  
&= \frac{2\bar{q}(t)}{(\bar{q}(t)^2-1)}E_t (q(t))
\end{align*}
\end{comment}
Using the expressions for $\dot{q}(t)$ and  $\ddot{q}(t)$ derived above    and substituting the delay equation \eqref{eq:delayequationgeneral},    we   find on each interval $\mathcal{J}_j$ that 
 \begin{align*}
\nonumber \ddot{q}(t) &= \frac{4 \bar{z}(\tau) (\bar{z}(\tau)^2+1)}{ ( \bar{z}(\tau)^2-1)^2}C        - \frac{2 \bar{z}(\tau) (\bar{z}(\tau)^2+1)}{( \bar{z}(\tau)^2-1)^2}\lvert \dot{q}(t)\rvert ^2 + \frac{4(1-\mu) \lvert z(\tau)\rvert \bar{z}(\tau)}{  (\bar{z}(\tau)-1)^2\lvert z(\tau)+1\rvert^2  } \\
\nonumber & \;\;\;\; + \frac{4\mu  \lvert z(\tau)\rvert \bar{z}(\tau)}{ (\bar{z}(\tau) +1)^2 \lvert z(\tau)-1\rvert^2 }  - \frac{z(\tau)^2-1}{2z(\tau)^2} \frac{\hat{z}}{w(z(\tau))} \mathfrak{B}(B(z(\tau)))iz'(\tau)\\
\nonumber & \;\;\;\;- \frac{z(\tau)^2-1}{2z(\tau)^2}\frac{\lvert z(\tau)\rvert^2}{w(z(\tau))^2}( \varepsilon_1(z)(\tau)+\varepsilon_2(z)(\tau)+\varepsilon_3(z)(\tau)) \\
\nonumber &= \frac{2\bar{q}(t)}{\bar{q}(t)^2-1}\left(C - \frac{1}{2}\lvert \dot{q}(t)\rvert^2\right)    +  \frac{1-\mu}{(\bar{q}(t)-1)\lvert q(t)+1\rvert}+  \frac{ \mu}{(\bar{q}(t)+ 1)\lvert q(t)-1\rvert}\\
\nonumber &\;\;\;\;- \mathfrak{B}(q(t))i\dot{q}(t)-  \frac{2\bar{q}(t)}{ (\bar{q}(t)^2-1)} \int_t^1 \dot{E}_s (q(s))ds\\
  & \;\;\;\; -  \nabla E_{t}(q(t))  - \frac{2\bar{q}(t)}{(\bar{q}(t)^2-1)}E_t (q(t))
 \end{align*}
where the constant $C$  is
\[
C = \int_0^1 \left( \frac{1}{2}\lvert \dot{q}(t)\rvert^2 - \frac{1-\mu}{\lvert q(t)+1\rvert}-\frac{\mu}{\lvert q(t)-1\rvert} \right)dt +\mathcal{C}(q) +\mathcal{C}^1(q).
\]
This can be rearranged as
\begin{align}\label{eq:fromztoqequationgeneral}
  \ddot{q}(t) +\mathfrak{B}(q(t)) i \dot{q}(t) +\nabla E_t(q(t))= \frac{2\bar{q}(t)}{\bar{q}(t)^2-1}\Phi(t) - \nabla U(q(t)),
\end{align}
where  
\[
U(q) = -\frac{1-\mu}{\lvert q+1\rvert}-\frac{\mu}{\lvert q-1\rvert}
\]
and
\begin{equation}\label{eq:Phigeneral}
  \Phi(t):=  C - \frac{1}{2}\lvert \dot{q}(t)\rvert^2 -U(q(t))-  \int_t^1 \dot{E}_s (q(s))ds- E_t (q(t)).
\end{equation}









\begin{lemma}\label{lem:generalfirstintegral}
The   expression 
    \[
\frac{1}{2}\lvert \dot{q}(t)\rvert^2+ U(q(t))+  \int_t^1 \dot{E}_s (q(s))ds+ E_t (q(t)) 
\]
    is conserved along solutions of \eqref{eq:fromztoqequationgeneral}, that is $\Phi \equiv 0.$
\end{lemma}
 \begin{proof}  
We first notice that, by definition of  $C, $ the mean value of $\Phi$ over $S^1$ is zero:
\begin{equation}\label{eq:meanvalueofPhi}
    \int_0^1\Phi(t)dt =0.
\end{equation}
Differentiating  \eqref{eq:Phigeneral} with respect to $t$, we   obtain  
\begin{align*}
\dot{\Phi}(t) &= - \left< \dot{q}(t), \ddot{q}(t)\right> - \left< \dot{q}(t), \nabla U(q(t))\right> +\dot{E}_t(q(t))-\dot{E}_t(q(t)) - \left< \nabla E_t(q(t)), \dot{q}(t)\right>\\
&= \left<  \dot{q}(t) , \mathfrak{B}(q(t)) i \dot{q}(t) +\nabla E_t(q(t))    \right>- \left< \dot{q}(t) , \frac{2\bar{q}(t)}{\bar{q}(t)^2-1}\Phi(t)-\nabla U(q(t))  \right>  \\
&\;\;\;\;\;- \left< \dot{q}(t), \nabla U(q(t))\right> - \left< \nabla E_t(q(t)), \dot{q}(t)\right>\\
&= g(t) \Phi(t), 
\end{align*}
where we define
\[
g(t):=- \left< \dot{q}(t) , \frac{2\bar{q}(t)}{\bar{q}(t)^2-1}\right>. 
\]
Thus, $\Phi(t)$ satisfies the ODE
\begin{equation*}\label{eq:ODEphit}
%\begin{aligned}
%\begin{cases} 
\dot{\Phi}(t) = g(t)\Phi(t). %, \;\;\; t \in S^1 \setminus \mathfrak{C}_q, \\
%\Phi(t_*)=0. \end{cases}
%\end{aligned}
\end{equation*}
We now write this ODE  in terms of $z$ and $\tau=\tau_z(t)$:
\begin{equation*}\label{eq:ODEphitau}
%\begin{aligned}
%\begin{cases}  
{\Phi}'(\tau) = f(\tau)\Phi(\tau),
%, \;\;\; \tau \in S^1 \setminus \mathfrak{C}_z, \\
%\Phi(\tau_*)=0, \end{cases}
%\end{aligned}
\end{equation*}
where  
\begin{align*}
    f(\tau)  := & \; g(t_z(\tau)) \frac{dt}{d\tau}\\
    =& \;   - \left< \dot{q}(t) , \frac{2\bar{q}(t)}{\bar{q}(t)^2-1} \right>   \frac{dt}{d\tau}    \\
    =& \;   - \left<  \frac{1}{2}\left( 1 - \frac{1}{z(\tau)^2}\right)  \frac{\hat{z}}{w(z(\tau ))} z'(\tau) , \frac{4 \bar{z}(\tau) (\bar{z}(\tau)^2+1)}{ ( \bar{z}(\tau)^2-1)^2}\right> \frac{w(z(\tau))}{\hat{z}}     \\
    =& \;   -{\rm Re}\Bigg[    \frac{2(z(\tau)^2+1)}{z(\tau)(z(\tau)^2-1)} z'(\tau)     \Bigg]    \\
    =& \;   {\rm Re}\Bigg[ \left(   \frac{2}{z(\tau)}-\frac{2}{z(\tau)-1}-\frac{2}{z(\tau)+1}     \right)z'(\tau)   \Bigg ]   
\end{align*}
% and $\tau_* =\tau_z(t_*)\in S^1 \setminus \mathfrak{C}_z.$ 
Choose any $\tau_0 \in \mathcal{I}_j$  and solve  the above ODE in $\mathcal{I}_j$: 
 \begin{align*}
     \Phi(\tau)&= \Phi(\tau_0) \exp \left( \int_{\tau_0}^{\tau} f(s) ds\right) \\
     &= \Phi(\tau_0) \exp \left({\rm Re} \int_{\tau_0}^{\tau}   \left(   \frac{2}{z(s)}-\frac{2}{z(s)-1}-\frac{2}{z(s)+1}     \right)z'(s)   ds \right)\\
     &= \Phi(\tau_0) \exp \left( \log   \frac{\lvert z(\tau) \rvert^2 }{ \lvert z(\tau)^2-1 \rvert^2     } + \text{constant} \right) \\
     &=   \Phi(\tau_0)   \frac{\lvert z(\tau) (z(\tau_0)^2-1) \rvert^2 }{\lvert z(\tau_0)(z(\tau)^2-1) \rvert^2} , \quad \tau \in \mathcal{I}_j
 \end{align*}
with a suitable choice of branch for the logarithm. This shows that the function
\begin{align*}
\Psi(\tau):=& \; \Phi(\tau) \frac{\lvert z(\tau)^2-1\rvert^2}{\lvert z(\tau)\rvert^2} \\
=& \; \frac{\lvert z(\tau)^2-1\rvert^2}{\lvert z(\tau)\rvert^2} \Bigg[ C- \int_t^1\dot{E}_s( B(z(\tau_z(s)))    )ds - E_t( B(z(\tau_z(t))))\Bigg] \\
& \;\;- 2 \hat{z}^2 \lvert z'(\tau )\rvert^2 \lvert z(\tau)\rvert^2  +\frac{2(1-\mu)\lvert z(\tau) -1\rvert^2}{ \lvert z(\tau) \rvert } +\frac{2\mu \lvert z(\tau) +1\rvert^2}{\lvert z(\tau) \rvert } 
\end{align*}
is constant on each component $\mathcal{I}_j.$ Since $z \in \mathfrak{L}^*\mathfrak{Z}_0,$ the function $\Psi$ is continuous on the whole circle, and hence there exists a global constant $K \in \R$ such that
\[
\Psi(\tau) = K, \quad \quad \forall \tau \in S^1,
\]
so that
\[
\Phi(\tau) = \frac{\lvert z(\tau)\rvert^2}{\lvert z(\tau)^2-1\rvert^2}K, \quad \quad \tau \in S^1 \setminus \mathfrak{C}_z.
\]
This in particular implies that $\Phi$ does not change its sign and therefore has to vanish because of   \eqref{eq:meanvalueofPhi}.  This completes the proof. 
\end{proof}









 Lemma \ref{lem:generalfirstintegral} shows that   the second-order ODE
\eqref{eq:fromztoqequationgeneral} recovers the Newtonian equation \eqref{eq:twistedODEforq} of the time-dependent two-center Stark-Zeeman system, implying that critical points   of the regularized functional $\mathscr{B}$  correspond to  generalized periodic solutions of the time-dependent two-center Stark-Zeeman system. 



