 \medskip


In the remainder of this note, we study more closely the relationship between   the critical points of   $\mathscr{B}$ and generalized periodic solutions of \eqref{eq:twistedODEforq}, with particular attention to the underlying symmetry.  


Since the function $w(z)$ defined in \eqref{eq:w}  is invariant under the inversion $\C \to \C, \; z \mapsto 1/z,$ it follows immediately that  the regularized functional $\mathscr{B} \colon \mathfrak{L}^*\mathfrak{Z}_0 \to \R$   is invariant under the   involution
\[
I \colon \mathfrak{L}^*\mathfrak{Z}_0 \to \mathfrak{L}^*\mathfrak{Z}_0, \quad I(z)=\frac{1}{z},
\]
that is,  
\begin{equation}\label{eq:symmetry}
\mathscr{B} \circ I = \mathscr{B}.
\end{equation}
Therefore, for all $z \in \mathfrak{L}^*\mathfrak{Z}_0$ and $ \xi \in T_z \mathfrak{L}^*\mathfrak{Z}_0,$ we have
\[
d\mathscr{B}(I(z))dI(z)\xi = d\mathscr{B}(z)\xi, \quad \forall \xi \in T_z \mathfrak{L}^* \mathfrak{Z}_0, \; \forall z \in \mathfrak{L}^* \mathfrak{Z}_0,
\]
which shows that  if $z$ is a critical point of $\mathscr{B},$ then so is $I(z).$ See Figure \ref{fig:inversion_symmetry}. 
 \begin{figure}[!ht]
    \includegraphics[width=0.4\textwidth]{inversion.png}
    \caption{The red and blue periodic orbits are symmetric under the involution $I.$
    The dashed curve indicates the unit circle}
    \label{fig:inversion_symmetry}
\end{figure}
Consequently,  both critical points $z$ and $I(z)$  correspond to the same generalized periodic solution $q_z$ of    \eqref{eq:twistedODEforq}, namely, 
\[
\Sigma(z) = \Sigma(I(z)) = q_z,
\]
where  $\Sigma$ is the map defined   in \eqref{eq:SIGMA}.


Recall that if the total winding number $w(K)$ of a loop $K$ in $\C \setminus \{ E, M\}$--the sum of the winding numbers around the two primaries--is even, then its preimage $B^{-1}(K)$ under the Birkhoff map has two connected components; if odd, then $B^{-1}(K)$ is connected.  See \cite[Proposition 4.2]{CFZ23SZ}. %We now  study the relationship between the critical points of the regularized functional $\mathscr{B}$ and collisional periodic solutions of \eqref{eq:twistedODEforq} by decomposing the loop spaces according to   total winding number. 



%We now decompose the free loop spaces $\mathfrak{L}\mathfrak{D}$ and $\mathfrak{L}\mathfrak{Z}$ according to the total winding number. Recall that all orbits in these sets avoids collisions at $\pm1. $
For each   $n \in \Z,$ let    $\mathfrak{L}_n\mathfrak{D}  \subset \mathfrak{L}\mathfrak{D}  $   be the subset of loops  with   total winding number   equal to  $n.$ This yields the   decomposition
\[
\mathfrak{L}\mathfrak{D} = \bigsqcup_{n \in \Z} \mathfrak{L}_n\mathfrak{D}
\]
In a similar manner, we define the decomposition  
\[
\mathfrak{L}\mathfrak{Z} = \bigsqcup_{n \in \Z} \mathfrak{L}_n\mathfrak{Z}
\]
Note that $z$ and $I(z)$ share  the same total winding number. 
Since the Birkhoff map $B$ is a branched double cover with two branch points at $E$ and $M,$ it doubles the total winding number. More precisely, if $z \in \mathfrak{L}_n\mathfrak{Z} ,$ then and $q := B(z) \in \mathfrak{L}_{2n}\mathfrak{D}.$ Therefore, for each $n \in \Z$ the map $\Sigma$ induces a diffeomorphism
\[
\Sigma_n \colon \mathfrak{L}_n \mathfrak{Z} / I \to \mathfrak{L}_{2n}\mathfrak{D}
\]


To account for loops with odd winding number, note that if  $q \in \mathfrak{L}_{2n+1}\mathfrak{D}$, then $B^{-1}(q)$ is connected. Following \cite[Section 7]{Fra25SZ}, we introduce   the twisted loop space
\[
\mathfrak{L}_I\mathfrak{Z} := \{ z \in C^\infty(\R, \mathfrak{Z}) \mid z(t+1) = I \circ z(t), \; t \in \R \}.
\]
Note that every element of $\mathfrak{L}_I\mathfrak{Z}$ is not a loop in the usual sense, but   satisfies  a twisted periodicity: as time increases by $1,$ a point is mapped to its image  under the involution $I$.   Given a twisted loop $z \in \mathfrak{L}_I\mathfrak{Z},$ we recover a genuine loop $\tilde z \in \mathfrak{L}\mathfrak{Z}$ by
\[
 \tilde{z}(t):=z(2t), \quad t \in \R.
 \]
 Indeed, using the twisted periodicity we find
 \[
 \tilde{z}(t+1) = z(2t+2) = I \circ z ( 2t+1) = z(2t) = \tilde{z}(t) .
 \]
%Hence, we obtain the doubling map
%\[
%\Delta\colon \mathfrak{L}_-\mathfrak{Z} \to \mathfrak{L}\mathfrak{Z}, \quad z \mapsto \tilde{z}
%\]
Thus,  twisted loops correspond to loops with odd winding number. We define the  decomposition 
\[
\mathfrak{L}_I\mathfrak{Z} = \bigsqcup_{n \in \Z}\mathfrak{L}_{I, n+\frac{1}{2}}\mathfrak{Z},
\]
where
\[
\mathfrak{L}_{I, n+\frac{1}{2}} \mathfrak{Z} := \{ z \in \mathfrak{L}_I\mathfrak{Z} \mid \tilde{z} \in \mathfrak{L}_{2n+1}{\mathfrak{Z}}\}
\]
We now define the map 
\[
\Sigma_I \colon \mathfrak{L}_I\mathfrak{Z} \to \mathfrak{L}\mathfrak{D}, \quad \Sigma_I(z):= q_z , 
\]
where $q_z$ is defined as in \eqref{eq:qz}. Although $z$ is not a loop, but a twisted loop, the map $q_z$ is an actual loop:  
\begin{align*}
q_z(t+1) &= \frac{1}{2}\left( z(\tau_z(t+1)) + \frac{1}{z(\tau_z(t+1))}\right)\\
&= \frac{1}{2}\left( z(\tau_z(t)+1 ) + \frac{1}{z(\tau_z(t)+1 )}\right)\\
&= \frac{1}{2}\left( I \circ z(\tau_z(t)) + \frac{1}{ I \circ z(\tau_z(t))}\right)\\
&=\frac{1}{2}\left(   \frac{1}{z(\tau_z(t+1))} + z(\tau_z(t+1)) \right)\\
&= q_z(t)
\end{align*}
Hence, for each $n \in \Z,$ we have  a diffeomorphism
\[
\Sigma_{ I,n } \colon \mathfrak{L}_{{2n}+1} \mathfrak{Z} /I\to \mathfrak{L}_{2n+1}\mathfrak{D}.
\]

 Combining the even and odd cases,   we define the extended map
\[
 \Sigma_0:=\Sigma \oplus \Sigma_I \colon \mathfrak{L}\mathfrak{Z} \cup \mathfrak{L}_I \mathfrak{Z} \to \mathfrak{L}\mathfrak{D}
 \]
and   consider the  pullback  functional 
 \[
\Sigma_0^* \mathscr{A} \colon \mathfrak{L}\mathfrak{Z} \cup \mathfrak{L}_I \mathfrak{Z} \to \R.
 \]
Then we obtain a one-to-one correspondence between the critical points
  \begin{align*}
  {\rm Crit}(\Sigma_0^*\mathscr{A})/I \;\;\; \xleftrightarrow{\hspace{1cm}} \;\;\; {\rm Crit} (\mathscr{A})
  \end{align*}
with
\[
  \text{critical points of winding number $\frac{n}{2}$}  \; \xmapsto{\hspace{0.5cm}} \;  {\text{critical points of winding number $n$}}
\]
To include  generalized solutions,  define the extended twisted loop space
\[
\mathfrak{L}_I^*\mathfrak{Z}_0 :=\{z \in \mathfrak{L}_I \mathfrak{Z}_0 \mid \hat{z}\neq 0 \}
\]
and   extend the regularized functional:
\[
\mathscr{B}_0 \colon \mathfrak{L}^*\mathfrak{Z}_0 \cup \mathfrak{L}_I^*\mathfrak{Z}_0  \to \R.
\]
Thus, as before, we  have a bijective  correspondence 
  \[ 
  {\rm Crit} (\mathscr{B}_0)/I \;  \xleftrightarrow{1:1}\; \{\text{generalized periodic solutions of \eqref{eq:twistedODEforq}}\} 
  \]


We summarize the result of this note in the following.

\begin{theorem}\label{thm:main}
    There is a one-to-one correspondence between critical points of the extended regularized functional $\mathscr{B}_0$ modulo the involution $I$ and generalized periodic solutions of the time-dependent Stark-Zeeman system \eqref{eq:twistedODEforq}.
\end{theorem}




































































































































































































































































































































