\subsection*{Symplectic Euler}
The semi-implicit (symplectic) Euler method for the harmonic oscillator:
\al{
v_{n+1}
	&=	v_n-\omega^2x_n\Delta t,\\
x_{n+1}
	&=	x_n+v_{n+1}\Delta t
	=	x_n+v_n\Delta t-\omega^2x_n\pn{\Delta t}^2.
}
This gives
\al{
\bmat{x_{n+1}\\ v_{n+1}}
	&=	\bmat{
			1-\omega^2\pn{\Delta t}^2&\Delta t\\
			-\omega^2\Delta t&1
			}\bmat{x_n\\ v_n}.
}
Since the determinant is unity, this time evolution is area-preserving in the phase space.

Hamilton equations:
\al{
\dot p
	&=	-{\p H\ov\p q},&
\dot q
	&=	{\p H\ov\p p}.
}
This gives the following ``symplectic'' semi-implicit Euler:
\al{
p_{n+1}
	&=	p_n-{\p H\ov\p q}\fn{q_n,p_n}\Delta t,\\
q_{n+1}
	&=	q_n+{\p H\ov\p p}\fn{q_n,p_{n+1}}\Delta t
	=	q_n+{\p H\ov\p p}\fn{q_n,p_n}\Delta t
		-{\p^2 H\ov\pn{\p p}^2}\fn{q_n,p_n}{\p H\ov\p q}\fn{q_n,p_n}\pn{\Delta t}^2.
}
This gives
\al{
\df p_{n+1}
	&=	\df p_n
		-{\p^2 H\ov\p q\p p}\Delta t\,\df p_n
		-{\p^2 H\ov\pn{\p q}^2}\Delta t\,\df q_n\nn
	&=	\df p_n-H_{pq}\Delta t\,\df p_n-H_{qq}\Delta t\,\df q_n,\\
\df q_{n+1}
	&=	\df q_n
		+{\p^2 H\ov\p p\p q}\Delta t\,\df q_n
		+{\p^2 H\ov\pn{\p p}^2}\Delta t\,\df p_n\nn
	&\quad
		-{\p^2 H\ov\pn{\p p}^2}{\p^2 H\ov\p q\p p}\pn{\Delta t}^2\,\df p_n
		-{\p^2 H\ov\pn{\p p}^2}{\p^2 H\ov\pn{\p q}^2}\pn{\Delta t}^2\,\df q_n
			\nn
	&\quad
		-{\p^3 H\ov\pn{\p p}^3}{\p H\ov\p q}\pn{\Delta t}^2\,\df p_n
		-{\p^3 H\ov\pn{\p p}^2\p q}{\p H\ov\p q}\pn{\Delta t}^2\,\df q_n\nn
	&=	\df q_n+H_{pq}\Delta t\,\df q_n+H_{pp}\Delta t\,\df p_n\nn
	&\quad
		-H_{pp}H_{pq}\pn{\Delta t}^2\df p_n-H_{pp}H_{qq}\pn{\Delta t}^2\df q_n\nn
	&\quad
		-H_{ppp}H_q\pn{\Delta t}^2\df p_n-H_{ppq}H_q\pn{\Delta t}^2\df q_n
}
Then we have
\al{
\df q_{n+1}\wedge\df p_{n+1}
	&=	\pn{
			\df q_n+H_{pq}\Delta t\,\df q_n
			-H_{pp}H_{qq}\pn{\Delta t}^2\df q_n
			-H_{ppq}H_q\pn{\Delta t}^2\df q_n
			}
			\wedge\pn{\df p_n-H_{pq}\Delta t\,\df p_n}\nn
	&\quad
		+\pn{
			H_{pp}\Delta t\,\df p_n
			-H_{pp}H_{pq}\pn{\Delta t}^2\df p_n
			-H_{ppp}H_q\pn{\Delta t}^2\df p_n
			}\wedge\pn{-H_{qq}\Delta t\,\df q_n}\nn
	&=	\df q_n\wedge\df p_n\sqbr{
			1
			-H_{pq}^2\pn{\Delta t}^2
			-H_{ppq}H_q\pn{\Delta t}^2
			+\mc O\fn{\pn{\Delta t}^3}
			}\nn
	&=	\df q_n\wedge\df p_n\sqbr{
			1
			-\ub{\pn{H_{pq}^2+H_{ppq}H_q}}_{\p_p\pn{H_{pq}H_q}}
				\pn{\Delta t}^2
			+\mc O\fn{\pn{\Delta t}^3}
			}.
}


In the case of the ordinary Euler method,
\al{
q_{n+1}
	&=	q_n+H_p\Delta t,\\
p_{n+1}
	&=	p_n-H_q\Delta t,
}
we get
\al{
\df q_{n+1}
	&=	\df q_n+H_{pq}\Delta t\df q_n+H_{pp}\Delta t\df p_n,\\
\df p_{n+1}
	&=	\df p_n-H_{qp}\Delta t\df p_n-H_{qq}\Delta t\df q_n,
}
and hence
\al{
\df q_{n+1}\wedge\df p_{n+1}
	&=	\pn{\df q_n+H_{pq}\Delta t\df q_n}
		\wedge
		\pn{\df p_n-H_{qp}\Delta t\df p_n}
		+\pn{H_{pp}\Delta t\df p_n}
		\wedge
		\pn{-H_{qq}\Delta t\df q_n}\nn
	&=	\df q_n\wedge\df p_n\sqbr{
			1
			+\pn{H_{pp}H_{qq}-H_{qp}^2}\pn{\Delta t}^2
			+\mc O\fn{\pn{\Delta t}^3}
			}
}
