\section{Circular current}
Circular motion:
\al{
x	&=	r\cos\fn{\theta\fn{t}},\\
y	&=	r\sin\fn{\theta\fn{t}}.
}
Velocity:
\al{
\dot x
	&=	-r\dot\theta\sin\fn{\theta\fn{t}},\\
\dot y
	&=	r\dot\theta\cos\fn{\theta\fn{t}}.
}
Speed in world frame:
\al{
v	&=	r\dot\theta<c.
}
We want
\al{
\dot\theta
	&\to	{c\ov r},&
\theta
	&\to	{c\ov r}t+\tx{const.}
}
as $t\to\infty$.
For example,
\al{
\dot\theta\fn{t}
	&=	{c\ov r}\pn{1+\tanh\fn{bt}\ov2}.
}
Then
\al{
\theta\fn{t}
	&=	{c\ov 2r}\pn{
			t
			+{\ln\fn{\cosh\fn{bt}}\ov b}
			}
		+\tx{const.}\nn
	&=	{1\ov 2r}\sqbr{
			ct
			+{c\ov b}\ln\fn{\cosh\fn{b\,ct\ov c}}
			}
		+\tx{const.}
}


