			+{\bs x-\bs x_n\fn{\sn }\ov\ab{\bs x-\bs x_n\fn{\sn }}}
				\cdot\bs u_n\fn{\sn }
				}
			{u_n^\mu\fn{\sn } \ov \ab{\bs x - \bs x_n\fn{\sn }}}
		}\nn
	&=	{1\ov u_n^0\fn{\sn }}{\df\ov\df\s_n }
		{u_n^\mu\fn{\sn }\ov
			\ab{\bs x-\bs x_n\fn{\sn }}u_n^0\fn{\sn }
			+\pn{\bs x-\bs x_n\fn{\sn }}
				\cdot\bs u_n\fn{\sn }
				}\nn
	&=	{1\ov u_n^0\fn{\sn }}
		{\alpha_n^\mu\fn{\sn }
		\pn{
			\ab{\bs x-\bs x_n\fn{\sn }}u_n^0\fn{\sn }
			+\pn{\bs x-\bs x_n\fn{\sn }}
				\cdot\bs u_n\fn{\sn }
			}
		-u_n^\mu\fn{\sn }
			\pn{
				\tx{hoge}
			}
		\ov
			\Pn{\ab{\bs x-\bs x_n\fn{\sn }}u_n^0\fn{\sn }
			+\pn{\bs x-\bs x_n\fn{\sn }}
				\cdot\bs u_n\fn{\sn }}^2
		},
}
where
\al{
\tx{hoge}
	&=	{\bs x-\bs x_n\fn{\sn }\ov\ab{\bs x-\bs x_n\fn{\sn }}}\cdot\bs u_n\fn{\sn }
			u_n^0\fn{\sn }
