\subsection*{Yasuda-kun version}
You can differentiate with respect to $\bs{x}$ only via $R\equiv \ab{\bs{x} - \bs{x}'}$:
\al{
	\p_i = \pn{\p_i R}{\p\ov\p R} = {\pn{\bs{x} - \bs{x}'}\ov R}{\p\ov\p R} = \bs{n}{\p\ov\p R},
}
where $\displaystyle \bs{n}\fn{\bs{x}, x^{\pr0}}:= {\bs{x}_n\fn{\sn\fn{x^{\pr0}}} - \bs{x}\ov R\fn{\bs{x}, x^{\pr0}}} = {\bs{R}\fn{\bs{x}, x^{\pr0}}\ov R\fn{\bs{x}, x^{\pr0}}}$; $\bs{R}\fn{\bs{x}, x^{\pr0}} := \bs{x}_n\fn{\sn\fn{x^{\pr0}}} - \bs{x}$.
\al{
	\df R &= \df \pn{\ab{\bs{x}_n\fn{\sn\fn{x^{\pr0}}} - \bs{x}}}\nn
	&= {\bs{x}_n\fn{\sn\fn{x^{\pr0}}} - \bs{x}\ov\ab{\bs{x}_n\fn{\sn\fn{x^{\pr0}}} - \bs{x}}} \cdot {\bs{u}_n\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\df x^{\pr0}
}
\subsubsection*{$\star\ \ \nu = 0$ Case}
\al{
	\p_0 A^\mu\fn{\lx} 
	&= \sum_n{q_n\ov 4\pi}\int \df^{d+1}\lv x' {\p_0\pn{\delta\fn{x^{\pr0}-x^0+\ab{\bs x-\bs x'}}} \ov \ab{\bs x - \bs x'}}{\delta^3\fn{\bs x'-\bs x_n\fn{\sn\fn{x^{\pr0}}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}
		u_n^\mu\fn{\sn\fn{x^{\pr0}}}\nn
	&= \sum_n{q_n\ov 4\pi}\int \df x^{\pr0} {\p_0\pn{\delta\fn{x^{\pr0}-x^0+\ab{\bs x-\bs x_n\fn{\sn\fn{x^{\pr0}}}}}} \ov \ab{\bs x - \bs x_n\fn{\sn\fn{x^{\pr0}}}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}
		\nn
	&= -\sum_n{q_n\ov 4\pi}\int \df x^{\pr0} {1 \ov R\fn{\bs{x}, x^{\pr0}}}{\p\ov\p R}\pn{\delta\fn{x^0 - x^{\pr0} - R\fn{\bs{x}, x^{\pr0}}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}
		\nn
}
The first and the second derivatives of the function $\displaystyle f\fn{x^{\pr0}} = x^{\pr0} + \ab{\bs x-\bs x_n\fn{\sn\fn{x^{\pr0}}}} = x^{\pr0} + R\fn{\bs{x}, x^{\pr0}}$ are yielded by
\al{
	{\df f\fn{x^{\pr0}}\ov \df x^{\pr0}} &= 1 + {\bs{x}_n\fn{\sn\fn{x^{\pr0}}} - \bs{x}\ov\ab{\bs{x}_n\fn{\sn\fn{x^{\pr0}}} - \bs{x}}} \cdot {\bs{u}_n\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}} = 1 + {\bs{n}\fn{\bs{x}, x^{\pr0}} \cdot \bs{u}_n\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\\
	{\df^2 f\fn{x^{\pr0}}\ov {\df x^{\pr0}}^2} &= {1\ov {u_n^0\fn{\sn\fn{x^{\pr0}}}}^2}\Bigg[\pn{{\p \bs{n}\fn{\bs{x}, x^{\pr0}}\ov \p x^{\pr0}}\cdot \bs{u}_n\fn{\sn\fn{x^{\pr0}}} + \bs{n}\fn{\bs{x}, x^{\pr0}}\cdot{\bs{\alpha}_n\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}u_n^0\fn{\sn\fn{x^{\pr0}}}\nn
	&\phantom{{1\ov {u_n^0\fn{\sn\fn{x^{\pr0}}}}^2}\Bigg[}- \bs{n}\fn{\bs{x}, x^{\pr0}}\cdot\bs{u}_n\fn{\sn\fn{x^{\pr0}}}{\alpha_n^0\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg],
}
where
\al{
	{\p \bs{n}\fn{\bs{x}, x^{\pr0}}\ov \p x^{\pr0}} = {1\ov R\fn{\bs{x}, x^{\pr0}}}\Bigg[{{{\bs{u}_n\fn{\sn\fn{x^{\pr0}}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}} - \bs{n}\fn{\bs{x}, x^{\pr0}}\pn{\bs{n}\fn{\bs{x}, x^{\pr0}}\cdot{{\bs{u}_n\fn{\sn\fn{x^{\pr0}}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}\Bigg]
}
Therefore
\al{
	\p_0 A^\mu\fn{\lx} &= -\sum_n{q_n\ov 4\pi}\int \df x^{\pr0} {1 \ov R\fn{\bs{x}, x^{\pr0}}}{\p\ov\p R}\pn{\delta\fn{x^0 - x^{\pr0} - R\fn{\bs{x}, x^{\pr0}}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}\nn
		&= -\sum_n{q_n\ov 4\pi}\int \df f {1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}} {1 \ov R\fn{\bs{x}, x^{\pr0}}}{\p\ov\p f}\pn{\delta\fn{x^0 - f\fn{x^{\pr0}}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}\nn
		&= \sum_n{q_n\ov 4\pi} {\p\ov\p x^0}\left.\Bigg[{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}} {1 \ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg]\right|_{x^{\pr0} = x^{\pr0}\fn{\s^*}}\nn
		&= \sum_n{q_n\ov 4\pi} \red{{\p x^{\pr0}\ov \p x^0}{\p\ov\p x^{\pr0}}}\left.\Bigg[{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}} {1 \ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg]\right|_{x^{\pr0} = x^{\pr0}\fn{\s^*}}\nn
		&= \sum_n{q_n\ov 4\pi} \red{{1\ov \left.{\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}\right|_{x^{\pr0} = x^{\pr0}\fn{\s^*}}}}{\p\ov\p x^{\pr0}}\left.\Bigg[{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}} {1 \ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg]\right|_{x^{\pr0} = x^{\pr0}\fn{\s^*}},
}
where
\al{
	{\p\ov\p x^{\pr0}}&\Bigg[{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}} {1 \ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg]\nn
		&= -{{\df^2 f\fn{x^{\pr0}}\ov \df {x^{\pr0}}^2}\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}^2}{1 \ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\nn
		&\phantom{= -} - {1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{1 \ov R^2\fn{\bs{x}, x^{\pr0}}}\red{\p R\ov\p x^{\pr0}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\nn
		&\phantom{\phantom{= -} - } + {1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{1 \ov R\fn{\bs{x}, x^{\pr0}}}{{\alpha_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}u_n^0\fn{\sn\fn{x^{\pr0}}} - {u_n^\mu\fn{\sn\fn{x^{\pr0}}}\alpha_n^0\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\ov \pn{u_n^0\fn{\sn\fn{x^{\pr0}}}}^2}\nn
		&= -{{\df^2 f\fn{x^{\pr0}}\ov \df {x^{\pr0}}^2}\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}^2}{1 \ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\nn
		&\phantom{= -} - {1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{1 \ov R^2\fn{\bs{x}, x^{\pr0}}}\red{{\bs{n}\fn{\bs{x}, x^{\pr0}} \cdot \bs{u}_n\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\nn
		&\phantom{\phantom{= -} - } + {1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{1 \ov R\fn{\bs{x}, x^{\pr0}}}{{\alpha_n^\mu\fn{\sn\fn{x^{\pr0}}}}u_n^0\fn{\sn\fn{x^{\pr0}}} - {u_n^\mu\fn{\sn\fn{x^{\pr0}}}\alpha_n^0\fn{\sn\fn{x^{\pr0}}}}\ov \pn{u_n^0\fn{\sn\fn{x^{\pr0}}}}^3}
}
\subsubsection*{$\star\ \ \nu = i$ Case$\ \ \ \pn{i = 1, 2, 3}$}
\al{
	\p_i A^\mu\fn{\lx} 
	&= \sum_n{q_n\ov 4\pi}\int \df^{d+1}\lv x' \p_i\pn{{\delta\fn{x^0 - x^{\pr0} - R\fn{\bs{x}, x^{\pr0}}} \ov \ab{\bs x - \bs x'}}}{\delta^3\fn{\bs x'-\bs x_n\fn{\sn\fn{x^{\pr0}}}}\ov
		u_n^0\fn{\sn\fn{x^{\pr0}}}}
		u_n^\mu\fn{\sn\fn{x^{\pr0}}}\nn
	&= \sum_n{q_n\ov 4\pi}\int \df x^{\pr0} \pn{\bs{n}_i\fn{\bs{x}, x^{\pr0}}{\p\ov\p R} {\delta\fn{x^0 - x^{\pr0} - R\fn{\bs{x}, x^{\pr0}}} \ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}
		\nn
	&= \sum_n{q_n\ov 4\pi}\int \df x^{\pr0} \Bigg[\pn{{-\bs{n}_i\fn{\bs{x}, x^{\pr0}}\delta\fn{x^0 - x^{\pr0} - R\fn{\bs{x}, x^{\pr0}}} \ov R^2\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}\nn
	&\phantom{= \sum_n{q_n\ov 4\pi}\int \df}+ \pn{{\bs{n}_i\fn{\bs{x}, x^{\pr0}}\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}{\p\ov\p R} \pn{\delta\fn{x^0 - x^{\pr0} - R\fn{\bs{x}, x^{\pr0}}}}}\Bigg]
	\nn
	&= \sum_n{q_n\ov 4\pi}\int \df x^{\pr0} \Bigg[\pn{{-\bs{n}_i\fn{\bs{x}, x^{\pr0}}\delta\fn{x^0 - f\fn{x^{\pr0}}} \ov R^2\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}\nn
	&\phantom{= \sum_n{q_n\ov 4\pi}\int \df}+ \pn{{\bs{n}_i\fn{\bs{x}, x^{\pr0}}\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}{\p\ov\p f} \pn{\delta\fn{x^0 - f\fn{x^{\pr0}}}}}\Bigg]
	\nn
	&= \sum_n{q_n\ov 4\pi}\int \df f {1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}} \Bigg[\pn{{-\bs{n}_i\fn{\bs{x}, x^{\pr0}}\delta\fn{x^0 - f\fn{x^{\pr0}}} \ov R^2\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}\nn
	&\phantom{= \sum_n{q_n\ov 4\pi}\int \df f {1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}}+ \pn{{\bs{n}_i\fn{\bs{x}, x^{\pr0}}\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}{\p\ov\p f} \pn{\delta\fn{x^0 - f\fn{x^{\pr0}}}}}\Bigg]
	\nn
	&= \sum_n{q_n\ov 4\pi} {1\ov \left.{\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}\right|_{x^{\pr0} = x^{\pr0}\fn{\sn^*}}} \left.\pn{{-\bs{n}_i\fn{\bs{x}, x^{\pr0}} \ov R^2\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}\right|_{x^{\pr0} = x^{\pr0}\fn{\sn^*}}\nn
	&\phantom{= \sum_n{q_n\ov 4\pi}}
	+ \sum_n{q_n\ov 4\pi} \int \df f{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}\pn{{\bs{n}_i\fn{\bs{x}, x^{\pr0}}\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}{\p\ov\p f} \pn{\delta\fn{x^0 - f\fn{x^{\pr0}}}}}
	\nn
	&= \sum_n{q_n\ov 4\pi} {1\ov \left.{\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}\right|_{x^{\pr0} = x^{\pr0}\fn{\sn^*}}} \left.\pn{{-\bs{n}_i\fn{\bs{x}, x^{\pr0}} \ov R^2\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}\right|_{x^{\pr0} = x^{\pr0}\fn{\sn^*}}\nn
	&\phantom{= \sum_n{q_n\ov 4\pi}}
	- \sum_n{q_n\ov 4\pi} \int \df f{\p\ov\p f}\pn{{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{\bs{n}_i\fn{\bs{x}, x^{\pr0}}\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}} {\delta\fn{x^0 - f\fn{x^{\pr0}}}}
	\nn
	&= \sum_n{q_n\ov 4\pi} {1\ov \left.{\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}\right|_{x^{\pr0} = x^{\pr0}\fn{\sn^*}}} \left.\pn{{-\bs{n}_i\fn{\bs{x}, x^{\pr0}} \ov R^2\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}}\right|_{x^{\pr0} = x^{\pr0}\fn{\sn^*}}\nn
	&\phantom{= \sum_n{q_n\ov 4\pi}}
	- \sum_n{q_n\ov 4\pi} {1\ov \left.{\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}\right|_{x^{\pr0} = x^{\pr0}\fn{\sn^*}}} {\p\ov\p x^{\pr0}}\left.\Bigg[{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{\bs{n}_i\fn{\bs{x}, x^{\pr0}}\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg]\right|_{x^{\pr0} = x^{\pr0}\fn{\sn^*}},
		\label{result from Sunakawa}
}
where
\al{
	&{\p\ov\p x^{\pr0}}\Bigg[{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{\bs{n}_i\fn{\bs{x}, x^{\pr0}}\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg]\nn
	&= {\p\ov\p x^{\pr0}}\Bigg[{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{1\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg]\bs{n}_i\fn{\bs{x}, x^{\pr0}} + \Bigg[{1\ov {\df f\fn{x^{\pr0}}\ov \df x^{\pr0}}}{1\ov R\fn{\bs{x}, x^{\pr0}}}{u_n^\mu\fn{\sn\fn{x^{\pr0}}}\ov u_n^0\fn{\sn\fn{x^{\pr0}}}}\Bigg]{\p \bs{n}_i\fn{\bs{x}, x^{\pr0}}\ov\p x^{\pr0}}
}
\section{Lattice reformulation}
In $d$ spatial dimensions, we label the lattice points by
\al{
\bs n
	&=	\pn{n_1,\dots,n_d}\in\mathbb Z^3
}
such that their spacetime points are
\al{
\lx\fn{\bs n}\in \mathbb R^{1,d}.
}
At $\sP$, the player is located at $\lv\xP\fn{\sP}$.
When the player is located at $\xP$, the relevant lattice spacetime points are
\al{
\lx\fn{\bs n}
	&=	\bmat{\xP^0-\Ab{\bs x\fn{\bs n}-\bs\xP}\\ \bs x\fn{\bs n}}.
}
On the $\PLC\fn{\lv\xP}$, we have these points, as well as the $n$th particle locations
\al{
\lv{x_n}
	&=	\bmat{\xP^0-\Ab{\bs x_n-\bs\xP}\\ \bs x_n}.
}
Given the EM fields on $\lv{x\fn{\bs n}}$ and $\lv{x_n}$, we want to determine them on $\PLC\fn{\lv\xP+\lv{\Delta\xP}}$.

\al{
A^\mu\fn{x^0,\bx}
	&=	{1\ov4\pi}\int_V\df^3\bs x'{j^\mu\fn{x'}\ov\ab{\bs x-\bs x'}}.
}
In the limit of $V\to\PLC\fn{x}$, we get
\al{
x^{\pr0}=x^0-\ab{\bs x-\bs x'},
}
and
\al{
A^\mu\fn{x^0,\bx}
	&=	{1\ov4\pi}\int_V\df^3\bs x'{j^\mu\fn{x^0-\ab{\bs x-\bs x'},\bs x'}\ov\ab{\bs x-\bs x'}}\nn
	&= {1\ov4\pi}\int_V\df^3\bs x'\sum_n q_n \int\df \sn{\delta\fn{x^0 - \ab{\bs{x} - \bs{x}'} - x_n^0\fn{\sn}}\delta^3\fn{\bs{x'} - \bs{x_n}\fn{\sn}}u_n^\mu\fn{\sn}\ov\ab{\bs x-\bs x'}}
}
\al{
	\p_i\pn{\delta\fn{x^0 - \ab{\bs{x} - \bs{x}'} - x_n^0\fn{\sn}}\ov\ab{\bs x-\bs x'}} &= \p_i\pn{1\ov\ab{\bs{x} - \bs{x}'}}\delta\fn{x^0 - \ab{\bs{x} - \bs{x}'} - x_n^0\fn{\sn}}\nn
	&
}
In taking a derivative with respect to $\lx$, we leave $V$ to be fixed. Then we get
\al{
\p_0A^\mu\fn{x}
	&=	{1\ov4\pi}\int_V\df^3\bs x'{1\ov\ab{\bs x-\bs x'}}
			{\p j^\mu\fn{x^0-\ab{\bs x-\bs x'},\bs x'}\ov\p x^0}\nn
	&= 0,\\%というゲージを取ったことになる
\p_iA^\mu\fn{x}
	&=	{1\ov4\pi}\int_V\df^3\bs x'\Bigg[
		\pn{{\p\ov\p x^i}{1\ov\ab{\bs x-\bs x'}}}
			j^\mu\fn{x^0-\ab{\bs x-\bs x'},\bs x'}\nn
	&\phantom{=	{1\ov4\pi}\int_V\df^3\bs x'\Bigg[}
			+{1\ov\ab{\bs x-\bs x'}}
			\left.{\p j^\mu\fn{x^{\pr0},\bs x'}\ov\p x^{\pr0}}\right|_{x^{\pr0}=x^0-\ab{\bs x-\bs x'}}\pn{-{\p\ab{\bs x-\bs x'}\ov\p x^i}}
			\Bigg]
		\nn
	&=	-{1\ov4\pi}\int_V\df^3\bs x'
		{x_i-x_i'\ov\ab{\bs x-\bs x'}^2}
		\sqbr{
			{j^\mu\fn{x^0-\ab{\bs x-\bs x'},\bs x'}\ov\ab{\bs x-\bs x'}}
		+
			\left.{\p j^\mu\fn{x^{\pr0},\bs x'}\ov\p x^{\pr0}}\right|_{x^{\pr0}=x^0-\ab{\bs x-\bs x'}}
			}\nn
	&= -{1\ov4\pi}\Bigg[\pn{\sum_n q_n {\pn{\bs{x}_i - \bs{x}_n\fn{\s^*}_i}\ov \pn{x^0 - x_n^0\fn{\s^*}}^3}u_n^\mu\fn{\s^*}} + \pn{\sum_n q_n \pn{-2\pn{\bs{x}_i - \bs{x}_n\fn{\s^*}_i}\ov\pn{x^0 - x_n^0\fn{\s^*}}^3}u_n^\mu\fn{\s^*}} \nn
	&\phantom{-{1\ov4\pi}\Bigg[}
	+ \left.\pn{\sum_n q_n \pn{-2\pn{\bs{x}_i - \bs{x}_n\fn{\s^*}_i}\ov\pn{x^0 - x_n^0\fn{\s^*}}^2}{\p u_n^\mu\fn{\sn}\ov\p\s_n}{\p\sn \ov \p x^0}\right|_{\sn = \s^*}}\Bigg]\nn
	&= ?.
}

The vector potential $\bs A \pn{\lv{x\fn{\bs n}}}$ on a lattice point $\lv{x\fn{\bs n}}$ is determined by an integral on an arbitrary spacelike hypersurface $V$ that contains $\lv{x\fn{\bs n}}$:
\al{
	\bs A \pn{\lv{x}} &= {1\ov4\pi} \int_V \df^{d} \bs x' {\bs j(x')\ov \ab{\bs x - \bs x'}}\nn
	&= {1\ov4\pi} \int_V \df^{d} \bs x' {1\ov \ab{\bs x - \bs x'}} \sum_nq_n\int\df\sn \,\delta^{d+1}\Fn{\lv x'-\lv{x_n}\fn{\sn}}\bs u_n\fn{\sn}\nn
	&= {1\ov4\pi} \sum_nq_n \int\df\sn \, {1\ov \ab{\bs x - \bs x_n\fn{\sn}}} \delta \Fn{x'^0 - x_n^0\fn{\sn}}\bs u_n\fn{\sn}\nn
	&=	{1\ov4\pi} \sum_nq_n \left.{1\ov \ab{\bs x - \bs x_n\fn{\sn}}} \bs v_n\fn{\sn}\right|_{\tx{$\sn$ that puts $\lv{x_n}$ on $V$}}.
}
When we take a limit of $V$ becoming $\PLC\fn{\lv{x}}$, we obtain $x_n^0\fn{\sn} = x^0 - {\ab{\bs x - \bs x_n\fn{\sn}}}$, which is called a retarded time of a particle in a position $\bs x$. In the same manner, scalar potential $\phi \pn{\lv{x}}$ on a lattice point $\lv{x}$ is determined by
\al{
	\phi \pn{\lv{x}} &= {1\ov4\pi} \int_V \df^{d} \bs x' {\rho(x')\ov \ab{\bs x - \bs x'}}\nn
	&= {1\ov4\pi} \int_V \df^{d} \bs x' {1\ov \ab{\bs x - \bs x'}} \sum_nq_n\int\df\sn \,\delta^{d+1}\Fn{\lv x'-\lv{x_n}\fn{\sn}} {\df x_n^0\ov\df\s}\fn{\sn}\nn
	&= {1\ov4\pi} \sum_nq_n \int\df\sn \, {1\ov \ab{\bs x- \bs x_n\fn{\sn}}} \delta\Fn{x'^0 - x_n^0\fn{\sn}} {\df x_n^0\ov\df\s}\fn{\sn}\nn
	&=	{1\ov4\pi}\sum_nq_n\left.{1\ov \ab{\bs x - \bs x_n\fn{\sn}}}\right|_\tx{$\sn$ that puts $\lv{x_n}$ on $V$}.
}
Then, you get 
\al{
A^\mu \pn{\lv{x}}
	&= {1\ov4\pi} \sum_nq_n \int\df\sn \,{1\ov \ab{\bs x - \bs x_n\fn{\sn}}} \delta\Fn{x'^0 - x_n^0\fn{\sn}} {\df x_n^\mu \ov\df\s}\fn{\sn}\nn
	&= {1\ov4\pi} \sum_nq_n\left.{1\ov \ab{\bs x - \bs x_n\fn{\sn}}} {u_n^\mu\fn{\sn}\ov{u_n^0}\fn{\sn}}\right|_\tx{$\sn$ that puts $\lv{x_n}$ on $V$}
}
We are choosing $V = PLC(\lv{x})$. Then
\al{
	x^0_n(\sn) &= x^0 - \left|\bs{x} - \bs{x}_n\right|
}
As the choice of the spatial hypersurface V is arbitrary, when you take derivative of $A^\mu$ with respect to $x^\nu$, you can use the same V for the infinitesimaly translated point.
\al{
	\partial_\mu A_\nu &= \partial_\mu \sqbr{{1\ov4\pi} \sum_nq_n \int\df\sn \,{1\ov \ab{\bs x - \bs x_n\fn{\sn}}} \delta\Fn{x'^0 - x_n^0\fn{\sn}} {\df x_{n, \nu} \ov\df\s}\fn{\sn}}\nn
	&= \partial_\mu \sqbr{{1\ov4\pi} \sum_nq_n \int\df\sn \,{1\ov \ab{\bs x - \bs x_n\fn{\sn}}} \delta\Fn{x'^0 - x^0 + {\ab{\bs x - \bs x_n\fn{\sn}}}} {\df x_{n, \nu} \ov\df\s}\fn{\sn}}
}

\subsection*{New note:}
\al{
	A^\mu\fn{x} &= {e\ov4\pi}\int_V\df^3\bs{x'}\int\df \sn {1\ov\ab{\bs{x} - \bs{x}'}}\delta^{d+1}\fn{\lv x' - \lv{x_n}\fn{\sn}}u_n^\mu\fn{\sn}\nn
	&= {e\ov4\pi}\int_V\df^3\bs{x'}\int\df \sn {1\ov\ab{\bs{x} - \bs{x}'}}\delta^{d}\fn{\bs{x'} - \bs{x}_n\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - \ab{\bs{x} - \bs{x}'}}u_n^\mu\fn{\sn}\label{Amu}
}
In this expression, $\s$ is independent of $\bs{x'}$ and you can first perform spatial integration with respect to $\bs{x'}$.
\al{
	A^\mu\fn{x} = {e\ov4\pi}\int\df \sn {1\ov\ab{\bs{x} - \bs{x}_n\fn{\sn}}}\delta\fn{x^0 - x_n^0\fn{\sn} - \ab{\bs{x} - \bs{x}_n\fn{\sn}}}u_n^\mu\fn{\sn}
}
Integrating with respect to worldline parameter $\sn$ becomes messy because of $\bs{x}_n\fn{\sn}$.
Therefore, in the following, we evaluate the integral
\al{
	\int_{-\infty}^{\infty}\df{\sn} g\fn{\sn}\delta\fn{x^0 - f\fn{\sn}}
}
for the general $g\fn{\sn}$, where $f\fn{\sn} = x_n^0\fn{\sn} + \ab{\bs{x} - \bs{x}_n\fn{\sn}}$.\\
Let $\sn = h(y)$ where $y = f(\sn)$, and you yield
\al{
	\int_{-\infty}^{\infty}\df{\sn} g\fn{\sn}\delta\fn{x^0 - f\fn{\sn}} &= \int_{-\infty}^{\infty}\df{y} {\df{h\fn{y}}\ov\df{y}}g\fn{h\fn{y}}\delta\fn{x^0 - y}\nn
	&= \left.{\df{h\fn{y}}\ov\df{y}}\right|_{y = x^0}g\fn{h\fn{x^0}}\nn
	&\equiv \Bigg[{\df{f\fn{\s^*}}\ov\df{\s^*}}\Bigg]^{-1}g\fn{\s^*},
}
where $\s^* \equiv h\fn{x^0}$. 
\al{
	\Bigg[{\df{f\fn{\s^*}}\ov\df{\s^*}}\Bigg]^{-1}g\fn{\s^*} &= \Bigg[{\df{\pn{x_n^0\fn{\s^*} + \ab{\bs{x} - \bs{x}_n\fn{\s^*}}}}\ov\df{\s^*}}\Bigg]^{-1}g\fn{\s^*}\nn
	&= \Bigg[u_n^0\fn{\s^*} - {\pn{\bs{x} - \bs{x}_n\fn{\s^*}}\ov\ab{\bs{x} - \bs{x}_n\fn{\s^*}}}\cdot\bs{u}_n\fn{\s^*}\Bigg]^{-1}g\fn{\s^*}\nn
	&\equiv \Bigg[u_n^0\fn{\s^*} - \bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Bigg]^{-1}g\fn{\s^*}\ \ \ \ \ \ \ \ \ \pn{\bs{n}\fn{\s^*}\equiv {\pn{\bs{x} - \bs{x}_n\fn{\s^*}}\ov\ab{\bs{x} - \bs{x}_n\fn{\s^*}}}}\nn
	&\equiv {g\fn{\s^*}\ov\beta\fn{\s^*}}\ \ \ \ \ \ \ \ \ \pn{\beta\fn{\s^*} \equiv u_n^0\fn{\s^*} - \bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}}\nn
	\Leftrightarrow &\int_{-\infty}^{\infty}\df{\sn} g\fn{\sn}\delta\fn{x^0 - f\fn{\sn}} = {g\fn{\s^*}\ov\beta\fn{\s^*}}.
}
Hence you gain the covariant expression of Li\'enard-Wiecherd potential:
\al{
	A^\mu\fn{x} = {e\ov4\pi}{u_n^\mu\fn{\s^*}\ov\ab{\bs{x} - \bs{x}_n\fn{\sn}}}{1\ov\beta\fn{\s^*}}.
}
\subsection*{Derivative of potential}
Second, we consider the spacetime derivative of potential $\p_\mu A^\nu\fn{x}$. We start with Eq.$\pn{\ref{Amu}}$, as we want to leave $\sn$ independent of $\bs{x'}$. You can differentiate with respect to $\bs{x}$ only via $R\equiv \ab{\bs{x} - \bs{x}'}$:
\al{
	\p_i = \pn{\p_i R}{\p\ov\p R} = {\pn{\bs{x} - \bs{x}'}\ov R}{\p\ov\p R} = \bs{n}{\p\ov\p R},
}
where $\displaystyle \bs{n}\equiv {\pn{\bs{x} - \bs{x}'}\ov R} = {\bs{R}\ov R}$; $\bs{R} \equiv \bs{x} - \bs{x'}$.
\al{
	dR &= d\pn{\ab{\bs{x} - \bs{x}_n\fn{\sn}}} = -\bs{n}\fn{\sn}\cdot \bs{u}_n\fn{\sn}d\sn
}
\subsubsection*{$\star\ \ \mu = 0\ \ \nu = i$ Case$\ \ \ \pn{i = 1, 2, 3}$}
\al{
	\p_0 A^i\fn{x} &= {e\ov4\pi}\int_V\df^3\bs{x'}\int\df \sn {1\ov\ab{\bs{x} - \bs{x}'}}\delta^{d}\fn{\bs{x'} - \bs{x}_n\fn{\sn}}\pn{{\p\ov\p x^0}\delta\fn{x^0 - x_n^0\fn{\sn} - \ab{\bs{x} - \bs{x}'}}}u_n^i\fn{\sn}\nn
	&= {e\ov4\pi}\int\df \sn {1\ov\ab{\bs{x} - \bs{x}_n\fn{\sn}}}\pn{{\p\ov\p x^0}\delta\fn{x^0 - x_n^0\fn{\sn} - \ab{\bs{x} - \bs{x}_n\fn{\sn}}}}u_n^i\fn{\sn}\nn
	&= {e\ov4\pi}\int\df y {1\ov\beta\fn{\sn}} {1\ov\ab{\bs{x} - \bs{x}_n\fn{\sn}}}\pn{{\p\ov\p x^0}\delta\fn{x^0 - y\fn{\sn}}}u_n^i\fn{\sn}\ \ \ \pn{\sn \rightarrow y \equiv x_n^0\fn{\sn} + \ab{\bs{x} - \bs{x}_n\fn{\sn}}}\nn
	&= {e\ov4\pi}\int\df y {1\ov\beta\fn{\sn}} {1\ov\ab{\bs{x} - \bs{x}_n\fn{\sn}}}{\p y\fn{\sn}\ov\p x^0}\pn{{\p\ov\p y\fn{\sn}}\delta\fn{x^0 - y\fn{\sn}}}u_n^i\fn{\sn}\nn
	&= {e\ov4\pi}\int\df y {1\ov\beta\fn{\sn}} {1\ov\ab{\bs{x} - \bs{x}_n\fn{\sn}}}\pn{\bs{n}\fn{\sn}\cdot{\p\bs{x}\ov\p x^0}}\pn{{\p\ov\p y\fn{\sn}}\delta\fn{x^0 - y\fn{\sn}}}u_n^i\fn{\sn}\nn
	&= {e\ov4\pi}\int\df y {1\ov\beta\fn{\sn}} {1\ov\ab{\bs{x} - \bs{x}_n\fn{\sn}}}\pn{\bs{n}\fn{\sn}\cdot{\bs{u}_\P\ov u^0_\P}}\pn{{\p\ov\p y\fn{\sn}}\delta\fn{x^0 - y\fn{\sn}}}u_n^i\fn{\sn} \ \ \ \ \pn{u_\P^\mu \equiv {\p x^\mu\ov \p \s}}\nn
	&= -{e\ov4\pi}{\p\ov\p y\fn{\s^*}}\pn{{1\ov\beta\fn{\s^*}} {u_n^i\fn{\s^*}\ov\ab{\bs{x} - \bs{x}_n\fn{\s^*}}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}}\nn
	&= -{e\ov4\pi}{1\ov\beta\fn{\s^*}}{\p\ov\p \s^*}\pn{{1\ov\beta\fn{\s^*}} {u_n^i\fn{\s^*}\ov R\fn{\s^*}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}}.
}
\subsubsection*{$\star\ \ \mu = i\ \ \nu = 0$ Case$\ \ \ \pn{i = 1, 2, 3}$}
\al{
	\p_i A^0\fn{x} &= {e\ov4\pi}\int_V\df^3\bs{x'}\int\df \sn \pn{\bs{n}}_i{\p\ov\p R}\pn{{1\ov\ab{\bs{x} - \bs{x}'}}\delta^{d}\fn{\bs{x'} - \bs{x}_n\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - \ab{\bs{x} - \bs{x}'}}}u_n^0\fn{\sn}\nn
	&= -{e\ov4\pi}\int\df \sn \fn{{\pn{\bs{n}\fn{\sn}}_i\ov R^2\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - R\fn{\sn}}}u_n^0\fn{\sn}\nn
	&\phantom{-{e\ov4\pi}} 
	+ {e\ov4\pi}\int\df \sn {\pn{\bs{n}\fn{\sn}}_i\ov R\fn{\sn}}\pn{{\p\ov\p R\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - R\fn{\sn}}}u_n^0\fn{\sn}\nn
	&= -{e\ov4\pi}{\pn{\bs{n}\fn{\s^*}}_i\ov R^2\fn{\s^*}}{u_n^0\fn{\s^*}\ov \beta\fn{\s^*}}\nn
	&\phantom{-{e\ov4\pi}} 
	+ {e\ov4\pi}\int\df R \pn{\p R\ov \p \sn}^{-1} {\pn{\bs{n}\fn{\sn}}_i\ov R\fn{\sn}}\pn{{\p\ov\p R\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - R\fn{\sn}}}u_n^0\fn{\sn}\nn
	&= -{e\ov4\pi}{\pn{\bs{n}\fn{\s^*}}_i\ov R^2\fn{\s^*}}{u_n^0\fn{\s^*}\ov \beta\fn{\s^*}}\nn
	&\phantom{-{e\ov4\pi}} 
	+ {e\ov4\pi}\int\df R {-1\ov\bs{n}\fn{\sn}\cdot \bs{u}_n\fn{\sn}}{\pn{\bs{n}\fn{\sn}}_i\ov R\fn{\sn}}\pn{{\p\ov\p R\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - R\fn{\sn}}}u_n^0\fn{\sn}\nn
	&= -{e\ov4\pi}{\pn{\bs{n}\fn{\s^*}}_i\ov R^2\fn{\s^*}}{u_n^0\fn{\s^*}\ov \beta\fn{\s^*}} + {e\ov4\pi\beta\fn{\s^*}}{\p\ov\p R\fn{\s^*}}\pn{{u_n^0\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}{\pn{\bs{n}\fn{\s^*}}_i\ov R\fn{\s^*}}}\nn
	&= -{e\ov4\pi}{\pn{\bs{n}\fn{\s^*}}_i\ov R^2\fn{\s^*}}{u_n^0\fn{\s^*}\ov \beta\fn{\s^*}} + {e\ov4\pi\beta\fn{\s^*}}\pn{-1\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}{\p\ov\p \s^*}\pn{{u_n^0\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}{\pn{\bs{n}\fn{\s^*}}_i\ov R\fn{\s^*}}}.
}
\subsubsection*{$\star\ \ \mu = i\ \ \nu = j$ Case$\ \ \ \pn{i, j = 1, 2, 3}$}
\al{
	\p_i A^j\fn{x} &= {e\ov4\pi}\int_V\df^3\bs{x'}\int\df \sn {\p\ov\p x^i}\pn{{1\ov\ab{\bs{x} - \bs{x}'}}\delta^{d}\fn{\bs{x'} - \bs{x}_n\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - \ab{\bs{x} - \bs{x}'}}u_n^j\fn{\sn}}\nn
	&= {e\ov4\pi}\int_V\df^3\bs{x'}\int\df \sn \delta^{d}\fn{\bs{x'} - \bs{x}_n\fn{\sn}}\pn{\bs{n}}_i{\p\ov\p R}\pn{{1\ov R}\delta\fn{x^0 - x_n^0\fn{\sn} - R}}u_n^j\fn{\sn}\nn
	&= {e\ov4\pi}\int\df \sn \pn{\bs{n}\fn{\sn}}_i{\p\ov\p R\fn{\sn}}\pn{{1\ov R\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - R\fn{\sn}}}u_n^j\fn{\sn}\nn
	&= -{e\ov4\pi}\int\df \sn {\pn{\bs{n}\fn{\sn}}_i\ov R^2\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - R\fn{\sn}}u_n^j\fn{\sn}\nn
	&\phantom{{e\ov4\pi}}
	+ {e\ov4\pi}\int\df \sn \pn{\bs{n}\fn{\sn}}_i{1\ov R\fn{\sn}}\pn{{\p\ov\p R\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - R\fn{\sn}}}u_n^j\fn{\sn}\nn
	&= -{e\ov4\pi}{\pn{\bs{n}\fn{\s^*}}_i\ov R^2\fn{\s^*}}{u_n^j\fn{\s^*}\ov\beta\fn{\s^*}}\nn
	&\phantom{{e\ov4\pi}}
	+ {e\ov4\pi}\int\df R {-u_n^j\fn{\sn}\ov\bs{n}\fn{\sn}\cdot \bs{u}_n\fn{\sn}}{\pn{\bs{n}\fn{\sn}}_i\ov R\fn{\sn}}\pn{{\p\ov\p R\fn{\sn}}\delta\fn{x^0 - x_n^0\fn{\sn} - R\fn{\sn}}}\nn
	&= -{e\ov4\pi}{\pn{\bs{n}\fn{\s^*}}_i\ov R^2\fn{\s^*}}{u_n^j\fn{\s^*}\ov\beta\fn{\s^*}} + {e\ov4\pi\beta\fn{\s^*}}\pn{-1\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}{\p\ov\p \s^*}\pn{{u_n^j\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}{\pn{\bs{n}\fn{\s^*}}_i\ov R\fn{\s^*}}}
}
The $\s^*$ derivative of $u_n^0\fn{\s^*}$, $\bs{n}\fn{\s^*}$ and $\pn{\beta\fn{\s^*}R\fn{\s^*}}$ are evaluated as:
\al{
	{\p u_n^0\fn{\s^*}\ov\p \s^*} &= {\p\ov\p \s^*}\sqrt{1 + \bs{u}_n^2\fn{\s^*}}\nn
	&= {\bs{u}_n\fn{\s^*}\ov\sqrt{1 + \bs{u}_n^2\fn{\s^*}}}\cdot {\p\bs{u}_n\fn{\s^*}\ov \p \s^*}\nn
	&\equiv {\bs{u}_n\fn{\s^*}\cdot \bs{\alpha}_n\fn{\s^*}\ov\sqrt{1 + \bs{u}_n^2\fn{\s^*}}}\ \ \ \ \pn{{\bs{\alpha}_n\fn{\s^*}\equiv {\p\bs{u}_n\fn{\s^*}\ov \p \s^*}}}
}
\al{
	{\p\bs{n}\fn{\s^*}\ov\p \s^*} &= {\p\ov\p \s^*}{\pn{\bs{x} - \bs{x}_n\fn{\s^*}}\ov R\fn{\s^*}}\nn
	&= {-\bs{u}_n\fn{\s^*}R\fn{\s^*} - \bs{R}\fn{\s^*}{\p R\fn{\s^*}\ov\p \s^*}\ov R^2\fn{\s^*}}\nn
	&= {1\ov R\fn{\s^*}}\Bigg[-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg]
}
\al{
	{\p\ov\p \s^*}\pn{1\ov\beta\fn{\s^*}R\fn{\s^*}} &= -{1\ov\beta^2\fn{\s^*}R^2\fn{\s^*}}\Bigg[\beta\fn{\s^*}{\p R\fn{\s^*}\ov\p\s^*} + {\p\beta\fn{\s^*}\ov\p \s^*}R\fn{\s^*}\Bigg]\nn
	&= {\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\ov \beta\fn{\s^*}R^2\fn{\s^*}} - {1\ov \beta^2\fn{\s^*}R\fn{\s^*}}\Bigg[{\p u_n^0\fn{\s^*}\ov \p\s^*} - {\p\bs{n}\fn{\s^*}\ov\p \s^*}\cdot\bs{u}_n\fn{\s^*} - \bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\Bigg]\nn
	&= {\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\ov \beta\fn{\s^*}R^2\fn{\s^*}} 
	-{1\ov \beta^2\fn{\s^*}R\fn{\s^*}}{\bs{u}_n\fn{\s^*}\cdot \bs{\alpha}_n\fn{\s^*}\ov\sqrt{1 + \bs{u}_n^2\fn{\s^*}}}\nn
	&\ \ \ \ \ \
	+{1\ov \beta^2\fn{\s^*}R^2\fn{\s^*}}\Bigg[-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg]\bs{u}_n\fn{\s^*}
	+ {\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov \beta^2\fn{\s^*}R\fn{\s^*}}
}
\al{
	&{\p\ov\p\s^*}\pn{1\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R\fn{\s^*}}\nn
	&= {1\ov R^2\fn{\s^*}} - {1\ov R\fn{\s^*}}{1\ov\Big(\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}\Big)^2}\pn{{\p\bs{n}\fn{\s^*}\ov\p\s^*}\cdot\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}}\nn
	&= {1\ov R^2\fn{\s^*}} - {1\ov R^2\fn{\s^*}}\Bigg[{-\bs{u}^2_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2} + 1\Bigg] - {1\ov R\fn{\s^*}}{\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}\nn
	&= {1\ov R^2\fn{\s^*}}{\bs{u}^2_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}- {1\ov R\fn{\s^*}}{\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}
}
\al{
	&{\p\ov\p \s^*}\pn{{1\ov\beta\fn{\s^*}} {u_n^i\fn{\s^*}\ov R\fn{\s^*}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}}\nn
	&= {\p\ov\p\s^*}\pn{1\ov\beta\fn{\s^*} R\fn{\s^*}}{u_n^i\fn{\s^*}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}
	+ {\alpha_n^i\fn{\s^*}\ov\beta\fn{\s^*} R\fn{\s^*}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}
	+ {u_n^i\fn{\s^*}\ov\beta\fn{\s^*} R\fn{\s^*}}{\p\bs{n}\fn{\s^*}\ov\p \s^*}\cdot{\bs{u}_\P\ov u^0_\P}\nn
	&= \Biggl\{{\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\ov \beta\fn{\s^*}R^2\fn{\s^*}} 
	-{1\ov \beta^2\fn{\s^*}R\fn{\s^*}}{\bs{u}_n\fn{\s^*}\cdot \bs{\alpha}_n\fn{\s^*}\ov\sqrt{1 + \bs{u}_n^2\fn{\s^*}}}\nn
	&\ \ \ \ \ \
	+{1\ov \beta^2\fn{\s^*}R^2\fn{\s^*}}\Bigg[-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg]\bs{u}_n\fn{\s^*}
	+ {\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov \beta^2\fn{\s^*}R\fn{\s^*}}\Biggl\}
	{u_n^i\fn{\s^*}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}\nn
	&\ \ \ \ \ \
	+ {\alpha_n^i\fn{\s^*}\ov\beta\fn{\s^*} R\fn{\s^*}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}
	+ {u_n^i\fn{\s^*}\ov\beta\fn{\s^*} R^2\fn{\s^*}}\Bigg[-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg]\cdot{\bs{u}_\P\ov u^0_\P}
}
\al{
	&{\p\ov\p \s^*}\pn{{u_n^0\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}{\pn{\bs{n}\fn{\s^*}}_i\ov R\fn{\s^*}}}\nn
	&= \Bigg[{1\ov R^2\fn{\s^*}}{\bs{u}^2_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}- {1\ov R\fn{\s^*}}{\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}\Bigg]u_n^0\fn{\s^*}\pn{\bs{n}\fn{\s^*}}_i\nn
	&\ \ \ \ \ \
	+ {\pn{\bs{n}\fn{\s^*}}_i\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R\fn{\s^*}}{\bs{u}_n\fn{\s^*}\cdot \bs{\alpha}_n\fn{\s^*}\ov\sqrt{1 + \bs{u}_n^2\fn{\s^*}}}\nn
	&\ \ \ \ \ \
	+ {u_n^0\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R^2\fn{\s^*}}\Bigg[-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg]_i
}
\al{
	&{\p\ov\p \s^*}\pn{{u_n^j\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}{\pn{\bs{n}\fn{\s^*}}_i\ov R\fn{\s^*}}}\nn
	&= \Bigg[{1\ov R^2\fn{\s^*}}{\bs{u}^2_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}- {1\ov R\fn{\s^*}}{\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}\Bigg]u_n^j\fn{\s^*}\pn{\bs{n}\fn{\s^*}}_i\nn
	&\ \ \ \ \ \
	+ {\pn{\bs{n}\fn{\s^*}}_i\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R\fn{\s^*}}\alpha_n^j\fn{\s^*}\nn
	&\ \ \ \ \ \
	+ {u_n^j\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R^2\fn{\s^*}}\Bigg[-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg]_i
}
\al{
	&\p_0 A^i\fn{x}=-{e\ov4\pi}{1\ov\beta\fn{\s^*}}\Biggl[\Biggl({\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\ov \beta\fn{\s^*}R^2\fn{\s^*}} 
	-{1\ov \beta^2\fn{\s^*}R\fn{\s^*}}{\bs{u}_n\fn{\s^*}\cdot \bs{\alpha}_n\fn{\s^*}\ov\sqrt{1 + \bs{u}_n^2\fn{\s^*}}}\nn
	&\ \ \ \ \ \
	+{1\ov \beta^2\fn{\s^*}R^2\fn{\s^*}}\Bigg\{-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg\}\bs{u}_n\fn{\s^*}
	+ {\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov \beta^2\fn{\s^*}R\fn{\s^*}}\Bigg)
	{u_n^i\fn{\s^*}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}\nn
	&\ \ \ \ \ \
	+ {\alpha_n^i\fn{\s^*}\ov\beta\fn{\s^*} R\fn{\s^*}}\pn{\bs{n}\fn{\s^*}\cdot{\bs{u}_\P\ov u^0_\P}}
	+ {u_n^i\fn{\s^*}\ov\beta\fn{\s^*} R^2\fn{\s^*}}\Bigg\{-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg\}\cdot{\bs{u}_\P\ov u^0_\P}\Biggl]
}
\al{
	&\p_i A^0\fn{x} = -{e\ov4\pi}{\pn{\bs{n}\fn{\s^*}}_i\ov R^2\fn{\s^*}}{u_n^0\fn{\s^*}\ov \beta\fn{\s^*}}\nn
	&+ {e\ov4\pi\beta\fn{\s^*}}\pn{-1\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}\Bigg[\Bigg\{{1\ov R^2\fn{\s^*}}{\bs{u}^2_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}- {1\ov R\fn{\s^*}}{\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}\Bigg\}u_n^0\fn{\s^*}\pn{\bs{n}\fn{\s^*}}_i\nn
	&+ {\pn{\bs{n}\fn{\s^*}}_i\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R\fn{\s^*}}{\bs{u}_n\fn{\s^*}\cdot \bs{\alpha}_n\fn{\s^*}\ov\sqrt{1 + \bs{u}_n^2\fn{\s^*}}}
	+ {u_n^0\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R^2\fn{\s^*}}\Bigg\{-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg\}_i\Bigg]
}
\al{
	&\p_i A^j\fn{x} = -{e\ov4\pi}{\pn{\bs{n}\fn{\s^*}}_i\ov R^2\fn{\s^*}}{u_n^j\fn{\s^*}\ov\beta\fn{\s^*}}\nn
	&+ {e\ov4\pi\beta\fn{\s^*}}\pn{-1\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*}}\Bigg[\Bigg\{{1\ov R^2\fn{\s^*}}{\bs{u}^2_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}- {1\ov R\fn{\s^*}}{\bs{n}\fn{\s^*}\cdot\bs{\alpha}_n\fn{\s^*}\ov\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)^2}\Bigg\}u_n^j\fn{\s^*}\pn{\bs{n}\fn{\s^*}}_i\nn
	&+ {\pn{\bs{n}\fn{\s^*}}_i\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R\fn{\s^*}}\alpha_n^j\fn{\s^*}
	+ {u_n^j\fn{\s^*}\ov\bs{n}\fn{\s^*}\cdot \bs{u}_n\fn{\s^*} R^2\fn{\s^*}}\Bigg\{-\bs{u}_n\fn{\s^*} + \bs{n}\fn{\s^*}\Big(\bs{n}\fn{\s^*}\cdot\bs{u}_n\fn{\s^*}\Big)\Bigg\}_i\Bigg]
}
