\begin{appendix}\label{app:app}

\section{The number of CM elliptic curves  ordered by conductor}
In this appendix, we will give an upper bound for the number of $\Q$-isogenous classes of CM elliptic curves over $\Q$, when ordered by conductor.\footnote{For the number of CM elliptic curves ordered by naive height, see \cite[Theorem 1.3]{BaCa2025}.} We were unable to find a proof in the literature. Therefore, we include it in the appendix. We will keep the notation from earlier sections. 


\begin{theorem}\label{app:thm}
  Let $\mathcal{E}^{CM}(N)$ be the set of $\Q$-isogeny classes of CM elliptic curves over $\Q$ with conductor bounded by $N$. Then, 
  \[
  |\mathcal{E}^{CM}(N)|\ll N^{\frac{1}{2}}.
  \]
\end{theorem}
\begin{proof}
We first recall that  there are only 13  CM $j$-invariants taking values in $\Q$. For each such rational number $j$, we fix a representative $E$ for the $\ol{\Q}$-isomorphism class corresponding to $j$ such that $E$ has the minimal conductor. We denote by $E_0$ (resp. $E_{1728}$) for the representative with $j$-invariant 0 (resp. 1728), and by $E_1, \ldots, E_{11}$ for the rest of the $j$-invariants.
Now by \cite[III.10 Theorem 10.1  and X.2.  Theorem 2.2]{Si2009}, any $\Q$-isomorphism class of  CM elliptic curves over $\Q$ is in one of the following sets:
\begin{align}\label{eq: cm}
  & \{E_i^{\chi}: \ \chi: \Gal(\ol{\Q}/\Q)\to \Z/2\Z,  \text{ $\chi$ is primitive}, 1\leq i\leq 11\}; \\ 
& \{E_{1728}^{\chi}:  \chi: \Gal(\ol{\Q}/\Q)\to \Z/4\Z, \text{ $\chi$ is primitive}\}; \\ 
  & \{E_{0}^{ \chi}:  \chi: \Gal(\ol{\Q}/\Q)\to \Z/6\Z, \text{ $\chi$ is primitive}\}. 
\end{align}
Here, for each elliptic curve  $E$ and each Galois character  $\chi\in \Hom(\Gal(\ol{\Q}/\Q),\Aut(E))$, there is a unique twist $E^\chi \in H^1(\Gal(\ol{\Q}/\Q), \Aut(E))$  which  is defined explicitly by \cite[X.5 Proposition 5.4]{Si2009}. We say the character $\chi$ is primitive if $\chi$ factor through a cyclic Galois extension that gives rise  to a primitive Dirichlet character.  


Since any $\Q$-isogeny class in  $\mathcal{E}^{CM}(N)$  contains  at most $8$ $\Q$-isomorphism classes of elliptic curves \cite{Ke1982}, in order to bound $|\mathcal{E}^{CM}(N)|$, it suffices to bound the number of $\Q$-isomorphism classes of  CM elliptic curves over $\Q$ listed by (A.1)-(A.3). The original counting problem  amounts to counting the number of  primitive characters that lie in one of the sets:
\begin{align}
    & \{\chi: \Gal(\ol{\Q}/\Q)\to \Z/2\Z \; :\: \chi \text{ is primitive, } N_{E_i^{\chi}} \leq N,  1\leq i\leq 11\};\\
   & \{\chi: \Gal(\ol{\Q}/\Q)\to \Z/4\Z \; :\: \chi \text{ is primitive, } N_{E_{1728}^{ \chi}}\leq N \}; \\
  & \{\chi: \Gal(\ol{\Q}/\Q)\to \Z/6\Z \; :\: \chi \text{ is primitive, } N_{E_{0}^{ \chi}}\leq N \}.
\end{align}


Finally, by identifying the above elliptic curves $E$ (resp. $E^\chi$) with a newform $f$ (resp. $f^\chi$) of weight 2 and applying \cite[Proposition 14.20]{DuKo2000}, we obtain 
\[
N_{E_i^{\chi}}=N_{E_i}D_\chi^2 \quad  \text{ if $(D_\chi, N_{E_i})=1$},\]
where $D_\chi$ is the conductor of $\chi$. Therefore, if $(D_\chi, N_{E_i})= 1$, then   
\begin{equation}\label{app:condu-bound}
   N_{E_i^{\chi}}\leq N \Longrightarrow  D_\chi^2 \ll N^{\frac{1}{2}}, \quad \text{ for each } i\in \{0, 1728, 1, \ldots, 11\}. 
\end{equation}
If $(D_\chi, N_{E_i})\neq 1$, then since the set  $\{E_i\}_{\substack{1\leq i\leq 11,\\ i=0, 1728}}$ is finite and $\chi$ is primitive, the bound \eqref{app:condu-bound} still holds. 
Therefore, these sets  (A.4)-(A.6) are  all bounded by $O(N^{\frac{1}{2}})$.
This gives the desired bound of $ |\mathcal{E}^{CM}(N)|$.

