\texttt{s := new stack()}\;
\texttt{node := root}\;
\While{\textnormal{\texttt{node != nil}}}{%
    \texttt{s.push(node)}\;
    \texttt{node := node.left}\;
}
\While{\textnormal{\texttt{!s.empty}}}{%
    \texttt{node = s.pop()}\;
    \texttt{visit(node)}\;
    \texttt{node = node.right}\;
