        \node[state] (q0) {$q_0$};
        \node[state,right=of q0] (q1) {$q_1$};
        \draw[-latex] (q0) edge[bend left] node[above] {$\alpha|p_2$} (q1);
        \draw[-latex] (q1) edge[bend left] node[above] {$\alpha|p_2$} (q0);
        \draw[-latex] (q0) edge[loop left] node[left] {$\beta|p_1$} (q0);
