%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Local Fr\'{e}chet Regression}\label{Sec2}
Let $(\Omega, d)$ be a metric space. Consider a random pair $(X, Y) \sim F$, where $X$ takes values in $\mathbb{R}$ and $Y$ takes values in $\Omega$, and $F$ is the joint distribution of $(X, Y)$ on $\mathbb{R} \times \Omega$. Denote the marginal distributions of $X$ and $Y$ by $F_X$ and $F_Y$, respectively, and assume that the mean $\mu = \mathrm{E}[X]$ and variance $\Sigma = \mathrm{Var}(X) > 0$ exist. We also assume that the conditional distributions $F_{X|Y}$ and $F_{Y|X}$ exist.
In this general setting, $Y$ is referred to as a random object. In the classical regression problem where $\Omega = \mathbb{R}$, the goal is to estimate the conditional mean $m(x) = \mathrm{E}[Y|X = x]$.
This regression function can be characterized as $m(x) = \arg\min_{y \in \mathbb{R}} \mathrm{E}[d_E^2(Y, y)|X = x]$,
where $d_E$ denotes the Euclidean distance.
[\cite{MR3909947}] introduced the Fr\'echet regression function by generalizing this representation: replacing the Euclidean distance $d_E$ with a general metric $d$, and replacing $\mathbb{R}$ with a general metric space $\Omega$.
\begin{definition}[{\textit{Fr\'{e}chet regression function} [\cite{MR3909947}]}]\label{de1}
\begin{align}
m_{\oplus}(x) = \argmin_{\omega \in \Omega} M_{\oplus} (\omega, x), \quad \quad
M_{\oplus}(\cdot, x) = \mathrm{E}[d^2(Y, \cdot) | X = x].  \label{2.1}
\end{align}
\end{definition}
A nonparametric regression model used to estimate $m_{\oplus}(x)$ is the \textit{local F\'echet regression model} 
proposed by [\cite{MR3909947}].
In the classical regression setting where $(\Omega, d) = (\mathbb{R}, d_E)$, [\cite{MR1383587}] consider the following nonparametric regression model:
\begin{align}
Y = m(X) + \sigma(X) \varepsilon, \label{2.2}
\end{align}
where $\sigma^2(x) = \mathrm{Var}(Y \mid X = x)$, and the random variable $\varepsilon$ is independent of $X$, with \\
$\mathrm{E}[\varepsilon] = 0$ and $\mathrm{Var}(\varepsilon) = 1$.
Given an i.i.d. sample $(X_1, Y_1), \ldots, (X_n, Y_n)$ from model \eqref{2.2}, the local linear (LL) estimator [\cite{MR1193323}, \cite{MR1212173}] of $m(x)$
is given by $\hat{m}_{\mathrm{LL}}(x) = \hat{\beta}_0$, where
\begin{align*}
(\hat{\beta}_0, \hat{\beta}_1) = \arg\min_{\beta_0, \beta_1 \in \mathbb{R}} \frac{1}{n} 
\sum_{i = 1}^{n} K_h(X_i - x) (Y_i - \beta_0 - \beta_1 (X_i - x))^2, 
\end{align*}
with a kernel function $K$, bandwidth $h$, and $K_h(\cdot) = h^{-1} K(\cdot / h)$.\\
{[\cite{MR3909947}]} interpreted $\hat{\beta}_0$ as a weighted Fr\'echet mean:
\begin{align}
\tilde{l}(x) &= \mathrm{E}[s(X, x, h) Y] = \arg\min_{y \in \mathbb{R}} \mathrm{E}[s(X, x, h) d_E^2 (Y, y)], \label{2.3}
\end{align}
where
$s(X, x, h) = \frac{1}{\sigma_0^2} K_h(X - x) \left\{\mu_2 - \mu_1 (X - x)\right\}$,\ $\mu_j = \mathrm{E}[K_h(X - x)(X - x)^j]$,\\
$(j = 0, 1, 2),\  \sigma_0^2 = \mu_0 \mu_2 - \mu_1^2$, 
and then extended the concept of local regression to random objects $Y \in \Omega$.
\begin{definition}[{\textit{Local Fr\'echet Regression model} [\cite{MR3909947}]}]\label{de2}
\begin{align}
\tilde{l}_{\oplus}(x) = \arg\min_{\omega \in \Omega} \tilde{L}_n(\omega), \quad 
\tilde{L}_n(\omega) = \mathrm{E}[s(X, x, h) d^2(Y, \omega)], \label{2.4}
\end{align}
where the dependency on $n$ is through the bandwidth sequence $h = h_n$.
\end{definition}

Given i.i.d. observations $(X_1, Y_1), \ldots, (X_n, Y_n) \overset{\mathrm{i.i.d.}}{\sim} F$, $\tilde{l}_{\oplus}(x)$ can be estimated using
\[
\hat{\mu}_j = \frac{1}{n} \sum_{i = 1}^{n} K_h(X_i - x) (X_i - x)^j, (j = 0, 1, 2), \quad \hat{\sigma}_0^2 = \hat{\mu}_0 \hat{\mu}_2 - \hat{\mu}_1^2,
\]
and the empirical weight function
\[
s_{in}(x, h) = \frac{1}{\hat{\sigma}_0^2} K_h(X_i - x) \left[\hat{\mu}_2 - \hat{\mu}_1 (X_i - x)\right].
\]

\begin{definition}[{\textit{LFR estimator} [\cite{MR3909947}]}]\label{de3}
\begin{align}
\hat{l}_{\oplus}(x) = \argmin_{\omega \in \Omega} \hat{L}_n(\omega), \quad 
\hat{L}_n(\omega) = \frac{1}{n} \sum_{i = 1}^{n} s_{in}(x, h) d^2(Y_i, \omega). \label{2.5}
\end{align}
\end{definition}
