%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\section{Local Fr\'echet Regression on a Hilbert Space}\label{Sec3}
In general metric spaces, algebraic structures such as addition and scalar multiplication, which are defined in vector spaces, are not necessarily available. Moreover, because the Fr\'echet regression function $m_{\oplus}(\cdot)$ is defined without assuming a structural model like \eqref{2.2}, it is extremely difficult to derive the asymptotic distribution of the LFR estimator. Even in [\cite{MR3909947}], the discussion is limited to convergence rates depending on the metric. Furthermore, the minimization problems in \eqref{2.4} and \eqref{2.5} require the computation of distances between points in the metric space and generally cannot be solved analytically.
On the other hand, when $\Omega$ is a Hilbert space, the solution $\tilde{l}_{\oplus}(x)$ to the minimization problem exists uniquely, and the estimator $\hat{l}_{\oplus}(x)$ can be explicitly computed.
In the following, for Hilbert space $\mathcal{H}$, 
We denote by $\langle \cdot , \cdot \rangle_{\mathcal{H}}$ the inner product on $\mathcal{H}$. 
The norm is given by $\| \omega \|_{\mathcal{H}} := \langle \omega , \omega \rangle^{1/2}_{\mathcal{H}}$, and the distance between two points $x, y \in \mathcal{H}$ is defined as $d(x, y) := \| x - y \|_{\mathcal{H}} = \langle x - y, x - y \rangle^{1/2}_{\mathcal{H}}$. 
Assume further that $\mathbb{E}[\| Y \|_{\Omega}^2] < \infty$ when $\Omega$ is a Hilbert space (i.e., $\Omega = \mathcal{H}$).

\begin{proposition}\label{pr1}
Suppose that $\Omega$ is a Hilbert space and $\mathbb{E}[\| Y \|_{\Omega}^2] < \infty$. Then, for any
fixed $x \in \mathbb{R}$, the minimizer $\tilde{l}_{\oplus}(x)$ in \eqref{2.4} exists and is unique.
\end{proposition}

\begin{proposition}\label{pr2}
Suppose that $\Omega$ is a Hilbert space. Then, for any fixed $x \in \mathbb{R}$,
the minimizer $\hat{l}_{\oplus}(x)$ in \eqref{2.5} is explicitly given by
\begin{align}
\hat{l}_{\oplus}(x) = \frac{1}{n} \sum_{i=1}^{n} s_{in}(x, h) Y_i. \label{3.1}
\end{align}
\end{proposition}

We extend the nonparametric regression model \eqref{2.2} for real-valued response variables to the case where $\Omega$ is a general Hilbert space, and derive the asymptotic distribution of the LFR estimator.
\begin{definition}[\textit{Nonparametric Regression Model for Hilbert Space-Valued Response Variables}]\label{de4}
\begin{align}
Y = m_{\oplus}(X) + \sigma(X) \varepsilon, \label{3.2}
\end{align}
where $\varepsilon$ is a random element in Hilbert space $\Omega$, independent of $X$, satisfying $\mathrm{E}[\langle \varepsilon, \omega \rangle_{\Omega}] = 0$ for all $\omega \in \Omega$, and 
$\mathrm{E}[ \| \varepsilon \|_{\Omega}^2 ] = \mathrm{E}[ \langle \varepsilon, \varepsilon \rangle_{\Omega} ] = 1$. 
Also, $\sigma^2(x) = \mathrm{E}[ \| Y - m_{\oplus}(x) \|_{\Omega}^2 \mid X = x ]$. 
\end{definition}
Then, $m_{\oplus}(\cdot)$ in Definition \ref{de4} coincides with $m_{\oplus}(\cdot)$ in Definition \ref{de1} 
(see SUPPLEMENTARY MATERIAL \hyperref[S1]{S.1} for details).
The regression model \eqref{3.2} is an extension of the regression model \eqref{2.2} to Hilbert spaces. 
By considering model \eqref{3.2}, and based on the asymptotic theory of local polynomial regression~[\cite{MR1383587}], we can derive the asymptotic normality of $\hat{l}_{\oplus}(x)$ when $\Omega$ is a real Hilbert space. We impose the following assumptions for a fixed $x \in \mathbb{R}$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{description}
\item[(N1)]
$X$ has a density function $f$, and $f$ is continuous and positive in some neighborhood $N_x$ of $x$.

\item[(N2)]
The kernel $K$ is a symmetric probability density function with bounded support, and both $\int u^2 K(u) \, du$ and $\int K^2(u) \, du$ are finite.

\item[(N3)]
$h = h_n > 0$ satisfies $h \to 0$, $nh \to \infty$, and $nh^5 \to 0$ as $n \to \infty$.

\item[(O1)]
For all $\omega \in \Omega$, the function $m_\omega(\cdot) = \langle m_{\oplus}(\cdot), \omega \rangle_{\Omega}$ is twice continuously differentiable on $N_x$.

\item[(O2)]
For all $\omega \in \Omega$, $\sigma^2(\cdot) \, \mathrm{E}[\langle \varepsilon, \omega \rangle^2_{\Omega}]$ is continuous and positive on $N_x$.

\item[(O3)]
For all $\omega \in \Omega$, $\mathrm{E}[\langle Y, \omega \rangle^4_{\Omega} \mid X = \cdot]$ is bounded on $N_x$.
\end{description}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
(N1)--(N3) are conditions on the density of $X$, the kernel, and the bandwidth, which are required for the asymptotic normality of the local linear (LL) estimator [\cite{MR1193323}, \cite{MR1212173}] for real-valued responses. 
(O1)--(O3) are the conditions on $m(\cdot)$ and $\sigma(\cdot)$ in model \eqref{2.2}, adapted to the model \eqref{3.2}.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}\label{th1}
Let $\Omega$ be a real Hilbert space, and suppose that a random sample $(X_1, Y_1), \ldots, (X_n, Y_n)$ 
is drawn from the model \eqref{3.2}. 
If (N1)--(N3) and (O1)--(O3) hold, then for any $\omega \in \Omega$, the following holds:
\begin{align*}
& \sqrt{nh} \left\{  \left \langle  \hat{l}_\oplus(x) - m_\oplus(x) , \omega \right \rangle _\Omega -  
 \left( \frac{\int u^2 K(u) \, du}{2} \cdot \frac{\partial ^2}{\partial x^2} \left \langle m_\oplus(x) , \omega \right \rangle _\Omega \right) h^2 \right\} \\
 {} \leadsto & \; \mathcal{N} \left( 0, \; \frac{\int K^2(u) \, du}{f(x)} \sigma^2(x) \, \mathrm{E}[\langle \varepsilon, \omega \rangle_\Omega^2] \right).
\end{align*}

In particular, if we take $\omega = m_\oplus(x)$, we obtain the following expression :
\begin{align*}
& \sqrt{nh} \left\{ \left \langle  \hat{l}_\oplus(x), m_\oplus(x) \right \rangle_\Omega - \| m_\oplus(x) \|_\Omega^2 
- \left( \frac{\int u^2 K(u) \, du}{2} \cdot\left.  \frac{\partial ^2}{\partial x^2} 
\left \langle m_\oplus(x) , \omega \right  \rangle _\Omega \right|_{\omega = m_{\oplus}(x)} \right) h^2 \right\} \\
{} \leadsto & \; \mathcal{N} \left( 0, \; \frac{\int K^2(u) \, du}{f(x)} \sigma^2(x) \, \mathrm{E}[\langle \varepsilon, m_\oplus(x) \rangle_\Omega^2] \right).
\end{align*}\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
If $\Omega$ is separable, then there exists a countable orthonormal basis $\{ e_i \}_{i = 1}^{\infty} \subset \Omega$. In this case, the difference 
$\hat{l}_\oplus(x) - m_\oplus(x)$ can be represented as:
\[
\hat{l}_\oplus(x) - m_\oplus(x) = \sum_{i = 1}^{\infty} a_{in}(x, X_1, \ldots, X_n) e_i, \quad a_{in}(x, X_1, \ldots, X_n) \in \mathbb{R}.
\]
Taking $\omega = e_j$, we obtain
\[
\left\langle \hat{l}_\oplus(x) - m_\oplus(x), e_j \right\rangle_{\Omega} = a_{jn}(x, X_1, \ldots, X_n),
\]
and hence the asymptotic normality of the $j$-th coefficient $a_{jn}(x, X_1, \ldots, X_n)$ of $\hat{l}_\oplus(x) - m_\oplus(x)$ is obtained.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\mbox{}\\

Next, using the result of Theorem \ref{th1}, we consider constructing a confidence region for $m_{\oplus}(x)$ on Hilbert space.
To derive the convergence rate of the estimator $\hat{l}_{\oplus}(x)$, we make the following assumptions similarly to [\cite{MR3909947}]. For simplicity, we assume that the marginal density $f$ of $X$, within the joint distribution $F$, has unbounded support, and 
consider a fixed point $x \in \mathbb{R}$ such that $f(x) > 0$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{description}
\item[(P1)] Let $B_\delta(m_{\oplus}(x)) \subset \Omega$ be the ball of radius $\delta$ centered at $m_{\oplus}(x)$ and
$N(\eta, B_\delta(m_{\oplus}(x)), d)$ be its covering number using balls of size $\eta$. Then
\begin{align*}
\int_{0}^{1} \sqrt{1 + \log N(\delta \eta, B_\delta(m_{\oplus}(x)), d)} \, d\eta = O(1) \ \  \quad \text{as } \delta \to 0.
\end{align*}

\item[(K0)] The kernel $K$ is a probability density function symmetric around zero. Furthermore, defining $K_{ij} = \int_{\mathbb{R}} K^i(u) u^j \,du$,  
$|K_{14}|$, $|K_{44}|$, and $|K_{26}|$ are finite.

\item[(L0)] 
The object $m_{\oplus}(x)$ exists and is unique. For all $n$, $\tilde{l}_{\oplus}(x)$ and $\hat{l}_{\oplus}(x)$ exist and are unique, 
the latter almost surely. Additionally, for any $\varepsilon > 0$, 
\[
\inf_{d(\omega, m_{\oplus}(x)) > \varepsilon} \left \{ M_{\oplus}(\omega, x) - M_{\oplus}(m_{\oplus}(x), x) \right \} > 0, 
\]
\[
\liminf_{n} \inf_{d(\omega, \tilde{l}_{\oplus}(x)) > \varepsilon} \left \{ \tilde{L}_n(\omega) - \tilde{L}_n(\tilde{l}_{\oplus}(x)) \right \} > 0.
\]

\item[(L1)] The marginal density $f$ of $X$, as well as the conditional densities $g_y$ of $X|Y = y$, exist and are twice continuously differentiable,
the latter for all $y \in \Omega$, and $\sup_{x,y} |g''_y(x)| < \infty$. Additionally, for any open $U \subset \Omega$, $\int_U dF_{Y|X}(y|x)$ is continuous 
as a function of $x$.

\item[(L2)]
There exists $\eta_1 > 0, C_1 > 0$ and $1 < \beta_1 < 2$ such that
\[
M_{\oplus}(\omega, x) - M_{\oplus}(m_{\oplus}(x), x) \geq C_1d(\omega, m_{\oplus}(x))^{\beta_1}, 
\]
provided $d(\omega, m_{\oplus}(x)) < \eta_1$.
\item[(L3)]
There exists $\eta_2 > 0, C_2 > 0$ and $1 < \beta_2 < 2$ such that
\[
\liminf_{n} \left\{ \tilde{L}_n(\omega) - \tilde{L}_n(\tilde{l}_{\oplus}(x))  \right\} \geq C_2d(\omega, \tilde{l}_{\oplus}(x))^{\beta_2},
\]
provided $d(\omega, m_{\oplus}(x)) < \eta_2$.

\end{description}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
(P1) and (L0) are based on empirical process theory and are used to control the behavior of the objective function near the minimizer.
(K0) and (L1) are standard assumptions in local regression estimation.
(L2) and (L3) provide the convergence rates between $m_{\oplus}(x)$ and $\tilde{l}_{\oplus}(x)$, and between $\tilde{l}_{\oplus}(x)$ and $\hat{l}_{\oplus}(x)$, respectively. 
Since the convergence is with respect to $(nh)^{1/2}$, we additionally assume $\beta_1, \beta_2 < 2$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Fix some $\alpha \in (0,1)$ and $m_{\oplus}(x) \in \Omega$, and define
\begin{align*}
    &B_x = \left( \frac{\int u^2 K(u) \, du}{2} \cdot
    \left. \frac{\partial^2}{\partial x^2} 
    \left\langle m_{\oplus}(x), \omega \right\rangle_{\Omega} 
    \right|_{\omega = m_{\oplus}(x)} \right) h^2 \quad \text{(asymptotic bias)}, \\
    &V_x = \frac{\int K^2(u) \, du}{f(x)} \sigma^2(x) \, \mathrm{E}[\left\langle \varepsilon, m_{\oplus}(x) \right\rangle_{\Omega}^2]
    \quad \text{(asymptotic variance)}.
\end{align*}

\begin{corollary}\label{cr1}
Assume the conditions of Theorem \ref{th1}, and suppose that consistent estimators $\hat{B}_x$ and $\hat{V}_x$ of $B_x$ and $V_x$, respectively, satisfy
\[
\hat{B}_x = B_x + o_P \left((nh)^{-1/2}\right), \quad \hat{V}_x = V_x + o_P (1).
\]
Additionally, assume conditions (P1), (K0), and (L0)--(L3) hold. Then, define
\begin{align*}
CI_{\alpha} &:= \left\{ \omega \in \Omega \;\middle|\; 
-2\hat{B}_x - 2\sqrt{\frac{\hat{V}_x}{nh}}\, z_{\alpha/2}
\le 
\left\| \omega - \hat{l}_{\oplus}(x) \right\|_{\Omega}^2
\le 
-2\hat{B}_x + 2\sqrt{\frac{\hat{V}_x}{nh}}\, z_{\alpha/2}
\right\},
\end{align*}
it follows that
\[
P\left( m_{\oplus}(x) \in CI_{\alpha} \right) \to 1 - \alpha \quad \text{as } n \to \infty.
\]
\end{corollary}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
By applying the result of Corollary \ref{cr1}, we obtain a confidence region for $m_{\oplus}(x)$ in the form of a spherical region centered at $\hat{l}_{\oplus}(x)$, when $\Omega$ is a real Hilbert space.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\mbox{}\\

Nonparametric estimation of $m_\oplus(\cdot)$ for response variables taking values in a general metric space $(\Omega, d)$ has predominantly been conducted using the Nadaraya-Watson-type estimator 
[\cite{steinke2008non}, \cite{hein2009robust}, \cite{davis2010population}, \cite{MR2736019}], which is defined as:
\begin{align}
\hat{m}^{\mathrm{NW}}_\oplus(x) = \argmin_{\omega \in \Omega} \frac{1}{n} \sum_{i = 1}^{n} K_h(X_i - x) d^2(Y_i, \omega). \label{3.3}
\end{align}

If $\Omega$ is a Hilbert space, the minimizer in \eqref{3.3} can be obtained explicitly, just as with the LFR estimator. For an i.i.d. sample $(X_1, Y_1), \ldots, (X_n, Y_n) \overset{\mathrm{i.i.d.}}{\sim} F$, we have
\begin{align}
\hat{m}^{\mathrm{NW}}_\oplus(x) 
&= \argmin_{\omega \in \Omega} \frac{1}{n} \sum_{i = 1}^{n} K_h(X_i - x) \| Y_i - \omega \|_\Omega^2 
= \frac{\sum_{i = 1}^{n} K_h(X_i - x) Y_i}{\sum_{j = 1}^{n} K_h(X_j - x)}. \label{3.4}
\end{align}

Given an arbitrary $\omega_0 \in \Omega$, we consider two estimators of $\langle m_\oplus(x), \omega_0 \rangle_\Omega$, namely, 
$\langle \hat{l}_\oplus(x), \omega_0 \rangle_\Omega$ and 
$\langle \hat{m}^{\mathrm{NW}}_\oplus(x), \omega_0 \rangle_\Omega$. 
We compare their conditional biases and variances, as summarized in Table~\ref{table1}. 
(See SUPPLEMENTARY MATERIAL \hyperref[S2]{S.2} for detailed derivations.)

\begin{table}
\centering
\caption{Conditional bias and variance of estimators for $\langle m_\oplus(x), \omega_0 \rangle$: Comparison between local Fr\'echet regression (LFR) and Nadaraya-Watson (NW) estimators.}
\label{table1}
\begin{tabular}{lcc}
\hline
\textbf{Method} & \textbf{Bias} & \textbf{Variance} \\ \hline\hline
\textbf{NW}   
& $\frac{\int u^2 K(u) du}{2}  \left \{  \frac{\partial ^2}{\partial x^2} \left \langle m_\oplus(x) , \omega_0   \right  \rangle _\Omega + 
2 \frac{f'(x) \frac{\partial}{\partial x} \left \langle m_\oplus(x) , \omega_0   \right  \rangle _\Omega } {f(x)} \right \} h^2$
& $\frac{\int K^2(u) du}{f(x) nh} \sigma ^2 (x)  \mathrm{E}[\langle \varepsilon, \omega_0 \rangle _\Omega ^2]  $  
\\ & $ \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \quad+ o_{P}(h^2)$ & $\qquad \qquad \qquad \qquad + o_{P}((nh)^{-1})$
\\  \hline
\textbf{LFR}    
& $\frac{\int u^2 K(u) du}{2} \cdot \frac{\partial ^2}{\partial x^2} \left \langle m_\oplus(x) , \omega_0   \right  \rangle _\Omega h^2$
& $\frac{\int K^2(u) du}{f(x) nh} \sigma ^2 (x)  \mathrm{E}[\langle \varepsilon, \omega_0 \rangle _\Omega^2]  $  
\\ & $\qquad \qquad \qquad \qquad \qquad \qquad  + o_{P}(h^2)$ & $\qquad \qquad \qquad \qquad + o_{P}((nh)^{-1})$
  \\ \hline
\end{tabular}
\end{table}

As shown in Table~\ref{table1}, the bias terms of both NW and LFR estimators are of the same order, 
but the NW estimator includes an additional term:
$\int u^2 K(u) \, du \cdot \frac{f'(x)}{f(x)} \cdot \frac{\partial}{\partial x} \langle m_\oplus(x), \omega_0 \rangle_\Omega$,
which does not appear in the bias of the LFR estimator.
As for the variance, the leading terms are identical for both estimators.
In LFR, the bias depends on the second derivative $\frac{\partial^2}{\partial x^2} \langle m_\oplus(x), \omega_0 \rangle_\Omega$, whereas in NW, the bias also depends on the first derivative $\frac{\partial}{\partial x} \langle m_\oplus(x), \omega_0 \rangle_\Omega$, as well as $f'(x)$ and $f(x)$. 
Therefore, the absolute value of the bias for the NW estimator tends to be larger in regions where the density $f(x)$ is small 
or where the derivatives of $\langle m_\oplus(\cdot), \omega_0 \rangle_\Omega$ or $f$ are large.
