\section{Local Fr\'echet Regression via RKHS embedding}\label{Sec4}
In Section \ref{Sec3}, we showed that when $\Omega$ is a Hilbert space, the LFR estimator can be obtained explicitly, and its asymptotic distribution can be derived using the inner product.
In this section, based on the concept of kernel methods[\cite{scholkopf2002learning}], we consider mapping data lying in a metric space $\Omega$ (which is not necessarily a Hilbert space) into a Reproducing Kernel Hilbert Space (RKHS) using a positive definite kernel, and then performing LFR in the RKHS. Furthermore, by mapping the obtained LFR estimator in the RKHS back to the original metric space using the distance function, we obtain a new estimator of the true regression function $m_{\oplus}(\cdot)$ based on LFR in the RKHS. This approach enables regression analysis even for data in metric spaces where distance computations are intractable and direct LFR estimation is not feasible.

Let $k : \Omega \times \Omega \to \mathbb{R}$ be a positive definite kernel on $\Omega$, and let $H_k$ denote the RKHS associated with the kernel $k$. Define the feature map $\Phi : \Omega \rightarrow H_k$ by $\Phi(\omega) = k(\cdot, \omega)$, i.e., $\Phi$ maps a point $\omega \in \Omega$ to the function $k(\cdot, \omega) \in H_k$. For any $f \in H_k$ and $\omega \in \Omega$, the identity 
$\langle f, k(\cdot, \omega) \rangle_{H_k} = f(\omega)$ holds, which is known as the reproducing property.
We assume the following condition:
\begin{align*}
\mathrm{E}[ \| \Phi(Y) \|_{H_k}^2 ] = \mathrm{E}[ k(Y, Y) ] < \infty.
\end{align*}
By applying the map $\Phi$ to the data $Y_i \in \Omega$, $i = 1, \ldots, n$, we obtain the transformed data in the RKHS as
\[
\{ \Phi(Y_i) \}_{i = 1}^{n} = \{ k(\cdot , Y_i) \}_{i = 1}^{n}.
\]
Given the transformed response variable $\Phi(Y) \in H_k$ and a real-valued explanatory variable $X \in \mathbb{R}$, we consider the following nonparametric regression model.
\begin{definition}[\textit{Nonparametric Regression Model for Responses in $H_k$}]\label{de5}
\begin{align}
\Phi(Y) = m_{\oplus}^{H_k}(X) + \sigma(X) \varepsilon, \label{4.1}
\end{align}
where $\varepsilon$ is a random element in $H_k$, independent of $X$, satisfying
$\mathrm{E}[\langle \varepsilon, f \rangle_{H_k}] = 0$ for all $f \in H_k$, and
$\mathrm{E}[\| \varepsilon \|^2_{H_k}] = \mathrm{E}[\langle \varepsilon, \varepsilon \rangle_{H_k}] = 1.$
Also, $\sigma^2(x) = \mathrm{E}[\| \Phi(Y) - m_{\oplus}^{H_k}(X) \|^2_{H_k} | X = x]$.
\end{definition}

The function $m_{\oplus}^{H_k}(X) \in H_k$ is the Fr\'echet regression function for explanatory variable $X \in \mathbb{R}$ and response variable $\Phi(Y) \in H_k$. If the positive definite kernel $k$ satisfies
\begin{align}
\argmin_{f \in H_k} \mathrm{E}[\| \Phi(Y) - f \|^2_{H_k} | X = x] = \Phi(m_{\oplus}(x)), \label{4.2}
\end{align}
then we have $m_{\oplus}^{H_k}(x) = \Phi(m_{\oplus}(x))$.
Equation \eqref{4.2} holds when the mapping $\Phi$ preserves the ordering of distances on $\Omega$, i.e., for  $x_1, y_1, x_2, y_2 \in \Omega$,
$d(x_1, y_1) < d(x_2, y_2) \Rightarrow \| \Phi(x_1) - \Phi(y_1) \|_{H_k} < \| \Phi(x_2) - \Phi(y_2) \|_{H_k}$,
and when the noise in $Y$ around the true regression function $m_{\oplus}(x)$ is small. In what follows, we consider such kernels $k$.
From model \eqref{4.1}, given a random sample $(X_1, \Phi(Y_1)), \ldots, (X_n, \Phi(Y_n))$, we consider the LFR estimator $\hat{l}_{\oplus}^{H_k}(x)$. Since $H_k$ is a Hilbert space, it follows from Proposition \ref{pr2} that
\begin{align}
\hat{l}_{\oplus}^{H_k}(x) = n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \Phi(Y_i). \label{4.3}
\end{align}
We associate $\hat{l}_{\oplus}^{H_k}(x) \in H_k$ with a point in $\Omega$ as the solution to the following minimization problem, and define it as $\hat{l}_{\oplus}^{k}(x)$:
\begin{align}
\hat{l}_{\oplus}^{k}(x) &= \argmin_{\omega \in \Omega} \| \hat{l}_{\oplus}^{H_k}(x) - \Phi(\omega) \|^2_{H_k} \label{4.4} \\ 
&= \argmin_{\omega \in \Omega} \Big\{ k(\omega, \omega) - 2n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) k(Y_i, \omega) \notag \\
& \qquad \qquad \qquad \qquad \quad+ n^{-2} \sum_{i = 1}^{n} \sum_{j = 1}^{n} s_{in}(x, h) s_{jn}(x, h) k(Y_i, Y_j) \Big\}. \notag
\end{align}
The transformation from the first line to the second and third in \eqref{4.4} uses the reproducing property of the kernel, i.e., $\forall x, y \in \Omega$, $\langle \Phi(x), \Phi(y) \rangle_{H_k} = k(x, y)$.
By transforming data $Y_i \in \Omega$ into $H_k$ via $\Phi$, we can consider local Fr\'echet regression in $H_k$. The resulting LFR estimator $\hat{l}_{\oplus}^{H_k}(x)$ is then mapped back to $\Omega$ using \eqref{4.4}, yielding an estimator $\hat{l}_{\oplus}^{k}(x)$ for $m_{\oplus}(x)$.
We refer to the estimator \eqref{4.4}, which is based on the positive definite kernel $k$, as the LFR$^k$ estimator.
Since equation \eqref{4.4} does not involve the distance $d$ on the metric space $\Omega$, it enables obtaining an LFR-based estimator on $\Omega$ even in cases where the structure of $\Omega$ is complex and solving the minimization problem \eqref{2.5} directly is intractable.
For simplicity, we assume that the marginal density $f$ of $X$, within the joint distribution $F$, has unbounded support and consider a fixed point $x \in \mathbb{R}$ such that $f(x) > 0$.
To establish the consistency of $\hat{l}_{\oplus}^{k}(x)$ for $m_{\oplus}(x)$, we impose the following assumptions.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{description}
\item[(S1)] The metric space $(\Omega, d)$ is compact.

\item[(S2)] There exists a constant $C > 0$ such that for all $\omega_1, \omega_2 \in \Omega$,
\[
\| \Phi(\omega_1) - \Phi(\omega_2) \|_{H_k} \leq C \, d(\omega_1, \omega_2).
\]

\item[(S3)] There exists $M > 0$ such that for all $\omega \in \Omega$,
\[
\| \Phi(\omega) \|_{H_k} = k(\omega, \omega)^{1/2} < M.
\]

\item[(S4)] The object $m_{\oplus}(x)$ exists and is unique. Additionally, defining\\
$M_{\oplus}^{H_k}(f, x) = \mathrm{E}[ \| \Phi(Y) - f \|_{H_k}^2 | X = x ]$,\ \ 
$\tilde{L}_n^{H_k}(f) = \mathrm{E}[ s(X, x, h) \| \Phi(Y) - f \|_{H_k}^2 ]$,\\
$\tilde{l}_{\oplus}^{H_k}(x) = \arg\min_{f \in H_k} \tilde{L}_n^{H_k}(f)$,
assume that for any $\varepsilon > 0$,
\[
\inf_{\| f - \Phi(m_{\oplus}(x)) \|_{H_k} > \varepsilon} \left\{ M_{\oplus}^{H_k}(f, x) - M_{\oplus}^{H_k}(\Phi(m_{\oplus}(x)), x) \right\} > 0,
\]
\[
\liminf_{n} \inf_{\| f - \tilde{l}_{\oplus}^{H_k}(x) \|_{H_k} > \varepsilon} \left\{ \tilde{L}_n^{H_k}(f) - \tilde{L}_n^{H_k}(\tilde{l}_{\oplus}^{H_k}(x)) \right\} > 0.
\]

\item[(S5)] Defining
$\tilde{L}_n^k(\omega) = \| \tilde{l}_{\oplus}^{H_k}(x) - \Phi(\omega) \|_{H_k}^2$, 
$\tilde{l}_{\oplus}^k(x) = \arg\min_{\omega \in \Omega} \tilde{L}_n^k(\omega)$,
assume that for all $n \in \mathbb{N}$, both $\tilde{l}_{\oplus}^k(x)$ and $\hat{l}_{\oplus}^k(x)$ exist
and are unique, the latter almost surely. Additionally, for any $\varepsilon > 0$,
\[
\liminf_n \inf_{d(\omega, \tilde{l}_{\oplus}^k(x)) > \varepsilon} \left\{ \tilde{L}_n^k(\omega) - \tilde{L}_n^k(\tilde{l}_{\oplus}^k(x)) \right\} > 0.
\]
\end{description}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Since any compact metric space is separable, assumption (S1) implies that $H_k$ is separable by Lemma 4.33 in [\cite{MR2450103}].  
Assumptions (S2) and (S3) ensure that the distance between two functions in $H_k$, obtained by mapping two elements from $\Omega$ via $\Phi$, can be controlled by the distance between those original points in $\Omega$, and that the norm of the mapped functions is uniformly bounded, respectively.  
Assumptions (S4) and (S5) are based on the theory of M-estimators, and they control the behavior of the objective functions $M_{\oplus}^{H_k}$, $\tilde{L}_n^{H_k}$, and $\tilde{L}_n^k$ around their respective minimizers. Under these assumptions, we obtain the following result:
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}\label{th2}
If (K0), (L1), and (S1)--(S5) hold, and if $h = h_n \to 0$ and $nh^4 \to \infty$. then
\begin{align*}
d(m_{\oplus}(x), \hat{l}_{\oplus}^{k}(x)) = o_{P}(1).
\end{align*}
\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Even when the metric space $\Omega$ is so complex that computing distances is difficult and LFR estimators cannot be obtained directly from \eqref{2.5}, one can always explicitly obtain the LFR estimator $\hat{l}_{\oplus}^{H_k}(x)$ in the Hilbert space $H_k$ by applying the mapping $\Phi$ to the data $Y_i \in \Omega$, $i = 1, \ldots, n$.  
Theorem \ref{th2} shows that, under appropriate assumptions, the LFR$^k$ estimator $\hat{l}_{\oplus}^{k}(x)$, which corresponds to $\hat{l}_{\oplus}^{H_k}(x)$ mapped back onto $\Omega$, serves as a consistent estimator for $m_{\oplus}(x)$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\mbox{} \\

Next, we consider constructing a confidence region on $\Omega$ using the result of Theorem \ref{th1}.  
By the reproducing property of the positive definite kernel, for any $g \in H_k$, we have:
\begin{align*}
  \left \langle  \hat{l}_\oplus ^{H_k}(x) - m_\oplus ^{H_k}(x) ,  g  \right \rangle_{H_k} &=
\left \langle  n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \Phi(Y_i) -  \Phi(m_{\oplus}(x)), \ g \right \rangle _{H_k} \\
&= n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) g(Y_i) -  g(m_{\oplus}(x)).
\end{align*}
We impose the following assumptions (Q1)--(Q3), which correspond to assumptions (O1)--(O3) in Theorem \ref{th1}.
\begin{description}
\item[(Q1)]
For all $g \in H_k$, the function $g(m_{\oplus}(\cdot))$ is twice continuously differentiable on $N_x$.
\item[(Q2)]
For all $g \in H_k$, the function $\sigma^2(\cdot) \mathrm{E}[\langle \varepsilon, g \rangle_{H_k}^2]$ is continuous and positive on $N_x$.
\item[(Q3)]
For all $g \in H_k$, the conditional fourth moment $\mathrm{E}[g(Y)^4 \mid X = \cdot]$ is bounded on $N_x$.
\end{description}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}\label{th3}
Suppose that a random sample $(X_1, \Phi(Y_1)), \ldots, (X_n, \Phi(Y_n))$ is drawn from model \eqref{4.1}.  
If (N1)--(N3) and (Q1)--(Q3) hold, then for any $g \in H_k$, the following holds:
\begin{align*}
& \sqrt{nh} \Bigg\{ \left \langle \hat{l}_\oplus^{H_k}(x) - m_\oplus^{H_k}(x), g \right \rangle_{H_k}
- \left( \frac{\int u^2 K(u) \, du}{2} \cdot \frac{\partial^2}{\partial x^2} g(m_\oplus(x)) \right) h^2 \Bigg\} \\
= & \sqrt{nh} \Bigg\{ n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) g(Y_i) - g(m_\oplus(x))
- \left( \frac{\int u^2 K(u) \, du}{2} \cdot \frac{\partial^2}{\partial x^2} g(m_\oplus(x)) \right) h^2 \Bigg\} \\
\leadsto & \ \mathcal{N} \left( 0, \ \frac{\int K^2(u) \, du}{f(x)}  \sigma^2(x) \, \mathrm{E}[\langle \varepsilon, g \rangle_{H_k}^2] \right).
\end{align*}
In particular, for $\omega \in \Omega$, taking $g = \Phi(\omega) = k(\cdot, \omega)$ gives:
\begin{align*}
& \sqrt{nh} \Bigg\{ n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) k(\omega, Y_i) - k(\omega, m_{\oplus}(x))  - \left( \frac{\int u^2 K(u) \, du}{2} \cdot \frac{\partial^2}{\partial x^2} k(\omega, m_{\oplus}(x)) \right) h^2 \Bigg\} \\
\leadsto & \ \mathcal{N} \left( 0, \ \frac{\int K^2(u) \, du}{f(x)} \sigma^2(x) \, \mathrm{E}[\varepsilon(\omega)^2] \right).
\end{align*}
\end{theorem}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Fix some $\alpha \in (0,1)$ and $m_{\oplus}(x) \in \Omega$, and define
\begin{align*}
&B_x^{H_k} = \left( \frac{\int u^2 K(u) \, du}{2} \cdot
\left. \frac{\partial^2}{\partial x^2} k(\omega, m_{\oplus}(x)) \right|_{\omega = m_{\oplus}(x)} \right) h^2 
\quad \text{(asymptotic bias)}, \\
&V_x^{H_k} = \frac{\int K^2(u) \, du}{f(x)} \, \sigma^2(x) \, \mathrm{E}[\varepsilon(m_{\oplus}(x))^2]
\quad \text{(asymptotic variance)}.
\end{align*}

\begin{corollary}\label{cr2}
Assume the conditions of Theorems \ref{th2} and \ref{th3}, and suppose that consistent estimators 
$\hat{B}_x^{H_k}$ and $\hat{V}_x^{H_k}$ satisfy
\[
\hat{B}_x^{H_k} = B_x^{H_k} + o_P \left((nh)^{-1/2}\right), \quad 
\hat{V}_x^{H_k} = V_x^{H_k} + o_P (1).
\]
Additionally, assume the analogues of (P1), (K0), and (L0)--(L3) hold in the reproducing kernel Hilbert space induced by the feature map $\Phi: \Omega \to H_k$.
Then, define
\begin{align*}
CI_{\alpha} := \left\{ \omega \in \Omega \;\middle|\; 
-2\hat{B}_x^{H_k} - 2\sqrt{\frac{\hat{V}_x^{H_k}}{nh}} \, z_{\alpha/2}
\le 
\left\| \Phi(\omega) - \hat{l}_{\oplus}^{H_k}(x) \right\|_{H_k}^2
\le 
-2\hat{B}_x^{H_k} + 2\sqrt{\frac{\hat{V}_x^{H_k}}{nh}} \, z_{\alpha/2}
\right\},
\end{align*}
it follows that
\begin{align*}
P \left( m_{\oplus}(x) \in CI_{\alpha} \right) \to 1 - \alpha, \ \ 
P\left( \hat{l}_{\oplus}^{k}(x) \in CI_{\alpha} \right) \to 1 - \alpha \quad \text{as } n \to \infty.
\end{align*}
\end{corollary}

By applying the result of Corollary \ref{cr2}, we can construct a confidence region for $m_{\oplus}(x)$ in the original metric space $\Omega$ where the data are distributed.
