\subsection{Propositions \ref{pr1}, \ref{pr2}}\mbox{}\\

Since $\mathrm{E}[\| s(X, x, h)Y \|_\Omega] = \mathrm{E}[  |s(X, x, h)| \| Y \|_\Omega]
\leq  \mathrm{E}[ s(X, x, h)^2 ]^{1/2} \mathrm{E}[\| Y \|_{\Omega}^2 ]^{1/2} < \infty$,  
the map $\omega \mapsto \mathrm{E}[\langle s(X, x, h)Y, \omega \rangle _{\Omega}]$ is a bounded linear functional.  
Therefore, by the Riesz Representation Theorem (c.f., Chapter II, 16 in [\cite{MR1255973}]),  
there exists a unique $\tilde{\omega} \in \Omega$ such that for any $\omega \in \Omega$,  
\[
\mathrm{E}[\langle s(X, x, h)Y, \omega \rangle _{\Omega}] = \langle \tilde{\omega}, \omega \rangle _{\Omega}, 
\]
holds. Thus, noting that $\mathrm{E}[s(X, x, h)] = 1$, we obtain
\begin{align*}
\tilde{L}_n(\omega) &= \mathrm{E}[s(X, x, h) \| Y - \omega \|_\Omega^2]  \\
& = \mathrm{E}\left[ s(X, x, h) \left\{ \|Y - \tilde{\omega} \|_\Omega^2  + 2 \langle Y - \tilde{\omega} , \tilde{\omega}  - \omega  \rangle _\Omega       
+     \| \tilde{\omega}  - \omega  \| _\Omega^2    \right\} \right] \\
& = \mathrm{E}\left[ s(X, x, h)\|Y - \tilde{\omega}  \| _\Omega^2  \right] + 2 \mathrm{E}\left[ \langle s(X, x, h)Y , \tilde{\omega}  - \omega  \rangle _\Omega \right] \\
& \qquad \qquad \qquad \qquad - 2 \mathrm{E}\left[ s(X, x, h) \langle \tilde{\omega} , \tilde{\omega}  - \omega  \rangle _\Omega \right] 
+ \mathrm{E}\left[ s(X, x, h) \| \tilde{\omega}  - \omega  \|_\Omega^2 \right] \\
& = \mathrm{E}\left[ s(X, x, h)\|Y - \tilde{\omega}  \|_\Omega^2  \right] +  \|\tilde{\omega}  - \omega  \|_\Omega^2  .
\end{align*}
Since the first term on the right-hand side does not contain $\omega$, we have  
\[
\tilde{l}_{\oplus}(x) = \arg\min_{\omega \in \Omega} \tilde{L}_n(\omega) = \tilde{\omega}.
\]

Similarly, setting $\omega' = n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) Y_i$ and noting that $n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) = 1$,  
\begin{align*}
\hat{L}_n(\omega) &= n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \| Y_i - \omega \|_\Omega^2  \\
&= n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \left\{ \|Y_i - \omega' \|_\Omega^2  + 2 \langle Y_i - \omega' , \omega' - \omega  \rangle _\Omega        
+     \| \omega' - \omega  \| _\Omega^2    \right\} \\
& = n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \|Y_i - \omega' \| _\Omega^2 +  \| \omega' - \omega  \| _\Omega^2  .
\end{align*}
Since the first term on the right-hand side does not contain $\omega$, we have  
\[
\hat{l}_{\oplus}(x) = \arg\min_{\omega \in \Omega} \hat{L}_n(\omega) = \omega'.
\]
\qed
