\subsection{Theorem \ref{th1}}\mbox{}\\

First, for the bivariate random sample $(X_1, Y_1), \ldots, (X_n, Y_n)$ from model \eqref{2.2}, the local linear estimator 
[\cite{MR1193323}, \cite{MR1212173}] $\hat{m}_{\mathrm{LL}}(x) = \hat{\beta}_0$ of $m(x)$ can be expressed using $s_{in}(x, h)$ as follows:
\begin{align*}
\hat{m}_{\mathrm{LL}}(x) = \sum_{i = 1}^{n} \frac{1}{n} \cdot \frac{\hat{\mu}_2 - \hat{\mu}_1 (X_i - x) }
{\hat{\mu}_2 \hat{\mu}_0 - \hat{\mu}_1 ^2} K_h(X_i - x) \cdot Y_i = n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) Y_i.
\end{align*}
The estimator $\hat{m}_{\mathrm{LL}}(x)$ is asymptotically normal under (N1)--(N3) and the following (M1)--(M3) 
(c.f., Theorem 5.2 of [\cite{MR1383587}]).
\begin{description}
\item[(M1)]
$m(\cdot)$ is twice continuously differentiable on $N_x$. 

\item[(M2)]
$\sigma^2(\cdot)$ is continuous and positive on $N_x$.

\item[(M3)]
$\mathrm{E}[ Y^4 \mid X = \cdot ]$ is bounded on $N_x$.
\end{description}
\begin{align*}
\sqrt{nh} \left\{ \hat{m}_{\mathrm{LL}}(x) - m(x) - \left( \frac{ m''(x) }{2} \int u^2 K(u) du \right) h^2 \right\} 
 \leadsto \mathcal{N} \left( 0, \frac{\int K^2(u) du}{f(x)} \sigma^2 (x) \right).
\end{align*}

Next, let $\Omega$ be a real Hilbert space, and suppose a random sample $(X_1, Y_1), \ldots, (X_n, Y_n)$ is obtained from model \eqref{3.2}:
\begin{align*}
Y_i = m_{\oplus}(X_i) + \sigma(X_i) \varepsilon_i, \quad i = 1, \ldots, n.
\end{align*}
Taking the inner product of both sides with some $\omega \in \Omega$ yields:
\begin{align*}
\langle Y_i, \omega \rangle_{\Omega} = \langle m_{\oplus}(X_i), \omega \rangle_{\Omega} + \sigma(X_i) \langle \varepsilon_i, \omega \rangle_{\Omega}, \quad i = 1, \ldots, n.
\end{align*}
Define $Z_i = \langle Y_i, \omega \rangle_{\Omega},\  m_\omega(X_i) = \langle m_{\oplus}(X_i), \omega \rangle_{\Omega}$, and 
$\sigma(X_i) \sqrt{\mathrm{E}[\langle \varepsilon_i, \omega \rangle_{\Omega}^2]} \, \delta_i =  \sigma(X_i) \langle \varepsilon_i, \omega \rangle_{\Omega}$,
where $\delta_i = \langle \varepsilon_i, \omega \rangle_{\Omega} / \sqrt{\mathrm{E}[\langle \varepsilon_i, \omega \rangle_{\Omega}^2]}$, so that
$\mathrm{E}[\delta_i] = 0$, $\mathrm{Var}(\delta_i) = 1.$
Then we obtain the nonparametric regression model for $(X_1, Z_1), \ldots, (X_n, Z_n)$:
\begin{align*} 
Z_i = m_\omega(X_i) + \sigma(X_i) \sqrt{\mathrm{E}[\langle \varepsilon_i, \omega \rangle_{\Omega}^2]} \, \delta_i.  \tag{$\ast$} \label{A2}
\end{align*}
Using Proposition \ref{pr2}, the local linear estimator of $m_\omega(x)$ can be written using \( \hat{l}_\oplus(x) \) in \eqref{2.5} as:
\begin{align*}
\hat{m}_\omega^{\mathrm{LL}}(x) = n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) Z_i
& = \left\langle n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) Y_i, \ \omega \right\rangle_{\Omega} \\
& =  \left\langle \hat{l}_\oplus(x), \ \omega \right\rangle_{\Omega}
\end{align*}
The assumptions corresponding to (M1)--(M3) for model \hyperref[A2]{$(\ast)$} are denoted (O1)--(O3).
Applying the asymptotic normality of the local linear estimator to $\hat{m}_\omega^{\mathrm{LL}}(x) = \left\langle \hat{l}_\oplus(x), \ \omega \right\rangle_{\Omega}$,
we obtain that under (N1)--(N3) and (O1)--(O3), for any $\omega \in \Omega$,
\begin{align*}
&\sqrt{nh} \left\{ \hat{m}_\omega^{\mathrm{LL}}(x) - m_\omega(x) - \left( \frac{ m_\omega''(x) }{2} \int u^2 K(u) du \right) h^2 \right\} \\
{}= & \sqrt{nh} \left\{ \left\langle \hat{l}_\oplus(x) - m_\oplus(x), \ \omega \right\rangle_{\Omega} -  
 \left( \frac{\int u^2 K(u) du}{2}  \frac{\partial^2}{\partial x^2} \left\langle m_\oplus(x), \omega \right\rangle_{\Omega} \right) h^2 \right\} \\
{} \leadsto & \mathcal{N} \left( 0, \frac{\int K^2(u) du}{f(x)} \sigma^2(x) \mathrm{E}[\langle \varepsilon, \omega \rangle_{\Omega}^2] \right).
\end{align*}
\qed
