\subsection{Corollary \ref{cr1}} \mbox{}\\

Let $Z \sim \mathcal{N}(0, 1)$. From the result of Theorem \ref{th1}, we have
\begin{align*}
\sqrt{nh} \, V_x^{-1/2} \left\{ \langle \hat{l}_{\oplus}(x), m_{\oplus}(x) \rangle_{\Omega} - \|m_{\oplus}(x)\|_{\Omega}^2 - B_x \right\} = Z + o_P (1).
\end{align*}
Suppose that consistent estimators $\hat{B}_x$ and $\hat{V}_x$ satisfy
\[
\hat{B}_x = B_x + o_ P \left((nh)^{-1/2}\right), \quad 
\hat{V}_x = V_x + o_P (1),
\]
then we obtain
\begin{align*}
\sqrt{nh} \, \hat{V}_x^{-1/2} \left\{ \langle \hat{l}_{\oplus}(x), m_{\oplus}(x) \rangle_{\Omega} - \|m_{\oplus}(x)\|_{\Omega}^2 - \hat{B}_x \right\} = Z + o_P (1).
\end{align*}
Therefore,
\begin{align*}
\langle \hat{l}_{\oplus}(x), m_{\oplus}(x) \rangle_{\Omega} 
= \|m_{\oplus}(x)\|_{\Omega}^2 + \hat{B}_x + \sqrt{\frac{\hat{V}_x}{nh}} \, Z + o_P \left((nh)^{-1/2}\right).
\end{align*}
Using this, we can derive the squared distance between the estimator and the true regression function as follows:
\begin{align*}
\|\hat{l}_{\oplus}(x) - m_{\oplus}(x)\|_{\Omega}^2 
&= \|\hat{l}_{\oplus}(x)\|_{\Omega}^2 + \|m_{\oplus}(x)\|_{\Omega}^2 - 2 \langle \hat{l}_{\oplus}(x), m_{\oplus}(x) \rangle_{\Omega} \\
&= \|\hat{l}_{\oplus}(x)\|_{\Omega}^2 - \|m_{\oplus}(x)\|_{\Omega}^2 - 2 \hat{B}_x - 2 \sqrt{\frac{\hat{V}_x}{nh}} \, Z + o_P \left((nh)^{-1/2}\right).
\end{align*}
According to Theorems 3 and 4 in [\cite{MR3909947}], under conditions (P1), (K0), and (L0)--(L3), we have
\begin{align*}
\left| \|\hat{l}_{\oplus}(x)\|_{\Omega}^2 - \|m_{\oplus}(x)\|_{\Omega}^2 \right|
&= \left| \langle \hat{l}_{\oplus}(x) + m_{\oplus}(x), \hat{l}_{\oplus}(x) - m_{\oplus}(x) \rangle_{\Omega} \right| \\
&\leq \|\hat{l}_{\oplus}(x) + m_{\oplus}(x)\|_{\Omega} \cdot \|\hat{l}_{\oplus}(x) - m_{\oplus}(x)\|_{\Omega} \\
&= O_P(1) \cdot O_P\left((nh)^{-1/(2(\beta_2 - 1))} + h^{2/(\beta_1 - 1)} \right) \\
&= o_P\left((nh)^{-1/2}\right).
\end{align*}
Hence, we obtain
\begin{align*}
\|\hat{l}_{\oplus}(x) - m_{\oplus}(x)\|_{\Omega}^2 
= -2 \hat{B}_x - 2 \sqrt{\frac{\hat{V}_x}{nh}} Z + o_P\left((nh)^{-1/2}\right),
\end{align*}
which leads to the approximation:
\begin{align*}
\sqrt{nh} \, \hat{V}_x^{-1/2} \left\{ \frac{1}{2} \|\hat{l}_{\oplus}(x) - m_{\oplus}(x)\|_{\Omega}^2 + \hat{B}_x \right\} = Z + o_P (1).
\end{align*}
Let $z_{\alpha/2}$ denote the upper $\alpha/2$ quantile of the standard normal distribution. Then, we obtain the asymptotic confidence statement:
\begin{align*}
P\left( 
- z_{\alpha/2} \leq 
\sqrt{nh} \, \hat{V}_x^{-1/2} \left\{ \frac{1}{2} \|\hat{l}_{\oplus}(x) - m_{\oplus}(x)\|_{\Omega}^2 + \hat{B}_x \right\}
\leq z_{\alpha/2} 
\right) = 1 - \alpha + o(1),
\end{align*}
which is equivalent to
\begin{align*}
P\left( 
-2\hat{B}_x - 2\sqrt{\frac{\hat{V}_x}{nh}} z_{\alpha/2} 
\leq \|\hat{l}_{\oplus}(x) - m_{\oplus}(x)\|_{\Omega}^2 
\leq -2\hat{B}_x + 2\sqrt{\frac{\hat{V}_x}{nh}} z_{\alpha/2}
\right) = 1 - \alpha + o(1).
\end{align*}
This establishes that
\[
P\left( m_{\oplus}(x) \in CI_{\alpha} \right) \to 1 - \alpha \quad \text{as } n \to \infty. 
\]
\qed
