\subsection{Theorem \ref{th2}}\mbox{}\\

Given
$\hat{l}_{\oplus}^{H_k} (x) = n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \Phi(Y_i)$,\ 
$\tilde{l}_{\oplus}^{H_k} (x) = \argmin_{f \in H_k} \tilde{L}_n^{H_k}(f)$,
we define the corresponding empirical and population risk functions as follows:
\begin{align*}
 \hat{L}_n ^k(\omega) &= \|\hat{l}_{\oplus}^{H_k} (x) -  \Phi(\omega)\|^2 _{H_k} \\ 
& =  k(\omega, \omega)  - 2 {n}^{-1} \sum_{i = 1}^{n} s_{in}(x, h) k(Y_i, \omega) 
 + {n}^{-2} \sum_{i = 1}^{n}\sum_{j = 1}^{n} s_{in}(x, h) s_{jn}(x, h)k(Y_i, Y_j)  , \\
\tilde{L}_n ^k(\omega) &= \|\tilde{l}_{\oplus}^{H_k} (x) -  \Phi(\omega)\|^2 _{H_k} \\
 &= k(\omega, \omega) - 2\mathrm{E}[s(X, x, h) k(Y, \omega)] + \| \tilde{l}_{\oplus} ^{H_k}(x) \|_{H_k} ^2.
\end{align*}
Then, \eqref{4.4} can be written as 
$\hat{l}_{\oplus}^{k} (x) = \argmin_{\omega \in \Omega} \hat{L}_n ^k(\omega)$, 
and we similarly define \\$\tilde{l}_{\oplus}^{k}(x) = \argmin_{\omega \in \Omega} \tilde{L}_n^k(\omega)$. \\
By the triangle inequality for the distance function, it suffices to show
\begin{align*}
d(m_{\oplus}(x), \tilde{l}_{\oplus}^{k}(x)) = o(1) \quad &\cdots \text{(i)}, \\
d(\tilde{l}_{\oplus}^{k}(x), \hat{l}_{\oplus}^{k}(x)) = o_P(1) \quad &\cdots \text{(ii)}.
\end{align*}
%%%%%%%%%%%%%%%%%%

First, regarding (i), by applying the same argument as in the proof of Theorem 3 in  SUPPLEMENTARY MATERIAL of [\cite{MR3909947}] 
(DOI:\href{https://doi.org/10.1214/17-AOS1624SUPP}{10.1214/17-AOS1624SUPP})
(hereafter referred to as [PM]),
and by replacing $\tilde{l}_{\oplus}(x)$ with $\tilde{l}_{\oplus}^{H_k}(x)$ and $m_{\oplus}(x)$ with $\Phi(m_{\oplus}(x))$,
under assumptions (K0), (L1), and (S4), we have
\[
\left\| \tilde{l}_{\oplus}^{H_k}(x) - \Phi(m_{\oplus}(x)) \right\|_{H_k}^2 = o(1) \quad \text{as } h = h_n \to 0.
\]
That is, since $\tilde{L}_n^k(m_{\oplus}(x)) \to 0$ as $h = h_n \to 0$, by (S5) it follows that
\[
d(m_{\oplus}(x), \tilde{l}_{\oplus}^{k}(x)) = o(1) \quad \text{as } h = h_n \to 0.
\]
%%%%%%%%%%%%%%%%%%

Next, regarding (ii), we utilize Corollary 3.2.3 of [\cite{MR1385671}] (hereafter referred to as [VW]).  
Since assumption (S5) holds, it suffices to show
\[
\sup_{\omega \in \Omega} \left| \hat{L}_n^k(\omega) - \tilde{L}_n^k(\omega) \right| = o_P(1).
\]
To this end, we prove that
\[
\hat{L}_n^k - \tilde{L}_n^k \leadsto 0 \quad \text{in} \quad l^{\infty}(\Omega),
\]
and apply Theorem 1.3.6 in [VW] with
\[
g(L) = \sup_{\omega \in \Omega} |L(\omega)|, \quad L \in l^{\infty}(\Omega),
\]
where $l^{\infty}(\Omega)$ denotes the space of all uniformly bounded real-valued functions on $\Omega$.
By using Theorem 1.5.4 in [VW], this weak convergence is equivalent to showing the following two points:
\begin{itemize}
\item[(ii-\textcircled{\scriptsize 1})] $\hat{L}_n^k(\omega) - \tilde{L}_n^k(\omega) = o_P(1)$ for all $\omega \in \Omega$,
\item[(ii-\textcircled{\scriptsize 2})] $\hat{L}_n^k - \tilde{L}_n^k$ is asymptotically tight.
\end{itemize}
%%%%%%%%%%%%%%%%%%
\quad
First, for (ii-\textcircled{\scriptsize 1}), the difference $\hat{L}_n^k(\omega) - \tilde{L}_n^k(\omega)$ can be written as:
\begin{align*}
&-2 \left\{ n^{-1} \sum_{i=1}^n s_{in}(x,h) k(Y_i,\omega) - \mathrm{E}[s(X,x,h)k(Y,\omega)] \right\} \\
&\quad \quad \quad \quad \quad+ n^{-2} \sum_{i=1}^n \sum_{j=1}^n s_{in}(x,h) s_{jn}(x,h) k(Y_i,Y_j) 
 - \| \tilde{l}_\oplus^{H_k}(x) \|_{H_k}^2.
\end{align*}
For the first term, by the result in the proof of Lemma 2 in [PM], it is $O_P((nh)^{-1/2})$. \\
For the second term, letting $s_i(x,h) = \sigma_0^{-2} K_h(X_i - x) \left\{ \mu_2 - \mu_1 (X_i - x) \right\}$,
we can write:
\begin{align*}
&n^{-2} \sum_{i=1}^n \sum_{j=1}^n \left\{ s_{in}(x,h) s_{jn}(x,h) - s_i(x,h) s_j(x,h) \right\} k(Y_i, Y_j) \tag{A-1} \label{A-1} \\
&\quad \quad \quad + n^{-2} \sum_{i=1}^n \sum_{j=1}^n s_i(x,h) s_j(x,h) k(Y_i, Y_j) - \| \tilde{l}_\oplus^{H_k}(x) \|_{H_k}^2 
\end{align*}
Now, for the first term in \eqref{A-1}, we compute the difference
$s_{in}(x,h) s_{jn}(x,h) - s_i(x,h) s_j(x,h)$ as:
\begin{align*}
&\left\{ \left (\frac{\hat{\mu}_2 }{\hat{\sigma}_0 ^2} \right)^2 -\left(\frac{\mu_2 }{\sigma_0 ^2} \right)^2 \right\} K_h(X_i - x) K_h(X_j - x) \\
& \quad\quad \quad - \left\{ \left(\frac{\hat{\mu}_1 }{\hat{\sigma}_0 ^2} \right)  \cdot  \left(\frac{\hat{\mu}_2 }{\hat{\sigma}_0 ^2} \right)
 - \left( \frac{\mu_1 }{\sigma_0 ^2} \right) \cdot \left( \frac{\mu_2 }{\sigma_0 ^2} \right) \right\} K_h(X_i - x) K_h(X_j - x) (X_i - x)\\
& \quad\quad \quad - \left\{ \left(\frac{\hat{\mu}_1 }{\hat{\sigma}_0 ^2} \right)  \cdot  \left(\frac{\hat{\mu}_2 }{\hat{\sigma}_0 ^2} \right)
 - \left( \frac{\mu_1 }{\sigma_0 ^2} \right) \cdot \left( \frac{\mu_2 }{\sigma_0 ^2} \right) \right\} K_h(X_i - x) K_h(X_j - x) (X_j - x)\\
&\quad \quad \quad \quad \quad \quad + \left\{ \left (\frac{\hat{\mu}_1 }{\hat{\sigma}_0 ^2} \right)^2 -\left(\frac{\mu_1 }{\sigma_0 ^2} \right)^2 \right\} 
 K_h(X_i - x) K_h(X_j - x) (X_i - x)(X_j - x).
\end{align*}
Lemma 1 in [PM], under assumptions (K0) and (L1), we have
\begin{align*}
\frac{\hat{\mu}_2 }{\hat{\sigma}_0 ^2}  - \frac{\mu_2}{\sigma_0 ^2} = O_{P}((nh)^{-1/2}), \quad
\frac{\hat{\mu}_1 }{\hat{\sigma}_0 ^2}  - \frac{\mu_1 }{\sigma_0 ^2} = O_{P}((nh^3)^{-1/2}).
\end{align*}
Therefore, it follows that
\begin{align*}
& \left( \frac{\hat{\mu}_2 }{\hat{\sigma}_0 ^2} \right)^2 - \left( \frac{\mu_2 }{\sigma_0 ^2} \right)^2 = O_{P}((nh)^{-1/2}), \quad
\left( \frac{\hat{\mu}_1 }{\hat{\sigma}_0 ^2} \right)^2 - \left( \frac{\mu_1 }{\sigma_0 ^2} \right)^2 = O_{P}((nh^3)^{-1/2}), \\
& \left( \frac{\hat{\mu}_1 }{\hat{\sigma}_0 ^2} \right) \cdot \left( \frac{\hat{\mu}_2 }{\hat{\sigma}_0 ^2} \right)
 - \left( \frac{\mu_1 }{\sigma_0 ^2} \right) \cdot \left( \frac{\mu_2 }{\sigma_0 ^2} \right) = O_{P}((nh^3)^{-1/2}).
\end{align*}
Moreover, under assumption (K0), we have
\begin{align*}
\mathrm{E}[K_h^i (X - x) (X - x)^j] 
= h^{j - i + 1} \int K^i(u) u^j f(x + hu) \, du 
= O(h^{j - i + 1}), \quad \text{for } i, j = 0,1,2,3,4 \ (i \neq 0).
\end{align*}
Therefore,
\begin{align*}
& K_h^2 (X_i - x) = O_{P}(h^{-3/2}), \quad K_h(X_i - x) K_h(X_j - x) = O_{P}(h^{-1}) \ (i \neq j), \\
& K_h^2 (X_i - x)(X_i - x) = O_{P}(h^{-1/2}), \quad K_h(X_i - x)K_h(X_j - x)(X_i - x) = O_{P}(1) \ (i \neq j), \\
& K_h^2 (X_i - x)(X_i - x)^2 = O_{P}(h^{1/2}), \quad K_h(X_i - x)K_h(X_j - x)(X_i - x)(X_j - x) = O_{P}(h) \ (i \neq j).
\end{align*}
Hence, we obtain
\begin{align*}
n^{-2} \sum_{i = 1}^{n} \sum_{j = 1}^{n} \left\{ s_{in}(x, h) s_{jn}(x, h) - s_i(x, h) s_j(x, h) \right\} k(Y_i, Y_j) = O_{P}((nh^4)^{-1/2}),
\end{align*}
and thus, under the condition $nh^4 \to \infty$, this term is $o_P(1)$. \\
Next, the second term of \eqref{A-1} can be written as:
\begin{align}
& \left\| n^{-1} \sum_{i = 1}^{n} s_i(x, h) \Phi(Y_i) - \tilde{l}_{\oplus}^{H_k}(x) \right\|_{H_k}^2  \tag{A-2} \label{A-2} \\
& \qquad \qquad \qquad \qquad 
+ 2 \left\langle \tilde{l}_{\oplus}^{H_k}(x), 
n^{-1} \sum_{i = 1}^{n} s_i(x, h) \Phi(Y_i) - \tilde{l}_{\oplus}^{H_k}(x) \right\rangle_{H_k}. \nonumber
\end{align}
Furthermore, define a functional $G: H_k \to \mathbb{R}$ for any $f \in H_k$ as
\begin{align*}
G(f) := \| f \|_{H_k}^2 + 2 \left\langle \tilde{l}_{\oplus}^{H_k}(x), f \right\rangle_{H_k}.
\end{align*}
Then $G$ is continuous, and expression \eqref{A-2} can be rewritten as
$G\left(n^{-1} \sum_{i = 1}^{n} s_i(x, h) \Phi(Y_i) - \tilde{l}_{\oplus}^{H_k}(x)\right)$.
From a result in the proof of Lemma 2 in [PM], for any $f \in H_k$, we have
\begin{align*}
\left\langle n^{-1} \sum_{i = 1}^{n} s_i(x, h) \Phi(Y_i) - \tilde{l}_{\oplus}^{H_k}(x), f \right\rangle_{H_k}
&= n^{-1} \sum_{i = 1}^{n} s_i(x, h) f(Y_i) - \mathbb{E}[s(X, x, h) f(Y)] \\
&= O_P((nh)^{-1/2}),
\end{align*}
and thus the left-hand side converges in probability to $0 = \langle 0, f \rangle$ as $nh \to \infty$.
Under assumption (S1), since $H_k$ is separable, there exists a countable orthonormal basis $\{e_i\}_{i=1}^\infty \subset H_k$. Then, for any $j \in \mathbb{N}$, the inner product between $e_j$ and $n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \Phi(Y_i) - \tilde{l}_{\oplus}^{H_k}(x)$ converges to zero in probability. Therefore, $n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \Phi(Y_i) - \tilde{l}_{\oplus}^{H_k}(x)$
is asymptotically finite-dimensional.
By Theorem 1.8.4 in [VW], we obtain
\begin{align*}
n^{-1} \sum_{i = 1}^{n} s_{in}(x, h) \Phi(Y_i) - \tilde{l}_{\oplus}^{H_k}(x) \leadsto 0.
\end{align*}
Applying Theorem 1.3.6 in [VW] to the functional $G$, the norm and inner product in \eqref{A-2} satisfy
$G\left(n^{-1} \sum_{i = 1}^{n} s_i(x, h) \Phi(Y_i) - \tilde{l}_{\oplus}^{H_k}(x)\right) = o_P(1)$.
Therefore, we conclude that for any $\omega \in \Omega$, $\hat{L}_n^k(\omega) - \tilde{L}_n^k(\omega) = o_P(1)$.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Next, regarding (ii-\textcircled{\scriptsize 2}), by applying Theorem 1.5.7 in [VW], it suffices to show that \\
$\hat{L}_n^k - \tilde{L}_n^k$ is asymptotically uniformly $d$-equicontinuous in probability, i.e., for any $\eta > 0$,
\begin{align*}
\limsup_{n} P \left( \sup_{d(\omega_1, \omega_2) < \delta}  
\left |  (\hat{L}_n^k  - \tilde{L}_n^k)(\omega_1) - (\hat{L}_n^k  - \tilde{L}_n^k)(\omega_2) \right | > \eta \right) \to 0 \quad \text{as } \delta \to 0. \tag{A-3} \label{A-3}
\end{align*}
Since $\mathrm{E}[|s(X, x, h)|] = O(1)$, $\mathrm{E}[s^2(X, x, h)] = O(h^{-1})$, and 
${n}^{-1} \sum_{i=1}^{n} | s_{in}(x, h) | = O_{P}(1)$, 
under assumptions (S2) and (S3), we have
\begin{align*}
\left | \hat{L}_n^k(\omega_1) - \hat{L}_n^k(\omega_2) \right | 
& \leq  \left | k(\omega_1, \omega_1) - k(\omega_2, \omega_2) \right | + 2 \left | \frac{1}{n} \sum_{i = 1}^{n} s_{in}(x, h) \left \{ k(Y_i, \omega_2) - k(Y_i, \omega_1) \right \} \right | \\
& \leq \left |  \| \Phi(\omega_2) \|^2_{\mathcal{H}_k} - \| \Phi(\omega_1) \|^2_{\mathcal{H}_k} \right | \\
& \quad \quad + \frac{1}{n} \sum_{i = 1}^{n} | s_{in}(x, h) | \times \\
& \quad \quad \quad \quad \left | \|\Phi(Y_i) - \Phi(\omega_1)\|^2_{\mathcal{H}_k} - \|\Phi(Y_i) - \Phi(\omega_2)\|^2_{\mathcal{H}_k} 
 + \| \Phi(\omega_2) \|^2_{\mathcal{H}_k} - \| \Phi(\omega_1) \|^2_{\mathcal{H}_k} \right | \\
& \leq 2MC\, d(\omega_1, \omega_2) + 
\frac{1}{n} \sum_{i = 1}^{n} | s_{in}(x, h) | \times 2C \left\{C\, \mathrm{diam}(\Omega)\, d(\omega_1, \omega_2) + M\, d(\omega_1, \omega_2) \right\} \\
& = O_{P}(d(\omega_1, \omega_2)).
\end{align*}
Here, we use the fact that, by assumption (S1),  
$d(\omega, \omega') \leq \mathrm{diam}(\Omega) < \infty$ holds for any $\omega, \omega' \in \Omega$.\\
Similarly, we have
\begin{align*}
\left| \tilde{L}_n^k(\omega_1) - \tilde{L}_n^k(\omega_2) \right| 
& \leq 2MC\, d(\omega_1, \omega_2) + \mathrm{E}[ | s(X, x, h) | ] \times 2C \left\{ C\,\mathrm{diam}(\Omega)\, d(\omega_1, \omega_2) + M\, d(\omega_1, \omega_2) \right\} \\
& = O( d(\omega_1, \omega_2) ).
\end{align*}
From the above, we conclude that for any $\eta > 0$, the condition \eqref{A-3} holds.
