$$\| \pi_n(s) - q_n\rho_n(s) q_n\|_{2,M_n} / \|q_n \|_{2,M_n}< \epsilon \text{ for all $s \in S$,}$$
then the cocycle associated with $\pi_n$ is a $2$-coboundary.
\end{theorem}

