\section{$L^1$-estimate of the Fourier transform of $H^s(\R^{d-1})$-functions} 
\begin{lemma}
\label{lm1}
For all $h \in H^s(\R^{d-1})$ with $s >\frac{d-1}{2}$, we have
$\cF(h) \in L^1(\R^{d-1})$ and the estimate
\bel{f0} 
\norm{\cF(h)}_{L^1(\R^{d-1})} \le \sqrt{C_s} \norm{h}_{H^{s}(\R^{d-1})},
\ee
where $C_s:=\int_{\R^{d-1}} (1+\abs{\xp}^2)^{-s} \dd \xp <\infty$.
\end{lemma}
\begin{proof}


Let $h\in H^s(\R^{d-1})$.
Applying the Cauchy-Schwarz inequality, we get 
\beas
\int_{\R^{d-1}} \abs{\cF(h)(\xp)} \dd \xp 
& = & \int_{\R^{d-1}} (1+\abs{\xp}^2)^{-\frac{s}{2}} (1+\abs{\xp}^2)^{\frac{s}{2}} \abs{\cF(h)(\xp)} \dd \xp \\
& \le & \sqrt{C_s} \norm{(1+\abs{\xp}^2)^{\frac{s}{2}} \cF(h)}_{L^2(\R^{d-1})}.
\eeas
The expected inequality then follows. 
\end{proof}

\section{Elliptic regularity}
\subsection{An elliptic regularity result} 
Consider the BVP:
\bel{r0}
\left\{ \begin{array}{ll} -\Delta u + q u = f & \mbox{in}\ \Om, \\ \pd_\nu u + \al u = 0 & \mbox{on}\ \Gamma. \end{array} \right. 
\ee
\begin{lemma}
\label{lm-er}
Fix $k \in \N_0 := \N \cup \{ 0 \}$ and $r \in \left( \frac{1}{2}, 1\right)$. Let $\Gamma$ be $\cC^{k+1,1}$, let $q \in W^{k,\infty}(\Om)$ and let $\al \in \cC^{k,r}(\Ga)$. Suppose moreover that $q$ and $\al$ satisfy either of the two following conditions 
\bel{c1b}
q \ge 0\; \mbox{in}\; \Om\quad \mbox{and}\quad \al \ge c >0\; \mbox{on}\ \Ga
\ee
or
\bel{c2b}
q \ge c > 0\ \mbox{in}\; \Om\quad \mbox{and}\quad \al \ge 0\; \mbox{on}\; \Ga.
\ee
Then, for all $f \in H^k(\Om)$, the BVP \eqref{r0} admits a unique solution $u \in H^{k+2}(\Om)$.
\end{lemma}
\begin{proof}
The proof is by induction on $k$. First, let $k=0$ and $f \in L^2(\Om)$. Applying either \cite[Theorem 2.4.2.6]{G} or \cite[Theorem 2.4.2.7]{G}, depending on whether $q$ and $\al$ satisfy the condition \eqref{c1b} or \eqref{c2b}, we get a unique solution $u \in H^2(\Om)$ to \eqref{r0}.
Assume that the lemma holds up to $k-1$ with $k\in \mathbb{N}$. If $f\in H^k(\Omega)$, we obtain 
$u \in H^{k+1}(\Om)$, and hence that $u_{| \Ga} \in H^{k+\frac{1}{2}}(\Ga)$. It follows from this and $\al \in \cC^{k,r}(\Ga)$, that $\al u \in H^{k+\frac{1}{2}}(\Ga)$, according to \cite[Theorem 2.3.9]{Ag}. Thus, keeping in mind that $q u \in H^k(\Om)$ since $q \in W^{k,\infty}(\Omega)$, we see from \eqref{r0} that $u$ solves
\bel{r1}
\left\{ \begin{array}{ll} -\Delta u = \tilde{f} & \mbox{in}\ \Om, \\ \pd_\nu u = g & \mbox{on}\ \Gamma, \end{array} \right. 
\ee
where $\tilde{f}:= f - q u \in H^k(\Om)$ and $g:= - \al u \in H^{k+\frac{1}{2}}(\Ga)$. Therefore, we have $u \in H^{k+1}(\Om)$ by 
\cite[Theorem 2.5.1.1]{G}.
\end{proof}



\subsection{Improved regularity of the eigenfunctions}
Let $\phi_n$ denote the $n$-th eigenfunction of the Schr\"odinger-Robin operator $A$. Then $-\Delta \phi_n=\lambda_n \phi_n$ in the distributional sense and $\partial_\nu\phi_n +\alpha\phi_n=0$ in $H^{-1/2}(\Gamma)$.
Suppose that $q$ and $\alpha$ fulfill either \eqref{c1b} or \eqref{c2b}. We get by applying Lemma \ref{lm-er} with $f=-\la_n \phi_n \in H^1(\Om)$ that $\phi_n \in H^3(\Om)$, provided that 
the boundary $\Ga$ is $\cC^{2,1}$, $q \in W^{1,\infty}(\Om)$ and $\al \in \cC^{1,r}(\Ga)$ for some $r \in \left( \frac{1}{2}, 1\right)$. Similarly, using that $\phi_n \in H^2(\Om)$, we get from Lemma \ref{lm-er} where $f=-\la_n \phi_n \in H^2(\Om)$ that $\phi_n \in H^4(\Om)$ whenever 
$\Ga$ is $\cC^{3,1}$, $q \in W^{2,\infty}(\Om)$ and $\al \in \cC^{2,r}(\Ga)$. By iterating, we obtain the following statement.

\begin{lemma}
\label{lm-ire}
For $k \in \N$, let $\Ga$ be of class $\cC^{k+1,1}$, $q \in W^{k,\infty}(\Om)$ and $\al \in \cC^{k,r}(\Ga)$, for some $r \in \left( \frac{1}{2}, 1\right)$. Furthermore, assume that $q$ and $\alpha$ fulfill either \eqref{c1b} or \eqref{c2b}. 
Then, we have $\phi_n \in H^{k+2}(\Om)$.
\end{lemma}


