      \field{journaltitle}{Inventiones mathematicae}
      \field{month}{2}
      \field{number}{1}
      \field{title}{Torsion and closed geodesics on complex hyperbolic manifolds}
      \field{volume}{91}
      \field{year}{1988}
      \field{pages}{31\bibrangedash 51}
      \range{pages}{21}
