        \hline
        $r_{02}$ & 0.666 & $771.9\,\mathrm{km}$ & $98.65\,\mathrm{km^2}$ & 0.586 & 1,176$\,\mathrm{km}$ & $166.3\,\mathrm{km^2}$\\
