\section{Phenomenological analysis}\label{pa}

\subsection{Test isospin symmetry in $\Xi_c\to \Xi\pi$ system}

In this subsection, we take $\Xi^0_c\to \Xi^-\pi^+$, $\Xi^0_c\to \Xi^0\pi^0$, and $\Xi^+_c\to \Xi^0\pi^+$ modes as examples to test rescattering amplitudes derived from topological amplitudes.
The decay amplitude for the $\Xi^0_c\to \Xi^-\pi^+$ mode is $\lambda_1(A_2+A_5)$.
The long-distance contributions modeled by triangle diagrams at hadron level include
\begin{align}\label{x4}
T(A_2)_4[u,d,s,u]\,&=\, \frac{1}{2}\Delta_{\alpha^+,\gamma^-}(\Xi^0_c,\pi^+,\Xi^-,\rho^0,\pi^+,\Xi^-)
-\frac{1}{2}\Delta_{\alpha^+,\gamma^-}(\Xi^0_c,\pi^+,\Xi^-,\omega,\pi^+,\Xi^-),
\nonumber\\
T(A_2)_5[u,d,s,u]\,&=\,\Delta_{\alpha^+,\gamma^0}(\Xi^0_c,\pi^+,\Xi^-,\omega,
\pi^+,\Xi^-),\nonumber\\
T(A_2)_6[u,d,s,u]\,&=\,
-\Delta_{\alpha^+,\gamma^0}(\Xi^0_c,\pi^+,\Xi^-,\omega,\pi^+,\Xi^-),
\nonumber\\
T(A_5)[u,d,s,u]\,&=\, \frac{1}{2}\Delta_{\alpha^+,\gamma^-}(\Xi^0_c,\pi^+,\Xi^-,\rho^0,\pi^+,\Xi^-)
+\frac{1}{2}\Delta_{\alpha^+,\gamma^-}(\Xi^0_c,\pi^+,\Xi^-,\omega,\pi^+,\Xi^-).
\end{align}
To distinguish different strong coupling constants, we add subscripts $\alpha^{\pm}, \beta^{\pm,0}, \gamma^{\pm,0}$ for rescattering amplitudes.
In $T(A_2)_4[u,d,s,u]$, the quark constituent of the vector meson is $d\overline d$ when it couples with pseudoscalar mesons, and $u\overline u$ when it couples with octet baryons.
Since $d\overline d =  -\rho^0/\sqrt 2+  \omega/\sqrt 2$ and $u\overline u =  \rho^0/\sqrt 2+  \omega/\sqrt 2$, the vector propagator is $ -\rho^0/2+\omega/2$.
In $T(A_5)[u,d,s,u]$, the quark constituent of the vector meson is $u\overline u$ and the vector propagator is $ \rho^0/2+\omega/2$.
The $VPP$ couplings in $T(A_2)_4[u,d,s,u]$ and $T(A_5)[u,d,s,u]$ are $\alpha^-$ and $\alpha^+$ respectively,
and the $VBB$ coupling in both is $\gamma^-$.
Given that $\alpha^-=-\alpha^+$, the vector propagators in $T(A_2)_4[u,d,s,u]$ and $T(A_5)[u,d,s,u]$ become $ \rho^0/2-\omega/2$ and $ \rho^0/2+\omega/2$, respectively.
Only the $\omega$ meson contributes to $T(A_2)_5[u,d,s,u]$ and $T(A_2)_6[u,d,s,u]$
because the $VBB$ coupling of them is $\gamma^0B^j_i V^k_k B^i_j$.
Amplitude $A_5$ also receives a long-distance contribution modeled by a bubble diagram,
\begin{align}
S(A_5)[u,d,s,u]\,&=\, \Theta_{\beta^-,\beta^-}(\Xi^0_c,\pi^+,\Xi^-,\Xi^0,\pi^+,\Xi^-).
\end{align}
Summing all FSI amplitudes for the $\Xi^0_c\to \Xi^-\pi^+$ decay yields
\begin{align}\label{x1}
\mathcal{A}_L(\Xi^0_c\to \Xi^-\pi^+)&= \lambda_1\{T(A_2)_4[u,d,s,u]+T(A_2)_5[u,d,s,u]+T(A_2)_6[u,d,s,u]\\&
~~~~~~+T(A_5)[u,d,s,u]+S(A_5)[u,d,s,u]\}\nonumber\\& = \lambda_1[\Delta_{\alpha^+,\gamma^-}(\Xi^0_c,\pi^+,\Xi^-,\rho^0,\pi^+,\Xi^-)
+\Theta_{\beta^-,\beta^-}(\Xi^0_c,\pi^+,\Xi^-,\Xi^0,\pi^+,\Xi^-)].
\end{align}
It should be noted that the contributions associated with the $\omega\pi\pi$ coupling cancel each other out.

The decay amplitude for the $\Xi^0_c\to \Xi^0\pi^0$ decay is $\lambda_1(A_3-A_5)/\sqrt{2}$.
The long-distance contributions include
\begin{align}
T(A_3)_1[u,d,s,u]\,&=\, -\Delta_{\alpha^+,\gamma^-}(\Xi^0_c,\pi^+,\Xi^-,\rho^+,\pi^0,\Xi^0),\nonumber\\
T(A_3)_2[u,d,s,u]\,&=\, \Delta_{\beta^-,\beta^-}(\Xi^0_c,\pi^+,\Xi^-,\Xi^-,\Xi^0,\pi^0),\nonumber\\
T(A_5)[u,d,s,d]\,&=\, \Delta_{\alpha^+,\gamma^-}(\Xi^0_c,\pi^+,\Xi^-,\rho^+,\pi^0,\Xi^0),\nonumber\\
S(A_5)[u,d,s,d]\,&=\, \Theta_{\beta^-,\beta^-}(\Xi^0_c,\pi^+,\Xi^-,\Xi^0,\pi^0,\Xi^0).
\end{align}
Summing $A_3$ and $A_5$ amplitudes, we have
\begin{align}\label{x2}
\mathcal{A}_L(\Xi^0_c\to \Xi^0\pi^0)=&\frac{1}{\sqrt{2}}\lambda_1\{T(A_3)_1[u,d,s,u]+T(A_3)_2[u,d,s,u]
-T(A_5)[u,d,s,d]-S(A_5)[u,d,s,d]\}\nonumber\\
=& -\sqrt{2}\lambda_1\Delta_{\alpha^+,\gamma^-}(\Xi^0_c,\pi^+,\Xi^-,\rho^+,\pi^0,\Xi^0)
+\frac{1}{\sqrt{2}}\lambda_1\Delta_{\beta^-,\beta^-}
(\Xi^0_c,\pi^+,\Xi^-,\Xi^-,\Xi^0,\pi^0)
\nonumber \\&~~~~-\frac{1}{\sqrt{2}}\lambda_1\Theta_{\beta^-,\beta^-}(\Xi^0_c,\pi^+,\Xi^-,\Xi^0,\pi^0,\Xi^0).
\end{align}
The decay amplitude for the $\Xi^+_c\to \Xi^0\pi^+$ decay is $-\lambda_1(A_2+A_3)$.
The rescattering contributions include
\begin{align}\label{x5}
T(A_2)_1[d,d,s,u]\,&=\, -\frac{1}{2}\Delta_{\alpha^+,\gamma^-}(\Xi^+_c,\pi^+,\Xi^0,\rho^0,\pi^+,\Xi^0)
+\frac{1}{2}\Delta_{\alpha^+,\gamma^-}(\Xi^+_c,\pi^+,\Xi^0,\omega,\pi^+,\Xi^0),\nonumber\\
T(A_2)_5[d,d,s,u]\,&=\,
\Delta_{\alpha^+,\gamma^0}(\Xi^+_c,\pi^+,\Xi^0,\omega,\pi^+,\Xi^0),\nonumber\\
T(A_2)_6[d,d,s,u]\,&=\,
-\Delta_{\alpha^+,\gamma^0}(\Xi^+_c,\pi^+,\Xi^0,\omega,\pi^+,\Xi^0),\nonumber\\
T(A_3)_1[d,d,s,u]\,&=\, -\frac{1}{2}\Delta_{\alpha^+,\gamma^-}(\Xi^+_c,\pi^+,\Xi^0,\rho^0,\pi^+,\Xi^0)
-\frac{1}{2}\Delta_{\alpha^+,\gamma^-}(\Xi^+_c,\pi^+,\Xi^0,\omega,\pi^+,\Xi^0),\nonumber\\
T(A_3)_2[d,d,s,u]\,&=\, \Delta_{\beta^-,\beta^-}(\Xi^+_c,\pi^+,\Xi^0,\Xi^-,\Xi^0,\pi^+).
\end{align}
Summing $A_2$ and $A_3$ amplitudes, we have
\begin{align}\label{x3}
\mathcal{A}_L(\Xi^+_c\to \Xi^0\pi^+)=&-\lambda_1\{T(A_2)_1[d,d,s,u]+T(A_2)_5[d,d,s,u]+T(A_2)_6[d,d,s,u]
\nonumber\\&~~~~~~~~+T(A_3)_1[d,d,s,u]
+T(A_3)_2[d,d,s,u]\}\nonumber\\
=& \lambda_1\Delta_{\alpha^+,\gamma^-}(\Xi^+_c,\pi^+,\Xi^0,\rho^0,\pi^+,\Xi^0)
-\lambda_1\Delta_{\beta^-,\beta^-}(\Xi^+_c,\pi^+,\Xi^0,\Xi^-,\Xi^0,\pi^+).
\end{align}
Again, all contributions associated with the $\omega\pi\pi$ vertex cancel each other out.

Equations~\eqref{x1}, \eqref{x2} and \eqref{x3} can also be derived directly from the chiral Lagrangian~\eqref{x6}.
Starting from topological amplitudes, we obtain the same results.
This indicates a correlation between topological amplitudes and chiral dynamics.
The decay modes for the $\Xi^0_c\to \Xi^-\pi^+$, $\Xi^0_c\to \Xi^0\pi^0$ and $\Xi^+_c\to \Xi^0\pi^+$ modes form an isospin sum rule,
\begin{align}\label{testb}
  \mathcal{A}(\Xi^0_c\to \Xi^-\pi^+)+\sqrt{2}\mathcal{A}(\Xi^0_c\to \Xi^0\pi^0)+\mathcal{A}(\Xi^+_c\to \Xi^0\pi^+)=0.
\end{align}
Under the isospin symmetry, particles in an isospin multiplet can be treated as identical in $\Delta$ and $\Theta$.
The isospin sum rule~\eqref{testb} can be verified in terms of $t$- and $s$-channel rescattering amplitudes.
Tests of isospin sum rules in other charmed baryon decay systems are presented in Appendix~\ref{exam}.

\subsection{Baryon\quad .$vs$.\quad Meson}

In this subsection, we compare rescattering amplitudes between meson and baryon systems.
The detailed analysis for the relation between topological amplitudes and rescattering amplitudes in charmed meson decays can be found in Ref.~\cite{Wang:2021rhd}.
\begin{itemize}
  \item The decay amplitude for a singly Cabibbo-suppressed charmed hadron decay mode is written as $\mathcal{A}=\lambda_d\mathcal{A}_d+\lambda_s\mathcal{A}_s$.
Then the $CP$ violation can then be expressed as
\begin{align}
A_{CP}^{\rm dir}\simeq -2\,\frac{{ Im}(\lambda_d^*\lambda_s)}{|\lambda_d|^2} \frac{{ Im}(\mathcal{A}_d^*\mathcal{A}_s)}{|\mathcal{A}_d-\mathcal{A}_s|^2}.
\end{align}
In $D\to PP$ decays, the quark-loop diagram $P$ is the primary source of $CP$ asymmetries, as its long-distance effect induced by rescattering dynamics is comparable to tree diagrams.
In the $B_{c\overline{3}} \to B_8 P$ decays, amplitudes $A_{11}$ and $A_{12}$ are the primary sources of $CP$ asymmetries.
Similarly to the $D$ meson decays, the rescattering contributions in $A_{11}$ and $A_{12}$ are comparable to the tree amplitudes.
It is possible that $CP$ violation in some charmed baryon decay channels could reach $\mathcal{O}(10^{-4})$ or even $\mathcal{O}(10^{-3})$.

  \item For charmed meson decays, only mesons can serve as intermediate propagators.
      The $\mathcal{V}\mathcal{P}\mathcal{P}$ coupling has only one coupling constant.
  Under $SU(3)$ symmetry, the long-distance contributions for the $E$ and $P$ diagrams are equivalent \cite{Wang:2021rhd},
 \begin{align}\label{p}
 \mathcal{A}_L(E)=\mathcal{A}_L(P).
 \end{align}
For charmed baryon decays, both the meson and baryon serve as intermediate propagators.
The $\mathcal{P}\mathcal{B}\mathcal{B}$ and $\mathcal{V}\mathcal{B}\mathcal{B}$ couplings each have two coupling constants.
A simple relation like Eq.~\eqref{p} is not found in charmed baryon decays.
  \item
In Ref.~\cite{Wang:2021rhd} and this work, we factor out the coefficients of meson and baryon tensors in triangle and bubble diagrams.
In meson sector, both pseudoscalar and vector mesons form nonets.
The tensor representation of a meson $M^i_j$, for example $M^u_u$, can be written as $1/\sqrt{2}\pi^0+1/\sqrt{6}\eta_8+1/\sqrt{3}\eta_1$.
The contraction of two $M^u_u$ terms serves as a propagator in rescattering amplitudes, written as $\pi^0/2+\eta_8/6+\eta_1/3$.
In baryon sector, spin-1/2 ground-state baryons form an octet.
There is no spin-1/2 ground-state singlet baryon due to symmetry constraints.
The tensor representation $B^u_u$ is written as $1/\sqrt{2}\Sigma^0+1/\sqrt{6}\Lambda^0$.
The propagator constructed by contracting two $B^u_u$ term is $\Sigma^0/2+\Lambda^0/6$.
The absence of a singlet propagator can be considered a $SU(3)_F$ breaking effect.
It can be expected that $SU(3)_F$ breaking effects in charmed baryon decays are greater than those in charmed meson decays.

\end{itemize}


\subsection{Test the K\"orner-Pati-Woo theorem}

In the literature, the K\"orner-Pati-Woo theorem \cite{Pati:1970fg,Korner:1970xq} plays an important role in analyzing charmed baryon weak decays.
It stress that the two quarks produced by weak operators must be antisymmetric in flavor if they enter the same low-lying baryon.
The K\"orner-Pati-Woo theorem can be explained by following argument.
The four-quark operator for weak decay is
\begin{eqnarray}
\mathcal{O}(x)=\{\overline{q}_{\alpha,i}(x)(1-\gamma_5)q_{\beta,j}(x)\}
\{\overline{q}_{\gamma,k}(x)(1-\gamma_5)q_{\delta,l}(x)\},
\end{eqnarray}
where $\alpha$, $\beta$, $\gamma$, and $\delta$ are color indices, and $i$, $j$, $k$, and $l$ are flavor indices.
It can be written as the following formula via Fierz transformation:
\begin{eqnarray}
\mathcal{O}(x)=\{\overline{q}_{\gamma,k}(x)(1-\gamma_5)q_{\beta,j}(x)\}
\{\overline{q}_{\alpha,i}(x)(1-\gamma_5)q_{\delta,l}(x)\}.
\end{eqnarray}
Thus, $\mathcal{O}(x)$ is symmetric under the interchange $(\alpha, i) \leftrightarrow (\gamma, k)$.
If two quarks produced by weak operators enter a final-state baryon, only the color-antisymmetric part of $\mathcal{O}(x)$ under the interchange $\alpha \leftrightarrow \gamma$ contributes, since the low-lying baryon is an $SU(3)_C$ singlet.
As a consequence, the two quarks must be antisymmetric in flavor.

By applying the K\"orner-Pati-Woo theorem and isospin symmetry to topological diagrams, we can derive relations between the branching fractions of heavy baryon weak decays, which extend beyond isospin sum rules.
The decay amplitudes for the $\Lambda_c^+\to \Sigma^+K^0$ and $\Lambda_c^+\to \Sigma^0K^+$ decays are \cite{Wang:2024ztg}
\begin{align}
 \mathcal{A}(\Lambda_c^+\to \Sigma^+K^0) &= \lambda_d(A_1+A_{11})+\lambda_s(A_7+A_{11}),\\
  \mathcal{A}(\Lambda_c^+\to \Sigma^0K^+) &= \frac{1}{\sqrt{2}}\lambda_d(-A_3+A_{11})+\frac{1}{\sqrt{2}}\lambda_s(A_7+A_{11}).
\end{align}
If the K\"orner-Pati-Woo theorem is valid for charmed baryon decays, we obtain $A_1= -A_3$ in the isospin limit \cite{Wang:2024ztg,Wang:2025bdl}.
Then we have
\begin{align}\label{q1}
\sqrt{2}\mathcal{A}(\Lambda_c^+\to \Sigma^0K^+) = \mathcal{A}(\Lambda_c^+\to \Sigma^+K^0).
\end{align}
The above equation was also derived in Ref.~~\cite{Geng:2019xbo}.
Equation~\eqref{q1} holds when considering $SU(3)_F$ breaking effects.
However, it is violated if the K\"orner-Pati-Woo theorem does not hold.
Isospin breaking is naively predicted to be $\mathcal{O}(1\%)$.
If Eq.~\eqref{q1} is significantly violated, it indicates the violation of the K\"orner-Pati-Woo theorem.

Equation \eqref{q1} does not hold in rescattering dynamics.
The rescattering contributions to the $\Lambda_c^+\to \Sigma^+K^0$ decay include
\begin{align}
 T(A_1)_1[s,d,u,d]\,&=\, -\frac{1}{2}\Delta_{\beta^-,\beta^-}(\Lambda^+_c,\pi^+,n,\Sigma^0,\Sigma^+,K^0)
 +\frac{1}{6}\Delta_{\beta^-,\beta^-}(\Lambda^+_c,\pi^+,n,\Lambda^0,\Sigma^+,K^0),
 \nonumber\\
 T(A_1)_2[s,d,u,d]\,&=\, -\frac{1}{3}\Delta_{\beta^-,\beta^+}(\Lambda^+_c,\pi^+,n,\Lambda^0,\Sigma^+,K^0),
 \nonumber\\
 T(A_1)_4[s,d,u,d]\,&=\, -\frac{1}{3}\Delta_{\beta^+,\beta^+}(\Lambda^+_c,\pi^+,n,\Lambda^0,\Sigma^+,K^0),
 \nonumber\\
 T(A_7)_1[s,s,u,d]\,&=\, -\frac{1}{3}\Delta_{\alpha^+,\gamma^-}(\Lambda^+_c,K^+,\Lambda^0,\rho^+,K^0,\Sigma^+),
 \nonumber\\
 T(A_7)_2[s,s,u,d]\,&=\, -\frac{1}{3}\Delta_{\alpha^+,\gamma^+}(\Lambda^+_c,K^+,\Lambda^0,\rho^+,K^0,\Sigma^+),
 \nonumber\\
 T(A_7)_3[s,s,u,d]\,&=\, -\frac{1}{3}\Delta_{\beta^+,\beta^+}(\Lambda^+_c,K^+,\Lambda^0,\Xi^0,\Sigma^+,K^0),
 \nonumber\\
 S(A_7)_1[s,s,u,d]\,&=\, -\frac{1}{3}\Delta_{\beta^-,\beta^-}(\Lambda^+_c,K^+,\Lambda^0,p,K^0,\Sigma^+),
 \nonumber\\
 T(A_{11})[s,d,u,d]\,&=\, \frac{1}{2}\Delta_{\beta^+,\beta^-}(\Lambda^+_c,\pi^+,n,\Sigma^0,\Sigma^+,K^0)
 +\frac{1}{6}\Delta_{\beta^+,\beta^-}(\Lambda^+_c,\pi^+,n,\Lambda^0,\Sigma^+,K^0),
 \nonumber\\
 S(A_{11})[s,d,u,d]\,&=\, \Theta_{\beta^+,\beta^-}(\Lambda^+_c,\pi^+,n,p,K^0,\Sigma^+),
 \nonumber\\
 T(A_{11})[s,s,u,d]\,&=\, \frac{2}{3}\Delta_{\beta^+,\beta^-}(\Lambda^+_c,K^+,\Lambda^0,\Xi^0,\Sigma^+,K^0),
 \nonumber\\
 S(A_{11})[s,s,u,d]\,&=\, \frac{2}{3}\Theta_{\beta^+,\beta^-}(\Lambda^+_c,K^+,\Lambda^0,p,K^0,\Sigma^+).
\end{align}
The rescattering contributions to the $\Lambda_c^+\to \Sigma^0K^+$ decay include
\begin{align}
 T(A_3)_1[s,d,d,u]\,&=\, -\Delta_{\alpha^+,\gamma^-}(\Lambda^+_c,\pi^+,n,K^{*0},K^+,\Sigma^0),
\nonumber\\
 T(A_3)_2[s,d,d,u]\,&=\, \Delta_{\beta^-,\beta^-}(\Lambda^+_c,\pi^+,n,\Sigma^-,\Sigma^0,K^+),
\nonumber\\
 T(A_7)_1[s,s,u,u]\,&=\, -\frac{1}{6}\Delta_{\alpha^+,\gamma^-}(\Lambda^+_c,K^+,\Lambda^0,\rho^0,K^+,\Sigma^0)
 -\frac{1}{6}\Delta_{\alpha^+,\gamma^-}(\Lambda^+_c,K^+,\Lambda^0,\omega,K^+,\Sigma^0),
\nonumber\\
 T(A_7)_2[s,s,u,u]\,&=\, -\frac{1}{6}\Delta_{\alpha^+,\gamma^+}(\Lambda^+_c,K^+,\Lambda^0,\rho^0,K^+,\Sigma^0)
 -\frac{1}{6}\Delta_{\alpha^+,\gamma^+}(\Lambda^+_c,K^+,\Lambda^0,\omega,K^+,\Sigma^0),
\nonumber\\
 T(A_7)_3[s,s,u,u]\,&=\, -\frac{1}{3}\Delta_{\beta^+,\beta^+}(\Lambda^+_c,K^+,\Lambda^0,\Xi^-,\Sigma^0,K^+),
\nonumber\\
 S(A_7)_1[s,s,u,u]\,&=\, -\frac{1}{3}\Theta_{\beta^-,\beta^-}(\Lambda^+_c,K^+,\Lambda^0,p,K^+,\Sigma^0),
\nonumber\\
 T(A_{11})[s,d,u,u]\,&=\, \Delta_{\beta^+,\beta^-}(\Lambda^+_c,\pi^+,n,\Sigma^-,\Sigma^0,K^+),
\nonumber\\
 S(A_{11})[s,d,u,u]\,&=\, \Theta_{\beta^+,\beta^-}(\Lambda^+_c,\pi^+,n,p,K^+,\Sigma^0),
\nonumber\\
 T(A_{11})[s,s,u,u]\,&=\, \frac{2}{3}\Delta_{\beta^+,\beta^-}(\Lambda^+_c,K^+,\Lambda^0,\Xi^-,\Sigma^0,K^+),
\nonumber\\
 S(A_{11})[s,s,u,u]\,&=\, \frac{2}{3}\Theta_{\beta^+,\beta^-}(\Lambda^+_c,K^+,\Lambda^0,p,K^+,\Sigma^0),
\nonumber\\
 T(A_{15})_1[s,s,d,d]\,&=\, \frac{1}{6}\Delta_{\alpha^+,\gamma^-}(\Lambda^+_c,K^+,\Lambda^0,\rho^0,K^+,\Sigma^0)
 -\frac{1}{6}\Delta_{\alpha^+,\gamma^-}(\Lambda^+_c,K^+,\Lambda^0,\omega,K^+,\Sigma^0),
\nonumber\\
 T(A_{15})_{2}[s,s,d,d]\,&=\, \frac{1}{6}\Delta_{\alpha^+,\gamma^+}(\Lambda^+_c,K^+,\Lambda^0,\rho^0,K^+,\Sigma^0)
 -\frac{1}{6}\Delta_{\alpha^+,\gamma^+}(\Lambda^+_c,K^+,\Lambda^0,\omega,K^+,\Sigma^0),
\nonumber\\
T(A_{15})_5[s,s,u,u]\,&=\,
 -\frac{1}{3}\Delta_{\alpha^+,\gamma^0}(\Lambda^+_c,K^+,\Lambda^0,\omega,K^+,\Sigma^0),
\nonumber\\
 T(A_{15})_{6}[s,s,u,u]\,&=\,
 \frac{1}{3}\Delta_{\alpha^+,\gamma^0}(\Lambda^+_c,K^+,\Lambda^0,\phi,K^+,\Sigma^0),
 \nonumber\\
T(A_{15})_5[s,s,d,d]\,&=\,
 -\frac{1}{3}\Delta_{\alpha^+,\gamma^0}(\Lambda^+_c,K^+,\Lambda^0,\omega,K^+,\Sigma^0),
\nonumber\\
 T(A_{15})_{6}[s,s,d,d]\,&=\,
 \frac{1}{3}\Delta_{\alpha^+,\gamma^0}(\Lambda^+_c,K^+,\Lambda^0,\phi,K^+,\Sigma^0).
\end{align}
In the above formula, we include contributions from the vanishing amplitudes $A_{15}^{u}$ and $A_{15}^{d}$, where the superscripts $u$ and $d$ denote the quark components of the $\Sigma^0$ baryon.
Summing all contributions, the rescattering amplitudes contributing to the $\Lambda_c^+\to \Sigma^+K^0$ and $\Lambda_c^+\to \Sigma^0K^+$ modes are
  \begin{align} \label{q4}
  \mathcal{A}_L(\Lambda_c^+\to \Sigma^+K^0) &=-\frac{1}{2}\lambda_d\Delta_{(\beta^++\beta^-),(2\beta^+-\beta^-)}
  (\Lambda_c^+,\pi^+,n,\Lambda^0,\Sigma^+,K^0) \nonumber\\ &~~  +\frac{1}{2}\lambda_d\Delta_{(\beta^+-\beta^-),\beta^-}(\Lambda_c^+,\pi^+,n,\Sigma^0,\Sigma^+,K^0)\nonumber\\&~~ -\frac{1}{3}\lambda_s\Delta_{\alpha^+,(\gamma^++\gamma^-)}(\Lambda_c^+,K^+,\Lambda^0, \rho^{+},K^0,\Sigma^+)\nonumber\\ &~~ -\frac{1}{3}\lambda_s\Delta_{\beta^+,(\beta^+-2\beta^-)}(\Lambda_c^+,K^+,\Lambda^0, \Xi^0,\Sigma^+,K^0)\nonumber\\ &~~+\lambda_d\Theta_{\beta^+,\beta^-}(\Lambda^+_c,\pi^+,n,p,K^0,\Sigma^+)\nonumber\\ &~~
  +\frac{1}{3}\lambda_s\Theta_{(2\beta^+-\beta^-),\beta^-}(\Lambda^+_c,K^+,\Lambda^0,p,K^0,\Sigma^+),
\end{align}
\begin{align}\label{q5}
  \mathcal{A}_L(\Lambda_c^+\to \Sigma^0K^+) &=
  \frac{1}{\sqrt{2}}\lambda_d\Delta_{\alpha^+,\gamma^-}(\Lambda_c^+,\pi^+,n,\overline K^{*0},K^+,\Sigma^0) \nonumber\\ &~~
 +\frac{1}{\sqrt{2}}\lambda_d\Delta_{(\beta^+-\beta^-),\beta^-}(\Lambda_c^+,\pi^+,n,\Sigma^-,\Sigma^0,K^+) \nonumber\\&~~ -\frac{1}{3\sqrt{2}}\lambda_s\Delta_{\alpha^+,(\gamma^++\gamma^-)}(\Lambda_c^+,K^+,\Lambda^0, \rho^{0},K^+,\Sigma^0)\nonumber\\&~~-\frac{1}{3\sqrt{2}}\lambda_s\Delta_{\beta^+,(\beta^+-2\beta^-)}(\Lambda_c^+,K^+,\Lambda^0, \Xi^-,\Sigma^0,K^+)\nonumber\\&~~+\frac{1}{\sqrt{2}}\lambda_d\Theta_{\beta^+,\beta^-}
  (\Lambda^+_c,\pi^+,n,p,K^+,\Sigma^0)\nonumber\\&~~+\frac{1}{3\sqrt{2}}\lambda_s\Theta_{(2\beta^+-\beta^-),\beta^-}
  (\Lambda^+_c,K^+,\Lambda^0,p,K^+,\Sigma^0).
  \end{align}
Note that Eq.~\eqref{q1} is violated in Eqs.~\eqref{q4} and \eqref{q5}.
The two particles generated from the emission diagram $T^{SD}$ rescatter into final-state particles by exchanging a baryon in the first term of Eq.~\eqref{q4}, while exchanging a meson in the first term of Eq.~\eqref{q5}.
The first terms in Eqs.~\eqref{q4} and \eqref{q5} include rescattering contributions from the decay amplitudes $A_1$ and $A_3$, respectively.
Thus, Eqs.~\eqref{q4} and \eqref{q5} indicate that the relation $A_1 = -A_3$ is violated in rescattering dynamics.

The final-state particles in Eq.~\eqref{q1}, such as $K^{+}$ and $K^{0}$ mesons, can be replaced by excited-state particles $K^{*+}$ and $K^{*0}$ mesons.
The branching fraction of the $\Lambda^+_c\to \Sigma^+K^{*0}$ mode is twice that of $\Lambda^+_c\to \Sigma^0K^{*+}$ mode according to Eq.~\eqref{q1}.
In Ref.~\cite{Jia:2024pyb}, the branching fractions for $\Lambda^+_c\to \Sigma^+K^{*0}$ and $\Lambda^+_c\to \Sigma^0K^{*+}$ are calculated to be
\begin{align}
 \mathcal{B}r(\Lambda^+_c\to \Sigma^+K^{*0}) = 2.10^{+1.37}_{-0.86}\times 10^{-3},\qquad \mathcal{B}r(\Lambda^+_c\to \Sigma^0K^{*+}) = 1.60^{+0.89}_{-0.62}\times 10^{-3}.
\end{align}
It is found Eq.~\eqref{q1} is violated.
The fact that the K\"orner-Pati-Woo theorem is violated by rescattering dynamics is also obtained in other decay channels.
See Refs.~\cite{Li:2020qrh,Han:2021gkl,Hu:2024uia,Jiang:2018oak,Jia:2024pyb,Han:2021azw} for additional cases.

