  \caption{Two topological diagrams contributing to the $\Lambda^+_c\to \Sigma^0K^+$ and $\Lambda^+_c\to \Sigma^+K^0$ decays, respectively.}\label{f3}
\end{figure}
\begin{figure}[t!]
