\nonumber\\
  T(A_1)_1[u,d,u,s]\,&=\,
-\frac{1}{3}\Delta_{\beta^-,\beta^-}(\Xi^0_c,\pi^+,\Xi^-,\Lambda^0,\Sigma^+,K^-),
\nonumber\\
  T(A_1)_3[u,d,u,s]\,&=\,
-\frac{1}{3}\Delta_{\beta^+,\beta^-}(\Xi^0_c,\pi^+,\Xi^-,\Lambda^0,\Sigma^+,K^-),
\nonumber\\
  T(A_1)_4[u,d,u,s]\,&=\,-\frac{1}{2}\Delta_{\beta^+,\beta^+}
  (\Xi^0_c,\pi^+,\Xi^-,\Sigma^0,\Sigma^+,K^-)
+\frac{1}{6}\Delta_{\beta^+,\beta^+}(\Xi^0_c,\pi^+,\Xi^-,\Lambda^0,\Sigma^+,K^-),
\nonumber\\
S(A_6)[u,d,u,s]\,&=\,\Theta_{\beta^-,\beta^+}(\Xi^0_c,\pi^+,\Xi^-,\Xi^0,K^-,\Sigma^+).
\end{align}
Summing all the long-distance contributions, we have
\begin{align}\label{xx5}
  \mathcal{A}_L(\Xi_{c}^{0}\to \Sigma^+K^-)&=-\frac{1}{2}\lambda_1\Delta_{(\beta^+-\beta^-),\beta^+}
  (\Xi^0_c,\pi^+,\Xi^-,\Sigma^0,\Sigma^+,K^-)\nonumber\\
  &~~+\frac{1}{6}\lambda_1\Delta_{(\beta^++\beta^-),(\beta^+-2\beta^-)}
  (\Xi^0_c,\pi^+,\Xi^-,\Lambda^0,\Sigma^+,K^-)\nonumber\\
  &~~+\lambda_1\Theta_{\beta^-,\beta^+}(\Xi^0_c,\pi^+,\Xi^-,\Xi^0,K^-,\Sigma^+).
