  T(A_8)_3[d,d,u,u]\,&=\, -\frac{1}{4}\Delta_{\beta^-,\beta^+}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^0, \Sigma^+,\pi^0)-\frac{1}{12}\Delta_{\beta^-,\beta^+}(\Xi^+_c,\pi^+,\Sigma^0,\Lambda^0, \Sigma^+,\pi^0)\nonumber\\&~~~~+\frac{1}{12}\Delta_{\beta^-,\beta^+}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^0, \Sigma^+,\pi^0)+\frac{1}{36}\Delta_{\beta^-,\beta^+}(\Xi^+_c,\pi^+,\Lambda^0,\Lambda^0, \Sigma^+,\pi^0),\nonumber\\
  T(A_8)_4[d,d,u,u]\,&=\, -\frac{1}{4}\Delta_{\beta^-,\beta^-}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^0, \Sigma^+,\pi^0)-\frac{1}{12}\Delta_{\beta^-,\beta^-}(\Xi^+_c,\pi^+,\Sigma^0,\Lambda^0, \Sigma^+,\pi^0)\nonumber\\&~~~~+\frac{1}{12}\Delta_{\beta^-,\beta^-}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^0, \Sigma^+,\pi^0)+\frac{1}{36}\Delta_{\beta^-,\beta^-}(\Xi^+_c,\pi^+,\Lambda^0,\Lambda^0, \Sigma^+,\pi^0),\nonumber\\
 S(A_{8})_1[d,d,u,u]\,&=\, -\frac{1}{2}\Theta_{\beta^-,\beta^+}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^+,\pi^0, \Sigma^+)+\frac{1}{6}\Theta_{\beta^-,\beta^+}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^+,\pi^0, \Sigma^+),\nonumber\\
  T(A_{10})_3[d,d,u,u]\,&=\, \frac{1}{4}\Delta_{\beta^+,\beta^+}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^0, \Sigma^+,\pi^0)-\frac{1}{12}\Delta_{\beta^+,\beta^+}(\Xi^+_c,\pi^+,\Sigma^0,\Lambda^0, \Sigma^+,\pi^0)\nonumber\\&~~~~-\frac{1}{12}\Delta_{\beta^+,\beta^+}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^0, \Sigma^+,\pi^0)+\frac{1}{36}\Delta_{\beta^+,\beta^+}(\Xi^+_c,\pi^+,\Lambda^0,\Lambda^0, \Sigma^+,\pi^0),\nonumber\\
  T(A_{10})_4[d,d,u,u]\,&=\, \frac{1}{4}\Delta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^0, \Sigma^+,\pi^0)-\frac{1}{12}\Delta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Sigma^0,\Lambda^0, \Sigma^+,\pi^0)\nonumber\\&~~~~-\frac{1}{12}\Delta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^0, \Sigma^+,\pi^0)+\frac{1}{36}\Delta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Lambda^0,\Lambda^0, \Sigma^+,\pi^0),\nonumber\\
  T(A_{11})[d,d,u,d]\,&=\, \frac{1}{4}\Delta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^0, \Sigma^+,\pi^0)+\frac{1}{12}\Delta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Sigma^0,\Lambda^0, \Sigma^+,\pi^0)\nonumber\\&~~~~+\frac{1}{12}\Delta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^0, \Sigma^+,\pi^0)+\frac{1}{36}\Delta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Lambda^0,\Lambda^0, \Sigma^+,\pi^0),\nonumber\\
  S(A_{11})[d,d,u,d]\,&=\, \frac{1}{2}\Theta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^+,\pi^0, \Sigma^+)+\frac{1}{6}\Theta_{\beta^+,\beta^-}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^+,\pi^0, \Sigma^+)\nonumber\\
  T(A_{11})[d,s,u,d]\,&=\, \Delta_{\beta^+,\beta^-}(\Xi^+_c,K^+,\Xi^0,\Xi^0, \Sigma^+,\pi^0),\nonumber\\
  S(A_{11})[d,s,u,d]\,&=\, \Theta_{\beta^+,\beta^-}(\Xi^+_c,K^+,\Xi^0,\Sigma^+,\pi^0, \Sigma^+),\\\nonumber
%\end{align}
%\begin{align}
   T(A_{12})[d,d,u,u]\,&=\, -\frac{1}{2}\Delta_{\alpha^+,\gamma^+}(\Xi^+_c,\pi^+,\Sigma^0,\rho^+,\pi^0, \Sigma^+)-\frac{1}{6}\Delta_{\alpha^+,\gamma^+}(\Xi^+_c,\pi^+,\Lambda^0,\rho^+,\pi^0, \Sigma^+),\nonumber\\
  S(A_{12})[d,d,u,u]\,&=\, \frac{1}{2}\Theta_{\beta^+,\beta^+}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^+,\pi^0, \Sigma^+)+\frac{1}{6}\Theta_{\beta^+,\beta^+}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^+,\pi^0, \Sigma^+),\nonumber\\
   T(A_{12})[d,s,u,u]\,&=\, -\Delta_{\alpha^+,\gamma^+}(\Xi^+_c,K^+,\Xi^0,K^{*+},\pi^0, \Sigma^+),\nonumber\\
   S(A_{12})[d,s,u,u]\,&=\, \Theta_{\beta^+,\beta^+}(\Xi^+_c,K^+,\Xi^0,\Sigma^+,\pi^0, \Sigma^+).
\end{align}
Summing all long-distance contributions, we have
\begin{align}
  \mathcal{A}_L(\Xi_{c}^{+}\to \Sigma^+\pi^0)&=\frac{1}{\sqrt{2}}\lambda_d\Delta_{\alpha^+,(\gamma^+-\gamma^-)}(\Xi^+_c,\pi^+,\Sigma^0,\rho^+,\pi^0, \Sigma^+)\nonumber\\&~~+\frac{1}{3\sqrt{2}}\lambda_d\Delta_{\alpha^+,(\gamma^++\gamma^-)}(\Xi^+_c,\pi^+,\Lambda^0,\rho^+,\pi^0, \Sigma^+)\nonumber\\&~~+\frac{1}{6\sqrt{2}}\lambda_d\Delta_{(\beta^++\beta^-),(\beta^++\beta^-)}(\Xi^+_c,\pi^+,\Sigma^0,\Lambda^0, \Sigma^+,\pi^0)\nonumber\\&~~+\frac{1}{6\sqrt{2}}\lambda_d\Delta_{(\beta^+-\beta^-),(\beta^++\beta^-)}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^0, \Sigma^+,\pi^0)\nonumber\\&~~+\frac{1}{\sqrt{2}}\lambda_s\Delta_{\alpha^+,\gamma^+}(\Xi^+_c,K^+,\Xi^0,K^{*+},\pi^0, \Sigma^+)\nonumber\\&~~+\frac{1}{\sqrt{2}}\lambda_s\Delta_{\beta^+,\beta^-}(\Xi^+_c,K^+,\Xi^0,\Xi^0, \Sigma^+,\pi^0)\nonumber\\&~~-\frac{1}{2\sqrt{2}}\lambda_d\Theta_{(\beta^+-\beta^-),(\beta^+-\beta^-)}(\Xi^+_c,\pi^+,\Sigma^0,\Sigma^+,\pi^0, \Sigma^+)\nonumber\\&~~-\frac{1}{6\sqrt{2}}\lambda_d\Theta_{(\beta^++\beta^-),(\beta^+-\beta^-)}(\Xi^+_c,\pi^+,\Lambda^0,\Sigma^+,\pi^0, \Sigma^+)\nonumber\\&~~-\frac{1}{\sqrt{2}}\lambda_s \Theta_{\beta^+,(\beta^+-\beta^-)}(\Xi^+_c,K^+,\Xi^0,\Sigma^+,\pi^0, \Sigma^+).
\end{align}
One can check isospin sum rule
\begin{align}
 &2\,\mathcal{A}( \Xi^0_c\to\Sigma^0\pi^0)-\mathcal{A}(\Xi^0_c\to\Sigma^+\pi^-)
-\mathcal{A}(\Xi^0_c\to\Sigma^-\pi^+)
+\sqrt{2}\mathcal{A}(\Xi^+_c\to\Sigma^+\pi^0)+
\sqrt{2}\mathcal{A}(\Xi^+_c\to\Sigma^0\pi^+)=0
\end{align}
is satisfied.

