\section{Some useful theorems}   \label{app}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%  

\noindent\textbf{Generalized Kronecker delta.}  
The generalized Kronecker delta is an extension of the usual Kronecker delta $\delta_i^j$, and is defined by  
%%%%  
\begin{align}  
\delta^{j_1 \cdots j_D}_{i_1 \cdots i_D} 
= \delta^{[j_1}_{[i_1} \cdots \delta^{j_D]}_{i_D]}  
= \delta^{[j_1}_{i_1} \cdots \delta^{j_D]}_{i_D},  
\end{align}  
%%%%  
where square brackets denote antisymmetrization with unit weight, i.e.,  
\begin{align}  
A_{[ij]} = \frac{1}{2}(A_{ij} - A_{ji}).  
\end{align}  

%%%%%%%%%%%%%%  
\noindent\textbf{Lemma.}  
Let $A_{i_1 \cdots i_D} = A_{[i_1 \cdots i_D]}$ be a totally antisymmetric tensor. Then,  
%%%%  
\begin{align}  
\delta^{j_1 \cdots j_D}_{i_1 \cdots i_D} A^{i_1 \cdots i_D} = A^{j_1 \cdots j_D}.  
\end{align}  
%%%%  
This identity follows directly from the definition of the generalized Kronecker delta and the antisymmetry of $A$.





%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{theorem}
%%%%%%%%%%%%%%%%
\begin{align}
\delta_{i_1 \cdots i_p}^{i_1 \cdots i_p} = \binom{D}{p}
\end{align}
%%%%%%%%%%%%%%%%
\end{theorem}
%%%%%%%%%
\begin{proof}
The key observation is that for a fixed set of indices,
\begin{align}
\delta_{i_1 \cdots i_p}^{i_1 \cdots i_p} = 1,
\end{align}
where \emph{no summation} is implied. The number of distinct antisymmetric combinations of $p$ indices from a set of $D$ is simply the number of $p$-element subsets of a $D$-element set, which is $\binom{D}{p}$. This identity generalizes the well-known result $\delta_{ii} = D$. In particular, when $p = D$, one finds
\begin{align}
\delta_{i_1 \cdots i_D}^{i_1 \cdots i_D} = 1.
\end{align}
\end{proof}
%%%%%%%%%%%%%%
\begin{theorem}
%%%%%%%%%%%%%%%%
\begin{align}
\varepsilon_{i_1 \cdots i_D} \varepsilon_{j_1 \cdots j_D} = D! \, \delta^{j_1 \cdots j_D}_{i_1 \cdots i_D}
\end{align}
%%%%%%%%%%%%%%%%
\end{theorem}
%%%%%%%%%
\begin{proof}
Both sides are totally antisymmetric under permutations of the indices $i_1, \ldots, i_D$ and $j_1, \ldots, j_D$, so they must be proportional. To determine the proportionality constant, contract both sides with $\delta_{j_1 \cdots j_D}^{i_1 \cdots i_D}$:
%%%%%%%%%%%%%%%%
\begin{align*}
\text{RHS} &= \delta_{j_1 \cdots j_D}^{i_1 \cdots i_D} \delta^{j_1 \cdots j_D}_{i_1 \cdots i_D}
= \delta^{i_1 \cdots i_D}_{i_1 \cdots i_D} = \binom{D}{D} = 1, \\\\
\text{LHS} &= \varepsilon_{i_1 \cdots i_D} \varepsilon_{j_1 \cdots j_D} \delta_{j_1 \cdots j_D}^{i_1 \cdots i_D}
= \varepsilon_{i_1 \cdots i_D} \varepsilon^{i_1 \cdots i_D} = D!\,,
\end{align*}
%%%%%%%%%%%%%%%%
where we used the identity $\varepsilon_{i_1 \cdots i_D} \varepsilon^{i_1 \cdots i_D} = D!$\,. Thus, the proportionality constant is $D!$, which completes the proof.
\end{proof}

%%%%%%%%%%%%%%
\begin{theorem}
%%%%%%%%%%%%%%%%
\begin{align}
\boxed{\quad
\delta^{i_1 \cdots i_p k_1 \cdots k_q}_{i_1 \cdots i_p j_1 \cdots j_q}  = \frac{p! \, q!}{D!} \, \delta^{k_1 \cdots k_q}_{j_1 \cdots j_q}
\quad}
\end{align}
%%%%%%%%%%%%%%%%
\end{theorem}
\begin{proof}
Left-hand side is totally antisymmetric in the sets $(j_1, \ldots, j_q)$ and $(k_1, \ldots, k_q)$, so the right-hand side must be proportional to $\delta^{k_1 \cdots k_q}_{j_1 \cdots j_q}$. To determine the proportionality constant, contract both sides with $\delta^{j_1 \cdots j_q}_{k_1 \cdots k_q}$.

\noindent\textbf{Left-hand side:}
%%%%%%%%%%%%%%%%
\begin{align}
\delta^{i_1 \cdots i_p k_1 \cdots k_q}_{i_1 \cdots i_p j_1 \cdots j_q} \, \delta^{j_1 \cdots j_q}_{k_1 \cdots k_q}
&= \delta^{i_1 \cdots i_p j_1 \cdots j_q}_{i_1 \cdots i_p j_1 \cdots j_q} = \binom{D}{D} = 1.
\end{align}
%%%%%%%%%%%%%%%%
\noindent\textbf{Right-hand side:}
%%%%%%%%%%%%%%%%
\begin{align}
\left( \frac{p! \, q!}{D!} \right) \delta^{k_1 \cdots k_q}_{j_1 \cdots j_q} \, \delta^{j_1 \cdots j_q}_{k_1 \cdots k_q}
&= \left( \frac{p! \, q!}{D!} \right) \delta^{j_1 \cdots j_q}_{j_1 \cdots j_q} = \left( \frac{p! \, q!}{D!} \right) \binom{D}{q}.
\end{align}
%%%%%%%%%%%%%%%%
Using the identity $\binom{D}{q} = \frac{D!}{p! \, q!}$, the right-hand side simplifies to 1, matching the left-hand side. This confirms that the proportionality constant is indeed $\frac{p! \, q!}{D!}$, completing the proof.
\end{proof}



%%%%%%%%%%%%%%
\begin{theorem} 
Let $D = p + q$. Then,
\begin{align}
\boxed{\quad 
\varepsilon_{i_1 \cdots i_p j_1 \cdots j_q} \, \varepsilon^{i_1 \cdots i_p k_1 \cdots k_q} = p! \, q! \, \delta^{k_1 \cdots k_q}_{j_1 \cdots j_q}\,.
\quad }
\end{align}
\end{theorem}
%%%%%%%%%%%%%%
\begin{proof}
We observe that:
\begin{align}
\varepsilon_{i_1 \cdots i_p j_1 \cdots j_q} \, \varepsilon^{i_1 \cdots i_p k_1 \cdots k_q}
= D! \, \delta^{i_1 \cdots i_p k_1 \cdots k_q}_{i_1 \cdots i_p j_1 \cdots j_q},
\end{align}
where it follows from Theorem 3. Applying Theorem 4 to the generalized Kronecker delta gives:
\begin{align}
\delta^{i_1 \cdots i_p k_1 \cdots k_q}_{i_1 \cdots i_p j_1 \cdots j_q}
= \frac{p! \, q!}{D!} \, \delta^{k_1 \cdots k_q}_{j_1 \cdots j_q}.
\end{align}
Substituting this into the previous expression yields:
\begin{align}
\varepsilon_{i_1 \cdots i_p j_1 \cdots j_q} \, \varepsilon^{i_1 \cdots i_p k_1 \cdots k_q}
= p! \, q! \, \delta^{k_1 \cdots k_q}_{j_1 \cdots j_q},
\end{align}
which completes the proof. Note that Theorem 3 is a special case of Theorem 5 with $p = 0$ and $q = D$.
\end{proof}


%%%%%%%%%%%%%%
\begin{theorem} 
Let $D = p + q$. Then,
%%%%%%%%%
\begin{align}
\boxed{\quad 
\varepsilon_{i_1 \cdots i_p j_1 \cdots j_q} \, \varepsilon_{m_1 \cdots m_p n_1 \cdots n_q}
\, A_{i_1 m_1} \cdots A_{i_p m_p} A_{j_1 k_1} \cdots A_{j_q k_q}
= p! \, q! \, \det A \, \delta_{n_1 \cdots n_q}^{k_1 \cdots k_q}.
\quad}
\label{det.A.delta}
\end{align}
%%%%%%%%%
\end{theorem}
%%%%%%%%%%%
\begin{proof}
The left-hand side must be proportional to $ \delta_{n_1 \cdots n_q}^{k_1 \cdots k_q}$, since both expressions are antisymmetric in the indices $\{k_1, \ldots, k_q\}$ and $\{n_1, \ldots, n_q\}$.

To see this, assume for contradiction that a term survives where $k_r \in \{m_1, \ldots, m_p\}$—i.e., some $k_r = m_s$. Then the combination $A_{i_s m_s} A_{j_r k_r}$ becomes symmetric under the exchange $i_s \leftrightarrow j_r$, while the Levi-Civita symbol $\varepsilon_{i_1 \cdots i_p j_1 \cdots j_q}$ is antisymmetric under that same exchange. Hence the term must vanish, and only terms where $\{k_1, \ldots, k_q\}$ matches $\{n_1, \ldots, n_q\}$ survive, up to antisymmetric reshuffling. Therefore, the structure must be:
%%%%%%%%%
\begin{align}
\varepsilon_{i_1 \cdots i_p j_1 \cdots j_q} \, \varepsilon_{m_1 \cdots m_p n_1 \cdots n_q}
\, A_{i_1 m_1} \cdots A_{i_p m_p} A_{j_1 k_1} \cdots A_{j_q k_q}
= \kappa \, \delta_{n_1 \cdots n_q}^{k_1 \cdots k_q}.
\end{align}
%%%%%%%%%
To determine the proportionality constant $\kappa$, contract both sides with $\delta_{k_1 \cdots k_q}^{n_1 \cdots n_q}$. The right-hand side yields:
\begin{align}
\kappa \, \delta_{n_1 \cdots n_q}^{k_1 \cdots k_q} \delta_{k_1 \cdots k_q}^{n_1 \cdots n_q}
= \kappa \, \delta_{n_1 \cdots n_q}^{n_1 \cdots n_q}
= \kappa \, \binom{D}{q}.
\end{align}
%%%%%%%%%
Now consider the left-hand side:
\begin{align}
&\varepsilon_{i_1 \cdots i_p j_1 \cdots j_q} \, \varepsilon_{m_1 \cdots m_p k_1 \cdots k_q}
A_{i_1 m_1} \cdots A_{i_p m_p} A_{j_1 k_1} \cdots A_{j_q k_q} \delta_{k_1 \cdots k_q}^{n_1 \cdots n_q} \nn\\
&= \varepsilon_{m_1 \cdots m_p n_1 \cdots n_q} \, \varepsilon_{r_1 \cdots r_p s_1 \cdots s_q}
A_{m_1 r_1} \cdots A_{m_p r_p} A_{n_1 s_1} \cdots A_{n_q s_q}
= D! \, \det A.
\end{align}
%%%%%%%%%
Equating both sides:
\begin{align}
D! \, \det A = \kappa \, \binom{D}{q} = \kappa \, \frac{D!}{p! \, q!} \quad \Rightarrow \quad \kappa = p! \, q! \, \det A.
\end{align}
This completes the proof.
\end{proof}


%%%%%%%%%%%%%%
\begin{theorem} 
Let $D = p + q$, and let $t$ denote the number of time-like directions in the metric. Then, for a $p$-form expressed in local coordinates:
%%%%%%%%%
\begin{align}
* * (dx^{i_1} \wedge \cdots \wedge dx^{i_p}) = (-1)^{pq + t} \, dx^{i_1} \wedge \cdots \wedge dx^{i_p}.
\end{align}
%%%%%%%%%
\end{theorem}
%%%%%%%%%%%%%%%
\begin{proof}
We revisit this well-known identity using a non-covariant representation. Begin by applying the Hodge star once:
%%%%%%%%%
\begin{align}
* (dx^{i_1} \wedge \cdots \wedge dx^{i_p}) &= \frac{1}{q!} \sqrt{(-1)^t \det g} \, g^{-1}_{i_1 k_1} \cdots g^{-1}_{i_p k_p} \, \varepsilon_{j_1 \cdots j_q k_1 \cdots k_p} \, dx^{j_1} \wedge \cdots \wedge dx^{j_q}.
\end{align}
%%%%%%%%%
Applying the Hodge star again gives:
%%%%%%%%%
\begin{align}
**(dx^{i_1} \wedge \cdots \wedge dx^{i_p}) 
&= \frac{1}{q! p!} (-1)^t \det g \, g^{-1}_{i_1 k_1} \cdots g^{-1}_{i_p k_p} \, \varepsilon_{j_1 \cdots j_q k_1 \cdots k_p} \nn\\
&\quad \times g^{-1}_{j_1 s_1} \cdots g^{-1}_{j_q s_q} \, \varepsilon_{r_1 \cdots r_p s_1 \cdots s_q} \, dx^{r_1} \wedge \cdots \wedge dx^{r_p}.
\label{startstar}
\end{align}
%%%%%%%%%
Now, applying Theorem~6 (Eq.~\eqref{det.A.delta}) to contract the epsilon symbols, we obtain:
%%%%%%%%%
\begin{align}
**(dx^{i_1} \wedge \cdots \wedge dx^{i_p})
&= (-1)^{pq + t} \frac{1}{p! \, q!} \det g \cdot \det g^{-1} \cdot p! \, q! \, \delta_{r_1 \cdots r_p}^{i_1 \cdots i_p} \, dx^{r_1} \wedge \cdots \wedge dx^{r_p} \nn\\
&= (-1)^{pq + t} \, dx^{i_1} \wedge \cdots \wedge dx^{i_p},
\end{align}
%%%%%%%%%
where we used $\det g \cdot \det g^{-1} = 1$ and the identity $\delta_{r_1 \cdots r_p}^{i_1 \cdots i_p} dx^{r_1} \wedge \cdots \wedge dx^{r_p} = dx^{i_1} \wedge \cdots \wedge dx^{i_p}$. This completes the proof.
\end{proof}



