% \end{align}

%We now investigate the Koopman modes obtained through Koopman mode decomposition.
Given a dictionary $\{\psi_{1},\psi_{2},\ldots,\psi_{N_k}\}$ of observables, the extended dynamic mode decomposition (EDMD) \cite{williams2015data} using Galerkin method selects a matrix $\bfA_{\rm{EDMD}}$ that approximates $\mathcal{K}$ on the subspace ${\mathcal{F}}_{N_{k}}:={\rm{span}}\{\psi_{1},\psi_{2},\ldots,\psi_{N_k}\}$, that is,
\begin{align*}
    {\mathcal{K}}\psi_{j}(\bfx)=\psi(\bfT(\bfx))\approx\sum_{i=1}^{N_k}(\bfA_{\rm{EDMD}})_{ij}\psi_i(\bfx)
\end{align*}
%${\mathcal{K}}\psi_{j}(\bfx)=\psi(\bfT(\bfx))\approx\sum_{i=1}^{N_k}(\bfA_{\rm{EDMD}})_{ij}\psi_i(\bfx)$ 
for $1\leq{j}\leq{N}_k$.
Define the vector-valued feature map $\Psi(\bfx)=[\psi_1(\bfx),\ldots,\psi_{N_k}(\bfx)]\in{\mathbb{C}}^{1\times{N_k}}$. Then for any observable $g\in{\mathcal{F}}_{N_k}$ can be written as $g(\bfx)=\sum_{j=1}^{N_k}\psi_j(\bfx)g_j=\Psi(\bfx){\bfg}$ for some vector ${\bfg}=[g_1,\ldots,g_{N_{K}}]^{\top}\in{\mathbb{C}}^{N_k}$. We have 
\begin{align*}
    &\quad\mathcal{K}g(\bfx)=\Psi(\bfT(\bfx))\bfg\\
    &=\Psi(\bfA_{\rm{EDMD}}\bfg)
   \!+\! \Bigg(\sum_{j=1}^{N_k}\psi_{j}(\bfT(\bfx))g_{j}-\Psi(\bfx)(\bfA_{\rm{EDMD}}\bfg)\Bigg).
\end{align*}

Furthermore, kernelized EDMD \cite{williams2016kernel} applies the kernel trick for EDMD setting to compute $\bfA_{\rm{EDMD}}$ by introducing a positive-definite kernel function $\kappa:\mathcal{M}\times\mathcal{M}\to{\mathbb{R}}$, which induces a feature map $\digamma:{\mathbb{R}}^{n}\to\mathcal{H}$ 
so that %$\langle\digamma(\bfx),\digamma(\bfx^{\prime})\rangle=\kappa(\bfx,\bfx^{\prime})$.
 \begin{align*}
\langle\digamma(\bfx),\digamma(\bfx^{\prime})\rangle=\kappa(\bfx,\bfx^{\prime}),
 \end{align*}
where $\mathcal{H}$ represents the reproducing kernel Hilbert space.

