\title{Singular Control in Inventory Management with Smooth Ambiguity}
% \title{Singular Controls in an Inventory Management with Model Learning under Recursive Robust Utility}
\author{Arnon Archankul\thanks{Department of Mathematics, University of York, United Kingdom. \ttfamily{arnon.archankul@york.ac.uk}} \hspace{0.5mm} and Jacco J.J. Thijssen\thanks{Department of Mathematics, University of York, United Kingdom. \ttfamily{jacco.thijssen@york.ac.uk}}}
\date{\today}
