% We define a random variable $\xi$ and a mapping $F$, so called the \emph{terminal value} and the \emph{driver}, respectively, satisfying the following definition:
\begin{definition}\label{ast: terminal+driver}
Given that $t\in[0,T]$, $r=(x,\ldots,x_d)\in \sr^d$ and $(y_i,z_i)\in\sr^2$ for $i=1,2$. The random variable $\xi$ and mapping $F$ are said to be \textit{proper} if
    \begin{enumerate}[{1.)}]
        \item $\xi\in\CL^{\infty}_T$
        \item $F$ is continuous in $(t,r)$.
        \item There exists $C_1<\infty$ such that 
        \begin{align}
            |F(t,r,y_i,z_i)| &\leq C_1(1 + |y_i|+|z_i|^2)\\
            |F(t,r,y_1,z_1) - F(t,r,y_2,z_2)|&\leq C_1\Big( |y_1-y_2|+(1+|y_1|+|y_2|+|z_1|+|z_2|)|z_1-z_2|\Big).
        \end{align}
    \end{enumerate}
\end{definition}
We call a random variable $\xi$ and a mapping $F$, \emph{terminal value} and \emph{driver}, respectively.

The following lemma will later be essential for the verification theorem. The proof can be found in \citet{Zhang2017-jp}, and so is omitted here.
\begin{lemma}[Exponential Martingale]\label{lem: exp mart}
    Let $\delta\in \CH^2_T$ with norm
    \begin{align}
         \Ep^{\Pp}_{\cG_t}\left[\int_t^T |\delta_s|^2 \rd s \right] \leq C_2<\infty,
    \end{align}
    for any $t\in [0,T]$, and suppose that the process $\Gamma=\pro{\Gamma}$ solves 
    \begin{align}
        \rd \Gamma_t = \delta_t \Gamma_t \rd \overline B_t\;\;\;\Gamma_0=1. 
    \end{align}
    Then
    \begin{align}
         \Ep^{\Pp}_{\cG_t}\left[ \expo{\epsilon \int_t^T |\delta_s|^2 \rd s}  \right] \leq \frac{1}{1-\epsilon C_2}, 
    \end{align}
    for any $\epsilon\in(0, \frac{1}{C_2})$, and there is $\epsilon'\in(0, \frac{1}{C_2})$ such that
    \begin{align}
         \Ep^{\Pp}_{\cG_t}\left[ \sup_{t\in [0,T]} |\Gamma_t|^{1+\epsilon} \right] \leq C_{\epsilon'}, 
    \end{align}
    where $C_{\epsilon'}$ depends on $C_2$. In particular, $\Gamma$ is a uniformly integrable martingale.
\end{lemma}

The existence and uniqueness result for FBSDEs satisfying Assumption \ref{ast: terminal+driver} are given by the following comparison theorem. For further detail, we refer to \citet{Kobylanski2000-zw} or \citet{Zhang2017-jp}.

\begin{lemma}[Comparison Theorem]\label{thm: comparison}
    Suppose that the process $(X_i ,A_i, Y_i, Z_i)\in(\CH^2_T)^{d}\times(\CH^{\infty}_T)^{d+1}\times\CH^{\infty}_T\times(\CH^2_T)^{d+1},$ is a solution to 
    \begin{align}
        -\rd Y_{i,t} = F_i(t,X_i,Y_i,Z_i) \rd t +  \rd A_{i,t}  - Z_{i,t} \cdot \rd \boldsymbol{B}_t,\;\;\;Y_{i,T}=\xi_{i,T}
    \end{align}
    where $\boldsymbol{B}$ is a $(d+1)-$Brownian motions under  $\Pp$, $X_i$ satisfy \eqref{eq: suff con a} and \eqref{eq: suff con s}, $A_i\in \cD^{d+1}$, $\xi_{i}$ and $F_i$ are proper, for $i=1,2$. Suppose, furthermore, that:
    \begin{enumerate}[{1.)}]
        \item $A_1 - A_2 \geq \boldsymbol{0}$ a.s.,
        \item $\xi_{1} - \xi_{2} \geq 0$ a.s. and
        \item $F_1 - F_2 \geq 0$ a.e.,
    \end{enumerate}
    where denoted by $\boldsymbol{0}$ is the $(d+1)$-dimensional null-vector. Then $Y_{1,t} - Y_{2,t} \geq 0 $ a.s. for $t\in [0,T]$.
\end{lemma}

Now we are ready to establish the FBSDE represention for the value function \eqref{def: value function}.
\begin{theorem}\label{thm: FBSDEs}
    There exists a unique solution to $(R^{M^{\Pp},A},A,J^{A},Z) \in (\CH^2_T)^3\times(\CH^{\infty}_T)^2\times\CH^{\infty}_T\times\CH^2_T $, where $R^{M^{\Pp},A}\triangleq(X^{M^{\Pp},A},M^{\Pp},S)$, such that
    \begin{align}
     &\rd X^{M^{\Pp},A}_t &&= (\alpha(X^{M^{\Pp},A}_t) -\sigma(X^{M^{\Pp},A}_t)M^{\Pp}_t )\rd t + \rd A_t+\sigma(X^{M^{\Pp},A}_t)\rd \overline B_t,&&  X^{M^{\Qp},A}_0=x, \label{eq: X^A_t}\\
         &\rd M_t^{\Pp} &&= S_t\rd \overline B_t +\rd D_t , && M^{\Pp}_0=m, \label{eq: M_t}\\
         &\rd S_t &&= -S_t^2 \rd t, && S_0=s, \label{eq: S_t}\\
         &\rd J_t^{A}&&= -F(t,R^{M,A}_t,J_t^{A},Z_t) \rd t  -\ell \rd A^-_t - u \rd A^+_t + Z_t \rd \overline B_t, &&J^{A}_T= \xi(X^{M^{\Pp},A}_T), \label{eq: J^A_t}
    \end{align}
    where 
    % $$F(t,r,y,z)\triangleq F(t,x,m,s,y,z)\triangleq -\rho y + c(x) + \frac{\gamma s}{2}z^2$$ for $(t,r,y,z)\in[0,T]\times \sr^5$.
    \begin{align}
       &F(t,r,y,z)\triangleq F(t,x,m,s,y,z)\triangleq -\rho y + f(x) + \frac{\gamma s}{2}z^2, \\
       &f\;\text{is convex in } x,
    \end{align}
    for $(t,r,y,z)\in[0,T]\times \sr^5$.
    Moreover, $J^{A}$ satisfies the inequality \eqref{def: robust control 2}, where equality holds for which
    \begin{align}\label{def: overline Q}
         \frac{\rd \Pp^{\phantom{\ast}}}{\rd \Qp^\ast}\Big|^{(s,t+h)}_{\cG_t} = \frac{\expo{\gamma (\theta_s - M^{\Pp}_s )Z_s}}{ \Ep^{\Pp}_{\cG_s}\left[\expo{\gamma (\theta_s - M^{\Pp}_s )Z_s} \right]},
    \end{align}
    where $s\in[t,t+h)$.
\end{theorem}

\begin{proof}[Proof of Theorem \ref{thm: FBSDEs}]
    We first establish existence and uniqueness of $(R^{M,A},A,J^{A},Z)$. It is clear that $R^{M,A}$ admits a unique solution since $\alpha$ and $\sigma$ satisfy \eqref{eq: suff con a} and \eqref{eq: suff con s}, respectively. The Riccati equation \eqref{eq: S_t} gives that $S_t = \frac{s}{1+st},\;\; t\in[0,T]$, which implies that $\sup_{t\geq0}|S_t|\leq s$. 
    The continuity of $f$ in $R^{M,A}$ and its Lipschitz continuity with linear growth in $J^{A}$ ensure that
    \begin{align*}
        |F(t,r,y,z)|&\leq C_f |y|  + \frac{\gamma |s|}{2}z^2 \\
        |F(t,r,y_1,z_2) - F(t,r,y_2,z_2)| &\leq C_f |y_1-y_2| + \frac{\gamma |s|}{2}(z_1^2-z_2^2) \\&= C_f |y_1-y_2| + \frac{\gamma |s|}{2}(z_1+z_2)(z_1-z_2)
    \end{align*}
    where $C_f$ is the Lipschitz constant of $f$. Therefore, if we choose $C_1=$ $C_f + \frac{\gamma |s|}{2}$, then $F$ is proper. Together with the boundedness of $\xi$, we conclude that there is a unique solution to $(R^{M^{\Pp},A},A,J^{A},Z) \in (\CH^2_T)^3\times(\CH^{\infty}_T)^2\times\CH^{\infty}_T\times\CH^2_T $.

