which is the completion of Theorem \ref{thm: FBSDEs}.
\end{proof}



% \section{Verification Theorem}
\section{Heuristic derivation of the optimal control policy}\label{sec:derivation}
Before we develop a heuristic derivation of the optimal control policy, we first show that the value function \eqref{def: value function} satisfies the dynamic programming principle (DPP). 

\begin{lemma}[Dynamic Programming Principle]\label{lem: DPP}
    Suppose that for a given feasible policy $A\in \cD$, $J^{A}$ is the solution to \eqref{eq: J^A_t}. 
    % We denote by $Y^{\ast}_t\triangleq Y^{A^\ast}_t=\inf_{A\in \cD} Y^{A}_t$, for any $0\leq t \leq T.$
    Then for any $h\in[0,T]$ and $t\in[0,T-h]$ it holds that
    \begin{align}\label{eq: DPP}
        \inf_{A\in \cD} J^{A}_t = \inf_{A\in \cD}  \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{t+h}   \left( F(s,R^{M,A}_s,J_s^{A},Z_s)  \rd s +\ell \rd A^-_s + u \rd A^+_s \right)  + \inf_{A\in \cD} J^{A}_{t+h}      \Bigg]
    \end{align}
\end{lemma}

\noindent\begin{proof}[Proof of Lemma \ref{lem: DPP}]
    By definition, we have
    \begin{align*}
        J^{A}_t &=  \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{T}   \bigg( F(s,R^{M,A}_s,J_s^{A},Z_s)  \rd s +\ell \rd A^-_s + u \rd A^+_s \bigg) + \xi(X^{M^{\Pp},A}_T)     \Bigg] \\
        &=  \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{t+h}   \bigg( F(s,R^{M,A}_s,J_s^{A},Z_s)  \rd s +\ell \rd A^-_s + u \rd A^+_s \bigg) +  J^{A}_{t+h}      \Bigg].
    \end{align*}
    Thus,
    \begin{align*}
        \inf_{A\in \cD} J^{A}_t &=\inf_{A\in \cD}   \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{t+h}   \bigg( F(s,R^{M,A}_s,J_s^{A},Z_s)  \rd s +\ell \rd A^-_s + u \rd A^+_s \bigg) +  J^{A}_{t+h}      \Bigg]\\
        &\geq \inf_{A\in \cD}  \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{t+h}   \bigg( F(s,R^{M,A}_s,J_s^{A},Z_s)  \rd s +\ell \rd A^-_s + u \rd A^+_s \bigg) + \inf_{A\in \cD} J^{A}_{t+h}      \Bigg].
    \end{align*}
    We next show that the opposite inequality also holds. Since $\inf_{A\in \cD} J^{A}_{t+h}$ is minimal among other feasible policies, the for any $\epsilon>0$, there exists a policy $\overline A\in \cD$ such that $\inf_{A\in \cD} J^{A}_{t+h} \geq  J^{\overline{L},\overline{U}}_{t+h} - \epsilon$. It follows that 
    \begin{align*}
        \inf_{A\in \cD} J^{A}_t &\leq   \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{t+h}   \left( F(s,R^{M,\overline A}_s,J_s^{\overline A},Z_s)  \rd s +\ell \rd \overline A^-_s + u \rd \overline A^+_s \right) +  J^{\overline{L},\overline{U}}_{t+h}      \Bigg]\\
        &\leq   \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{t+h}   \left( F(s,R^{M,\overline A}_s,J_s^{\overline A},Z_s)  \rd s +\ell \rd \overline A^-_s + u \rd \overline A^+_s \right) +  \inf_{A\in \cD} J^{A}_{t+h} + \epsilon      \Bigg]
    \end{align*}
    By arbitrariness of $\epsilon$, Lemma \ref{lem: DPP} is obtained.
\end{proof}

In order to solve \eqref{eq: DPP}, we first try the classical approach of the optimal (singular) control by \emph{assuming} that there is a $C^{1,2}([0,T]\times \sr^3)$ function $v(t,r)$ such that $v(t,r) = \inf_{A\in \cD} J^{A}_t$ given that $R^{M,A}_{t} = r= (x,m,s)$. If this assumption holds, then we can rewrite \eqref{eq: DPP} as
\begin{align}\label{eq: DPP v}
    v(t,r) &= \inf_{A\in \cD}  \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{t+h}   \bigg( F(s,R^{M,A}_s,J_s^{A},Z_s)  \rd s +\ell \rd A^-_s + u \rd A^+_s \bigg)  + v(t+h,R^{M,A}_{t+h})      \Bigg]
\end{align}
By applying It\={o}'s lemma to $v(t+h,R^{M,A}_{t+h})$ we can see that
\begin{align}\label{eq: HJB1}
    v(t,r) &= \inf_{A\in \cD}  \Ep^{\Pp}_{\cG_t}\Bigg[ v(t,r) + \int_t^{t+h}   \Bigg[  \bigg(\cL v(s,R^{M,A}_s)  +F(s,R^{M,A}_s,J_s^{A},Z_s) \bigg) \rd s \nonumber \\ & \hspace{4cm} + \left(\ell +\diff{v(s,R^{M,A}_s)}{x}\right)\rd A^-_s + \left(u-\diff{v(s,R^{M,A}_s)}{x}\right)\rd A^+_s   \Bigg]  \nonumber\\ & \hspace{4cm} + \diff{v(s,R^{M,A}_s)}{m}\rd D^-_s  -\diff{v(s,R^{M,A}_s)}{m}\rd D^+_s   \Bigg]      \Bigg]
\end{align}
where $\cL$ is so-called the infinitestimal generator operator of $v$, and defined by
\begin{align*}
    \cL v \triangleq \diff{v}{t}  + [\alpha(x)-m\sigma(x)]&\diff{v}{x} -s^2\diff{v}{s}  +\frac{\sigma^2(x)}{2}\frac{\partial^2v}{\partial x^2} +\frac{s^2}{2}\frac{\partial^2v}{\partial m^2} + s\sigma(x)\frac{\partial^2v}{\partial x\partial m}
\end{align*}
It is important to note that in order for a feasible policy to be optimal, it is sufficient from \eqref{eq: HJB1} that for any $A\in \cD$, 
\begin{align}\label{def: actions inequalities}
    \cL v(s,r) + F(t,r,y,z) \geq 0,\;\;\;\;  \ell +\diff{v(s,r)}{x} \geq 0,\;\;\;\;\textup{and}\;\;\;\;
     u - \diff{v(s,r)}{x} \geq 0,
\end{align}
for any $(s,r)\in [0,T]\times \sr^3$. That is to say,
\begin{align*}
    0 &\leq  \Ep^{\Pp}_{\cG_t}\Bigg[ \int_t^{t+h}   \Bigg[  \left(\cL v(s,R^{M^{\Pp},A}_s) +  F(s,R^{M^{\Pp},A}_s,J_s^{ A},Z_s) \right) \rd s \nonumber \\ & \hspace{4cm} + \left(\ell +\diff{v(s,R^{M^{\Pp},A}_s)}{x}\right)\rd  L^x_s + \left(u-\diff{v(s,R^{M^{\Pp},A}_s)}{x}\right)\rd  U^x_s   \Bigg]  \nonumber\\ & \hspace{4cm} + \diff{v(s,R^{M,A}_s)}{m}\rd D^-_s  -\diff{v(s,R^{M,A}_s)}{m}\rd D^+_s   \Bigg]      \Bigg],
\end{align*}
and the equality holds if there exists the optimal control policy $A^\ast\in \cD$. We show later by the verification theorem that these are also necessary conditions. Otherwise, a contradiction occurs. 

In order to establish the optimality conditions for the feasible control, let us recall the main idea behind  classical singular control given by \citet{harrison1983instantaneous}. Now we define by
\begin{align}
     h_{\underline m} \triangleq \inf\left\{h>0 :  M^{\Pp}_{t+h}=\mL\right\}\text{  and    }h_{\overline m} \triangleq\inf\left\{h>0 :  M^{\Pp}_{t+h}=\mU\right\}
    % \\
    % h_x &\triangleq \inf\left\{h'\geq0 : \left| X_{t+h'}^{  A} - X_t^{  A} \right| \leq \epsilon \right\},
\end{align} 
a $\cG_t$--stopping time. Here the operator $\wedge$ is that $a\wedge b = \min\{a,b\}$ for any $a,b\in\sr$. This stopping time determines a sequence of actions for the DM to consider. That is, for a given $\epsilon>0$ if $h_{\underline m}\wedge h_{\overline m}<\epsilon$, DM must reflect the belief process upward or downward, respectively, to keep $M^{\Pp}\in [\mL,\mU]$. Therefore, the value function is either
\begin{align}
    v_{\mL}(t,r)  &\triangleq \Ep^{\Pp}_{\cG_t}\left[v(t,r)+\int_t^{t+h_{\underline m}}\diff{v(s,R^{M^{\Pp},A}_s)}{m}\rd   D^-_s \right],\;\;\textup{or} \\
    v_{\mU}(t,r)  &\triangleq\Ep^{\Pp}_{\cG_t}\left[v(t,r) - \int_t^{t+h_{\overline m}}\diff{v(s,R^{M^{\Pp},A}_s)}{m}\rd   D^+_s \right].
\end{align}
On the other hand, if $h_{\underline m}\wedge h_{\overline m} > \epsilon$, there are three options to exercise;
(i) to exert the lower or (ii) upper singular control, or (iii) to remain inactive and incur the continuation value. It follows from \eqref{eq: HJB1} that the value function on $[t,t+\epsilon)$ for these options is either
\begin{align}
    v_{\ell}(t,r)  &\triangleq \Ep^{\Pp}_{\cG_t}\left[v(t,r)+\int_t^{t+\epsilon}\left(\ell +\diff{v(s,R^{M^{\Pp},A}_s)}{x}\right)\rd    A^-_s \right],\\
    v_{u}(t,r)  &\triangleq \Ep^{\Pp}_{\cG_t}\left[v(t,r)+\int_t^{t+\epsilon}\left(u -\diff{v(s,R^{M^{\Pp},A}_s)}{x}\right)\rd    A^+_s \right], \;\;\textup{or} \\
     v_c(t,r)  &\triangleq \Ep^{\Pp}_{\cG_t}\left[v(t,r)+\int_t^{t+\epsilon}\left(\cL v(s,R^{A}_s)  +F(s,R^{M^{\Pp},A}_s,J_s^{  A},Z_s)\right)\rd s \right],
\end{align}
respectively. Here there DM must take the option that minimises the cost function, then value function at $t+h_m\wedge\epsilon$ satisfies
\begin{align}\label{eq: HJB2}
    v(t,r)=\mathds1_{\{h_{\underline m}\wedge h_{\overline m}>\epsilon\}}\min\left\{v_{\ell}(t,r),v_{u}(t,r),v_{c}(t,r)\right\} +  \mathds1_{\{h_{\underline m}< h_{\overline m}<\epsilon\}}v_{\mL}(t,r)+  \mathds1_{\{h_{\overline m}< h_{\underline m}<\epsilon\}}v_{\mU}(t,r).
\end{align}
Dividing \eqref{eq: HJB2} by $h_{\underline m}\wedge h_{\overline m}\wedge\epsilon$ and send $\epsilon \to 0$, the MVT gives
\begin{align}
    0&=\min\left\{\cL v(t,r) +F(s,r,J_t^{A^\ast},Z_t), \;\;\ell + \diff{v(t,r)}{x},\;\; u - \diff{v(t,r)}{x}  \right\}, \\
    0&=\diff{v(t,x,\mL+,s)}{m}=\diff{v(t,x,\mU-,s)}{m}\\
    v(T,r)&=\xi(x).
\end{align}
By It\={o}'s lemma and the definition of $v$ it follows that
\begin{align}\label{eq: sol1}
    J_t^{A^\ast} = v(t,r)\;\;\textup{and}\;\;Z_t = \sigma(x) \diff{v(t,r)}{x} + s \diff{v(t,r)}{m}
\end{align}
Therefore, if the regularity of $v$ holds then we finally have that $v$ is the solution to the following HJB equation for singular control,
\begin{align}\label{eq: HJB3}
    0&=\min\left\{\cL v(t,r) + F\left(t,r,v(t,r),\sigma(x) \diff{v(t,r)}{x} + s \diff{v(t,r)}{m}\right),\;\; \ell + \diff{v(t,r)}{x},\;\; u - \diff{v(t,r)}{x}  \right\},\\
    0&=\diff{v(t,x,\mL+,s)}{m}=\diff{v(t,x,\mU-,s)}{m}\\
    v(T,r)&=\xi(x).
\end{align}
Now we defines by $\CC_v,\LB_v,\UB_v\subset[0,T]\times\sr$ such that
\begin{align}
    \LB_v&\triangleq\left\{(t,x)\in [0,T]\times\sr: -\ell\geq\diff{v(t,r)}{x}\right\}\label{def: lower stopped region}\\
    \UB_v&\triangleq\left\{(t,x)\in [0,T]\times\sr: \phantom{-}u\leq\diff{v(t,r)}{x} \right\}\;\;\;\text{and,}\label{def: upper stopped region}\\
    \CC_{ v}&\triangleq[0,T]\times\sr\setminus (\LB_{v}\cup\UB_{ v}),\label{def: continuation region}
\end{align}
It can be noticed as regard the definition of $\CC_v,\LB_v$ and $\UB_v$ that HJB equation \eqref{eq: HJB3} is equivalent to solving
\begin{align}
    \cL v(t,r) + F\left(t,r,v(t,r),\sigma(x) \diff{v(t,r)}{x} + s \diff{v(t,r)}{m}\right)&=0\;\;\;(t,x)\in\CC_v \label{eq: continue PDE}\\
    \ell + \diff{v(t,r)}{x}&=0\;\;\;(t,x)\in\LB_v\label{eq: lower barrier PDE}\\
    u - \diff{v(t,r)}{x}&=0\;\;\;(t,x)\in\UB_v.\label{eq: upper barrier PDE}\\
    \diff{v(t,x,\mL+,s)}{m}=\diff{v(t,x,\mU-,s)}{m}&=0 \label{eq: m barrier PDE}
\end{align}
This tells us that it is optimal to incur the continuation value, rather than exercising control, as long as the inventory stock explores in $\CC_v$. In other words, the control policy $A$ do not increase in this region. Mathematically speaking, it must holds that
\begin{align}\label{ast:not incressing L U}
    \int_0^T \mathds{1}_{\left\{(t,X^{M^{\Pp},A}_t)\in \CC_v\right\}} \rd (L^x_t + U^x_t)=0,\; \Pp-\textup{a.s.}
\end{align}
in which to be shown to be crucial in the verification theorem for the existence and uniqueness of the optimal control policy. On the other hands, once the inventory reaches $\LB_v$, for the HJB equation \eqref{eq: HJB3} to holds, the lower control must be exerted to keep the inventory within the continuation region. The upper control is taken into account in the same way  whenever $(t,R^{A})\in \UB_v$. 
For these reasons, we refer to the space $\CC_v,\LB_v$ and $\UB_v$ as a \textit{continuation region}, \textit{lower control barrier} and \textit{upper control barrier}, respectively. Moreover, we realise by construction of $F$ 
 that $v$ is \textit{convex} in $x$ (cf. \citet{Wang2004-js}, Proposition 3), which ensures that $\CC_v\cap\LB_v\cap\UB_v=\varnothing$. In other words, at most one decision is made, either to do nothing (when $(t,x)\in\CC_v$), or else to take either upper or lower controls.

However, the earlier claims are invalid if the value function is non-smooth, in which case there is no classical solution to \eqref{eq: HJB3}. We show in the next section that only continuity is required to construct the value function as a viscosity solution to the HJB equation.

% We establish in the verification theorem that this continuation region exists by showing that there cannot be strict greater inequalities at the time for all terms in \eqref{def: actions inequalities}. In other words, at most one decision is made, either to do nothing (when $(t,x)\in\CC$), or else to take either upper or lower controls.  

\section{Viscosity Solution of the Value Function}\label{sec:viscosity}
Given the previous argument, we cannot immediately say that the BSDE $(J^{A^\ast}, Z)$ given by \eqref{eq: sol1} is the solution the fully nonlinear PDE \eqref{eq: HJB3} (at least in a classical sense) since $J^{A^\ast}$ is only known to be continuous, but not necessary smooth, opposing to the assumption of $v$.  To deal with is issue, we employ the notion of viscosity solution introduced by \citet{crandall1983viscosity}, in which they generalise the solution of fully nonlinear PDEs to equip in a weaker sense, where the only locally boundedness is assumed. The development of a viscosity solution to the second order PDEs thanks to \citet{crandall1987uniqueness}, and our following argument will rely on this paper. In other words, we show that $J^{A^\ast}$ is a viscosity solution to \eqref{eq: HJB3}. Before doing so, let us first state the definition of viscosity solution.
\begin{definition}[Viscosity Solution]
    For all $v(t,r)\in C([0,T]\times \sr^3)$ and $\phi\in C^{1,2}([0,T]\times \sr^3)$, define the operator $\mathbb{L}$, for any $(t,r)\in[0,T]\times \sr^3$, by 
    \begin{equation}\label{eq:viscosity}
        \mathbb{L}\phi(t,r) \triangleq \cL\phi(t,r) + F\left(t,r,\phi(t,r),\sigma(x) \diff{\phi(t,r)}{x} + s \diff{\phi(t,r)}{m}\right).
    \end{equation}
    \begin{enumerate}[{1.)}]
        \item The function $v$ is a viscosity subsolution of~\eqref{eq: HJB3} if for all local maximum points $(t',r')\in[0,T]\times \sr^3$ of $v-\phi$ it holds that
        \begin{align}
            \min\Bigg\{ \mathbb{L}\phi(t',r'),\;\; \ell + \diff{\phi(t',r')}{x},\;\; u - \diff{\phi(t',r')}{x}  \Bigg\}\geq 0, \hspace{1cm} \phi(T,r')=h(x'). \label{eq: subsolution}
        \end{align}

        \item The function $v$ is a viscosity supersolution of~\eqref{eq: HJB3} if for all local minimum points $(t',r')\in[0,T]\times \sr^3$ of $v-\phi$ it holds that
        \begin{align}
            \min\Bigg\{ \mathbb{L}\phi(t',r'),\;\; \ell + \diff{\phi(t',r')}{x},\;\; u - \diff{\phi(t',r')}{x}  \Bigg\}\leq 0, \hspace{1cm} \phi(T,r')=h(x'), \label{eq: supersolution}
        \end{align}

        \item $v(t,r)\in C([0,T]\times \sr^3)$ is a viscosity solution of~\eqref{eq: HJB3} if it both viscosity subsolution and supersolution.
    \end{enumerate}
\end{definition}

\begin{remark}[]
    Given the possible non-smoothness of $u$, the construction of inaction or action regions, as outlined in definitions~\eqref{def: continuation region} to \eqref{def: upper stopped region}, becomes impractical. This also means that the condition~\eqref{ast:not incressing L U} is invalid. Consequently, it is imperative to revise~\eqref{def: continuation region} to \eqref{def: upper stopped region} and strengthen assumption~\eqref{ast:not incressing L U} to accommodate similar considerations for the non-smoothness of $u$. These adjustments will be shown in the verification theorem, highlighting their necessity for establishing the existence and uniqueness of the viscosity solution. 
\end{remark}

\begin{definition}
    For given $v\in C[0,T]\times \sr^3$ and $h>0$,
    \begin{align}
    \LB_v^h&\triangleq\left\{(t,x)\in [0,T]\times\sr: -\ell h\geq v(t,x,m,s)-v(t,x-h,m,s)\right\}\label{def: refined lower stopped region}\\
    \UB_v^h&\triangleq\left\{(t,x)\in [0,T]\times\sr: \phantom{-}uh\leq v(t,x+h,m,s)-v(t,x,m,s)\right\}\label{def: refined upper stopped region}\;\;\;\text{and,}\\
    \CC_{ v}^{h}&\triangleq[0,T]\times\sr\setminus (\LB_{v}^{h}\cup\UB_{v}^{h}),\label{def: refined continuation region}
\end{align}
\end{definition}

\begin{assumption}\label{ast:refined not incressing L U}
    Given  $v\in C[0,T]\times \sr^3$ and. For any feasible policy $A\in \cD$, there exists $h>0$ such that
    \begin{align}
        \int_0^T\mathds{1}_{\{(t,X^{M^{\Pp},A}_t)\in \CC_v^h\}} \rd (L^x_t + U^x_t) = 0,\;\Pp-\textup{a.s.}
    \end{align}
\end{assumption}

Now, we show that $J^{A^\ast}$ is indeed a viscosity solution of \eqref{eq: HJB3}.
\begin{theorem}\label{thm: viscosity 1}
    The value function defined by  \eqref{def: value function} is the unique continuous viscosity solution to \eqref{eq: HJB3}.
\end{theorem}

\noindent\begin{proof}[Proof of Theorem \ref{thm: viscosity 1}]\phantom{==}\\
    \textbf{Uniqueness: } First we claim that there exists a viscosity solution to \eqref{eq: HJB3}, which will be proved in the subsequent section. To this end, we suppose that $v$ is a viscosity solution to a smooth function $\phi\in C^{1,2}([0,T]\times \sr^3)$. Given $h>0$, it is straightforward from \citet{crandall1983viscosity} that $v$ admits a unique viscosity solution on the regions $\LB^h_v$ and $\UB^h_v$ since it is just a first order PDE.  Because $v$ is a viscosity solution to a PDE with quadratic in gradients on $\CC^h_v$, we have that there is also a unique viscosity solution on this region according to the argument given by \citet{Kobylanski2000-zw}. By smoothness of $\phi$ we conclude that $v$ has a unique viscosity solution.

    \textbf{Existence: }For what follows we adopt the idea from \citet{Zhang2017-jp}, which establishes the verification theorem for the non-controlled BSDE with a regular driver i.e. $f$ is Lipchitz in $Z$. Then we develop the argument to equip the theorem with singular controls and a driver with quadratic growth in $Z$. 

    Suppose that $\phi\in C^{1,2}([0,T]\times \sr^3)$. It is obvious from the definition that at $T$, $v(T,r')=h(x')=\phi(T,r')$. Thus, it is left to show the viscosity property of $v$ on $[0,T)\times \sr^3$. First, we prove that $v$ is a viscosity subsolution before proceeding to verify its supersolution property.

    \textbf{Subsolution:} we suppose $v-\phi$ has a maximum point at $(t',r')$. In other word, $(v-\phi)(t',r')=0$ and  $(v-\phi)(t',r')\geq (v-\phi)(t,r)$ for all $(t,r)\in [0,T)\times \sr^3$. Then we show that \eqref{eq: subsolution} holds. Suppose that $v(t,r)\triangleq \inf_{A\in \cD} J^{A}_{t}\triangleq J^{A^\ast}_{t}$. By DPP (Lemma \ref{lem: DPP}), it gives
    \begin{align}\label{eq: DPP v t'}
        v(t',r') = \Ep^{\Pp}_{\cG_{t'}}\left[ \int_{t'}^{t'+h}   \left( F\left(t,R_s^{A^\ast},v(s,R^{A^\ast}_{s}),Z_s\right)\rd s +\ell \rd A^{\ast-}_s + u \rd A^{\ast+}_s \right ) + v(t'+h,R^{A^\ast}_{t'+h})\right]
    \end{align}
    for $h>0$ such that $t'\leq t'+h \leq T.$ By It\={o}'s lemma, $\phi(t',r')$ solves
    \begin{align}
        \phi(t',r')=  \Ep^{\Pp}_{\cG_{t'}} \Bigg[-\int_{t'}^{t'+h}   \Bigg( \cL \phi(s,R^{A^\ast}_s) \rd s &+ \diff{\phi}{x}(s,R^{A^\ast}_s)\rd A^\ast_s +\diff{\phi}{m}(s,R^{A^\ast}_s)\rd D_s\Bigg) + \phi(t'+h,R^{A^\ast}_{t'+h})
        \Bigg]\label{eq: DPP phi t'}
    \end{align}
    Because $v-\phi$ has a maximum point at $(t',r')$, \eqref{eq: DPP v t'} and \eqref{eq: DPP phi t'} implies that
    \begin{align}
        0\leq  \Ep^{\Pp}_{\cG_{t'}}\Bigg[\int_{t'}^{t'+h}   \Bigg( &\left(\cL \phi(s,R^{A^\ast}_s) +  F\left(t,R_s^{A^\ast},v(s,R^{A^\ast}_{s}),Z_s\right) \right)\rd s \nonumber\\ &+ \left(\ell + \diff{\phi}{x}(s,R^{A^\ast}_s) 
        \right)\rd A^{\ast-}_s + \left(u - \diff{\phi}{x}(s,R^{A^\ast}_s) 
        \right)\rd A^{\ast+}_s +\diff{\phi}{m}(s,R^{A^\ast}_s)\rd D_s\Bigg)\Bigg]
     \end{align}
    Now we show that \eqref{eq: subsolution} holds by splitting the proof into two cases: when (i) for each $\omega_t\in\Omega$ such that $A^\ast(\omega_t)=(0,0)$ and (ii) such that $A^\ast(\omega_t)\neq(0,0)$, for $t\in[t',t'+h]$.

    \textbf{(i): }First of all, we choose $Z\triangleq\sigma(x)\diff{\phi}{x}+s\diff{\phi}{m}$. The smoothness of $\phi$ gives that $Z\in \CH^2_T$, implying that $v$ still admits a unique solution according to Theorem~\ref{thm: comparison}. Since the first case means there is no intervention on $[t',t'+h]$ and is one of the feasible policies as follows \eqref{cond:never intervene}, the integrals with respect to  $A^\ast$ vanish. Together with the MVT, these imply that $\mathbb{L}\phi(t',r')\geq 0$.


    \textbf{(ii): }Given that $A^\ast\neq(0,0)$, $\Pp-$a.s. on $[t',t'+h]$. We show that if $\ell + \diff{\phi}{x}(t',r')<0$ or $u - \diff{\phi}{x}(t',r')<0$ then they lead to some contradiction. By the fundamental calculus, we know that there exists $h>0$ such that 
    \begin{align*}
        \diff{\phi}{x}(t',r')\cdot h=\phi(t',x',m',s') - \phi(t',x'-h,m',s')
        =\phi(t',x'+h,m',s') - \phi(t',x',m',s')
    \end{align*}
    Since $v-\phi$ has a maximum point at $(t',r')$, it is easy to check that
    \begin{align*}
        h\ell +v(t',x',m',s') - v(t',x'-h,m',s')&\geq h\ell+ \phi(t',x',m',s') - \phi(t',x'-h,m',s')>0, \textup{ or}\\
        hu- v(t',x'+h,m',s') + v(t',x',m',s')&\geq hu-\phi(t',x'+h,m',s') + \phi(t',x',m',s')>0.
    \end{align*}
    This means that $(t', x') \notin \LB^h_{v}\cup\UB^h_{v}$. Since $v$ is convex in $x$, we arrive with a conclusion that   $(t', r') \in \CC^h_{v}$. By Assumption~\ref{ast:refined not incressing L U}, we then have $A^\ast=(0,0)$, $\Pp-$a.s. which is a contradiction. Therefore, this implies that $\ell+\diff{\phi}{x}(t',r')\geq0$ and $u - \diff{\phi}{x}(t',r')\geq 0$.

    All in all, we conclude that \eqref{eq: subsolution} holds and therefore $v$ is a viscosity subsolution.

    \textbf{Supersolution:} Now we show that $v$ is a viscosity supersolution. To this end, we suppose $v-\phi$ has a minimum point at $(t',r')$. In other word, it holds that $(v-\phi)(t',r')=0$ and  $(v-\phi)(t',r')\leq (v-\phi)(t,r)$ for all $(t,r)\in [0,T)\times \sr^3$. From now on, we proceed the argument by contradiction, which means in opposite to \eqref{eq: supersolution} that
    \begin{align}
        \mathbb{L}\phi(t',r')>0,\;\;\;
        \ell + \diff{\phi(t',r')}{x} >0 \;\;\;\textup{and}\;\;\;
        u - \diff{\phi(t',r')}{x} >0
    \end{align}
    At this point we may assume that there exist $C_c,C_{\ell},C_u>0$ such that
    \begin{align}
        \mathbb{L}\phi(t',r')=C_c,\;\;\;
        \ell + \diff{\phi(t',r')}{x} =C_{\ell} \;\;\;\textup{and}\;\;\;
        u - \diff{\phi(t',r')}{x} =C_u.\label{eq: sub contra}
    \end{align}
    Let $C'=\frac{C_c\wedge C_{\ell} \wedge C_u}{3}$, then by smoothness of $\phi$, the following the stopping time is well defined:
    \begin{align}\label{def: tau}
        \tau(t')\triangleq T \wedge\inf\Bigg\{\tau\geq t': &\Bigg(\mathbb{L}\phi(\tau,R_{\tau}^{A^\ast})\Bigg) \wedge  \left( \ell + \diff{\phi(\tau,R_{\tau}^{A^\ast})}{x} \right)\wedge\nonumber\\&\left( u - \diff{\phi(\tau,R_{\tau}^{A^\ast})}{x} \right) \wedge \left(\diff{\phi(\tau,R_{\tau}^{A^\ast})}{m} \right) \wedge \left(- \diff{\phi(\tau,R_{\tau}^{A^\ast})}{m}\right)\leq C'\Bigg\},
    \end{align}
     Thus, for $t\in[t', \tau(t')]$ we have by the DPP (Lemma \ref{lem: DPP}) that
    \begin{align}\label{eq: DPP2}
        J^{A^\ast}_{t'} =  \int_{t'}^{\tau(t')}   \left[ F\left(t,R_s^{A^\ast},J_s^{A^\ast},Z_s\right)\rd s +\ell \rd A^{\ast-}_s + u \rd A^{\ast+}_s - Z_s \rd \overline B_s \right] + J^{A^\ast}_{\tau(t')}
    \end{align}
    % Since $|\phi(\tau(t'),R_{\tau(t')}^{A^\ast})|<\infty $ \textbf{[remain to be proved]}, then we have by the comparison theorem (Theorem \ref{thm: comparison}), there exists a unique solution to the process $( {R}^{A^\ast}, {Y}^{A^\ast},  {Z} )$ such that
    % \begin{align}\label{eq: DPP3}
    %       J^{A^\ast}_t = \phi(\tau(t'),R_{\tau(t')}^{A^\ast}) + \int_t^{\tau(t')}   \left[ F\left(s, {R}_s^{A^\ast}, {Y}_s^{A^\ast},  Z_s\right)   \rd s +\ell \rd A^-^{\ast}_s + u \rd A^+^{\ast}_s -   Z_s \rd \overline B_s\right]  
    % \end{align}
    % Because $v-\phi$ attains a minimum point at $(t',r')$, one can infer that $\phi(\tau(t'),R_{\tau(t')}^{A^\ast}) = J^{A^\ast}_{\tau(t')}$ and so, again, by the comparison theorem it holds that
    % \begin{align}\label{eq: comparison}
    %       J^{A^\ast}_t = J^{A^\ast}_t, \;\Pp-\textup{a.s.}
    % \end{align}
    For each $t'\leq t \leq \tau(t')$. Now if we define by 
    \begin{align}
        \check J^{A^\ast}_{t'} = \phi(t',R^{A^\ast}_{t'}) \;\;\;\textup{and}\;\;\; \check Z_{t'} =  \sigma( X^{A^\ast}_{t'})  \diff{\phi(t,R^{A^\ast}_{t'})}{x} + S_{t'} \diff{\phi(t',R^{A^\ast}_{t'})}{m},
    \end{align}
    it then follows from the It\={o}'s lemma and \eqref{def: tau} that
    \begin{align}\label{eq: DPP4}
        \check J^{A^\ast}_{t'} &= \phi(\tau(t'),R^{A^\ast}_{\tau(t')}) - \int_{t'}^{\tau(t')}   \Bigg[ \cL \phi(s,R^{A^\ast}_s) \rd s + \diff{\phi}{x}(s,R^{A^\ast}_s)\rd A^\ast_s  \nonumber\\& \hspace{6.5cm} + \diff{\phi}{m}(s,R^{A^\ast}_s)\rd D_s + \check Z_s \rd \overline B_s \Bigg]\nonumber\\
        &\leq \phi(\tau(t'),R^{A^\ast}_{\tau(t')}) - \int_{t'}^{\tau(t')}   \bigg[ \left(C'-F\left(s,{R}_s^{A^\ast},\check{J}_s^{A^\ast},\check Z_s\right)\right)\rd s +  \check Z_s \rd \overline B_s\nonumber\\ &\hspace{5cm} + (C'-\ell)\rd A^{\ast-}_s + (C'-u)\rd A^{\ast+}_s  + C'(\rd D^-_s +\rd D^+_s)\bigg].
    \end{align}
    Since $(v-\phi)(t',r')=0$, it follows that the terms $\Delta J_t \triangleq J^{A^\ast}_t - \check J^{A^\ast}_t$ and $\Delta  Z_t \triangleq  Z_t - \check Z_t$ satisfy
    \begin{align*}
        -\Delta J_{\tau(t')} &\geq \int_{t'}^{\tau(t')}\Bigg[ \left(C'  + F(s,{R}_s^{A^\ast},{J}_s^{A^\ast}, Z_s)  -F(s,{R}_s^{A^\ast},\check{J}_s^{A^\ast},\check Z_s) \right)\rd s \\ &\hspace{2cm}+ C'(\rd A^{\ast-}_s+\rd A^{\ast+}_s + \rd L^{m}_s+\rd U^{m}_s) +  \left( \check Z_s -   Z_s \right)\rd \overline B_s  \Bigg]\\
        &\geq  \int_{t'}^{\tau(t')}\Bigg[ C'(\rd s + \rd A^{\ast-}_s + \rd A^{\ast+}_s + \rd L^{m}_s+\rd U^{m}_s) + 
        \left( \delta_s^J \Delta {J}_s + \delta_s^Z \Delta  Z_s  \right) \rd s -\Delta Z_s\rd \overline B_s\Bigg] \\
        &> \int_{t'}^{\tau(t')}\Bigg[
        \left( \delta_s^J \Delta {J}_s + \delta_s^Z \Delta  Z_s  \right) \rd s -\Delta Z_s\rd \overline B_s\Bigg],
    \end{align*}
    where
    \begin{align}
        \delta_s^J &\triangleq \frac{F(s, {R}_s^{A^\ast}, {J}_s^{A^\ast},\check Z_s) - F(s, {R}_s^{A^\ast},\check{J}_s^{A^\ast},\check Z_s)}{\Delta {Y}_s}\mathds{1}_{\Delta {J}_s\neq 0}\\
        \delta_s^Z &\triangleq \frac{F(s, {R}_s^{A^\ast}, {J}_s^{A^\ast},  Z_s) - F(s, {R}_s^{A^\ast}, {J}_s^{A^\ast},\check Z_s)}{\Delta {Z}_s}\mathds{1}_{\Delta {Z}_s\neq 0}.
    \end{align}
    The second inequality holds by \eqref{def: tau}. From the facts that $C'>0$ and that $A^\ast$ and $D$ are non-decreasing, we infer the last strict inequality. 

    From the comparison theorem one can see that
    \begin{align}\label{eq: delta}
        \delta_s^J \leq C_1 < \infty \;\;\textup{and}\;\;\delta_s^Z \leq C_1(1 + | {Y}_s^{A^\ast}|+|\check{J}_s^{A^\ast}|+| {Z}_s|+|\check{Z}_s|). 
    \end{align}
    Now we define the processes $(\Gamma^J,\Gamma^Z)\triangleq(\Gamma^J_t,\Gamma^Z_t)_{t\geq 0}$ by
    \begin{align}
        \rd \Gamma^J_t = \delta_t^y \Gamma^J_t \rd t,\;\;\Gamma_0^y=1,\;\;\textup{and}\;\;\rd \Gamma^Z_t = \delta_t^z \Gamma^Z_t \rd \overline B_t,\;\;\Gamma_0^z=1,
    \end{align}
    respectively. By It\={o}'s integration by parts, we have
    \begin{align*}
        \rd \Gamma^J_t \Delta J^{A}_t &=  \Gamma^J_t\rd \Delta J^{A}_t + \delta^y_t \Delta J^{A}_t \Gamma^J_t \rd t,
    \end{align*}
    and therefore
    \begin{align}\label{eq: gamma inequality}
        \rd \Gamma^Z_t\Gamma^J_t\Delta J^{A}_t &= \Gamma_t^z(\Gamma^J_t\rd \Delta J^{A}_t + \delta^y_t \Delta J^{A}_t \Gamma^J_t \rd t) +\delta_t^z \Gamma^Z_t\Gamma^J_t \Delta J^{A}_t \rd \overline B_t + \delta_t^z\Gamma_t^y\Gamma_t^z\Delta Z_t \rd t \nonumber\\
        &<   \Gamma_t^z(\Gamma^J_t
         [-\left(\delta_t^y \Delta {Y}_t+ \delta_t^z \Delta  Z_t  \right) \rd t  +\Delta Z_t\rd \overline B_t] + \delta^y_t \Delta J^{A}_t \Gamma^J_t \rd t)\nonumber \\& \hspace{6cm}+\delta_t^z \Gamma^Z_t\Gamma^J_t \Delta J^{A}_t \rd \overline B_t+ \delta_t^z\Gamma_t^y\Gamma_t^z\Delta Z_t \rd t\nonumber\\
        &=\Gamma^Z_t\Gamma^J_t(\Delta Z_t + \delta^z_t\Delta J^{A}_t)\rd \overline B_t.
    \end{align}
    From \eqref{eq: delta}, it is clear that $\delta^Z\in \CH^2_T$. Thus, we immediately obtain by Lemma \ref{lem: exp mart} that $\Gamma^Z$ is a uniformly integrable martingale which therefore induces that
    \begin{align}
        \Ep^{\Pp}_{\cG_{t'}}\left[ \int_{t'}^{\tau(t')} \Gamma^Z_s\Gamma^J_s(\Delta Z_s + \delta^z_s\Delta J_s)\rd \overline B_s\right] = 0.
    \end{align}
    This implies from \eqref{eq: gamma inequality} that
    \begin{align*}
        \Ep^{\Pp}_{\cG_{t'}}\left[ \Gamma^Z_{\tau(t')}\Gamma^J_{\tau(t')}\Delta J_{\tau(t')} -  \Gamma^Z_{t'}\Gamma^J_{t'}\Delta J_{t'}\right] <0
    \end{align*}
    However, since $v-\phi$ attains its minimum at $(t',r')$, it follows that $\Delta J_{\tau(t')}\geq\Delta J_{t'} = 0$. Therefore,
    \begin{align*}
        \Ep^{\Pp}_{\cG_{t'}}\left[ \Gamma^Z_{\tau(t')}\Gamma^J_{\tau(t')}\Delta J_{\tau(t')} -  \Gamma^Z_{t'}\Gamma^J_{t'}\Delta J_{t'}\right] \geq 0,
    \end{align*}
    which is a contradiction. As a result, the value function defined by  \eqref{def: value function} is a continuous viscosity supersolution to \eqref{eq: HJB3}.

    Hence, we conclude that $v$ is a viscosity solution to \eqref{eq: HJB3}.
\end{proof}

\section{Coordination transform and free boundaries characterisation}\label{sec:coor tran}



To solve the HJB equation \eqref{eq: HJB3}, we need to know the initial condition (IC) and the free boundary conditions (BC) for $(X^{M^{\Pp},A},M^{\Pp},S)$. It is well established that the BCs for $X^{M^{\Pp},A}$ are implemented using Neumann free BCs \eqref{eq: lower barrier PDE} and \eqref{eq: upper barrier PDE}, while the BCs for $M^{\Pp}$ impose Neumann fixed BCs because the triggers are predetermined. By combining this with a deterministic solution of $S$ to a Ricati equation, a verification theorem can be easily constructed, as shown, for example, by \citet{kushner2001numerical}. Once we have the solution, we can use it to intervene in the dynamics of $(X^{M^{\Pp},A},M^{\Pp})$ in accordance with the optimal control policy.

However, even with a solution to the HJB equation \eqref{eq: HJB3} (whether obtained analytically or numerically), it cannot be directly applied in practice. This is because we can only observe $X^{M^{\Pp}}$ and not $M^{\Pp}$. Therefore, we use a technique called \emph{coordinate transformation} from \cite{johnson2017quickest} to reduce a diffusion dimension from $M^{\Pp}$ so that only $X^{M^{\Pp}}$ exhibits stochastic evolution. The main idea is to apply a suitable transformation that converts the FBSDE system \eqref{eq: X^A_t}-\eqref{eq: J^A_t} into a different coordinate system where the (transformed) unobservable process is independent of the innovation process. We demonstrate that after this transformation, it follows a deterministic evolution dependent on both bounded variation processes $A$ and $(L^m,U^m)$. This allows us to impose the BCs in the new system in the classical sense of singular control. To do this, we define a transformation $\mathcal{T}:\sr^2\times\sr_+\to\sr^2\times\sr_+$ by 
\begin{align}\label{def: transform}
    \mathcal{T}(x,m,s)=(x,x-\frac{\sigma}{s}m,s)
\end{align}
where the invertible is given by 
\begin{align}\label{def: inverse transform}
    \mathcal{T}^{-1}(x,m,s)=(x,\frac{s}{\sigma}(x-m),s)
\end{align}
Taking $X_2\triangleq X_2(x,m,s)=x-\frac{\sigma}{s}m$, then it follows by It\={o}'s lemma that the new system of the forward SDEs $( X_1,X_2,S)\triangleq(X_{1,t},X_2(X_{1,t},M^{\Pp}_t,S_t),S_t)$ solve
\begin{align}
     &\rd  X_{1,t} &&= \bigg(\alpha( X_{1,t}) + S_t( X_{2,t} - X_{1,t} )\bigg)\rd t + \rd A_t+\sigma( X_{1,t})\rd \overline B_t,&& X_{1,0}=x, \label{eq: X1}\\
    &\rd X_{2,t} &&= \bigg(\alpha( X_{1,t})+ 2S_t( X_{2,t} - X_{1,t} )\bigg) \rd t  + \rd A_t -\frac{\sigma(X_{1,t})}{S_t}\rd D_t, && X_{2,0}=x-\frac{\sigma}{s}m, \label{eq: X2}\\
    &\rd S_t &&= -S^2_t \rd t, && S_0=s. \label{eq: S_t 2}
    \end{align}

% \begin{align*}
%     f(x,m)&=x-\frac{\sigma}{S(t)}m=x-\sigma m \left(\frac{1+s_0t}{s_0}\right)\\
%     \diff{f}{t}&=-\sigma m\\
%     \diff{f}{x}&=1\\
%     \diff{f}{m}&=-\frac{\sigma}{S(t)}\\
%     \secdiff{f}{x}&=\secdiff{f}{m}=\crossdiff{f}{x}{m}=0\\
%     \rd f(X_t,M_t) &= \bigg(\alpha(X_t) -2\sigma(X_t)M_t \bigg) \rd t + \rd A^-^x_t - \rd A^+^x_t  -\frac{\sigma(X_t)}{S_t}\bigg(\rd A^-^m_t - \rd A^+^m_t\bigg)\\
%     &=\bigg(\alpha(X_t) +2S(t)\Big(f(X_t,M_t)-X_t\Big) \bigg) \rd t + \rd A^-^x_t - \rd A^+^x_t  -\frac{\sigma(X_t)}{S_t}\bigg(\rd A^-^m_t - \rd A^+^m_t\bigg)
% \end{align*}

The inverse transformed version of the value function \eqref{eq: DPP v} is defined by the mapping $\vt:[0,T]\times\sr^2\times\sr_+\to[0,T]\times\sr^2\times\sr_+$ where
\begin{align}\label{def: tran val fn}
    \vt (t,\hat x) \triangleq  v (t,\mathcal{T}^{-1}(\hat x)) = v (t,x,m,s),
\end{align}
given $\hat x=(x_1,x_2,s).$ By this transformation, $D$ now only increases when $\frac{S_t}{\sigma(X_{1,t})}(X_{1,t} - X_{2,t})= \mL$ or $\mU$, respectively. 

We observe that $X_1 = X^{ M^{\Pp},A}$, which remains consistent with the pre-transformed process. In contrast, the process $X_2$ offers an entirely new interpretation. While $X_2$ resembles $X_1$, it notably lacks exposure to risk. This transformation yields a practical advantage, as it enables us to elicit $M^{\Pp}$ from the environment by observing $X_2$, which is itself dynamically inferred from $X_1$. For this reason, we refer to $X_2$ as an \textit{auxiliary controlled inventory process}. Furthermore, from~\eqref{eq: X1} and~\eqref{eq: X2}, we obtain 
\begin{align}\label{eq: X1-X2} 
    \rd (X_{1,t}-X_{2,t}) = S_t(X_{1,t}-X_{2,t})\rd t +\sigma( X_{1,t})\rd \overline B_t+\frac{\sigma(X_{1,u})}{S_t}\rd D_t, 
\end{align} 
which implies that, in expectation over the long run, the increment of $X_1$ converges to that of $X_2$. This follows from the fact that $S$ is a strictly decreasing function of time and bounded within $(0,s]$, while $X_1$ and $X_2$ are themselves bounded by the processes $A$ and $D$, respectively. Therefore, the DM may eventually expect to recover full information about the controlled inventory process $X_1$ through sufficiently long observation.

Since by construction, $v(t,r)=\vt(t,\hat x)$, it implies that a transformed HJB equation (to be shown later) solved by $\vt(t,\mathcal{T}(\hat x))$, gives a new optimal control policy that is equivalent to that of $v(t,r)$. To see this, one can check by the inverse transformation that
\begin{align}
    \diff{ v (t,x_1,\frac{s}{\sigma}(x_1-x_2),s)}{x} &=\diff{\vt (t,\hat x)}{x_1} + \diff{\vt (t,\hat x)}{x_2} ,\\
    \diff{ v (t,x_1,\frac{s}{\sigma}(x_1-x_2),s)}{m} &=-\frac{\sigma(x_1)}{s} \diff{\vt (t,\hat x)}{x_2} ,\\
    \frac{\partial^2v(t,x_1,\frac{s}{\sigma}(x_1-x_2),s)}{\partial x^2} &=\frac{\partial^2\vt(t,\hat x)}{\partial x_1^2} + \frac{\partial^2\vt(t,\hat x)}{\partial x_2^2} + 2\frac{\partial^2\vt(t,\hat x)}{\partial x_1 \partial x_2},\\
    \cL v(t,x_1,\frac{s}{\sigma}(x_1-x_2),s) &= \diff{\vt(t,\hat x)}{t} + \bigg(\alpha(x_1) + s(x_2-x_1)\bigg) \diff{\vt(t,\hat x)}{x_1}     \nonumber\\&\hspace{0.5cm} + \bigg(\alpha(x_1) + 2s(x_2-x_1)\bigg)\diff{\vt(t,\hat x)}{x_2}-s^2\diff{\vt(t,\hat x)}{s}+\frac{\sigma^2(x)}{2}\frac{\partial^2\vt(t,\hat x)}{\partial x_1^2}\nonumber\\&\triangleq \cL \vt(t,\hat x).
\end{align}
By plugging these terms into \eqref{eq: HJB3}, we then obtained so-called a transformed HJB equation:
\begin{align}\label{eq: HJB4}
    0&=\min\Bigg\{\cL \vt(t,\hat x) + F\bigg(t,\hat x,\vt(t,\hat x),\sigma(x_1) \diff{\vt(t,\hat x)}{x_1}  \bigg),\nonumber\\&\hspace{3cm}\;\; \ell + \diff{\vt (t,\hat x)}{x_1} + \diff{\vt (t,\hat x)}{x_2},\;\; u - \diff{\vt (t,\hat x)}{x_1} - \diff{\vt (t,\hat x)}{x_2}  \Bigg\}\\
    0&= \diff{\vt (t,x_1,x_1 - \frac{\sigma(x_1)}{s} \mL )}{x_2} = \diff{\vt (t,x_1,x_1 - \frac{\sigma(x_1)}{s} \mU )}{x_2}, 
    \\ \vt(T,\hat x)&=\xi(x_1),
\end{align}
claimed earlier. In consequence, the transformed optimal control policy represented by form of inaction and action regions can be defined by $\CC_{\hat v},\LB_{\hat v},\UB_{\hat v}\subset[0,T]\times\sr$ such that
\begin{align}
    \CC_{\hat v}&\triangleq\left\{(t,x_1,x_2)\in [0,T]\times\sr: -\ell<\diff{\vt (t,\hat x)}{x_1} + \diff{\vt (t,\hat x)}{x_2}<u\right\},\label{def: continuation region 2}\\
    \LB_{\hat v}&\triangleq\left\{(t,x_1,x_2)\in [0,T]\times\sr: -\ell\geq\diff{\vt (t,\hat x)}{x_1} + \diff{\vt (t,\hat x)}{x_2}\right\}\;\;\;\text{and,}\label{def: lower stopped region 2}\\
    \UB_{\hat v}&\triangleq\left\{(t,x_1,x_2)\in [0,T]\times\sr: \qquad\;\;\diff{\vt (t,\hat x)}{x_1} + \diff{\vt (t,\hat x)}{x_2}\geq u\right\},\label{def: upper stopped region 2}
\end{align}
which basically become a two dimensional singular controls problem. As a result, a solution the HJB equation \eqref{eq: HJB4} is equivalent to that of solving
\begin{align}
    \cL \vt(t,\hat x) + F\bigg(t,\hat x,v(t,\hat x),\sigma(x_1) \diff{\vt(t,\hat x)}{x_1}\bigg)&=0\;\;\;(t,x_1,x_2)\in\CC_{\hat v} \label{eq: continue PDE 2}\\
    \ell +\diff{\vt (t,\hat x)}{x_1} + \diff{\vt (t,\hat x)}{x_2}&=0\;\;\;(t,x_1,x_2)\in\LB_{\hat v}\label{eq: lower barrier PDE 2}\\
    u - \diff{\vt (t,\hat x)}{x_1} - \diff{\vt (t,\hat x)}{x_2}&=0\;\;\;(t,x_1,x_2)\in\UB_{\hat v}.\label{eq: upper barrier PDE 2}
\end{align}
Now we modify Assumption~\ref{ast:refined not incressing L U} to define an optimal control policy for the transformed value function \eqref{def: tran val fn} and show that it is a viscosity solution to \eqref{eq: HJB4}.

\begin{definition}
    For given $\hat v\in C[0,T]\times \sr^3$ and $h_1,h_2>0$,
    \begin{align}
    \LB_{\hat v}^{h_1,h_2}&\triangleq\{(t,x_1,x_2)\in [0,T]\times\sr^2: -\ell h_1h_2\geq \phantom{-}(h_1+h_2)\hat v(t,x,m,s)-h_2\hat v(t,x_1-h_1,x_2,s)\nonumber\\&\hspace{9.cm}-h_1\hat v(t,x_1,x_2-h_2,s)\}\label{def: tran refined lower stopped region}\\
    \UB_{\hat v}^{h_1,h_2}&\triangleq\{(t,x_1,x_2)\in [0,T]\times\sr^2: \phantom{-}uh_1h_2\geq -(h_1+h_2)\hat v(t,x,m,s)+h_2\hat v(t,x_1+h_1,x_2,s)\nonumber\\&\hspace{9.cm}+h_1\hat v(t,x_1,x_2+h_2,s)\},\label{def: tran refined upper stopped region}\;\;\;\text{and,}\\
    \CC_{\hat v}^{h_1,h_2}&\triangleq[0,T]\times\sr^2\setminus (\LB_{\hat v}^{h_1,h_2}\cup\UB_{\hat v}^{h_1,h_2}).\label{def: tran refined continuation region}
\end{align}
\end{definition}

\begin{assumption}\label{ast: tran refined not incressing L U}
    Given  $v\in C[0,T]\times \sr^3$ and. For any feasible policy $A\in \cD$, there exists $h_1,h_2>0$ such that
    \begin{align}
        \int_0^T\mathds{1}_{\{(t,X^{M^{\Pp},A}_t)\in \CC_{\hat v}^{h_1,h_2}\}} \rd A_t = 0,\;\Pp\textup{--a.s.}
    \end{align}
\end{assumption}

\begin{theorem}\label{thm: viscosity 2}
    The value function defined by  \eqref{def: tran val fn} is a unique continuous viscosity solution to \eqref{eq: HJB4}.
\end{theorem}
\noindent\begin{proof}[Proof of Theorem \ref{thm: viscosity 2}]
Since $\mathcal{T}$ has a smooth transformation, it is straightforward to check that \eqref{def: tran val fn} is a unique continuous viscosity solution to \eqref{eq: HJB4} by utilising Assumption~\ref{ast: tran refined not incressing L U} and repeating the argument given in Theorem~\ref{thm: viscosity 1}. 
\end{proof}

