\section{Simulations and results}\label{sec:sim}

In Subsection~\ref{sec:full} we present the full models for the cAMP signaling pathways for EP2, EP4 and their crosstalk. Subsequently,  we show in numerical simulations that the models qualitatively predict the experimentally observed cAMP levels in response to PGE2 shown in Figures~\ref{experiment} and~\ref{im:schematic}.  Numerical codes for simulations of model equations are implemented
in Python, taking advantage of the Scipy module \cite{Jones2001} and  solutions for systems of ODEs were obtained using the scipy.integrate.odeint package.

\subsection{Full models for signaling pathways}\label{sec:full}

The full PGE2 induced  cAMP signalling cascade for EP2 is described by the following system of ordinary differential equations combining the model for ligand-receptor binding \eqref{eq:lig_dyn} (with $m=1$)  with the models for the EP2 G-protein activation cycle  \eqref{EP2:model1} and cAMP expression \eqref{eq:EP2cAMP} (with $\eta=0$),
\begin{equation}\label{eq:EP2full}
\begin{aligned}
\frac{d p} {dt} & = - \mu_{1} \, r_1 \,   p^{n_1}  + \delta_1 r^\ast_1,  \qquad 
\frac{dr_1}{dt}  =   - \mu_{1} \, r_1  p^{n_1}  + \delta_1 r^\ast_1,  \qquad  
\frac{d r^\ast_1}{dt}  = \mu_{1} \, r_1 p^{n_1} - \delta_1 r_1^\ast,\\
\frac{d\alpha_s^\ast}{dt} &= k_{s}r^\ast_1 \frac{ b_1 - \beta}{b_1 - \beta + K_{r_1s}} - d_s \alpha^\ast_s,\\
 \frac{d\beta}{dt}& =k_{s}  r^\ast_1 \frac{ b_1 - \beta}{b_1 - \beta + K_{r_1s}} + d_{\beta s}(b_1 - \beta) - k_{\beta s} \beta(a_s - b_1 + \beta - \alpha^\ast_s),\\
  \frac{dw}{dt} & = k_{w}A^{tot}\frac{ \alpha^\ast_s }{\alpha^\ast_s+K_{as}}  - d_{w} P^{tot}\frac{ w}{w+K_{w}}. %- d_{w2} P_2^{tot}\frac{w}{w+K_{w_2}}
\end{aligned}
\end{equation}

The full PGE2 induced  cAMP signalling cascade for EP4 is described by the following system of ODEs combining the model for ligand-receptor binding~\eqref{eq:lig_dyn} (with $m=2$)  with the models for the EP4 G-protein activation cycles  \eqref{EP4:model3} and cAMP expression \eqref{eq:EP2cAMP} (with $\eta=1$),
\begin{align}\label{eq:EP4full}
\begin{split}
\frac{d p} {dt} & = - \mu_{2} \, r_2 \,   p  + \delta_2 r^\ast_2,   \qquad 
\frac{dr_2}{dt}  =   - \mu_{2} \, r_2 \, p  + \delta_2 r^\ast_2,    \qquad 
\frac{d r^\ast_2}{dt}  = \mu_{2} \, r_2 p - \delta_2 r_2^\ast-\rho_2r_2^*,\\
\frac{d\alpha_s^\ast}{dt} &= k_{s} r^*_2 \, f(\beta_i, \beta) - d_s   \alpha_s^\ast,  \qquad 
\frac{d\alpha_i^\ast}{dt} = \, k_{i} r^*_2  g(\beta_i, \beta)- d_i   \alpha_i^\ast,\\
\frac{d\beta_i}{dt}& =- k_{i} r^\ast_2 \, g(\beta_i, \beta) + k_{\beta i} \beta ( a_i - \beta_i - \alpha_i^\ast) - d_{\beta i} \beta_i, \\
\frac{d\beta}{dt} & = \;  k_{i} r^\ast_2\,   g(\beta_i, \beta)
 + k_{s} r^*_2  f(\beta_i, \beta) + d_{\beta i} \beta_i +  d_{\beta s} (b_2 - \beta- \beta_i)\\
& \qquad - \beta(k_{\beta s}(a_s - b_2 + \beta + \beta_i -\alpha_s^\ast) + k_{\beta i}(a_i - \beta_i - \alpha_i^\ast)),\\
  \frac{dw}{dt} & = k_{w}\frac{ \alpha^\ast_sA^{tot}}{\alpha^\ast_s + K_{as} (1+ \alpha^\ast_i /K_{ai})}  - d_{w} \frac{ wP^{tot}}{w+K_{w}}, %- d_{w2} P_2^{tot}\frac{w}{w+K_{w_2}}
\end{split}
\end{align}
where
$$
\begin{aligned} 
f(\beta_i, \beta) & = \frac{ b_2 - \beta- \beta_i}{b_2 - \beta  - \beta_i+ K_{r_2s} + (K_{r_2s}/K_{r_2i}) \beta_i},  \\
g(\beta_i, \beta) & = \frac{\beta_i}{\beta_i + K_{r_2i} + (b_2 - \beta - \beta_i)K_{r_2i}/K_{r_2s}} .
\end{aligned} 
$$

To describe crosstalk we combine the models for the single receptors as follows.
The combined activation of EP2 and EP4 by PGE2 is modeled by
\begin{equation}\label{eq:ligands_coupled}
\begin{aligned}
\frac{d p} {dt} & = - (1-\sigma) \mu_{1} \, r_1 \,   p^{n_1} -\sigma\mu_{2} \, r_2 \,   p  + \delta_1 r^\ast_1+ \delta_2 r^\ast_2,  \\
\frac{dr_1}{dt} & =   - (1-\sigma)\mu_{1} \, r_1  p^{n_1}  + \delta_{1} r^\ast_1, \qquad \quad 
\frac{d r^\ast_1}{dt}  =  (1-\sigma)\mu_{1} \, r_1 p^{n_1} - \delta_{1} r^\ast_1,\\
\frac{dr_2}{dt} & =   - \sigma\mu_{2} \, r_2  p  + \delta_{2} r^\ast_2, \qquad \qquad \qquad \;
\frac{d r^\ast_2}{dt}  =\sigma \mu_{2} \, r_2 p - \delta_{2} r^\ast_2 -\rho_{2}r^*_2,
\end{aligned}
\end{equation}
where $\sigma\in(0,1)$ indicates the fraction of PGE2 binding to EP4.
This system  is combined with the models for the G-protein activation cycles for EP2 \eqref{EP2:model1} and EP4 \eqref{EP4:model3} and cAMP expression \eqref{eq:EP2cAMP} (with $\eta=1$),
\begin{equation}\label{eq:EP2-EP4}
\begin{aligned}
\frac{d\alpha_s^\ast}{dt} &= \, k_{s} r^*_2 \sigma_0\, 
f(\beta_i, \beta)+k_{s}r^\ast_1 (1-\sigma_0)\frac{ b_2 - \beta-\beta_i}{b_2 - \beta -\beta_i+ K_{r_1s}} - d_s \,  \alpha_s^\ast,\\
\frac{d\alpha_i^\ast}{dt}&= \, k_{i} r^*_2\,  g(\beta_i, \beta) - d_i \,  \alpha_i^\ast,\\
\frac{d\beta_i}{dt}& =- k_{i} r^\ast_2 \, g(\beta_i, \beta)  + k_{\beta i} \beta ( a_i - \beta_i - \alpha_i^\ast) - d_{\beta i} \beta_i, \\
\frac{d\beta}{dt} & = \, k_{i} r^\ast_2 \, g(\beta_i, \beta)  
 + k_{s} r^*_2 \sigma_0 \; f(\beta_i, \beta) +k_{s}  r^\ast_1(1-\sigma_0) \frac{ b_2 - \beta-\beta_i}{b_2 - \beta -\beta_i+ K_{r_1s}} 
 + d_{\beta i} \beta_i \\
& \quad +  d_{\beta s} (b_2 - \beta- \beta_i) - \beta(k_{\beta s}(a_s - b_2 + \beta + \beta_i -\alpha_s^\ast) + k_{\beta i}(a_i - \beta_i - \alpha_i^\ast)),\\
 \frac{dw}{dt} & = k_{w}\frac{ \alpha^\ast_sA^{tot}}{\alpha^\ast_s + K_{as} (1+ \alpha^\ast_i /K_{ai})}  - d_{w} \frac{ wP^{tot}}{w+K_{w}}.
\end{aligned}
\end{equation}
where $\sigma_0\in(0,1)$ indicates the fraction of G$_{\alpha_s\beta\gamma}$-units binding to EP4.


